window.PK_HTML = {"shakai-1":"<!DOCTYPE html>\n<html lang=\"ja\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>第1章 人間と社会 — まとめフローチャート</title>\n<link href=\"https://fonts.googleapis.com/css2?family=Noto+Sans+JP:wght@300;400;500;700;900&family=Noto+Serif+JP:wght@400;700&display=swap\" rel=\"stylesheet\">\n<style>\n  :root {\n    --green-dark: #2d6a4f;\n    --green-mid: #40916c;\n    --green-light: #74c69d;\n    --green-pale: #d8f3dc;\n    --yellow: #f4d35e;\n    --orange: #f79d65;\n    --red: #e07a5f;\n    --blue: #457b9d;\n    --blue-light: #a8dadc;\n    --purple: #7b6d8d;\n    --gray: #f8f9fa;\n    --text: #1b1b2f;\n    --white: #ffffff;\n  }\n\n  * { margin: 0; padding: 0; box-sizing: border-box; }\n\n  body {\n    font-family: 'Noto Sans JP', sans-serif;\n    background: #f0f7f4;\n    color: var(--text);\n    min-height: 100vh;\n  }\n\n  /* HEADER */\n  header {\n    background: linear-gradient(135deg, var(--green-dark) 0%, var(--green-mid) 60%, var(--green-light) 100%);\n    padding: 36px 24px 28px;\n    text-align: center;\n    position: relative;\n    overflow: hidden;\n  }\n  header::before {\n    content: '';\n    position: absolute;\n    top: -40px; right: -40px;\n    width: 200px; height: 200px;\n    background: rgba(255,255,255,0.06);\n    border-radius: 50%;\n  }\n  header::after {\n    content: '';\n    position: absolute;\n    bottom: -60px; left: -30px;\n    width: 150px; height: 150px;\n    background: rgba(255,255,255,0.04);\n    border-radius: 50%;\n  }\n  .header-badge {\n    display: inline-block;\n    background: rgba(255,255,255,0.18);\n    border: 1px solid rgba(255,255,255,0.35);\n    color: #fff;\n    font-size: 11px;\n    letter-spacing: 2px;\n    padding: 4px 14px;\n    border-radius: 20px;\n    margin-bottom: 12px;\n    text-transform: uppercase;\n  }\n  header h1 {\n    font-family: 'Noto Serif JP', serif;\n    color: #fff;\n    font-size: clamp(20px, 5vw, 32px);\n    font-weight: 700;\n    line-height: 1.4;\n    margin-bottom: 6px;\n  }\n  header p {\n    color: rgba(255,255,255,0.8);\n    font-size: 13px;\n  }\n\n  /* MAIN */\n  main {\n    max-width: 820px;\n    margin: 0 auto;\n    padding: 28px 16px 60px;\n  }\n\n  /* SECTION BLOCK */\n  .section {\n    margin-bottom: 24px;\n    animation: fadeUp 0.5s ease both;\n  }\n  .section:nth-child(1) { animation-delay: 0.05s; }\n  .section:nth-child(2) { animation-delay: 0.1s; }\n  .section:nth-child(3) { animation-delay: 0.15s; }\n  .section:nth-child(4) { animation-delay: 0.2s; }\n  .section:nth-child(5) { animation-delay: 0.25s; }\n  .section:nth-child(6) { animation-delay: 0.3s; }\n\n  @keyframes fadeUp {\n    from { opacity: 0; transform: translateY(18px); }\n    to { opacity: 1; transform: translateY(0); }\n  }\n\n  .section-header {\n    display: flex;\n    align-items: center;\n    gap: 12px;\n    padding: 14px 18px;\n    border-radius: 14px 14px 0 0;\n    cursor: pointer;\n    user-select: none;\n    transition: filter 0.2s;\n  }\n  .section-header:hover { filter: brightness(1.07); }\n  .section-icon {\n    width: 38px; height: 38px;\n    border-radius: 50%;\n    background: rgba(255,255,255,0.22);\n    display: flex; align-items: center; justify-content: center;\n    font-size: 18px;\n    flex-shrink: 0;\n  }\n  .section-title {\n    flex: 1;\n  }\n  .section-title .jp {\n    font-size: 17px;\n    font-weight: 700;\n    color: #fff;\n    display: block;\n  }\n  .section-title .id {\n    font-size: 11px;\n    color: rgba(255,255,255,0.75);\n    display: block;\n    margin-top: 1px;\n  }\n  .toggle-arrow {\n    color: rgba(255,255,255,0.8);\n    font-size: 14px;\n    transition: transform 0.3s;\n  }\n  .section.open .toggle-arrow { transform: rotate(180deg); }\n\n  .section-body {\n    background: #fff;\n    border-radius: 0 0 14px 14px;\n    border: 1px solid #e2ede9;\n    border-top: none;\n    overflow: hidden;\n    max-height: 0;\n    transition: max-height 0.45s ease;\n  }\n  .section.open .section-body {\n    max-height: 3000px;\n  }\n  .section-inner {\n    padding: 20px 18px 22px;\n  }\n\n  /* COLOR THEMES */\n  .theme-green .section-header { background: linear-gradient(90deg, #2d6a4f, #40916c); }\n  .theme-blue .section-header  { background: linear-gradient(90deg, #1d3557, #457b9d); }\n  .theme-orange .section-header { background: linear-gradient(90deg, #c05c35, #f79d65); }\n  .theme-purple .section-header { background: linear-gradient(90deg, #4a3860, #7b6d8d); }\n  .theme-red .section-header   { background: linear-gradient(90deg, #a63d2f, #e07a5f); }\n  .theme-teal .section-header  { background: linear-gradient(90deg, #007f8c, #4cc9c0); }\n\n  /* FLOW NODES */\n  .flow {\n    display: flex;\n    flex-direction: column;\n    gap: 0;\n  }\n  .flow-row {\n    display: flex;\n    align-items: stretch;\n    gap: 10px;\n    margin-bottom: 6px;\n  }\n  .flow-connector {\n    display: flex;\n    justify-content: center;\n    margin: 0 0 6px 30px;\n  }\n  .flow-connector::before {\n    content: '';\n    width: 2px;\n    height: 18px;\n    background: #b7d5c8;\n    display: block;\n  }\n\n  .node {\n    border-radius: 10px;\n    padding: 10px 14px;\n    flex: 1;\n    position: relative;\n  }\n  .node-label {\n    font-size: 10px;\n    font-weight: 700;\n    letter-spacing: 1px;\n    text-transform: uppercase;\n    margin-bottom: 5px;\n    opacity: 0.65;\n  }\n  .node-main {\n    font-size: 14px;\n    font-weight: 700;\n    line-height: 1.4;\n  }\n  .node-sub {\n    font-size: 11px;\n    margin-top: 4px;\n    line-height: 1.5;\n    opacity: 0.82;\n  }\n  .node-id {\n    font-size: 11px;\n    margin-top: 5px;\n    padding-top: 5px;\n    border-top: 1px dashed currentColor;\n    opacity: 0.6;\n    font-style: italic;\n  }\n\n  /* NODE COLORS */\n  .node-green   { background: #d8f3dc; color: #1b5e38; }\n  .node-blue    { background: #e3f2fd; color: #1d3557; }\n  .node-yellow  { background: #fff8e1; color: #7a5c00; }\n  .node-orange  { background: #fde8d8; color: #7a3010; }\n  .node-red     { background: #fce4e0; color: #7a2010; }\n  .node-purple  { background: #ede7f6; color: #3d2060; }\n  .node-teal    { background: #e0f7f4; color: #005f6b; }\n  .node-gray    { background: #f3f4f6; color: #374151; }\n\n  /* BADGE ROW */\n  .badge-row {\n    display: flex;\n    flex-wrap: wrap;\n    gap: 8px;\n    margin-top: 10px;\n  }\n  .badge {\n    display: inline-flex;\n    flex-direction: column;\n    align-items: center;\n    padding: 8px 12px;\n    border-radius: 10px;\n    font-size: 12px;\n    font-weight: 700;\n    min-width: 80px;\n    text-align: center;\n  }\n  .badge .num {\n    font-size: 20px;\n    font-weight: 900;\n    line-height: 1.1;\n  }\n  .badge .lbl { font-size: 10px; opacity: 0.72; margin-top: 2px; }\n\n  /* STAT GRID */\n  .stat-grid {\n    display: grid;\n    grid-template-columns: repeat(auto-fill, minmax(130px, 1fr));\n    gap: 10px;\n    margin-top: 12px;\n  }\n  .stat-card {\n    border-radius: 10px;\n    padding: 12px;\n    text-align: center;\n  }\n  .stat-card .stat-num {\n    font-size: 22px;\n    font-weight: 900;\n    line-height: 1;\n    display: block;\n  }\n  .stat-card .stat-jp {\n    font-size: 12px;\n    font-weight: 700;\n    display: block;\n    margin-top: 4px;\n  }\n  .stat-card .stat-id {\n    font-size: 10px;\n    opacity: 0.65;\n    display: block;\n    margin-top: 2px;\n    font-style: italic;\n  }\n\n  /* CAUSE OF DEATH TABLE */\n  .cause-table {\n    width: 100%;\n    border-collapse: collapse;\n    font-size: 13px;\n    margin-top: 10px;\n  }\n  .cause-table th {\n    padding: 7px 10px;\n    text-align: left;\n    font-size: 11px;\n    font-weight: 700;\n    letter-spacing: 0.5px;\n  }\n  .cause-table td {\n    padding: 7px 10px;\n    border-bottom: 1px solid #f0f0f0;\n  }\n  .cause-table tr:last-child td { border-bottom: none; }\n  .rank-num {\n    display: inline-flex;\n    align-items: center;\n    justify-content: center;\n    width: 22px; height: 22px;\n    border-radius: 50%;\n    font-size: 11px;\n    font-weight: 700;\n    color: #fff;\n  }\n\n  /* FURIGANA */\n  ruby rt {\n    font-size: 9px;\n    color: #40916c;\n    line-height: 1;\n  }\n\n  /* ARROW DOWN */\n  .arrow-down {\n    text-align: center;\n    font-size: 20px;\n    color: #b7d5c8;\n    margin: 4px 0;\n    line-height: 1;\n  }\n\n  /* HIGHLIGHT BOX */\n  .highlight-box {\n    border-left: 4px solid;\n    padding: 10px 14px;\n    border-radius: 0 10px 10px 0;\n    margin-top: 10px;\n    font-size: 13px;\n    line-height: 1.6;\n  }\n  .hl-green { border-color: var(--green-mid); background: #f0faf5; color: #1b5e38; }\n  .hl-blue  { border-color: var(--blue); background: #f0f6fc; color: #1d3557; }\n  .hl-orange { border-color: var(--orange); background: #fef6f0; color: #7a3010; }\n  .hl-purple { border-color: var(--purple); background: #f5f0fb; color: #3d2060; }\n\n  /* FAMILY TREE MINI */\n  .family-grid {\n    display: grid;\n    grid-template-columns: 1fr 1fr;\n    gap: 8px;\n    margin-top: 10px;\n  }\n\n  /* TIMELINE */\n  .timeline {\n    position: relative;\n    padding-left: 22px;\n    margin-top: 10px;\n  }\n  .timeline::before {\n    content: '';\n    position: absolute;\n    left: 7px; top: 0; bottom: 0;\n    width: 2px;\n    background: #b7d5c8;\n  }\n  .tl-item {\n    position: relative;\n    margin-bottom: 12px;\n    font-size: 13px;\n  }\n  .tl-item::before {\n    content: '';\n    position: absolute;\n    left: -18px; top: 5px;\n    width: 10px; height: 10px;\n    border-radius: 50%;\n    border: 2px solid var(--green-mid);\n    background: #fff;\n  }\n  .tl-item .tl-year {\n    font-weight: 700;\n    font-size: 11px;\n    color: var(--green-mid);\n    display: block;\n  }\n  .tl-item .tl-text { color: #333; }\n\n  /* RESPONSIVE */\n  @media (max-width: 500px) {\n    .stat-grid { grid-template-columns: repeat(2, 1fr); }\n    .family-grid { grid-template-columns: 1fr; }\n    .badge { min-width: 70px; }\n  }\n\n  /* INTRO LABEL */\n  .intro-label {\n    text-align: center;\n    font-size: 12px;\n    color: #40916c;\n    margin-bottom: 16px;\n    letter-spacing: 1px;\n    font-weight: 700;\n  }\n</style>\n<style id=\"pk-fix\">\n.sec-body{max-height:none!important;overflow:visible!important;display:none;transition:none!important}\n.section.open .sec-body{display:block}\n.section{animation:none!important;opacity:1!important;transform:none!important}\n*{min-width:0}\nbody{overflow-x:hidden;-webkit-text-size-adjust:100%}\nmain{padding-left:10px!important;padding-right:10px!important}\np,div,span,td,th,li{overflow-wrap:anywhere;word-break:normal}\nimg,svg,video{max-width:100%;height:auto}\ntable{display:block;max-width:100%;overflow-x:auto;-webkit-overflow-scrolling:touch;border-collapse:collapse}\n@media (max-width:560px){\n [class*=\"grid\"],[class*=\"cols\"],[class*=\"compare\"],[class*=\"pair\"],[class*=\"two\"],[class*=\"stats\"]{grid-template-columns:1fr 1fr!important}\n [class*=\"grid3\"],[class*=\"grid-3\"],[class*=\"three\"]{grid-template-columns:1fr!important}\n [class*=\"row\"],[class*=\"flex\"],[class*=\"flow\"],[class*=\"chain\"]{flex-wrap:wrap!important}\n [class*=\"compare\"] > *,[class*=\"pair\"] > *{min-width:0}\n}\n</style>\n<script>\n(function(){\n function post(){try{parent.postMessage({pkH:Math.ceil(document.documentElement.scrollHeight)},'*');}catch(e){}}\n document.addEventListener('DOMContentLoaded',function(){\n  document.querySelectorAll('.section').forEach(function(s,i){ if(i===0) s.classList.add('open'); });\n  post();\n  if(window.ResizeObserver) new ResizeObserver(post).observe(document.body);\n  document.addEventListener('click',function(){setTimeout(post,30);setTimeout(post,400);});\n });\n window.addEventListener('load',post);\n})();\n<\/script></head>\n<body>\n\n<header>\n  <div class=\"header-badge\">第1章・第1節 — まとめ</div>\n  <h1>個人・家族と社会<br><span style=\"font-size:0.65em;font-weight:400;\">Individu, Keluarga & Masyarakat</span></h1>\n  <p>タップして各テーマを開く ／ Ketuk untuk membuka setiap topik</p>\n</header>\n\n<main>\n  <div class=\"intro-label\">▼ 順番に読もう ／ Baca Secara Berurutan ▼</div>\n\n  <!-- ======= SECTION 1 ======= -->\n  <div class=\"section theme-green open\" id=\"s1\">\n    <div class=\"section-header\" onclick=\"toggle('s1')\">\n      <div class=\"section-icon\">📊</div>\n      <div class=\"section-title\">\n        <span class=\"jp\"><ruby>日本<rt>にほん</rt></ruby>の<ruby>人口動態<rt>じんこうどうたい</rt></ruby></span>\n        <span class=\"id\">Dinamika Kependudukan Jepang</span>\n      </div>\n      <span class=\"toggle-arrow\">▼</span>\n    </div>\n    <div class=\"section-body\">\n      <div class=\"section-inner\">\n\n        <!-- Stats -->\n        <div class=\"stat-grid\">\n          <div class=\"stat-card node-green\">\n            <span class=\"stat-num\">81.09<small style=\"font-size:14px\">歳</small></span>\n            <span class=\"stat-jp\"><ruby>平均寿命<rt>へいきんじゅみょう</rt></ruby>（男）</span>\n            <span class=\"stat-id\">Harapan Hidup Pria</span>\n          </div>\n          <div class=\"stat-card node-blue\">\n            <span class=\"stat-num\">87.14<small style=\"font-size:14px\">歳</small></span>\n            <span class=\"stat-jp\"><ruby>平均寿命<rt>へいきんじゅみょう</rt></ruby>（女）</span>\n            <span class=\"stat-id\">Harapan Hidup Wanita</span>\n          </div>\n          <div class=\"stat-card node-orange\">\n            <span class=\"stat-num\">29.3<small style=\"font-size:14px\">%</small></span>\n            <span class=\"stat-jp\"><ruby>高齢化率<rt>こうれいかりつ</rt></ruby></span>\n            <span class=\"stat-id\">Tingkat Lansia</span>\n          </div>\n          <div class=\"stat-card node-yellow\">\n            <span class=\"stat-num\">1.20</span>\n            <span class=\"stat-jp\"><ruby>合計特殊出生率<rt>ごうけいとくしゅしゅっしょうりつ</rt></ruby></span>\n            <span class=\"stat-id\">Angka Kelahiran 2023</span>\n          </div>\n          <div class=\"stat-card node-red\">\n            <span class=\"stat-num\">73<small style=\"font-size:14px\">万</small></span>\n            <span class=\"stat-jp\"><ruby>出生数<rt>しゅっしょうすう</rt></ruby>（令和5）</span>\n            <span class=\"stat-id\">Jumlah Kelahiran</span>\n          </div>\n          <div class=\"stat-card node-purple\">\n            <span class=\"stat-num\">158<small style=\"font-size:14px\">万</small></span>\n            <span class=\"stat-jp\"><ruby>死亡数<rt>しぼうすう</rt></ruby>（令和5）</span>\n            <span class=\"stat-id\">Jumlah Kematian</span>\n          </div>\n        </div>\n\n        <!-- Cause of death -->\n        <div class=\"highlight-box hl-green\" style=\"margin-top:16px;\">\n          <strong><ruby>死因<rt>しいん</rt></ruby>ランキング（Penyebab Kematian Utama）</strong>\n        </div>\n        <table class=\"cause-table\">\n          <tr style=\"background:#f0faf5;\">\n            <th>順位</th>\n            <th>男性（<ruby>男<rt>おとこ</rt></ruby>）</th>\n            <th>女性（<ruby>女<rt>おんな</rt></ruby>）</th>\n          </tr>\n          <tr>\n            <td><span class=\"rank-num\" style=\"background:#e07a5f;\">1</span></td>\n            <td><ruby>肺<rt>はい</rt></ruby>がん ／ Kanker Paru</td>\n            <td><ruby>大腸<rt>だいちょう</rt></ruby>がん ／ Kanker Usus</td>\n          </tr>\n          <tr>\n            <td><span class=\"rank-num\" style=\"background:#f79d65;\">2</span></td>\n            <td><ruby>大腸<rt>だいちょう</rt></ruby>がん ／ Kanker Usus</td>\n            <td><ruby>肺<rt>はい</rt></ruby>がん ／ Kanker Paru</td>\n          </tr>\n          <tr>\n            <td><span class=\"rank-num\" style=\"background:#f4d35e;color:#333;\">3</span></td>\n            <td><ruby>胃<rt>い</rt></ruby>がん ／ Kanker Lambung</td>\n            <td><ruby>膵<rt>すい</rt></ruby>がん ／ Kanker Pankreas</td>\n          </tr>\n        </table>\n\n        <div class=\"highlight-box hl-orange\" style=\"margin-top:14px;\">\n          💡 <ruby>現在<rt>げんざい</rt></ruby>の<ruby>人口<rt>じんこう</rt></ruby>ピラミッドは「<strong><ruby>逆<rt>さか</rt></ruby>ひょうたん<ruby>型<rt>がた</rt></ruby></strong>」<br>\n          <span style=\"font-size:11px;opacity:0.75;\">→ Piramida penduduk Jepang saat ini berbentuk \"labu terbalik\" (lebih banyak lansia)</span>\n        </div>\n\n      </div>\n    </div>\n  </div>\n\n  <div class=\"arrow-down\">↓</div>\n\n  <!-- ======= SECTION 2 ======= -->\n  <div class=\"section theme-blue\" id=\"s2\">\n    <div class=\"section-header\" onclick=\"toggle('s2')\">\n      <div class=\"section-icon\">📉</div>\n      <div class=\"section-title\">\n        <span class=\"jp\"><ruby>少子高齢化<rt>しょうしこうれいか</rt></ruby>の<ruby>進行<rt>しんこう</rt></ruby></span>\n        <span class=\"id\">Penurunan Kelahiran & Penuaan Penduduk</span>\n      </div>\n      <span class=\"toggle-arrow\">▼</span>\n    </div>\n    <div class=\"section-body\">\n      <div class=\"section-inner\">\n\n        <div class=\"flow\">\n          <div class=\"node node-blue\">\n            <div class=\"node-label\">原因 ／ Penyebab</div>\n            <div class=\"node-main\">女性のライフスタイルの変化</div>\n            <div class=\"node-sub\">Perubahan gaya hidup wanita</div>\n            <div class=\"node-id\">\n              <ruby>平均初婚年齢<rt>へいきんしょこんねんれい</rt></ruby>：24.2歳（昭和45）→ <strong>29.7歳</strong>（令和5）<br>\n              Usia rata-rata pernikahan pertama naik dari 24→29 tahun\n            </div>\n          </div>\n          <div class=\"flow-connector\"></div>\n          <div class=\"node node-orange\">\n            <div class=\"node-label\">結果 ／ Akibat</div>\n            <div class=\"node-main\"><ruby>合計特殊出生率<rt>ごうけいとくしゅしゅっしょうりつ</rt></ruby>が低下</div>\n            <div class=\"node-sub\">Angka fertilitas total menurun: 2.13 → 1.20</div>\n          </div>\n          <div class=\"flow-connector\"></div>\n          <div class=\"node node-red\">\n            <div class=\"node-label\">将来予測 ／ Proyeksi</div>\n            <div class=\"node-main\"><ruby>人口<rt>じんこう</rt></ruby>は<ruby>今後<rt>こんご</rt></ruby>も<ruby>減少<rt>げんしょう</rt></ruby></div>\n            <div class=\"node-sub\">Penduduk Jepang akan terus berkurang di masa mendatang</div>\n            <div class=\"node-id\">\n              1997年：<ruby>老年人口<rt>ろうねんじんこう</rt></ruby>が<ruby>年少人口<rt>ねんしょうじんこう</rt></ruby>を<ruby>上回<rt>うわまわ</rt></ruby>る<br>\n              1997: Jumlah lansia melampaui jumlah anak-anak\n            </div>\n          </div>\n        </div>\n\n        <!-- Age classification -->\n        <div class=\"highlight-box hl-blue\" style=\"margin-top:14px;\">\n          <strong>日本の総人口 1億2380万人（令和6年）</strong><br>\n          <div class=\"badge-row\" style=\"margin-top:8px;\">\n            <div class=\"badge node-green\">\n              <span class=\"num\" style=\"color:#2d6a4f;\">11.2%</span>\n              <span>年少<br>0〜14歳</span>\n              <span class=\"lbl\">Anak-anak</span>\n            </div>\n            <div class=\"badge node-blue\">\n              <span class=\"num\" style=\"color:#1d3557;\">59.6%</span>\n              <span>生産年齢<br>15〜64歳</span>\n              <span class=\"lbl\">Usia Produktif</span>\n            </div>\n            <div class=\"badge node-orange\">\n              <span class=\"num\" style=\"color:#7a3010;\">29.3%</span>\n              <span>老年<br>65歳〜</span>\n              <span class=\"lbl\">Lansia</span>\n            </div>\n          </div>\n        </div>\n\n        <!-- Aging speed comparison -->\n        <div class=\"highlight-box hl-orange\" style=\"margin-top:14px;\">\n          <strong>⚡ 高齢化のスピード比較 ／ Kecepatan Penuaan</strong><br>\n          <span style=\"font-size:12px;\">（7%→14%に<ruby>達<rt>たっ</rt></ruby>するまでの<ruby>年数<rt>ねんすう</rt></ruby>）</span>\n          <div class=\"badge-row\" style=\"margin-top:8px;\">\n            <div class=\"badge node-red\"><span class=\"num\" style=\"color:#7a2010;\">18年</span><span>韓国</span><span class=\"lbl\">Korea</span></div>\n            <div class=\"badge node-red\"><span class=\"num\" style=\"color:#7a2010;\">24年</span><span>🇯🇵 日本</span><span class=\"lbl\">Jepang</span></div>\n            <div class=\"badge node-yellow\"><span class=\"num\" style=\"color:#7a5c00;\">72年</span><span>米国</span><span class=\"lbl\">Amerika</span></div>\n            <div class=\"badge node-green\"><span class=\"num\" style=\"color:#2d6a4f;\">115年</span><span>仏国</span><span class=\"lbl\">Prancis</span></div>\n          </div>\n          <div style=\"font-size:11px;margin-top:6px;opacity:0.75;\">→ Jepang & Korea menua jauh lebih cepat dibanding negara Barat</div>\n        </div>\n\n      </div>\n    </div>\n  </div>\n\n  <div class=\"arrow-down\">↓</div>\n\n  <!-- ======= SECTION 3 ======= -->\n  <div class=\"section theme-orange\" id=\"s3\">\n    <div class=\"section-header\" onclick=\"toggle('s3')\">\n      <div class=\"section-icon\">🌿</div>\n      <div class=\"section-title\">\n        <span class=\"jp\">ライフスタイルの<ruby>変化<rt>へんか</rt></ruby></span>\n        <span class=\"id\">Perubahan Gaya Hidup</span>\n      </div>\n      <span class=\"toggle-arrow\">▼</span>\n    </div>\n    <div class=\"section-body\">\n      <div class=\"section-inner\">\n\n        <div class=\"flow\">\n          <!-- Life Stage -->\n          <div class=\"node node-yellow\">\n            <div class=\"node-label\">ライフステージ ／ Life Stage</div>\n            <div class=\"node-main\"><ruby>人生<rt>じんせい</rt></ruby>の<ruby>発達段階<rt>はったつだんかい</rt></ruby></div>\n            <div class=\"node-sub\">Tahapan perkembangan kehidupan manusia</div>\n            <div class=\"node-id\">\n              <ruby>乳幼児<rt>にゅうようじ</rt></ruby>期 → <ruby>児童<rt>じどう</rt></ruby>期 → <ruby>青年<rt>せいねん</rt></ruby>期 → <ruby>成人<rt>せいじん</rt></ruby>期 → <ruby>老年<rt>ろうねん</rt></ruby>期<br>\n              Bayi → Anak → Remaja → Dewasa → Lansia\n            </div>\n          </div>\n          <div class=\"flow-connector\"></div>\n          <!-- Life Cycle -->\n          <div class=\"node node-orange\">\n            <div class=\"node-label\">ライフサイクル ／ Life Cycle</div>\n            <div class=\"node-main\">各<ruby>段階<rt>だんかい</rt></ruby>の<ruby>発達課題<rt>はったつかだい</rt></ruby>を<ruby>達成<rt>たっせい</rt></ruby>する<ruby>過程<rt>かてい</rt></ruby></div>\n            <div class=\"node-sub\">Proses mencapai tugas perkembangan di tiap tahap</div>\n          </div>\n          <div class=\"flow-connector\"></div>\n          <!-- Life Course -->\n          <div class=\"node node-green\">\n            <div class=\"node-label\">ライフコース ／ Life Course</div>\n            <div class=\"node-main\"><ruby>個人<rt>こじん</rt></ruby>を<ruby>中心<rt>ちゅうしん</rt></ruby>に<ruby>複数<rt>ふくすう</rt></ruby>のコースを<ruby>選択<rt>せんたく</rt></ruby></div>\n            <div class=\"node-sub\">Individu memilih jalur hidup sendiri, bukan sekadar mengikuti tahapan umum</div>\n          </div>\n        </div>\n\n        <!-- Social Role -->\n        <div class=\"highlight-box hl-orange\" style=\"margin-top:16px;\">\n          <strong><ruby>社会的役割<rt>しゃかいてきやくわり</rt></ruby> ／ Peran Sosial</strong>\n        </div>\n        <div class=\"family-grid\" style=\"margin-top:8px;\">\n          <div class=\"node node-blue\" style=\"font-size:12px;\">\n            <strong><ruby>役割取得<rt>やくわりしゅとく</rt></ruby></strong><br>\n            <span style=\"opacity:0.75;\">Perolehan Peran</span><br>\n            他者の役割を認識して自我を形成<br>\n            <span style=\"opacity:0.65;font-size:11px;\">Mengenali peran orang lain → membentuk diri sendiri</span>\n          </div>\n          <div class=\"node node-teal\" style=\"font-size:12px;\">\n            <strong><ruby>役割形成<rt>やくわりけいせい</rt></ruby></strong><br>\n            <span style=\"opacity:0.75;\">Pembentukan Peran</span><br>\n            既存の枠を超えて新しい行動を展開<br>\n            <span style=\"opacity:0.65;font-size:11px;\">Melampaui batasan peran yang ada</span>\n          </div>\n          <div class=\"node node-purple\" style=\"font-size:12px;\">\n            <strong><ruby>役割葛藤<rt>やくわりかっとう</rt></ruby></strong><br>\n            <span style=\"opacity:0.75;\">Konflik Peran</span><br>\n            複数の役割間で矛盾・対立が生じる<br>\n            <span style=\"opacity:0.65;font-size:11px;\">Tekanan dari peran yang saling bertentangan</span>\n          </div>\n          <div class=\"node node-gray\" style=\"font-size:12px;\">\n            <strong><ruby>役割距離<rt>やくわりきょり</rt></ruby></strong><br>\n            <span style=\"opacity:0.75;\">Jarak Peran</span><br>\n            期待される役割からずれた行動<br>\n            <span style=\"opacity:0.65;font-size:11px;\">Tindakan menyimpang dari peran yang diharapkan</span>\n          </div>\n        </div>\n\n        <!-- Seikatsu Ryoiki -->\n        <div class=\"highlight-box hl-green\" style=\"margin-top:14px;\">\n          <strong><ruby>生活領域<rt>せいかつりょういき</rt></ruby> ／ Area Kehidupan</strong>\n          <div class=\"badge-row\" style=\"margin-top:8px;\">\n            <div class=\"badge node-green\">\n              <span>🍚</span>\n              <span><ruby>基礎生活<rt>きそせいかつ</rt></ruby></span>\n              <span class=\"lbl\">Kehidupan Dasar<br>(makan, tidur)</span>\n            </div>\n            <div class=\"badge node-blue\">\n              <span>💼</span>\n              <span><ruby>社会生活<rt>しゃかいせいかつ</rt></ruby></span>\n              <span class=\"lbl\">Kehidupan Sosial<br>(kerja, sekolah)</span>\n            </div>\n            <div class=\"badge node-yellow\">\n              <span>🎨</span>\n              <span><ruby>余暇生活<rt>よかせいかつ</rt></ruby></span>\n              <span class=\"lbl\">Waktu Luang<br>(hobi)</span>\n            </div>\n          </div>\n        </div>\n\n      </div>\n    </div>\n  </div>\n\n  <div class=\"arrow-down\">↓</div>\n\n  <!-- ======= SECTION 4 ======= -->\n  <div class=\"section theme-purple\" id=\"s4\">\n    <div class=\"section-header\" onclick=\"toggle('s4')\">\n      <div class=\"section-icon\">⚖️</div>\n      <div class=\"section-title\">\n        <span class=\"jp\">ジェンダーと<ruby>労働<rt>ろうどう</rt></ruby></span>\n        <span class=\"id\">Gender & Ketenagakerjaan</span>\n      </div>\n      <span class=\"toggle-arrow\">▼</span>\n    </div>\n    <div class=\"section-body\">\n      <div class=\"section-inner\">\n\n        <div class=\"flow\">\n          <div class=\"node node-purple\">\n            <div class=\"node-label\">ジェンダー ／ Gender</div>\n            <div class=\"node-main\"><ruby>社会的<rt>しゃかいてき</rt></ruby>・<ruby>文化的<rt>ぶんかてき</rt></ruby>な<ruby>性別役割<rt>せいべつやくわり</rt></ruby></div>\n            <div class=\"node-sub\">Peran gender yang dibentuk oleh masyarakat & budaya (bukan biologi)</div>\n          </div>\n          <div class=\"flow-connector\"></div>\n          <div class=\"node node-orange\">\n            <div class=\"node-label\">ジェンダー・バイアス ／ Gender Bias</div>\n            <div class=\"node-main\"><ruby>固定的<rt>こていてき</rt></ruby>な<ruby>観念<rt>かんねん</rt></ruby></div>\n            <div class=\"node-sub\">Prasangka/stereotip gender yang sudah mengakar di masyarakat</div>\n            <div class=\"node-id\">例：女性が働くのは標準外→ Contoh: anggapan wanita tidak perlu bekerja</div>\n          </div>\n          <div class=\"flow-connector\"></div>\n          <div class=\"node node-red\">\n            <div class=\"node-label\">ジェンダー・ギャップ ／ Gender Gap</div>\n            <div class=\"node-main\">🇯🇵 日本は146か国中 <strong>118位</strong>（2024年）</div>\n            <div class=\"node-sub\">Jepang peringkat 118 dari 146 negara dalam kesetaraan gender</div>\n            <div class=\"node-id\">スコア 0.663（0＝完全不平等、1＝完全平等）<br>0 = ketimpangan penuh, 1 = kesetaraan penuh</div>\n          </div>\n        </div>\n\n        <div class=\"highlight-box hl-purple\" style=\"margin-top:14px;\">\n          <strong>女性の<ruby>労働力率<rt>ろうどうりょくりつ</rt></ruby>「Mカーブ」</strong><br>\n          <span style=\"font-size:12px;\">Tingkat partisipasi kerja wanita membentuk pola \"M-curve\"</span><br><br>\n          <span style=\"font-size:12px;\">\n            ① 就職 → ② <ruby>結婚<rt>けっこん</rt></ruby>・<ruby>出産<rt>しゅっさん</rt></ruby>で<strong>低下</strong> → ③ <ruby>育児<rt>いくじ</rt></ruby>後に<strong>回復</strong><br>\n            Bekerja → Menurun saat menikah/melahirkan → Naik lagi setelah anak besar\n          </span>\n        </div>\n\n        <div class=\"highlight-box hl-blue\" style=\"margin-top:10px;\">\n          <strong>ワーク・ライフ・バランス</strong><br>\n          <span style=\"font-size:12px;\">仕事と生活の調和を目指す ／ Keseimbangan antara pekerjaan & kehidupan pribadi</span>\n        </div>\n\n      </div>\n    </div>\n  </div>\n\n  <div class=\"arrow-down\">↓</div>\n\n  <!-- ======= SECTION 5 ======= -->\n  <div class=\"section theme-red\" id=\"s5\">\n    <div class=\"section-header\" onclick=\"toggle('s5')\">\n      <div class=\"section-icon\">👨‍👩‍👧</div>\n      <div class=\"section-title\">\n        <span class=\"jp\"><ruby>家族<rt>かぞく</rt></ruby>と<ruby>親族<rt>しんぞく</rt></ruby></span>\n        <span class=\"id\">Keluarga & Kekerabatan</span>\n      </div>\n      <span class=\"toggle-arrow\">▼</span>\n    </div>\n    <div class=\"section-body\">\n      <div class=\"section-inner\">\n\n        <!-- 親族 legal def -->\n        <div class=\"node node-red\" style=\"margin-bottom:10px;\">\n          <div class=\"node-label\"><ruby>民法<rt>みんぽう</rt></ruby>上の<ruby>親族<rt>しんぞく</rt></ruby> ／ Kerabat Menurut Hukum Perdata</div>\n          <div class=\"node-main\">① 6親等以内の<ruby>血族<rt>けつぞく</rt></ruby>　② <ruby>配偶者<rt>はいぐうしゃ</rt></ruby>　③ 3親等以内の<ruby>姻族<rt>いんぞく</rt></ruby></div>\n          <div class=\"node-sub\">① Kerabat darah s.d. tingkat ke-6 ② Pasangan ③ Kerabat pernikahan s.d. tingkat ke-3</div>\n        </div>\n\n        <div class=\"highlight-box hl-orange\" style=\"margin-bottom:12px;\">\n          <strong><ruby>扶養義務<rt>ふようぎむ</rt></ruby> ／ Kewajiban Nafkah</strong><br>\n          <span style=\"font-size:12px;\">直系血族・兄弟姉妹 → 互いに扶養する義務あり<br>Kerabat langsung & saudara kandung wajib saling menafkahi</span>\n        </div>\n\n        <!-- 家族の形態 -->\n        <div class=\"highlight-box hl-green\">\n          <strong><ruby>家族<rt>かぞく</rt></ruby>の<ruby>形態<rt>けいたい</rt></ruby> ／ Bentuk-Bentuk Keluarga</strong>\n        </div>\n        <div class=\"family-grid\" style=\"margin-top:8px;\">\n          <div class=\"node node-blue\" style=\"font-size:12px;\">\n            <strong>DINKs（ディンクス）</strong><br>\n            Double Income No Kids<br>\n            <span style=\"opacity:0.7;\">Pasangan kerja, tidak punya anak</span>\n          </div>\n          <div class=\"node node-green\" style=\"font-size:12px;\">\n            <strong>DEWKs（デュークス）</strong><br>\n            Double Employed With Kids<br>\n            <span style=\"opacity:0.7;\">Pasangan kerja, punya anak</span>\n          </div>\n          <div class=\"node node-orange\" style=\"font-size:12px;\">\n            <strong>ステップファミリー</strong><br>\n            Step Family<br>\n            <span style=\"opacity:0.7;\">Keluarga dengan anak dari pernikahan sebelumnya</span>\n          </div>\n          <div class=\"node node-purple\" style=\"font-size:12px;\">\n            <strong>ネットワークファミリー</strong><br>\n            Network Family<br>\n            <span style=\"opacity:0.7;\">Keluarga pilihan, tak terikat darah/pernikahan</span>\n          </div>\n        </div>\n\n        <div class=\"highlight-box hl-blue\" style=\"margin-top:12px;\">\n          <strong><ruby>核家族世帯<rt>かくかぞくせたい</rt></ruby> ／ Rumah Tangga Inti</strong><br>\n          <span style=\"font-size:12px;\">\n            ①<ruby>夫婦<rt>ふうふ</rt></ruby>のみ　②<ruby>夫婦<rt>ふうふ</rt></ruby>と<ruby>未婚<rt>みこん</rt></ruby>の<ruby>子<rt>こ</rt></ruby>のみ　③ひとり<ruby>親<rt>おや</rt></ruby>と<ruby>未婚<rt>みこん</rt></ruby>の<ruby>子<rt>こ</rt></ruby>のみ<br>\n            ① Hanya suami-istri ② Suami-istri + anak belum menikah ③ Orang tua tunggal + anak\n          </span>\n        </div>\n\n      </div>\n    </div>\n  </div>\n\n  <div class=\"arrow-down\">↓</div>\n\n  <!-- ======= SECTION 6 ======= -->\n  <div class=\"section theme-teal\" id=\"s6\">\n    <div class=\"section-header\" onclick=\"toggle('s6')\">\n      <div class=\"section-icon\">🏠</div>\n      <div class=\"section-title\">\n        <span class=\"jp\"><ruby>世帯<rt>せたい</rt></ruby>の<ruby>変化<rt>へんか</rt></ruby></span>\n        <span class=\"id\">Perubahan Komposisi Rumah Tangga</span>\n      </div>\n      <span class=\"toggle-arrow\">▼</span>\n    </div>\n    <div class=\"section-body\">\n      <div class=\"section-inner\">\n\n        <div class=\"flow\">\n          <div class=\"node node-teal\">\n            <div class=\"node-label\">全体の傾向 ／ Tren Keseluruhan</div>\n            <div class=\"node-main\"><ruby>平均世帯人員<rt>へいきんせたいじんいん</rt></ruby>が<ruby>減少<rt>げんしょう</rt></ruby>、<ruby>単独世帯<rt>たんどくせたい</rt></ruby>が<ruby>増加<rt>ぞうか</rt></ruby></div>\n            <div class=\"node-sub\">Rata-rata anggota rumah tangga menurun, rumah tangga individu meningkat</div>\n            <div class=\"node-id\">3.22人（1986年）→ 2.23人（2023年）<br>Dari 3.22 → 2.23 orang per rumah tangga</div>\n          </div>\n          <div class=\"flow-connector\"></div>\n          <div class=\"node node-orange\">\n            <div class=\"node-label\">高齢者世帯の変化 ／ Rumah Tangga Lansia</div>\n            <div class=\"node-main\">65歳<ruby>以上<rt>いじょう</rt></ruby>のいる<ruby>世帯<rt>せたい</rt></ruby>が<strong>49.5%</strong>（2023年）</div>\n            <div class=\"node-sub\">Hampir separuh rumah tangga memiliki anggota berusia 65+</div>\n            <div class=\"node-id\">26.0%（1986）→ 49.5%（2023）</div>\n          </div>\n        </div>\n\n        <!-- Composition breakdown -->\n        <div class=\"highlight-box hl-blue\" style=\"margin-top:14px;\">\n          <strong><ruby>世帯構造<rt>せたいこうぞう</rt></ruby>（2023）／ Struktur Rumah Tangga</strong>\n          <div class=\"badge-row\" style=\"margin-top:8px;\">\n            <div class=\"badge node-gray\">\n              <span class=\"num\">34.0%</span>\n              <span><ruby>単独<rt>たんどく</rt></ruby></span>\n              <span class=\"lbl\">Tinggal Sendiri</span>\n            </div>\n            <div class=\"badge node-blue\">\n              <span class=\"num\">24.6%</span>\n              <span><ruby>夫婦<rt>ふうふ</rt></ruby>のみ</span>\n              <span class=\"lbl\">Suami-Istri Saja</span>\n            </div>\n            <div class=\"badge node-green\">\n              <span class=\"num\">24.8%</span>\n              <span><ruby>夫婦<rt>ふうふ</rt></ruby>+子</span>\n              <span class=\"lbl\">Kel. Inti</span>\n            </div>\n          </div>\n        </div>\n\n        <div class=\"highlight-box hl-orange\" style=\"margin-top:10px;\">\n          <strong>💡 ポイント ／ Poin Penting</strong><br>\n          <span style=\"font-size:12px;\">\n            高齢者のみの世帯が60%を超える傾向（2023）<br>\n            → Lebih dari 60% rumah tangga lansia hanya dihuni lansia saja<br>\n            （<ruby>単独<rt>たんどく</rt></ruby>51.6% ＋ <ruby>夫婦<rt>ふうふ</rt></ruby>のみ44.1%）\n          </span>\n        </div>\n\n      </div>\n    </div>\n  </div>\n\n  <!-- Footer note -->\n  <div style=\"text-align:center; margin-top:30px; font-size:11px; color:#40916c; opacity:0.7;\">\n    出典：厚生労働省「人口動態調査」・総務省「人口推計」（令和5〜6年）<br>\n    Sumber: Kementerian Kesehatan & Biro Statistik Jepang\n  </div>\n\n</main>\n\n<script>\n  function toggle(id) {\n    const el = document.getElementById(id);\n    el.classList.toggle('open');\n  }\n<\/script>\n</body>\n</html>\n","shakai-2":"<!DOCTYPE html>\n<html lang=\"ja\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>第1章・第2節 — 地域社会・行政組織</title>\n<link href=\"https://fonts.googleapis.com/css2?family=Noto+Sans+JP:wght@300;400;500;700;900&family=Noto+Serif+JP:wght@400;700&display=swap\" rel=\"stylesheet\">\n<style>\n  :root {\n    --green-dark: #1b4332;\n    --green-mid: #2d6a4f;\n    --green-light: #52b788;\n    --green-pale: #d8f3dc;\n    --blue-dark: #1d3557;\n    --blue: #457b9d;\n    --blue-light: #a8dadc;\n    --orange: #e76f51;\n    --yellow: #f4a261;\n    --purple: #6d597a;\n    --teal: #2a9d8f;\n    --red: #c1121f;\n    --gray: #f8f9fa;\n    --text: #1b1b2f;\n  }\n  * { margin:0; padding:0; box-sizing:border-box; }\n  body {\n    font-family: 'Noto Sans JP', sans-serif;\n    background: #eef4f0;\n    color: var(--text);\n    min-height: 100vh;\n  }\n  /* HEADER */\n  header {\n    background: linear-gradient(135deg, #1b4332 0%, #2d6a4f 55%, #52b788 100%);\n    padding: 34px 20px 26px;\n    text-align: center;\n    position: relative;\n    overflow: hidden;\n  }\n  header::before {\n    content:''; position:absolute; top:-50px; right:-50px;\n    width:200px; height:200px; border-radius:50%;\n    background:rgba(255,255,255,0.05);\n  }\n  .hbadge {\n    display:inline-block;\n    background:rgba(255,255,255,0.15);\n    border:1px solid rgba(255,255,255,0.3);\n    color:#fff; font-size:11px; letter-spacing:2px;\n    padding:4px 14px; border-radius:20px; margin-bottom:10px;\n  }\n  header h1 {\n    font-family:'Noto Serif JP',serif;\n    color:#fff;\n    font-size:clamp(18px,5vw,30px);\n    font-weight:700; line-height:1.45; margin-bottom:6px;\n  }\n  header p { color:rgba(255,255,255,0.75); font-size:12px; }\n\n  /* MAIN */\n  main { max-width:820px; margin:0 auto; padding:26px 14px 60px; }\n\n  .intro-label {\n    text-align:center; font-size:12px; color:#2d6a4f;\n    margin-bottom:16px; letter-spacing:1px; font-weight:700;\n  }\n\n  /* SECTION */\n  .section { margin-bottom:20px; animation: fadeUp 0.5s ease both; }\n  .section:nth-child(1){animation-delay:.05s}\n  .section:nth-child(2){animation-delay:.10s}\n  .section:nth-child(3){animation-delay:.15s}\n  .section:nth-child(4){animation-delay:.20s}\n  .section:nth-child(5){animation-delay:.25s}\n  .section:nth-child(6){animation-delay:.30s}\n  @keyframes fadeUp {\n    from{opacity:0;transform:translateY(16px)}\n    to{opacity:1;transform:translateY(0)}\n  }\n\n  .sec-head {\n    display:flex; align-items:center; gap:12px;\n    padding:13px 16px; border-radius:13px 13px 0 0;\n    cursor:pointer; user-select:none; transition:filter .2s;\n  }\n  .sec-head:hover{filter:brightness(1.07)}\n  .sec-icon {\n    width:36px;height:36px;border-radius:50%;\n    background:rgba(255,255,255,0.2);\n    display:flex;align-items:center;justify-content:center;\n    font-size:17px;flex-shrink:0;\n  }\n  .sec-title .jp { font-size:16px;font-weight:700;color:#fff;display:block; }\n  .sec-title .id { font-size:11px;color:rgba(255,255,255,0.73);display:block;margin-top:1px; }\n  .toggle-arr { color:rgba(255,255,255,0.8);font-size:13px;margin-left:auto;transition:transform .3s; }\n  .section.open .toggle-arr { transform:rotate(180deg); }\n\n  .sec-body {\n    background:#fff; border-radius:0 0 13px 13px;\n    border:1px solid #d4e8dc; border-top:none;\n    overflow:hidden; max-height:0; transition:max-height .45s ease;\n  }\n  .section.open .sec-body { max-height:5000px; }\n  .sec-inner { padding:18px 16px 22px; }\n\n  /* THEME COLORS */\n  .th-green .sec-head  { background:linear-gradient(90deg,#1b4332,#2d6a4f); }\n  .th-blue  .sec-head  { background:linear-gradient(90deg,#1d3557,#457b9d); }\n  .th-orange.sec-head  { background:linear-gradient(90deg,#9e3f25,#e76f51); }\n  .th-orange .sec-head { background:linear-gradient(90deg,#9e3f25,#e76f51); }\n  .th-purple .sec-head { background:linear-gradient(90deg,#3d2b4f,#6d597a); }\n  .th-teal  .sec-head  { background:linear-gradient(90deg,#155f58,#2a9d8f); }\n  .th-red   .sec-head  { background:linear-gradient(90deg,#7a0c13,#c1121f); }\n\n  /* NODES */\n  .node {\n    border-radius:10px; padding:10px 13px; margin-bottom:8px;\n    position:relative;\n  }\n  .node-lbl { font-size:10px;font-weight:700;letter-spacing:1px;opacity:.6;margin-bottom:4px;text-transform:uppercase; }\n  .node-main { font-size:14px;font-weight:700;line-height:1.45; }\n  .node-sub  { font-size:11.5px;margin-top:4px;line-height:1.55;opacity:.82; }\n  .node-id   { font-size:11px;margin-top:5px;padding-top:5px;border-top:1px dashed currentColor;opacity:.6;font-style:italic; }\n\n  .n-green  { background:#d8f3dc; color:#1b4332; }\n  .n-blue   { background:#dce9f7; color:#1d3557; }\n  .n-yellow { background:#fff3cd; color:#7a5000; }\n  .n-orange { background:#fde4d8; color:#7a2a10; }\n  .n-red    { background:#fce0e2; color:#7a0c13; }\n  .n-purple { background:#ece5f5; color:#3d2060; }\n  .n-teal   { background:#d5f5f2; color:#0d4a44; }\n  .n-gray   { background:#f3f4f6; color:#374151; }\n\n  /* FLOW connector */\n  .flow-conn { height:14px; display:flex; justify-content:flex-start; padding-left:24px; margin-bottom:0; }\n  .flow-conn::before { content:''; width:2px; background:#b7d5c8; display:block; }\n\n  /* HIGHLIGHT BOX */\n  .hl {\n    border-left:4px solid; padding:10px 13px;\n    border-radius:0 10px 10px 0; margin-top:10px; margin-bottom:10px;\n    font-size:13px; line-height:1.6;\n  }\n  .hl-green  { border-color:#2d6a4f; background:#f0faf5; color:#1b4332; }\n  .hl-blue   { border-color:#457b9d; background:#eef5fc; color:#1d3557; }\n  .hl-orange { border-color:#e76f51; background:#fef5f2; color:#7a2a10; }\n  .hl-purple { border-color:#6d597a; background:#f5f0fb; color:#3d2060; }\n  .hl-teal   { border-color:#2a9d8f; background:#f0fbfa; color:#0d4a44; }\n  .hl-red    { border-color:#c1121f; background:#fef0f1; color:#7a0c13; }\n\n  /* GRID */\n  .grid2 { display:grid; grid-template-columns:1fr 1fr; gap:8px; margin-top:8px; }\n  .grid3 { display:grid; grid-template-columns:repeat(3,1fr); gap:8px; margin-top:8px; }\n  @media(max-width:500px){\n    .grid2,.grid3{grid-template-columns:1fr;}\n  }\n\n  /* BADGE */\n  .badge-row { display:flex; flex-wrap:wrap; gap:8px; margin-top:10px; }\n  .badge {\n    display:inline-flex;flex-direction:column;align-items:center;\n    padding:8px 10px;border-radius:10px;font-size:11px;font-weight:700;\n    min-width:72px;text-align:center;\n  }\n  .badge .num { font-size:18px;font-weight:900;line-height:1.1; }\n  .badge .lbl { font-size:10px;opacity:.7;margin-top:2px; }\n\n  /* TABLE */\n  .tbl { width:100%;border-collapse:collapse;font-size:12.5px;margin-top:10px; }\n  .tbl th { padding:7px 9px;text-align:left;font-size:11px;font-weight:700;letter-spacing:.4px; }\n  .tbl td { padding:7px 9px;border-bottom:1px solid #f0f0f0;vertical-align:top; }\n  .tbl tr:last-child td { border-bottom:none; }\n\n  /* PERIOD TAG */\n  .period {\n    display:inline-block;padding:2px 8px;border-radius:20px;\n    font-size:11px;font-weight:700;margin-left:6px;\n    background:#fff3cd;color:#7a5000;\n  }\n  .period.red { background:#fce0e2;color:#7a0c13; }\n  .period.blue { background:#dce9f7;color:#1d3557; }\n\n  /* ARROW */\n  .arrow-down { text-align:center;font-size:20px;color:#a0c4b0;margin:6px 0; }\n\n  /* FURIGANA */\n  ruby rt { font-size:9px;color:#2d6a4f;line-height:1; }\n\n  /* ORG CHART mini */\n  .org {\n    display:flex;flex-direction:column;gap:0;margin-top:12px;\n  }\n  .org-row {\n    display:flex;gap:6px;flex-wrap:wrap;justify-content:center;\n    margin-bottom:4px;\n  }\n  .org-box {\n    border-radius:8px;padding:7px 10px;font-size:12px;font-weight:700;\n    text-align:center;min-width:90px;\n  }\n  .org-line {\n    display:flex;justify-content:center;\n    margin:0 0 4px;\n  }\n  .org-line::before {\n    content:'';width:2px;height:16px;background:#b7d5c8;display:block;\n  }\n\n  /* SPECIALIST CARD */\n  .spec-card {\n    border-radius:10px;padding:12px;margin-bottom:10px;\n    border:1px solid #e2ede9;\n  }\n  .spec-title {\n    font-size:14px;font-weight:700;margin-bottom:6px;\n    display:flex;align-items:center;gap:8px;\n  }\n  .spec-tag {\n    font-size:10px;padding:2px 8px;border-radius:20px;\n    background:#d8f3dc;color:#1b4332;font-weight:700;\n  }\n  .spec-duties { margin-top:8px; }\n  .duty-item {\n    display:flex;gap:8px;align-items:flex-start;\n    font-size:12px;margin-bottom:5px;line-height:1.5;\n  }\n  .duty-num {\n    display:inline-flex;align-items:center;justify-content:center;\n    width:18px;height:18px;border-radius:50%;\n    background:#2d6a4f;color:#fff;font-size:10px;font-weight:700;flex-shrink:0;\n  }\n  .staff-list {\n    font-size:11px;color:#2d6a4f;margin-top:6px;padding:6px 10px;\n    background:#f0faf5;border-radius:7px;\n  }\n</style>\n<style id=\"pk-fix\">\n.sec-body{max-height:none!important;overflow:visible!important;display:none;transition:none!important}\n.section.open .sec-body{display:block}\n.section{animation:none!important;opacity:1!important;transform:none!important}\n*{min-width:0}\nbody{overflow-x:hidden;-webkit-text-size-adjust:100%}\nmain{padding-left:10px!important;padding-right:10px!important}\np,div,span,td,th,li{overflow-wrap:anywhere;word-break:normal}\nimg,svg,video{max-width:100%;height:auto}\ntable{display:block;max-width:100%;overflow-x:auto;-webkit-overflow-scrolling:touch;border-collapse:collapse}\n@media (max-width:560px){\n [class*=\"grid\"],[class*=\"cols\"],[class*=\"compare\"],[class*=\"pair\"],[class*=\"two\"],[class*=\"stats\"]{grid-template-columns:1fr 1fr!important}\n [class*=\"grid3\"],[class*=\"grid-3\"],[class*=\"three\"]{grid-template-columns:1fr!important}\n [class*=\"row\"],[class*=\"flex\"],[class*=\"flow\"],[class*=\"chain\"]{flex-wrap:wrap!important}\n [class*=\"compare\"] > *,[class*=\"pair\"] > *{min-width:0}\n}\n</style>\n<script>\n(function(){\n function post(){try{parent.postMessage({pkH:Math.ceil(document.documentElement.scrollHeight)},'*');}catch(e){}}\n document.addEventListener('DOMContentLoaded',function(){\n  document.querySelectorAll('.section').forEach(function(s,i){ if(i===0) s.classList.add('open'); });\n  post();\n  if(window.ResizeObserver) new ResizeObserver(post).observe(document.body);\n  document.addEventListener('click',function(){setTimeout(post,30);setTimeout(post,400);});\n });\n window.addEventListener('load',post);\n})();\n<\/script></head>\n<body>\n\n<header>\n  <div class=\"hbadge\">第1章・第2節 — まとめ</div>\n  <h1><ruby>地域社会<rt>ちいきしゃかい</rt></ruby>・<ruby>行政組織<rt>ぎょうせいそしき</rt></ruby><br>\n    <span style=\"font-size:.62em;font-weight:400;\">Masyarakat Lokal & Organisasi Pemerintahan</span>\n  </h1>\n  <p>タップして各テーマを開く ／ Ketuk untuk membuka setiap topik</p>\n</header>\n\n<main>\n  <div class=\"intro-label\">▼ 順番に読もう ／ Baca Secara Berurutan ▼</div>\n\n  <!-- ===== SECTION 1: 地域福祉の歴史 ===== -->\n  <div class=\"section th-green open\" id=\"s1\">\n    <div class=\"sec-head\" onclick=\"toggle('s1')\">\n      <div class=\"sec-icon\">📜</div>\n      <div class=\"sec-title\">\n        <span class=\"jp\"><ruby>地域福祉<rt>ちいきふくし</rt></ruby>の<ruby>歴史的展開<rt>れきしてきてんかい</rt></ruby></span>\n        <span class=\"id\">Sejarah Perkembangan Kesejahteraan Lokal</span>\n      </div>\n      <span class=\"toggle-arr\">▼</span>\n    </div>\n    <div class=\"sec-body\"><div class=\"sec-inner\">\n\n      <!-- Timeline flow -->\n      <div class=\"node n-blue\" style=\"margin-bottom:8px;\">\n        <div class=\"node-lbl\">COS — <ruby>慈善組織協会<rt>じぜんそしききょうかい</rt></ruby> ／ Charity Organisation Society</div>\n        <div class=\"node-main\">🇬🇧 1869年 イギリスで<ruby>設立<rt>せつりつ</rt></ruby></div>\n        <div class=\"node-sub\">各救済団体を組織化し、活動を連絡調整。<br>\n          <span style=\"opacity:.7;\">Mengorganisasi lembaga bantuan & mengoordinasikan kegiatan sosial</span></div>\n        <div class=\"node-id\">\n          <ruby>友愛訪問員<rt>ゆうあいほうもんいん</rt></ruby>が要救護者を訪問し生活相談・救済活動を実施<br>\n          <span style=\"font-style:normal;opacity:.8;\">Petugas kunjungan ramah mengunjungi orang yang membutuhkan bantuan</span>\n        </div>\n      </div>\n\n      <div class=\"flow-conn\"></div>\n\n      <div class=\"node n-green\">\n        <div class=\"node-lbl\">セツルメント<ruby>運動<rt>うんどう</rt></ruby> ／ Settlement Movement</div>\n        <div class=\"node-main\"><ruby>貧困地域<rt>ひんこんちいき</rt></ruby>（スラム）への住み込み支援活動</div>\n        <div class=\"node-sub\">知識・<ruby>教養<rt>きょうよう</rt></ruby>のある人が住み込んで実態調査・教育・生活支援を行う<br>\n          <span style=\"opacity:.7;\">Orang berpendidikan tinggal di kawasan miskin untuk melakukan riset & memberi dukungan</span>\n        </div>\n      </div>\n\n      <div class=\"grid2\" style=\"margin-top:10px;\">\n        <div class=\"node n-yellow\" style=\"margin-bottom:0;\">\n          <div class=\"node-lbl\">🏛 トインビーホール</div>\n          <div class=\"node-main\">1884年 イギリス</div>\n          <div class=\"node-sub\"><ruby>バーネット夫妻<rt>ふさい</rt></ruby>が設立<br>世界初のセツルメント<br><span style=\"opacity:.7;\">Settlement pertama di dunia</span></div>\n        </div>\n        <div class=\"node n-orange\" style=\"margin-bottom:0;\">\n          <div class=\"node-lbl\">🏛 ハルハウス</div>\n          <div class=\"node-main\">1889年 アメリカ</div>\n          <div class=\"node-sub\">アダムス（J.）がシカゴで開設<br><span style=\"opacity:.7;\">Didirikan Adams di Chicago</span></div>\n        </div>\n      </div>\n\n    </div></div>\n  </div>\n\n  <div class=\"arrow-down\">↓</div>\n\n  <!-- ===== SECTION 2: コミュニティ ===== -->\n  <div class=\"section th-blue\" id=\"s2\">\n    <div class=\"sec-head\" onclick=\"toggle('s2')\">\n      <div class=\"sec-icon\">🌐</div>\n      <div class=\"sec-title\">\n        <span class=\"jp\">コミュニティの<ruby>概念<rt>がいねん</rt></ruby></span>\n        <span class=\"id\">Konsep Komunitas</span>\n      </div>\n      <span class=\"toggle-arr\">▼</span>\n    </div>\n    <div class=\"sec-body\"><div class=\"sec-inner\">\n\n      <!-- Tönnies -->\n      <div class=\"hl hl-blue\">\n        <strong>テンニース（Tönnies, F.）</strong>\n      </div>\n      <div class=\"grid2\">\n        <div class=\"node n-green\">\n          <div class=\"node-lbl\">ゲマインシャフト</div>\n          <div class=\"node-main\"><ruby>共同社会<rt>きょうどうしゃかい</rt></ruby></div>\n          <div class=\"node-sub\"><ruby>本質意志<rt>ほんしついし</rt></ruby>によって結ばれた<strong><ruby>自然的集団<rt>しぜんてきしゅうだん</rt></ruby></strong><br>\n            <span style=\"opacity:.7;\">Kelompok alami berdasarkan ikatan batin</span><br>\n            例）<ruby>家族<rt>かぞく</rt></ruby>、<ruby>村落<rt>そんらく</rt></ruby>\n          </div>\n        </div>\n        <div class=\"node n-orange\">\n          <div class=\"node-lbl\">ゲゼルシャフト</div>\n          <div class=\"node-main\"><ruby>利益社会<rt>りえきしゃかい</rt></ruby></div>\n          <div class=\"node-sub\"><ruby>選択意志<rt>せんたくいし</rt></ruby>によって結ばれた<strong><ruby>人為的集団<rt>じんいてきしゅうだん</rt></ruby></strong><br>\n            <span style=\"opacity:.7;\">Kelompok buatan berdasarkan pilihan & kepentingan</span><br>\n            例）<ruby>大都市<rt>だいとし</rt></ruby>、<ruby>国民社会<rt>こくみんしゃかい</rt></ruby>\n          </div>\n        </div>\n      </div>\n\n      <!-- MacIver -->\n      <div class=\"hl hl-blue\" style=\"margin-top:14px;\">\n        <strong>マッキーヴァー（MacIver, R. M.）</strong>\n      </div>\n      <div class=\"grid2\">\n        <div class=\"node n-teal\">\n          <div class=\"node-lbl\">コミュニティ ／ Community</div>\n          <div class=\"node-main\"><ruby>共同生活<rt>きょうどうせいかつ</rt></ruby>の<ruby>基礎<rt>きそ</rt></ruby></div>\n          <div class=\"node-sub\"><ruby>近隣集団<rt>きんりんしゅうだん</rt></ruby>・<ruby>村落<rt>そんらく</rt></ruby>・<ruby>都市<rt>とし</rt></ruby>など<br>\n            <ruby>地域性<rt>ちいきせい</rt></ruby>・<ruby>共同生活<rt>きょうどうせいかつ</rt></ruby>・<ruby>共属感情<rt>きょうぞくかんじょう</rt></ruby>を満たす集団<br>\n            <span style=\"opacity:.7;\">Kelompok yang memenuhi unsur wilayah, kehidupan bersama & rasa kebersamaan</span>\n          </div>\n        </div>\n        <div class=\"node n-purple\">\n          <div class=\"node-lbl\">アソシエーション ／ Association</div>\n          <div class=\"node-main\"><ruby>人為的集団<rt>じんいてきしゅうだん</rt></ruby></div>\n          <div class=\"node-sub\"><ruby>特定<rt>とくてい</rt></ruby>の<ruby>関心<rt>かんしん</rt></ruby>や<ruby>目的<rt>もくてき</rt></ruby>のためにつくられた集団<br>\n            コミュニティの<ruby>生活課題<rt>せいかつかだい</rt></ruby>を<ruby>分担<rt>ぶんたん</rt></ruby>する機関<br>\n            例）<ruby>家族<rt>かぞく</rt></ruby>、<ruby>教会<rt>きょうかい</rt></ruby><br>\n            <span style=\"opacity:.7;\">Organisasi dibentuk untuk tujuan/minat tertentu</span>\n          </div>\n        </div>\n      </div>\n\n    </div></div>\n  </div>\n\n  <div class=\"arrow-down\">↓</div>\n\n  <!-- ===== SECTION 3: 都市化と過疎地域 ===== -->\n  <div class=\"section th-orange\" id=\"s3\">\n    <div class=\"sec-head\" onclick=\"toggle('s3')\">\n      <div class=\"sec-icon\">🏙️</div>\n      <div class=\"sec-title\">\n        <span class=\"jp\"><ruby>都市化<rt>としか</rt></ruby>と<ruby>過疎地域<rt>かそちいき</rt></ruby></span>\n        <span class=\"id\">Urbanisasi & Daerah Berpenduduk Jarang</span>\n      </div>\n      <span class=\"toggle-arr\">▼</span>\n    </div>\n    <div class=\"sec-body\"><div class=\"sec-inner\">\n\n      <div class=\"node n-orange\">\n        <div class=\"node-lbl\"><ruby>都市化<rt>としか</rt></ruby> ／ Urbanisasi</div>\n        <div class=\"node-main\"><ruby>都市的<rt>としてき</rt></ruby>な<ruby>生活様式<rt>せいかつようしき</rt></ruby>が<ruby>浸透<rt>しんとう</rt></ruby>していくこと</div>\n        <div class=\"node-sub\">Penyebaran gaya hidup perkotaan ke seluruh wilayah</div>\n        <div class=\"node-id\">\n          特徴：<ruby>交通渋滞<rt>こうつうじゅうたい</rt></ruby>・コンクリートの環境・<ruby>競争社会<rt>きょうそうしゃかい</rt></ruby>のストレス・<ruby>犯罪<rt>はんざい</rt></ruby><br>\n          Ciri: kemacetan, lingkungan beton, stres persaingan, kriminalitas\n        </div>\n      </div>\n\n      <div class=\"flow-conn\"></div>\n\n      <div class=\"node n-yellow\">\n        <div class=\"node-lbl\"><ruby>過疎地域<rt>かそちいき</rt></ruby> ／ Daerah Berpenduduk Jarang</div>\n        <div class=\"node-main\"><ruby>人口減少率<rt>じんこうげんしょうりつ</rt></ruby>が<ruby>一定率以上<rt>いっていりついじょう</rt></ruby>など、<ruby>法律<rt>ほうりつ</rt></ruby>で<ruby>指定<rt>してい</rt></ruby>された<ruby>地域<rt>ちいき</rt></ruby></div>\n        <div class=\"node-sub\">Daerah yang ditetapkan oleh hukum karena tingkat penurunan penduduk yang tinggi</div>\n      </div>\n\n      <div class=\"flow-conn\"></div>\n\n      <div class=\"node n-red\">\n        <div class=\"node-lbl\"><ruby>限界集落<rt>げんかいしゅうらく</rt></ruby> ／ Desa Ambang Batas</div>\n        <div class=\"node-main\">65歳<ruby>以上<rt>いじょう</rt></ruby>の<ruby>人口<rt>じんこう</rt></ruby>が<strong>50%を超え</strong>た<ruby>集落<rt>しゅうらく</rt></ruby></div>\n        <div class=\"node-sub\">Desa di mana lebih dari 50% penduduknya berusia 65+ tahun sehingga fungsi komunitas sulit dipertahankan</div>\n      </div>\n\n      <!-- Stats -->\n      <div class=\"hl hl-orange\" style=\"margin-top:14px;\">\n        <strong><ruby>過疎地域<rt>かそちいき</rt></ruby>の<ruby>現状<rt>げんじょう</rt></ruby>（令和5年度）／ Kondisi Daerah Jarang Penduduk</strong>\n        <div class=\"badge-row\" style=\"margin-top:8px;\">\n          <div class=\"badge n-orange\">\n            <span class=\"num\">51.5%</span>\n            <span><ruby>市町村数<rt>しちょうそんすう</rt></ruby></span>\n            <span class=\"lbl\">Jumlah Kota/Desa</span>\n          </div>\n          <div class=\"badge n-yellow\">\n            <span class=\"num\">-9.3%</span>\n            <span><ruby>人口<rt>じんこう</rt></ruby></span>\n            <span class=\"lbl\">Populasi Berkurang</span>\n          </div>\n          <div class=\"badge n-red\">\n            <span class=\"num\">63.2%</span>\n            <span><ruby>面積<rt>めんせき</rt></ruby></span>\n            <span class=\"lbl\">Luas Wilayah</span>\n          </div>\n        </div>\n        <div style=\"font-size:11px;margin-top:6px;opacity:.75;\">→ <ruby>公共<rt>こうきょう</rt></ruby>サービス（<ruby>消防<rt>しょうぼう</rt></ruby>・<ruby>治安<rt>ちあん</rt></ruby>）の<ruby>供給<rt>きょうきゅう</rt></ruby>が<ruby>困難<rt>こんなん</rt></ruby>になりがち<br>Layanan publik (pemadam kebakaran, keamanan) sulit disediakan</div>\n      </div>\n\n    </div></div>\n  </div>\n\n  <div class=\"arrow-down\">↓</div>\n\n  <!-- ===== SECTION 4: 行政計画 ===== -->\n  <div class=\"section th-teal\" id=\"s4\">\n    <div class=\"sec-head\" onclick=\"toggle('s4')\">\n      <div class=\"sec-icon\">📋</div>\n      <div class=\"sec-title\">\n        <span class=\"jp\"><ruby>行政計画<rt>ぎょうせいけいかく</rt></ruby></span>\n        <span class=\"id\">Rencana Administratif Pemerintah</span>\n      </div>\n      <span class=\"toggle-arr\">▼</span>\n    </div>\n    <div class=\"sec-body\"><div class=\"sec-inner\">\n\n      <div class=\"hl hl-teal\">📌 <strong><ruby>福祉<rt>ふくし</rt></ruby>に<ruby>関<rt>かん</rt></ruby>する<ruby>計画<rt>けいかく</rt></ruby> ／ Rencana Bidang Kesejahteraan</strong>\n      </div>\n      <table class=\"tbl\">\n        <thead>\n          <tr style=\"background:#d5f5f2;\">\n            <th><ruby>計画名<rt>けいかくめい</rt></ruby></th>\n            <th><ruby>内容<rt>ないよう</rt></ruby></th>\n            <th><ruby>期間<rt>きかん</rt></ruby></th>\n            <th><ruby>根拠法<rt>こんきょほう</rt></ruby></th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><ruby>地域福祉計画<rt>ちいきふくしけいかく</rt></ruby></strong></td>\n            <td><ruby>地域福祉推進<rt>ちいきふくしすいしん</rt></ruby>の計画<br><span style=\"font-size:10px;opacity:.7;\">Rencana promosi kesejahteraan lokal</span></td>\n            <td>—</td>\n            <td><ruby>社会福祉法<rt>しゃかいふくしほう</rt></ruby></td>\n          </tr>\n          <tr>\n            <td><strong><ruby>老人福祉計画<rt>ろうじんふくしけいかく</rt></ruby></strong></td>\n            <td><ruby>老人福祉事業<rt>ろうじんふくしじぎょう</rt></ruby>の供給体制確保<br><span style=\"font-size:10px;opacity:.7;\">Menjamin layanan kesejahteraan lansia</span></td>\n            <td>—</td>\n            <td><ruby>老人福祉法<rt>ろうじんふくしほう</rt></ruby></td>\n          </tr>\n          <tr>\n            <td><strong><ruby>介護保険事業計画<rt>かいごほけんじぎょうけいかく</rt></ruby></strong></td>\n            <td><ruby>介護保険事業<rt>かいごほけんじぎょう</rt></ruby>の円滑な実施<br><span style=\"font-size:10px;opacity:.7;\">Pelaksanaan asuransi perawatan lansia</span></td>\n            <td><span class=\"period\">3年1期</span></td>\n            <td><ruby>介護保険法<rt>かいごほけんほう</rt></ruby></td>\n          </tr>\n          <tr>\n            <td><strong><ruby>障害者計画<rt>しょうがいしゃけいかく</rt></ruby></strong></td>\n            <td><ruby>障害者<rt>しょうがいしゃ</rt></ruby>のための施策の基本計画<br><span style=\"font-size:10px;opacity:.7;\">Kebijakan dasar untuk penyandang disabilitas</span></td>\n            <td>—</td>\n            <td><ruby>障害者基本法<rt>しょうがいしゃきほんほう</rt></ruby></td>\n          </tr>\n          <tr>\n            <td><strong><ruby>障害福祉計画<rt>しょうがいふくしけいかく</rt></ruby></strong></td>\n            <td><ruby>障害福祉<rt>しょうがいふくし</rt></ruby>サービスの提供体制確保<br><span style=\"font-size:10px;opacity:.7;\">Memastikan layanan kesejahteraan disabilitas</span></td>\n            <td><span class=\"period\">3年1期</span></td>\n            <td><ruby>障害者総合支援法<rt>しょうがいしゃそうごうしえんほう</rt></ruby></td>\n          </tr>\n          <tr>\n            <td><strong><ruby>次世代育成支援行動計画<rt>じせだいいくせいしえんこうどうけいかく</rt></ruby></strong></td>\n            <td><ruby>次世代育成支援対策<rt>じせだいいくせいしえんたいさく</rt></ruby>の実施<br><span style=\"font-size:10px;opacity:.7;\">Dukungan pengembangan generasi berikutnya</span></td>\n            <td><span class=\"period blue\">5年1期</span></td>\n            <td><ruby>次世代育成支援対策推進法<rt>じせだいいくせいしえんたいさくすいしんほう</rt></ruby></td>\n          </tr>\n          <tr>\n            <td><strong>子ども・<ruby>子育<rt>こそだ</rt></ruby>て支援事業計画</strong></td>\n            <td>子ども・<ruby>子育<rt>こそだ</rt></ruby>て支援給付等の円滑な実施<br><span style=\"font-size:10px;opacity:.7;\">Dukungan pengasuhan anak</span></td>\n            <td><span class=\"period blue\">5年1期</span></td>\n            <td>子ども・<ruby>子育<rt>こそだ</rt></ruby>て支援法</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"hl hl-green\" style=\"margin-top:16px;\">\n        🏥 <strong><ruby>医療<rt>いりょう</rt></ruby>に<ruby>関<rt>かん</rt></ruby>する<ruby>計画<rt>けいかく</rt></ruby> ／ Rencana Bidang Kesehatan</strong>\n      </div>\n      <div class=\"grid3\" style=\"margin-top:8px;\">\n        <div class=\"node n-blue\" style=\"margin-bottom:0;\">\n          <div class=\"node-lbl\"><ruby>医療計画<rt>いりょうけいかく</rt></ruby></div>\n          <div class=\"node-main\"><ruby>医療提供体制<rt>いりょうていきょうたいせい</rt></ruby>の確保</div>\n          <div class=\"node-sub\"><span class=\"period red\">6年1期</span></div>\n          <div class=\"node-id\"><ruby>医療法<rt>いりょうほう</rt></ruby><br>Layanan medis</div>\n        </div>\n        <div class=\"node n-orange\" style=\"margin-bottom:0;\">\n          <div class=\"node-lbl\"><ruby>医療費適正化計画<rt>いりょうひてきせいかけいかく</rt></ruby></div>\n          <div class=\"node-main\"><ruby>生活習慣病<rt>せいかつしゅうかんびょう</rt></ruby>対策など</div>\n          <div class=\"node-sub\"><span class=\"period red\">6年1期</span></div>\n          <div class=\"node-id\">Rasionalisasi biaya medis</div>\n        </div>\n        <div class=\"node n-green\" style=\"margin-bottom:0;\">\n          <div class=\"node-lbl\"><ruby>健康増進計画<rt>けんこうぞうしんけいかく</rt></ruby></div>\n          <div class=\"node-main\"><ruby>住民<rt>じゅうみん</rt></ruby>の<ruby>健康増進<rt>けんこうぞうしん</rt></ruby>の推進</div>\n          <div class=\"node-sub\">—</div>\n          <div class=\"node-id\"><ruby>健康増進法<rt>けんこうぞうしんほう</rt></ruby><br>Promosi kesehatan warga</div>\n        </div>\n      </div>\n\n    </div></div>\n  </div>\n\n  <div class=\"arrow-down\">↓</div>\n\n  <!-- ===== SECTION 5: 行政組織 ===== -->\n  <div class=\"section th-purple\" id=\"s5\">\n    <div class=\"sec-head\" onclick=\"toggle('s5')\">\n      <div class=\"sec-icon\">🏛️</div>\n      <div class=\"sec-title\">\n        <span class=\"jp\"><ruby>行政組織<rt>ぎょうせいそしき</rt></ruby></span>\n        <span class=\"id\">Struktur Organisasi Pemerintahan</span>\n      </div>\n      <span class=\"toggle-arr\">▼</span>\n    </div>\n    <div class=\"sec-body\"><div class=\"sec-inner\">\n\n      <!-- Hierarchy -->\n      <div class=\"org\">\n        <div class=\"org-row\">\n          <div class=\"org-box n-red\" style=\"color:#7a0c13;\">\n            🇯🇵 <ruby>国<rt>くに</rt></ruby> ／ Pemerintah Pusat<br>\n            <span style=\"font-size:10px;font-weight:400;opacity:.75;\">全国一律の事務・国家存立<br>Urusan nasional & kedaulatan</span>\n            <div style=\"font-weight:900;font-size:14px;margin-top:4px;\">1</div>\n          </div>\n        </div>\n        <div class=\"org-line\"></div>\n        <div class=\"org-row\">\n          <div class=\"org-box n-orange\" style=\"color:#7a2a10;\">\n            <ruby>都道府県<rt>とどうふけん</rt></ruby> ／ Provinsi<br>\n            <span style=\"font-size:10px;font-weight:400;opacity:.75;\">広域・専門技術的事務<br>Urusan wilayah luas & teknis</span>\n            <div style=\"font-weight:900;font-size:14px;margin-top:4px;\">47</div>\n          </div>\n        </div>\n        <div class=\"org-line\"></div>\n        <div class=\"org-row\" style=\"gap:8px;\">\n          <div class=\"org-box n-blue\" style=\"font-size:11px;color:#1d3557;flex:1;\">\n            <ruby>市<rt>し</rt></ruby> ／ Kota<br>\n            <span style=\"opacity:.7;font-size:10px;\">人口5万以上</span><br>\n            <strong>772</strong><br>\n            <div style=\"font-size:10px;margin-top:4px;\">\n              <ruby>政令指定都市<rt>せいれいしていとし</rt></ruby> 50万以上（20市）<br>\n              <ruby>中核市<rt>ちゅうかくし</rt></ruby> 20万以上（62市）\n            </div>\n          </div>\n          <div class=\"org-box n-green\" style=\"font-size:11px;color:#1b4332;flex:1;\">\n            <ruby>町村<rt>ちょうそん</rt></ruby> ／ Kecamatan/Desa<br>\n            <span style=\"opacity:.7;font-size:10px;\"><ruby>住民<rt>じゅうみん</rt></ruby>に<ruby>身近<rt>みぢか</rt></ruby>な事務</span><br>\n            <strong><ruby>町<rt>まち</rt></ruby> 743 ／ <ruby>村<rt>むら</rt></ruby> 189</strong><br>\n            <div style=\"font-size:10px;margin-top:4px;\">特別区23（東京）を含む<br>Termasuk 23 ward Tokyo</div>\n          </div>\n        </div>\n      </div>\n\n    </div></div>\n  </div>\n\n  <div class=\"arrow-down\">↓</div>\n\n  <!-- ===== SECTION 6: 専門機関 ===== -->\n  <div class=\"section th-red\" id=\"s6\">\n    <div class=\"sec-head\" onclick=\"toggle('s6')\">\n      <div class=\"sec-icon\">🏥</div>\n      <div class=\"sec-title\">\n        <span class=\"jp\"><ruby>専門機関<rt>せんもんきかん</rt></ruby></span>\n        <span class=\"id\">Lembaga Spesialis Sosial</span>\n      </div>\n      <span class=\"toggle-arr\">▼</span>\n    </div>\n    <div class=\"sec-body\"><div class=\"sec-inner\">\n\n      <!-- 身体障害者更生相談所 -->\n      <div class=\"spec-card\" style=\"border-color:#dce9f7;\">\n        <div class=\"spec-title\">\n          🦾 <ruby>身体障害者更生相談所<rt>しんたいしょうがいしゃこうせいそうだんじょ</rt></ruby>\n          <span class=\"spec-tag\"><ruby>身体障害者福祉法<rt>しんたいしょうがいしゃふくしほう</rt></ruby></span>\n        </div>\n        <div style=\"font-size:12px;color:#1d3557;\"><ruby>都道府県<rt>とどうふけん</rt></ruby>は<strong>義務設置</strong>（<ruby>指定都市<rt>していとし</rt></ruby>は任意）／ Wajib didirikan oleh prefektur</div>\n        <div class=\"spec-duties\">\n          <div class=\"duty-item\"><span class=\"duty-num\">1</span>専門的な知識・技術を要する相談および指導</div>\n          <div class=\"duty-item\"><span class=\"duty-num\">2</span>医学的・心理学的・職能的判定、補装具の処方・適合判定</div>\n          <div class=\"duty-item\"><span class=\"duty-num\">3</span>市町村への技術的援助・助言、情報提供、連絡調整、研修</div>\n        </div>\n        <div class=\"staff-list\">👥 配置職員：<ruby>身体障害者福祉司<rt>しんたいしょうがいしゃふくしし</rt></ruby>・医師・心理判定員・職能判定員・理学療法士・作業療法士・義肢装具士・言語聴覚士・保健師・看護師</div>\n      </div>\n\n      <!-- 知的障害者 -->\n      <div class=\"spec-card\" style=\"border-color:#d8f3dc;\">\n        <div class=\"spec-title\">\n          🧠 <ruby>知的障害者更生相談所<rt>ちてきしょうがいしゃこうせいそうだんじょ</rt></ruby>\n          <span class=\"spec-tag\" style=\"background:#d8f3dc;color:#1b4332;\"><ruby>知的障害者福祉法<rt>ちてきしょうがいしゃふくしほう</rt></ruby></span>\n        </div>\n        <div style=\"font-size:12px;color:#1b4332;\"><ruby>都道府県<rt>とどうふけん</rt></ruby>は<strong>義務設置</strong>（<ruby>指定都市<rt>していとし</rt></ruby>は任意）／ Wajib didirikan oleh prefektur</div>\n        <div class=\"spec-duties\">\n          <div class=\"duty-item\"><span class=\"duty-num\">1</span>専門的な知識・技術を要する相談および指導</div>\n          <div class=\"duty-item\"><span class=\"duty-num\">2</span>医学的・心理学的・職能的判定業務</div>\n          <div class=\"duty-item\"><span class=\"duty-num\">3</span>市町村への技術的援助・助言、情報提供、連絡調整、研修</div>\n        </div>\n        <div class=\"staff-list\">👥 配置職員：<ruby>知的障害者福祉司<rt>ちてきしょうがいしゃふくしし</rt></ruby>・医師・心理判定員・職能判定員・保健師 or 看護師・理学療法士・作業療法士</div>\n      </div>\n\n      <!-- 精神保健福祉センター -->\n      <div class=\"spec-card\" style=\"border-color:#ece5f5;\">\n        <div class=\"spec-title\">\n          💜 <ruby>精神保健福祉<rt>せいしんほけんふくし</rt></ruby>センター\n          <span class=\"spec-tag\" style=\"background:#ece5f5;color:#3d2060;\"><ruby>精神保健福祉法<rt>せいしんほけんふくしほう</rt></ruby></span>\n        </div>\n        <div style=\"font-size:12px;color:#3d2060;\"><ruby>都道府県<rt>とどうふけん</rt></ruby>・<ruby>指定都市<rt>していとし</rt></ruby>は<strong><ruby>義務設置<rt>ぎむせっち</rt></ruby></strong> ／ Wajib didirikan</div>\n        <div class=\"spec-duties\">\n          <div class=\"duty-item\"><span class=\"duty-num\" style=\"background:#6d597a;\">1</span><ruby>精神医療審査会<rt>せいしんいりょうしんさかい</rt></ruby>の審査に関する事務</div>\n          <div class=\"duty-item\"><span class=\"duty-num\" style=\"background:#6d597a;\">2</span>自立支援医療（<ruby>精神通院医療<rt>せいしんつういんいりょう</rt></ruby>）の判定</div>\n          <div class=\"duty-item\"><span class=\"duty-num\" style=\"background:#6d597a;\">3</span><ruby>精神障害者保健福祉手帳<rt>せいしんしょうがいしゃほけんふくしてちょう</rt></ruby>の判定</div>\n          <div class=\"duty-item\"><span class=\"duty-num\" style=\"background:#6d597a;\">4</span><ruby>精神障害者福祉<rt>せいしんしょうがいしゃふくし</rt></ruby>に関する複雑・困難な相談および援助</div>\n        </div>\n        <div class=\"staff-list\">👥 医師・<ruby>精神保健福祉士<rt>せいしんほけんふくしし</rt></ruby>・公認心理師・保健師・看護師・作業療法士・<ruby>精神保健福祉相談員<rt>せいしんほけんふくしそうだんいん</rt></ruby></div>\n      </div>\n\n      <!-- 児童相談所 -->\n      <div class=\"spec-card\" style=\"border-color:#fde4d8;\">\n        <div class=\"spec-title\">\n          👶 <ruby>児童相談所<rt>じどうそうだんじょ</rt></ruby>\n          <span class=\"spec-tag\" style=\"background:#fde4d8;color:#7a2a10;\"><ruby>児童福祉法<rt>じどうふくしほう</rt></ruby></span>\n        </div>\n        <div style=\"font-size:12px;color:#7a2a10;\"><ruby>都道府県<rt>とどうふけん</rt></ruby>・<ruby>指定都市<rt>していとし</rt></ruby>は<strong><ruby>義務設置<rt>ぎむせっち</rt></ruby></strong>（<ruby>中核市<rt>ちゅうかくし</rt></ruby>・特別区は任意）</div>\n        <div class=\"spec-duties\">\n          <div class=\"duty-item\"><span class=\"duty-num\" style=\"background:#e76f51;\">1</span>専門的な知識・技術を要する相談</div>\n          <div class=\"duty-item\"><span class=\"duty-num\" style=\"background:#e76f51;\">2</span>児童およびその家庭につき、医学的・心理学的・教育学的・社会学的・精神保健上の判定</div>\n          <div class=\"duty-item\"><span class=\"duty-num\" style=\"background:#e76f51;\">3</span>特別児童扶養手当および<ruby>療育手帳<rt>りょういくてちょう</rt></ruby>の判定</div>\n          <div class=\"duty-item\"><span class=\"duty-num\" style=\"background:#e76f51;\">4</span>児童の一時保護（2か月超は<ruby>家庭裁判所<rt>かていさいばんしょ</rt></ruby>の承認が必要）</div>\n        </div>\n        <div class=\"staff-list\">👥 <ruby>児童福祉司<rt>じどうふくしし</rt></ruby>・<ruby>児童心理司<rt>じどうしんりし</rt></ruby>・心理療法担当職員・保健師・理学療法士</div>\n      </div>\n\n      <!-- 保健所 -->\n      <div class=\"spec-card\" style=\"border-color:#d5f5f2;\">\n        <div class=\"spec-title\">\n          🏨 <ruby>保健所<rt>ほけんじょ</rt></ruby>\n          <span class=\"spec-tag\" style=\"background:#d5f5f2;color:#0d4a44;\"><ruby>地域保健法<rt>ちいきほけんほう</rt></ruby></span>\n        </div>\n        <div style=\"font-size:12px;color:#0d4a44;\"><ruby>都道府県<rt>とどうふけん</rt></ruby>・<ruby>指定都市<rt>していとし</rt></ruby>・<ruby>中核市<rt>ちゅうかくし</rt></ruby>・<ruby>特別区<rt>とくべつく</rt></ruby>などが設置</div>\n        <div class=\"spec-duties\">\n          <div class=\"duty-item\"><span class=\"duty-num\" style=\"background:#2a9d8f;\">1</span><ruby>難病<rt>なんびょう</rt></ruby>等により長期に療養を必要とする者の保健</div>\n          <div class=\"duty-item\"><span class=\"duty-num\" style=\"background:#2a9d8f;\">2</span><ruby>精神保健<rt>せいしんほけん</rt></ruby>に関する事項</div>\n          <div class=\"duty-item\"><span class=\"duty-num\" style=\"background:#2a9d8f;\">3</span><ruby>感染症<rt>かんせんしょう</rt></ruby>その他の疾病の予防</div>\n          <div class=\"duty-item\"><span class=\"duty-num\" style=\"background:#2a9d8f;\">4</span><ruby>栄養<rt>えいよう</rt></ruby>の改善および食品衛生</div>\n        </div>\n        <div class=\"staff-list\">👥 所長（医師）・医師・歯科医師・薬剤師・獣医師・保健師・助産師・看護師</div>\n      </div>\n\n    </div></div>\n  </div>\n\n  <div class=\"arrow-down\">↓</div>\n\n  <!-- ===== SECTION 7: 民生委員・福祉事務所 ===== -->\n  <div class=\"section th-green\" id=\"s7\">\n    <div class=\"sec-head\" onclick=\"toggle('s7')\">\n      <div class=\"sec-icon\">🤝</div>\n      <div class=\"sec-title\">\n        <span class=\"jp\"><ruby>民生委員<rt>みんせいいいん</rt></ruby>・<ruby>福祉事務所<rt>ふくしじむしょ</rt></ruby></span>\n        <span class=\"id\">Komisioner Kesejahteraan & Kantor Sosial</span>\n      </div>\n      <span class=\"toggle-arr\">▼</span>\n    </div>\n    <div class=\"sec-body\"><div class=\"sec-inner\">\n\n      <div class=\"hl hl-green\">\n        👥 <strong><ruby>民生委員<rt>みんせいいいん</rt></ruby> ／ Komisioner Kesejahteraan Masyarakat</strong>\n      </div>\n      <div class=\"grid2\" style=\"margin-top:8px;\">\n        <div class=\"node n-green\">\n          <div class=\"node-lbl\"><ruby>委嘱<rt>いしょく</rt></ruby> ／ Pengangkatan</div>\n          <div class=\"node-main\"><ruby>都道府県知事<rt>とどうふけんちじ</rt></ruby>の<ruby>推薦<rt>すいせん</rt></ruby>で<ruby>厚生労働大臣<rt>こうせいろうどうだいじん</rt></ruby>が委嘱</div>\n          <div class=\"node-sub\">Diangkat Menteri Kesehatan atas rekomendasi gubernur prefektur</div>\n        </div>\n        <div class=\"node n-yellow\">\n          <div class=\"node-lbl\"><ruby>任期<rt>にんき</rt></ruby>・<ruby>給与<rt>きゅうよ</rt></ruby> ／ Masa Jabatan & Gaji</div>\n          <div class=\"node-main\"><ruby>任期<rt>にんき</rt></ruby>：<strong>3年</strong>　<ruby>給与<rt>きゅうよ</rt></ruby>：<strong><ruby>なし<rt></rt></ruby>（無給）</strong></div>\n          <div class=\"node-sub\">Masa jabatan 3 tahun, tidak digaji (sukarela)</div>\n        </div>\n        <div class=\"node n-blue\" style=\"grid-column:1/-1;\">\n          <div class=\"node-lbl\"><ruby>職務<rt>しょくむ</rt></ruby> ／ Tugas</div>\n          <div class=\"node-main\"><ruby>住民<rt>じゅうみん</rt></ruby>の生活状態を把握 → 福祉に関する相談・支援</div>\n          <div class=\"node-sub\">Memahami kondisi kehidupan warga → memberikan konsultasi & dukungan kesejahteraan<br>\n            💡 <ruby>民生委員<rt>みんせいいいん</rt></ruby>は<strong><ruby>児童委員<rt>じどういいん</rt></ruby>を兼ねる</strong>（全員）<br>\n            Semua komisioner kesejahteraan juga merangkap sebagai komisioner anak\n          </div>\n        </div>\n      </div>\n\n      <div class=\"hl hl-blue\" style=\"margin-top:14px;\">\n        🏢 <strong><ruby>福祉事務所<rt>ふくしじむしょ</rt></ruby> ／ Kantor Urusan Sosial</strong>\n      </div>\n      <div class=\"grid2\" style=\"margin-top:8px;\">\n        <div class=\"node n-blue\">\n          <div class=\"node-lbl\"><ruby>設置<rt>せっち</rt></ruby> ／ Pendirian</div>\n          <div class=\"node-main\"><ruby>都道府県<rt>とどうふけん</rt></ruby>・市：<strong><ruby>義務設置<rt>ぎむせっち</rt></ruby></strong></div>\n          <div class=\"node-sub\"><ruby>町村<rt>ちょうそん</rt></ruby>：任意設置<br>Prefektur & kota: wajib / Kecamatan-desa: opsional</div>\n        </div>\n        <div class=\"node n-green\">\n          <div class=\"node-lbl\"><ruby>所管事務<rt>しょかんじむ</rt></ruby></div>\n          <div class=\"node-main\"><ruby>都道府県<rt>とどうふけん</rt></ruby>：<ruby>福祉三法<rt>ふくしさんぽう</rt></ruby></div>\n          <div class=\"node-sub\"><ruby>市町村<rt>しちょうそん</rt></ruby>：<ruby>福祉六法<rt>ふくしろっぽう</rt></ruby><br>\n            <span style=\"font-size:10px;opacity:.75;\">\n              三法：生活保護・児童福祉・母子父子及び寡婦福祉<br>\n              六法：三法＋老人福祉・身体障害者福祉・知的障害者福祉\n            </span>\n          </div>\n        </div>\n      </div>\n\n    </div></div>\n  </div>\n\n  <div style=\"text-align:center;margin-top:28px;font-size:11px;color:#2d6a4f;opacity:.65;\">\n    出典：厚生労働省・総務省資料（令和5〜6年）<br>\n    Sumber: Kementerian Kesehatan & Biro Statistik Jepang\n  </div>\n\n</main>\n\n<script>\n  function toggle(id) {\n    document.getElementById(id).classList.toggle('open');\n  }\n<\/script>\n</body>\n</html>\n","songen-3":"<!DOCTYPE html>\n<html lang=\"ja\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>第2節・3&4 — 人間の尊厳と人権・権利擁護</title>\n<link href=\"https://fonts.googleapis.com/css2?family=Noto+Sans+JP:wght@300;400;500;700;900&family=Noto+Serif+JP:wght@400;700&display=swap\" rel=\"stylesheet\">\n<style>\n  :root {\n    --g1:#1b4332;--g2:#2d6a4f;--g3:#52b788;--gp:#d8f3dc;\n    --b1:#1d3557;--b2:#457b9d;--bl:#a8dadc;\n    --o1:#9e4a1e;--o2:#e76f51;--op:#fde4d8;\n    --y1:#7a5000;--y2:#f4a261;--yp:#fff3cd;\n    --p1:#3d2060;--p2:#6d597a;--pp:#ece5f5;\n    --t1:#0d4a44;--t2:#2a9d8f;--tp:#d5f5f2;\n    --r1:#7a0c13;--r2:#c1121f;--rp:#fce0e2;\n    --tx:#1b1b2f;\n  }\n  *{margin:0;padding:0;box-sizing:border-box;}\n  body{font-family:'Noto Sans JP',sans-serif;background:#eef4f0;color:var(--tx);min-height:100vh;}\n\n  /* HEADER */\n  header{background:linear-gradient(135deg,#3d2060 0%,#6d597a 55%,#a89bba 100%);\n    padding:34px 20px 26px;text-align:center;position:relative;overflow:hidden;}\n  header::before{content:'';position:absolute;top:-50px;right:-50px;\n    width:200px;height:200px;border-radius:50%;background:rgba(255,255,255,0.06);}\n  .hbadge{display:inline-block;background:rgba(255,255,255,0.15);border:1px solid rgba(255,255,255,0.3);\n    color:#fff;font-size:11px;letter-spacing:2px;padding:4px 14px;border-radius:20px;margin-bottom:10px;}\n  header h1{font-family:'Noto Serif JP',serif;color:#fff;\n    font-size:clamp(17px,5vw,29px);font-weight:700;line-height:1.45;margin-bottom:6px;}\n  header p{color:rgba(255,255,255,0.75);font-size:12px;}\n\n  /* MAIN */\n  main{max-width:820px;margin:0 auto;padding:26px 14px 60px;}\n  .intro-label{text-align:center;font-size:12px;color:#2d6a4f;\n    margin-bottom:16px;letter-spacing:1px;font-weight:700;}\n\n  /* SECTION */\n  .section{margin-bottom:20px;animation:fadeUp .5s ease both;}\n  .section:nth-child(1){animation-delay:.05s}\n  .section:nth-child(2){animation-delay:.10s}\n  .section:nth-child(3){animation-delay:.15s}\n  .section:nth-child(4){animation-delay:.20s}\n  .section:nth-child(5){animation-delay:.25s}\n  @keyframes fadeUp{from{opacity:0;transform:translateY(16px)}to{opacity:1;transform:translateY(0)}}\n\n  .sec-head{display:flex;align-items:center;gap:12px;padding:13px 16px;\n    border-radius:13px 13px 0 0;cursor:pointer;user-select:none;transition:filter .2s;}\n  .sec-head:hover{filter:brightness(1.07)}\n  .sec-icon{width:36px;height:36px;border-radius:50%;background:rgba(255,255,255,0.2);\n    display:flex;align-items:center;justify-content:center;font-size:17px;flex-shrink:0;}\n  .sec-title .jp{font-size:16px;font-weight:700;color:#fff;display:block;}\n  .sec-title .id{font-size:11px;color:rgba(255,255,255,.73);display:block;margin-top:1px;}\n  .toggle-arr{color:rgba(255,255,255,.8);font-size:13px;margin-left:auto;transition:transform .3s;}\n  .section.open .toggle-arr{transform:rotate(180deg);}\n\n  .sec-body{background:#fff;border-radius:0 0 13px 13px;\n    border:1px solid #ddd;border-top:none;overflow:hidden;max-height:0;transition:max-height .45s ease;}\n  .section.open .sec-body{max-height:6000px;}\n  .sec-inner{padding:18px 16px 22px;}\n\n  /* THEMES */\n  .th-purple .sec-head{background:linear-gradient(90deg,#3d2060,#6d597a);}\n  .th-green  .sec-head{background:linear-gradient(90deg,#1b4332,#2d6a4f);}\n  .th-blue   .sec-head{background:linear-gradient(90deg,#1d3557,#457b9d);}\n  .th-teal   .sec-head{background:linear-gradient(90deg,#0d4a44,#2a9d8f);}\n  .th-orange .sec-head{background:linear-gradient(90deg,#9e4a1e,#e76f51);}\n\n  /* NODES */\n  .node{border-radius:10px;padding:10px 13px;margin-bottom:8px;}\n  .node-lbl{font-size:10px;font-weight:700;letter-spacing:1px;opacity:.6;margin-bottom:4px;text-transform:uppercase;}\n  .node-main{font-size:14px;font-weight:700;line-height:1.45;}\n  .node-sub{font-size:11.5px;margin-top:4px;line-height:1.55;opacity:.82;}\n  .node-id{font-size:11px;margin-top:5px;padding-top:5px;border-top:1px dashed currentColor;opacity:.6;font-style:italic;}\n\n  .n-green {background:#d8f3dc;color:#1b4332;}\n  .n-blue  {background:#dce9f7;color:#1d3557;}\n  .n-yellow{background:#fff3cd;color:#7a5000;}\n  .n-orange{background:#fde4d8;color:#7a2a10;}\n  .n-red   {background:#fce0e2;color:#7a0c13;}\n  .n-purple{background:#ece5f5;color:#3d2060;}\n  .n-teal  {background:#d5f5f2;color:#0d4a44;}\n  .n-gray  {background:#f3f4f6;color:#374151;}\n\n  .flow-conn{height:14px;display:flex;justify-content:flex-start;padding-left:24px;}\n  .flow-conn::before{content:'';width:2px;background:#b7d5c8;display:block;}\n\n  /* HIGHLIGHT */\n  .hl{border-left:4px solid;padding:10px 13px;border-radius:0 10px 10px 0;\n    margin-top:10px;margin-bottom:10px;font-size:13px;line-height:1.6;}\n  .hl-green {border-color:#2d6a4f;background:#f0faf5;color:#1b4332;}\n  .hl-blue  {border-color:#457b9d;background:#eef5fc;color:#1d3557;}\n  .hl-orange{border-color:#e76f51;background:#fef5f2;color:#7a2a10;}\n  .hl-purple{border-color:#6d597a;background:#f5f0fb;color:#3d2060;}\n  .hl-teal  {border-color:#2a9d8f;background:#f0fbfa;color:#0d4a44;}\n  .hl-red   {border-color:#c1121f;background:#fef0f1;color:#7a0c13;}\n\n  /* GRID */\n  .grid2{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:8px;}\n  .grid3{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-top:8px;}\n  .grid4{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin-top:8px;}\n  @media(max-width:520px){.grid2,.grid3,.grid4{grid-template-columns:1fr;}}\n\n  /* BADGE */\n  .badge-row{display:flex;flex-wrap:wrap;gap:8px;margin-top:10px;}\n  .badge{display:inline-flex;flex-direction:column;align-items:center;\n    padding:7px 10px;border-radius:10px;font-size:11px;font-weight:700;min-width:68px;text-align:center;}\n  .badge .num{font-size:16px;font-weight:900;line-height:1.1;}\n  .badge .lbl{font-size:10px;opacity:.7;margin-top:2px;}\n\n  /* TIMELINE */\n  .timeline{position:relative;padding-left:22px;margin-top:10px;}\n  .timeline::before{content:'';position:absolute;left:7px;top:0;bottom:0;width:2px;background:#b7d5c8;}\n  .tl-item{position:relative;margin-bottom:12px;font-size:12.5px;}\n  .tl-item::before{content:'';position:absolute;left:-18px;top:4px;\n    width:10px;height:10px;border-radius:50%;border:2px solid #2d6a4f;background:#fff;}\n  .tl-year{font-weight:900;font-size:12px;color:#2d6a4f;display:inline-block;\n    background:#d8f3dc;padding:1px 8px;border-radius:20px;margin-bottom:3px;}\n  .tl-title{font-weight:700;color:#1b4332;font-size:13px;}\n  .tl-text{color:#374151;line-height:1.5;}\n\n  /* TABLE */\n  .tbl{width:100%;border-collapse:collapse;font-size:12px;margin-top:10px;}\n  .tbl th{padding:7px 9px;text-align:left;font-size:11px;font-weight:700;letter-spacing:.4px;border-bottom:2px solid #e0e0e0;}\n  .tbl td{padding:7px 9px;border-bottom:1px solid #f0f0f0;vertical-align:top;line-height:1.5;}\n  .tbl tr:last-child td{border-bottom:none;}\n\n  /* COMPARISON TABLE */\n  .cmp-table{width:100%;border-collapse:collapse;font-size:12px;margin-top:10px;}\n  .cmp-table th{padding:8px 10px;font-size:11px;font-weight:700;text-align:center;border:1px solid #e0e0e0;}\n  .cmp-table td{padding:8px 10px;border:1px solid #efefef;vertical-align:top;line-height:1.5;font-size:12px;}\n  .cmp-table .row-lbl{background:#f5f5f5;font-weight:700;font-size:11px;color:#374151;text-align:center;}\n  .head-left{background:#d8f3dc;color:#1b4332;}\n  .head-right{background:#dce9f7;color:#1d3557;}\n\n  /* ARTICLE BOX */\n  .art-box{border-radius:8px;padding:10px 13px;margin-bottom:8px;border:1px solid;}\n  .art-num{display:inline-block;width:28px;height:28px;border-radius:50%;\n    text-align:center;line-height:28px;font-weight:900;font-size:13px;\n    margin-right:8px;flex-shrink:0;}\n\n  /* UD 7 principles */\n  .ud-grid{display:grid;grid-template-columns:1fr 1fr;gap:6px;margin-top:10px;}\n  @media(max-width:400px){.ud-grid{grid-template-columns:1fr;}}\n  .ud-item{background:#fff3cd;color:#7a5000;border-radius:8px;padding:8px 10px;font-size:12px;}\n  .ud-num{font-weight:900;font-size:14px;color:#e76f51;margin-right:5px;}\n\n  /* ARROW */\n  .arrow-down{text-align:center;font-size:20px;color:#a0c4b0;margin:6px 0;}\n\n  ruby rt{font-size:9px;color:#2d6a4f;line-height:1;}\n</style>\n<style id=\"pk-fix\">\n.sec-body{max-height:none!important;overflow:visible!important;display:none;transition:none!important}\n.section.open .sec-body{display:block}\n.section{animation:none!important;opacity:1!important;transform:none!important}\n*{min-width:0}\nbody{overflow-x:hidden;-webkit-text-size-adjust:100%}\nmain{padding-left:10px!important;padding-right:10px!important}\np,div,span,td,th,li{overflow-wrap:anywhere;word-break:normal}\nimg,svg,video{max-width:100%;height:auto}\ntable{display:block;max-width:100%;overflow-x:auto;-webkit-overflow-scrolling:touch;border-collapse:collapse}\n@media (max-width:560px){\n [class*=\"grid\"],[class*=\"cols\"],[class*=\"compare\"],[class*=\"pair\"],[class*=\"two\"],[class*=\"stats\"]{grid-template-columns:1fr 1fr!important}\n [class*=\"grid3\"],[class*=\"grid-3\"],[class*=\"three\"]{grid-template-columns:1fr!important}\n [class*=\"row\"],[class*=\"flex\"],[class*=\"flow\"],[class*=\"chain\"]{flex-wrap:wrap!important}\n [class*=\"compare\"] > *,[class*=\"pair\"] > *{min-width:0}\n}\n</style>\n<script>\n(function(){\n function post(){try{parent.postMessage({pkH:Math.ceil(document.documentElement.scrollHeight)},'*');}catch(e){}}\n document.addEventListener('DOMContentLoaded',function(){\n  document.querySelectorAll('.section').forEach(function(s,i){ if(i===0) s.classList.add('open'); });\n  post();\n  if(window.ResizeObserver) new ResizeObserver(post).observe(document.body);\n  document.addEventListener('click',function(){setTimeout(post,30);setTimeout(post,400);});\n });\n window.addEventListener('load',post);\n})();\n<\/script></head>\n<body>\n\n<header>\n  <div class=\"hbadge\">第2節・3&4 — まとめ</div>\n  <h1><ruby>人間<rt>にんげん</rt></ruby>の<ruby>尊厳<rt>そんげん</rt></ruby>と<ruby>人権<rt>じんけん</rt></ruby>・<ruby>権利擁護<rt>けんりようご</rt></ruby><br>\n    <span style=\"font-size:.62em;font-weight:400;\">Martabat Manusia, Hak Asasi & Perlindungan Hak</span>\n  </h1>\n  <p>タップして各テーマを開く ／ Ketuk untuk membuka setiap topik</p>\n</header>\n\n<main>\n  <div class=\"intro-label\">▼ 順番に読もう ／ Baca Secara Berurutan ▼</div>\n\n  <!-- ===== SECTION 1: 重要用語 ===== -->\n  <div class=\"section th-purple open\" id=\"s1\">\n    <div class=\"sec-head\" onclick=\"toggle('s1')\">\n      <div class=\"sec-icon\">💡</div>\n      <div class=\"sec-title\">\n        <span class=\"jp\"><ruby>人間<rt>にんげん</rt></ruby>の<ruby>尊厳<rt>そんげん</rt></ruby>・<ruby>重要用語<rt>じゅうようようご</rt></ruby></span>\n        <span class=\"id\">Istilah Penting tentang Martabat Manusia</span>\n      </div>\n      <span class=\"toggle-arr\">▼</span>\n    </div>\n    <div class=\"sec-body\"><div class=\"sec-inner\">\n\n      <!-- 自立生活 -->\n      <div class=\"node n-purple\">\n        <div class=\"node-lbl\"><ruby>自立生活<rt>じりつせいかつ</rt></ruby> ／ Kehidupan Mandiri</div>\n        <div class=\"node-main\">「<ruby>自分<rt>じぶん</rt></ruby>で<ruby>決<rt>き</rt></ruby>めること＝<ruby>自立<rt>じりつ</rt></ruby>」</div>\n        <div class=\"node-sub\"><ruby>介助<rt>かいじょ</rt></ruby>を<ruby>受<rt>う</rt></ruby>けていても<ruby>自<rt>みずか</rt></ruby>ら<ruby>選択<rt>せんたく</rt></ruby>し<ruby>行動<rt>こうどう</rt></ruby>すれば「<ruby>自立<rt>じりつ</rt></ruby>」とする<ruby>理念<rt>りねん</rt></ruby><br>\n          <span style=\"opacity:.75;\">Mandiri = menentukan sendiri, bukan berarti tanpa bantuan</span></div>\n        <div class=\"node-id\">\n          例）2時間かけて服を着るより介助を受けて15分で着替え社会参加するほうが自立<br>\n          <span style=\"font-style:normal;opacity:.8;\">Contoh: 15 menit dengan bantuan lebih \"mandiri\" daripada 2 jam sendirian</span>\n        </div>\n      </div>\n      <div class=\"hl hl-purple\" style=\"font-size:12px;\">\n        <strong><ruby>自立生活<rt>じりつせいかつ</rt></ruby>の<ruby>概念<rt>がいねん</rt></ruby> ／ Konsep Kehidupan Mandiri</strong><br>\n        ① ライフスタイルの選択や日々の生活の意思決定を障害者本人が行うこと<br>\n        ② 自立生活を営むために必要な知識やスキルを身につけること（介助利用も含む）<br>\n        ③ 施設や病院ではなく、<ruby>地域社会<rt>ちいきしゃかい</rt></ruby>の中で一般の人と同様に生活すること<br>\n        <span style=\"opacity:.7;font-size:11px;\">① Penyandang disabilitas menentukan sendiri gaya hidup & keputusan harian<br>\n        ② Memiliki pengetahuan & keterampilan hidup mandiri (termasuk penggunaan bantuan)<br>\n        ③ Hidup di masyarakat umum, bukan di institusi/rumah sakit</span>\n      </div>\n\n      <div class=\"flow-conn\"></div>\n\n      <!-- ノーマライゼーション -->\n      <div class=\"node n-green\">\n        <div class=\"node-lbl\">ノーマライゼーション ／ Normalization</div>\n        <div class=\"node-main\"><ruby>障害<rt>しょうがい</rt></ruby>のある<ruby>人<rt>ひと</rt></ruby>たちを<ruby>一市民<rt>いちしみん</rt></ruby>として<ruby>地域<rt>ちいき</rt></ruby>で<ruby>普通<rt>ふつう</rt></ruby>に<ruby>生活<rt>せいかつ</rt></ruby>できるよう<ruby>社会<rt>しゃかい</rt></ruby>の<ruby>仕組<rt>しく</rt></ruby>みを<ruby>変<rt>か</rt></ruby>えること</div>\n        <div class=\"node-sub\">Mengubah sistem masyarakat agar penyandang disabilitas bisa hidup normal sebagai warga biasa</div>\n      </div>\n\n      <div class=\"grid2\">\n        <div class=\"node n-teal\" style=\"margin-bottom:0;\">\n          <div class=\"node-lbl\">バンク－ミケルセン（Bank-Mikkelsen）🇩🇰</div>\n          <div class=\"node-main\"><ruby>デンマーク<rt></rt></ruby>、1959<ruby>年法<rt>ねんほう</rt></ruby></div>\n          <div class=\"node-sub\"><ruby>知的障害者<rt>ちてきしょうがいしゃ</rt></ruby>の<ruby>親<rt>おや</rt></ruby>の<ruby>会<rt>かい</rt></ruby>の<ruby>運動<rt>うんどう</rt></ruby>にかかわり、<strong><ruby>世界初<rt>せかいはつ</rt></ruby>のノーマライゼーション原理</strong>が入った法律制定に貢献<br>\n            <span style=\"opacity:.7;\">Tokoh pertama yang memasukkan prinsip normalisasi ke dalam hukum</span></div>\n        </div>\n        <div class=\"node n-blue\" style=\"margin-bottom:0;\">\n          <div class=\"node-lbl\">ニィリエ（Nirje, B.）🇸🇪</div>\n          <div class=\"node-main\">ノーマライゼーションの<strong>8つの<ruby>原理<rt>げんり</rt></ruby></strong></div>\n          <div class=\"node-sub\" style=\"font-size:11px;\">\n            ①1日のノーマルなリズム ②1週間のノーマルなリズム ③1年間のノーマルなリズム<br>\n            ④ライフサイクルでのノーマルな経験 ⑤ノーマルな要求の尊重<br>\n            ⑥異性とのかかわり ⑦ノーマルな経済水準 ⑧ノーマルな環境水準<br>\n            <span style=\"opacity:.7;\">8 prinsip kehidupan normal dalam dimensi waktu, pengalaman, hak & lingkungan</span>\n          </div>\n        </div>\n      </div>\n\n      <div class=\"flow-conn\"></div>\n\n      <!-- その他の重要概念 -->\n      <div class=\"grid2\" style=\"margin-top:0;\">\n        <div class=\"node n-orange\">\n          <div class=\"node-lbl\">ヴォルフェンスベルガー（Wolfensberger）</div>\n          <div class=\"node-main\">ソーシャルロール・バロリゼーション</div>\n          <div class=\"node-sub\">「<ruby>価値<rt>かち</rt></ruby>のある<ruby>社会的役割<rt>しゃかいてきやくわり</rt></ruby>の<ruby>獲得<rt>かくとく</rt></ruby>」を<ruby>目指<rt>めざ</rt></ruby>す<br>\n            <span style=\"opacity:.7;\">Meraih peran sosial yang bernilai</span></div>\n        </div>\n        <div class=\"node n-yellow\">\n          <div class=\"node-lbl\"><ruby>糸賀一雄<rt>いとがかずお</rt></ruby></div>\n          <div class=\"node-main\"><ruby>人間<rt>にんげん</rt></ruby>の<ruby>発達保障<rt>はったつほしょう</rt></ruby></div>\n          <div class=\"node-sub\">「この子らを世の光に」を著し、知的障害者も<ruby>発達<rt>はったつ</rt></ruby>の<ruby>可能性<rt>かのうせい</rt></ruby>と<ruby>権利<rt>けんり</rt></ruby>をもつ主体としてとらえた<br>\n            <span style=\"opacity:.7;\">Menjamin hak berkembang bagi penyandang disabilitas intelektual</span></div>\n        </div>\n        <div class=\"node n-teal\">\n          <div class=\"node-lbl\">リハビリテーション</div>\n          <div class=\"node-main\"><ruby>全人間的復権<rt>ぜんにんげんてきふっけん</rt></ruby></div>\n          <div class=\"node-sub\">障害のある人が<ruby>身体的<rt>しんたいてき</rt></ruby>・<ruby>精神的<rt>せいしんてき</rt></ruby>・<ruby>社会的<rt>しゃかいてき</rt></ruby>・<ruby>職業的<rt>しょくぎょうてき</rt></ruby>に能力を発揮し、<ruby>人間<rt>にんげん</rt></ruby>らしく<ruby>生<rt>い</rt></ruby>きる権利を<ruby>回復<rt>かいふく</rt></ruby>すること<br>\n            <span style=\"opacity:.7;\">Memulihkan hak sepenuhnya sebagai manusia</span></div>\n        </div>\n        <div class=\"node n-purple\">\n          <div class=\"node-lbl\">ソーシャル・インクルージョン（<ruby>社会的包摂<rt>しゃかいてきほうせつ</rt></ruby>）</div>\n          <div class=\"node-main\">すべての<ruby>人々<rt>ひとびと</rt></ruby>を<ruby>包<rt>つつ</rt></ruby>み<ruby>込<rt>こ</rt></ruby>み、<ruby>共<rt>とも</rt></ruby>に<ruby>生<rt>い</rt></ruby>き<ruby>支<rt>ささ</rt></ruby>え<ruby>合<rt>あ</rt></ruby>う</div>\n          <div class=\"node-sub\">Social Inclusion: tidak ada seorang pun yang terisolasi atau terpinggirkan<br>\n            <span style=\"opacity:.7;\">Semua orang saling mendukung dalam masyarakat</span></div>\n        </div>\n      </div>\n\n      <!-- ナショナルミニマム・アドボカシー -->\n      <div class=\"grid2\" style=\"margin-top:0;\">\n        <div class=\"node n-blue\">\n          <div class=\"node-lbl\">ナショナルミニマム ／ National Minimum</div>\n          <div class=\"node-main\"><ruby>国<rt>くに</rt></ruby>が<ruby>保障<rt>ほしょう</rt></ruby>する<ruby>最低生活水準<rt>さいていせいかつすいじゅん</rt></ruby></div>\n          <div class=\"node-sub\">国が社会保障その他の公共政策によって国民に保障する最低限の生活水準<br>\n            <span style=\"opacity:.7;\">Standar kehidupan minimum yang dijamin negara</span></div>\n        </div>\n        <div class=\"node n-red\">\n          <div class=\"node-lbl\">アドボカシー（<ruby>権利擁護<rt>けんりようご</rt></ruby>）</div>\n          <div class=\"node-main\"><ruby>利用者<rt>りようしゃ</rt></ruby>の<ruby>利益<rt>りえき</rt></ruby>・<ruby>権利<rt>けんり</rt></ruby>を<ruby>擁護<rt>ようご</rt></ruby>する<ruby>活動<rt>かつどう</rt></ruby></div>\n          <div class=\"node-sub\">利用者の利益を図り生活の質を高めるために主張・代弁し権利を護る<br>\n            <span style=\"opacity:.7;\">Advokasi: memperjuangkan hak & kepentingan pengguna layanan</span></div>\n        </div>\n      </div>\n\n    </div></div>\n  </div>\n\n  <div class=\"arrow-down\">↓</div>\n\n  <!-- ===== SECTION 2: バリアフリー・UD ===== -->\n  <div class=\"section th-teal\" id=\"s2\">\n    <div class=\"sec-head\" onclick=\"toggle('s2')\">\n      <div class=\"sec-icon\">♿</div>\n      <div class=\"sec-title\">\n        <span class=\"jp\">バリアフリー・ユニバーサルデザイン</span>\n        <span class=\"id\">Barrier-Free & Universal Design</span>\n      </div>\n      <span class=\"toggle-arr\">▼</span>\n    </div>\n    <div class=\"sec-body\"><div class=\"sec-inner\">\n\n      <div class=\"grid2\">\n        <div class=\"node n-teal\">\n          <div class=\"node-lbl\">バリアフリー ／ Barrier-Free</div>\n          <div class=\"node-main\"><ruby>障害<rt>しょうがい</rt></ruby>のある<ruby>人<rt>ひと</rt></ruby>が<ruby>社会生活<rt>しゃかいせいかつ</rt></ruby>で<ruby>直面<rt>ちょくめん</rt></ruby>する<ruby>障壁<rt>しょうへき</rt></ruby>（バリア）を<ruby>除去<rt>じょきょ</rt></ruby>すること</div>\n          <div class=\"node-sub\">Menghilangkan hambatan fisik & sosial bagi penyandang disabilitas</div>\n        </div>\n        <div class=\"node n-orange\">\n          <div class=\"node-lbl\">ユニバーサルデザイン ／ Universal Design</div>\n          <div class=\"node-main\"><ruby>年齢<rt>ねんれい</rt></ruby>や<ruby>障害<rt>しょうがい</rt></ruby>に<ruby>関<rt>かか</rt></ruby>わらず<ruby>すべての人<rt>ひと</rt></ruby>が<ruby>使<rt>つか</rt></ruby>いやすいデザイン</div>\n          <div class=\"node-sub\">Desain fasilitas & produk yang bisa digunakan semua orang, tanpa memandang usia/disabilitas</div>\n        </div>\n      </div>\n\n      <!-- 7原則 -->\n      <div class=\"hl hl-orange\" style=\"margin-top:10px;\">\n        <strong>ユニバーサルデザイン 7<ruby>原則<rt>げんそく</rt></ruby> ／ 7 Prinsip Universal Design</strong>\n      </div>\n      <div class=\"ud-grid\">\n        <div class=\"ud-item\"><span class=\"ud-num\">1</span><ruby>誰<rt>だれ</rt></ruby>でも<ruby>公平<rt>こうへい</rt></ruby>に<ruby>利用<rt>りよう</rt></ruby>できる<br><span style=\"font-size:10px;opacity:.75;\">Dapat digunakan secara adil oleh semua orang</span></div>\n        <div class=\"ud-item\"><span class=\"ud-num\">2</span><ruby>使<rt>つか</rt></ruby>う<ruby>人<rt>ひと</rt></ruby>の<ruby>好<rt>この</rt></ruby>みや<ruby>能力<rt>のうりょく</rt></ruby>に<ruby>合<rt>あ</rt></ruby>うように<ruby>作<rt>つく</rt></ruby>られている<br><span style=\"font-size:10px;opacity:.75;\">Fleksibel sesuai kemampuan pengguna</span></div>\n        <div class=\"ud-item\"><span class=\"ud-num\">3</span><ruby>使<rt>つか</rt></ruby>い<ruby>方<rt>かた</rt></ruby>が<ruby>簡単<rt>かんたん</rt></ruby>ですぐわかる<br><span style=\"font-size:10px;opacity:.75;\">Mudah dipahami cara penggunaannya</span></div>\n        <div class=\"ud-item\"><span class=\"ud-num\">4</span><ruby>必要<rt>ひつよう</rt></ruby>な<ruby>情報<rt>じょうほう</rt></ruby>がすぐ<ruby>理解<rt>りかい</rt></ruby>できる<br><span style=\"font-size:10px;opacity:.75;\">Informasi yang diperlukan mudah dipahami</span></div>\n        <div class=\"ud-item\"><span class=\"ud-num\">5</span><ruby>簡単<rt>かんたん</rt></ruby>なミスが<ruby>危険<rt>きけん</rt></ruby>につながらないデザイン<br><span style=\"font-size:10px;opacity:.75;\">Toleransi terhadap kesalahan kecil</span></div>\n        <div class=\"ud-item\"><span class=\"ud-num\">6</span><ruby>身体<rt>しんたい</rt></ruby>への<ruby>過度<rt>かど</rt></ruby>な<ruby>負担<rt>ふたん</rt></ruby>がなく<ruby>楽<rt>らく</rt></ruby>に<ruby>使用<rt>しよう</rt></ruby>できる<br><span style=\"font-size:10px;opacity:.75;\">Bisa digunakan dengan sedikit tenaga fisik</span></div>\n        <div class=\"ud-item\" style=\"grid-column:1/-1;\"><span class=\"ud-num\">7</span><ruby>誰<rt>だれ</rt></ruby>にでも<ruby>使<rt>つか</rt></ruby>える<ruby>大<rt>おお</rt></ruby>きさと<ruby>広<rt>ひろ</rt></ruby>さが<ruby>確保<rt>かくほ</rt></ruby>されている<br><span style=\"font-size:10px;opacity:.75;\">Ukuran & ruang yang cukup untuk semua pengguna</span></div>\n      </div>\n\n      <!-- フランクル3つの価値 -->\n      <div class=\"hl hl-teal\" style=\"margin-top:14px;\">\n        <strong>フランクル（Frankl, V.）— 3つの<ruby>価値<rt>かち</rt></ruby> ／ 3 Nilai Manusia</strong>\n      </div>\n      <div class=\"grid3\" style=\"margin-top:8px;\">\n        <div class=\"node n-teal\" style=\"margin-bottom:0;\">\n          <div class=\"node-lbl\"><ruby>創造価値<rt>そうぞうかち</rt></ruby></div>\n          <div class=\"node-main\">何かを<ruby>創造<rt>そうぞう</rt></ruby>することで<ruby>実現<rt>じつげん</rt></ruby>される<ruby>価値<rt>かち</rt></ruby></div>\n          <div class=\"node-sub\">Nilai yang terwujud melalui kreasi/karya</div>\n        </div>\n        <div class=\"node n-blue\" style=\"margin-bottom:0;\">\n          <div class=\"node-lbl\"><ruby>体験価値<rt>たいけんかち</rt></ruby></div>\n          <div class=\"node-main\">何かを<ruby>体験<rt>たいけん</rt></ruby>することで<ruby>実現<rt>じつげん</rt></ruby>される<ruby>価値<rt>かち</rt></ruby></div>\n          <div class=\"node-sub\">Nilai yang terwujud melalui pengalaman</div>\n        </div>\n        <div class=\"node n-purple\" style=\"margin-bottom:0;\">\n          <div class=\"node-lbl\"><ruby>態度価値<rt>たいどかち</rt></ruby></div>\n          <div class=\"node-main\"><ruby>生命<rt>せいめい</rt></ruby>が<ruby>制限<rt>せいげん</rt></ruby>される<ruby>状況<rt>じょうきょう</rt></ruby>でいかなる<ruby>態度<rt>たいど</rt></ruby>をとるかで<ruby>実現<rt>じつげん</rt></ruby></div>\n          <div class=\"node-sub\">Nilai dari sikap saat menghadapi penderitaan/keterbatasan</div>\n        </div>\n      </div>\n\n      <!-- ケアの本質 -->\n      <div class=\"hl hl-green\" style=\"margin-top:14px;\">\n        <strong>ミルトン・メイヤロフ（Mayeroff, M.）— ケアの<ruby>本質<rt>ほんしつ</rt></ruby></strong><br>\n        <span style=\"font-size:12px;\">「一人の<ruby>人格<rt>じんかく</rt></ruby>をケアするとは、<ruby>最<rt>もっと</rt></ruby>も<ruby>深<rt>ふか</rt></ruby>い<ruby>意味<rt>いみ</rt></ruby>で、その<ruby>人<rt>ひと</rt></ruby>が<ruby>成長<rt>せいちょう</rt></ruby>すること、<ruby>自己実現<rt>じこじつげん</rt></ruby>することをたすけることである」</span><br>\n        <span style=\"font-size:11px;opacity:.7;\">Merawat seseorang artinya membantu mereka tumbuh & mengaktualisasikan diri</span>\n      </div>\n\n    </div></div>\n  </div>\n\n  <div class=\"arrow-down\">↓</div>\n\n  <!-- ===== SECTION 3: 人権運動の歴史 ===== -->\n  <div class=\"section th-green\" id=\"s3\">\n    <div class=\"sec-head\" onclick=\"toggle('s3')\">\n      <div class=\"sec-icon\">✊</div>\n      <div class=\"sec-title\">\n        <span class=\"jp\"><ruby>人権運動<rt>じんけんうんどう</rt></ruby>の<ruby>歴史<rt>れきし</rt></ruby></span>\n        <span class=\"id\">Sejarah Gerakan Hak Asasi Manusia</span>\n      </div>\n      <span class=\"toggle-arr\">▼</span>\n    </div>\n    <div class=\"sec-body\"><div class=\"sec-inner\">\n\n      <div class=\"timeline\">\n        <div class=\"tl-item\">\n          <span class=\"tl-year\">1960年代後半</span>\n          <div class=\"tl-title\">自立生活運動（ＩＬ運動）</div>\n          <div class=\"tl-text\">エド・ロバーツ（Roberts, E.）らによって始められた。障害者が自立生活の権利を主張した社会運動。<strong><ruby>障害者自身<rt>しょうがいしゃじしん</rt></ruby>の<ruby>選択<rt>せんたく</rt></ruby>と<ruby>自己決定<rt>じこけってい</rt></ruby>の<ruby>尊重<rt>そんちょう</rt></ruby></strong>を中心理念。<br>\n            <span style=\"opacity:.7;\">Gerakan hidup mandiri oleh penyandang disabilitas — mengutamakan pilihan & otonomi diri</span></div>\n        </div>\n        <div class=\"tl-item\">\n          <span class=\"tl-year\">1971年</span>\n          <div class=\"tl-title\"><ruby>知的障害者<rt>ちてきしょうがいしゃ</rt></ruby>の<ruby>権利宣言<rt>けんりせんげん</rt></ruby></div>\n          <div class=\"tl-text\">第26回<ruby>国連総会<rt>こくれんそうかい</rt></ruby>で採択。「知的障害者は、実際上可能な限りにおいて、<strong>他の人間と同等の権利を有する</strong>」<br>\n            <span style=\"opacity:.7;\">Sidang Umum PBB ke-26: penyandang disabilitas intelektual memiliki hak setara</span></div>\n        </div>\n        <div class=\"tl-item\">\n          <span class=\"tl-year\">1975年</span>\n          <div class=\"tl-title\"><ruby>障害者<rt>しょうがいしゃ</rt></ruby>の<ruby>権利宣言<rt>けんりせんげん</rt></ruby></div>\n          <div class=\"tl-text\">第30回<ruby>国連総会<rt>こくれんそうかい</rt></ruby>で採択。「障害者は、その障害の原因・特質・程度にかかわらず、<strong><ruby>同年齢<rt>どうねんれい</rt></ruby>の<ruby>市民<rt>しみん</rt></ruby>と<ruby>同等<rt>どうとう</rt></ruby>の<ruby>基本的権利<rt>きほんてきけんり</rt></ruby>を有する</strong>」<br>\n            <span style=\"opacity:.7;\">PBB ke-30: hak dasar yang sama terlepas dari jenis/tingkat disabilitas</span></div>\n        </div>\n        <div class=\"tl-item\">\n          <span class=\"tl-year\">1981年</span>\n          <div class=\"tl-title\"><ruby>国際障害者年<rt>こくさいしょうがいしゃねん</rt></ruby></div>\n          <div class=\"tl-text\">テーマ：障害者の<strong><ruby>完全参加<rt>かんぜんさんか</rt></ruby>と<ruby>平等<rt>びょうどう</rt></ruby></strong>。1983〜1992年を「<ruby>国連<rt>こくれん</rt></ruby>・障害者の十年」と宣言。<br>\n            <span style=\"opacity:.7;\">Tema: partisipasi penuh & kesetaraan. 1983-1992 dinyatakan \"Dekade Penyandang Disabilitas PBB\"</span></div>\n        </div>\n        <div class=\"tl-item\">\n          <span class=\"tl-year\">1990年</span>\n          <div class=\"tl-title\"><ruby>障害<rt>しょうがい</rt></ruby>をもつアメリカ人法（ADA）</div>\n          <div class=\"tl-text\">障害のある人の<ruby>社会参加<rt>しゃかいさんか</rt></ruby>を保障。公共施設・商業施設・交通機関の利用、<ruby>雇用<rt>こよう</rt></ruby>・教育での差別禁止を義務づけた。<br>\n            <span style=\"opacity:.7;\">Mewajibkan aksesibilitas & melarang diskriminasi di tempat umum, pekerjaan, pendidikan</span></div>\n        </div>\n        <div class=\"tl-item\">\n          <span class=\"tl-year\">2006年</span>\n          <div class=\"tl-title\"><ruby>障害者<rt>しょうがいしゃ</rt></ruby>の<ruby>権利<rt>けんり</rt></ruby>に<ruby>関<rt>かん</rt></ruby>する<ruby>条約<rt>じょうやく</rt></ruby></div>\n          <div class=\"tl-text\">\n            🇯🇵 <ruby>日本<rt>にほん</rt></ruby>は<strong>2014（平成26）年1月<ruby>批准<rt>ひじゅん</rt></ruby></strong><br>\n            「<strong>Nothing about us without us</strong>（私たち抜きに私たちのことを決めるな）」の考え方のもと、障害者が作成段階から関与。<br>\n            「<strong><ruby>合理的配慮<rt>ごうりてきはいりょ</rt></ruby></strong>」の概念が<ruby>国際条約上<rt>こくさいじょうやくじょう</rt></ruby>初めて取り上げられた。<br>\n            <span style=\"opacity:.7;\">Jepang meratifikasi 2014. Konsep \"akomodasi yang wajar\" pertama kali dalam perjanjian internasional</span>\n          </div>\n        </div>\n      </div>\n\n    </div></div>\n  </div>\n\n  <div class=\"arrow-down\">↓</div>\n\n  <!-- ===== SECTION 4: 日本国憲法 ===== -->\n  <div class=\"section th-blue\" id=\"s4\">\n    <div class=\"sec-head\" onclick=\"toggle('s4')\">\n      <div class=\"sec-icon\">📜</div>\n      <div class=\"sec-title\">\n        <span class=\"jp\"><ruby>日本国憲法<rt>にほんこくけんぽう</rt></ruby>と<ruby>基本的人権<rt>きほんてきじんけん</rt></ruby></span>\n        <span class=\"id\">Konstitusi Jepang & Hak Asasi Dasar</span>\n      </div>\n      <span class=\"toggle-arr\">▼</span>\n    </div>\n    <div class=\"sec-body\"><div class=\"sec-inner\">\n\n      <div class=\"hl hl-blue\">\n        🗓 <strong>1946（昭和21）年11月3日<ruby>公布<rt>こうふ</rt></ruby></strong><br>\n        <span style=\"font-size:12px;\"><ruby>国民主権<rt>こくみんしゅけん</rt></ruby>の<ruby>原則<rt>げんそく</rt></ruby>に<ruby>基<rt>もと</rt></ruby>づき「<ruby>個人<rt>こじん</rt></ruby>の<ruby>尊厳<rt>そんげん</rt></ruby>」を<ruby>基礎<rt>きそ</rt></ruby>に「<ruby>基本的人権の尊重<rt>きほんてきじんけんのそんちょう</rt></ruby>」を掲げる<br>\n        Berdasarkan kedaulatan rakyat, menjunjung \"martabat individu\" & \"penghormatan HAM dasar\"</span>\n      </div>\n\n      <!-- 憲法の権利一覧 -->\n      <div class=\"hl hl-blue\" style=\"margin-top:12px;\">\n        <strong><ruby>基本的人権<rt>きほんてきじんけん</rt></ruby>の<ruby>分類<rt>ぶんるい</rt></ruby> ／ Klasifikasi HAM Dasar</strong>\n      </div>\n      <div class=\"grid3\" style=\"margin-top:8px;\">\n        <div class=\"node n-purple\" style=\"margin-bottom:0;text-align:center;\">\n          <div class=\"node-main\"><ruby>包括的基本権<rt>ほうかつてききほんけん</rt></ruby></div>\n          <div class=\"node-sub\">Hak dasar yang menyeluruh</div>\n        </div>\n        <div class=\"node n-blue\" style=\"margin-bottom:0;text-align:center;\">\n          <div class=\"node-main\"><ruby>自由権<rt>じゆうけん</rt></ruby></div>\n          <div class=\"node-sub\">Hak kebebasan</div>\n        </div>\n        <div class=\"node n-green\" style=\"margin-bottom:0;text-align:center;\">\n          <div class=\"node-main\"><ruby>社会権<rt>しゃかいけん</rt></ruby></div>\n          <div class=\"node-sub\">Hak sosial</div>\n        </div>\n        <div class=\"node n-yellow\" style=\"margin-bottom:0;text-align:center;\">\n          <div class=\"node-main\"><ruby>平等権<rt>びょうどうけん</rt></ruby></div>\n          <div class=\"node-sub\">Hak kesetaraan</div>\n        </div>\n        <div class=\"node n-orange\" style=\"margin-bottom:0;text-align:center;\">\n          <div class=\"node-main\"><ruby>請求権<rt>せいきゅうけん</rt></ruby>・<ruby>受益権<rt>じゅえきけん</rt></ruby></div>\n          <div class=\"node-sub\">Hak klaim/manfaat</div>\n        </div>\n        <div class=\"node n-teal\" style=\"margin-bottom:0;text-align:center;\">\n          <div class=\"node-main\"><ruby>参政権<rt>さんせいけん</rt></ruby></div>\n          <div class=\"node-sub\">Hak berpartisipasi</div>\n        </div>\n      </div>\n\n      <!-- 主な条文 -->\n      <div class=\"hl hl-blue\" style=\"margin-top:14px;\"><strong><ruby>主<rt>おも</rt></ruby>な<ruby>条文<rt>じょうぶん</rt></ruby> ／ Pasal-Pasal Utama</strong></div>\n      <table class=\"tbl\">\n        <thead>\n          <tr style=\"background:#eef5fc;\">\n            <th style=\"width:40px;\"><ruby>条<rt>じょう</rt></ruby></th>\n            <th><ruby>内容<rt>ないよう</rt></ruby></th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td style=\"text-align:center;font-weight:900;color:#457b9d;\">11</td>\n            <td><ruby>基本的人権<rt>きほんてきじんけん</rt></ruby>の<ruby>享有<rt>きょうゆう</rt></ruby>：<ruby>侵<rt>おか</rt></ruby>すことのできない<strong><ruby>永久<rt>えいきゅう</rt></ruby>の<ruby>権利<rt>けんり</rt></ruby></strong>として<ruby>現在及<rt>げんざいおよ</rt></ruby>び<ruby>将来<rt>しょうらい</rt></ruby>の<ruby>国民<rt>こくみん</rt></ruby>に<ruby>与<rt>あた</rt></ruby>えられる<br><span style=\"font-size:10px;opacity:.7;\">HAM yang tidak dapat dilanggar, diberikan kepada rakyat masa kini & mendatang</span></td>\n          </tr>\n          <tr>\n            <td style=\"text-align:center;font-weight:900;color:#457b9d;\">13</td>\n            <td><ruby>個人<rt>こじん</rt></ruby>の<ruby>尊重<rt>そんちょう</rt></ruby>・<ruby>生命<rt>せいめい</rt></ruby>・<ruby>自由<rt>じゆう</rt></ruby>・<ruby>幸福追求<rt>こうふくついきゅう</rt></ruby>の<ruby>権利<rt>けんり</rt></ruby>：<ruby>公共<rt>こうきょう</rt></ruby>の<ruby>福祉<rt>ふくし</rt></ruby>に<ruby>反<rt>はん</rt></ruby>しない<ruby>限<rt>かぎ</rt></ruby>り<ruby>最大限尊重<rt>さいだいげんそんちょう</rt></ruby><br><span style=\"font-size:10px;opacity:.7;\">Hak atas kehidupan, kebebasan & mengejar kebahagiaan dihormati seluas-luasnya</span></td>\n          </tr>\n          <tr>\n            <td style=\"text-align:center;font-weight:900;color:#457b9d;\">14</td>\n            <td><ruby>法<rt>ほう</rt></ruby>の<ruby>下<rt>もと</rt></ruby>の<ruby>平等<rt>びょうどう</rt></ruby>：<ruby>人種<rt>じんしゅ</rt></ruby>・<ruby>信条<rt>しんじょう</rt></ruby>・<ruby>性別<rt>せいべつ</rt></ruby>・<ruby>社会的身分<rt>しゃかいてきみぶん</rt></ruby>などによる<ruby>差別<rt>さべつ</rt></ruby>禁止<br><span style=\"font-size:10px;opacity:.7;\">Kesetaraan di hadapan hukum; larangan diskriminasi berdasarkan ras, kepercayaan, gender, dll.</span></td>\n          </tr>\n          <tr>\n            <td style=\"text-align:center;font-weight:900;color:#457b9d;\">19</td>\n            <td><ruby>思想<rt>しそう</rt></ruby>及び<ruby>良心<rt>りょうしん</rt></ruby>の<ruby>自由<rt>じゆう</rt></ruby>：これを<ruby>侵<rt>おか</rt></ruby>してはならない<br><span style=\"font-size:10px;opacity:.7;\">Kebebasan berpikir & berkeyakinan tidak boleh dilanggar</span></td>\n          </tr>\n          <tr>\n            <td style=\"text-align:center;font-weight:900;color:#457b9d;\">24</td>\n            <td><ruby>家族生活<rt>かぞくせいかつ</rt></ruby>における<ruby>個人<rt>こじん</rt></ruby>の<ruby>尊厳<rt>そんげん</rt></ruby>と<ruby>両性<rt>りょうせい</rt></ruby>の<ruby>平等<rt>びょうどう</rt></ruby>：<ruby>婚姻<rt>こんいん</rt></ruby>は<ruby>両性<rt>りょうせい</rt></ruby>の<ruby>合意<rt>ごうい</rt></ruby>のみに<ruby>基<rt>もと</rt></ruby>づく<br><span style=\"font-size:10px;opacity:.7;\">Pernikahan berdasarkan persetujuan kedua pihak; kesetaraan esensial antara suami-istri</span></td>\n          </tr>\n          <tr style=\"background:#f0faf5;\">\n            <td style=\"text-align:center;font-weight:900;color:#c1121f;\">25</td>\n            <td>\n              <strong><ruby>生存権<rt>せいぞんけん</rt></ruby>・<ruby>国<rt>くに</rt></ruby>の<ruby>生存権保障義務<rt>せいぞんけんほしょうぎむ</rt></ruby></strong><br>\n              すべて<ruby>国民<rt>こくみん</rt></ruby>は、<ruby>健康<rt>けんこう</rt></ruby>で<ruby>文化的<rt>ぶんかてき</rt></ruby>な<ruby>最低限度<rt>さいていげんど</rt></ruby>の<ruby>生活<rt>せいかつ</rt></ruby>を<ruby>営<rt>いとな</rt></ruby>む<ruby>権利<rt>けんり</rt></ruby>を有する<br>\n              <span style=\"font-size:10px;opacity:.7;\">Setiap warga berhak atas kehidupan yang sehat & bermartabat pada tingkat minimum</span><br><br>\n              <strong>📋 <ruby>判例<rt>はんれい</rt></ruby>：</strong><br>\n              🔵 <ruby>朝日訴訟<rt>あさひそしょう</rt></ruby>：<ruby>生活扶助基準<rt>せいかつふじょきじゅん</rt></ruby>が最低限度の生活を維持できない<ruby>違憲<rt>いけん</rt></ruby>・<ruby>違法<rt>いほう</rt></ruby>かを争った「<ruby>人間裁判<rt>にんげんさいばん</rt></ruby>」<br>\n              🔵 <ruby>堀木訴訟<rt>ほりきそしょう</rt></ruby>：<ruby>障害福祉年金<rt>しょうがいふくしねんきん</rt></ruby>と<ruby>児童扶養手当<rt>じどうふようてあて</rt></ruby>の<ruby>併給<rt>へいきゅう</rt></ruby>禁止が<ruby>違法<rt>いほう</rt></ruby>かを争った裁判<br>\n              <span style=\"font-size:10px;opacity:.7;\">Kasus Asahi: apakah standar bantuan hidup terlalu rendah? | Kasus Horiki: larangan tunjangan ganda</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n    </div></div>\n  </div>\n\n  <div class=\"arrow-down\">↓</div>\n\n  <!-- ===== SECTION 5: 成年後見制度 vs 日常生活自立支援事業 ===== -->\n  <div class=\"section th-orange\" id=\"s5\">\n    <div class=\"sec-head\" onclick=\"toggle('s5')\">\n      <div class=\"sec-icon\">⚖️</div>\n      <div class=\"sec-title\">\n        <span class=\"jp\"><ruby>成年後見制度<rt>せいねんこうけんせいど</rt></ruby> vs <ruby>日常生活自立支援事業<rt>にちじょうせいかつじりつしえんじぎょう</rt></ruby></span>\n        <span class=\"id\">Perbandingan: Perwalian Dewasa vs Layanan Kemandirian Hidup Sehari-hari</span>\n      </div>\n      <span class=\"toggle-arr\">▼</span>\n    </div>\n    <div class=\"sec-body\"><div class=\"sec-inner\">\n\n      <div style=\"overflow-x:auto;\">\n      <table class=\"cmp-table\">\n        <thead>\n          <tr>\n            <th style=\"background:#f3f4f6;width:90px;\"></th>\n            <th class=\"head-left\"><ruby>成年後見制度<rt>せいねんこうけんせいど</rt></ruby><br><span style=\"font-weight:400;font-size:10px;\">Sistem Perwalian Dewasa</span></th>\n            <th class=\"head-right\"><ruby>日常生活自立支援事業<rt>にちじょうせいかつじりつしえんじぎょう</rt></ruby><br><span style=\"font-weight:400;font-size:10px;\">Layanan Kemandirian Hidup Sehari-hari</span></th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td class=\"row-lbl\"><ruby>法律<rt>ほうりつ</rt></ruby></td>\n            <td><ruby>民法<rt>みんぽう</rt></ruby></td>\n            <td><ruby>社会福祉法<rt>しゃかいふくしほう</rt></ruby></td>\n          </tr>\n          <tr>\n            <td class=\"row-lbl\"><ruby>管轄<rt>かんかつ</rt></ruby></td>\n            <td><ruby>法務省<rt>ほうむしょう</rt></ruby></td>\n            <td><ruby>厚生労働省<rt>こうせいろうどうしょう</rt></ruby></td>\n          </tr>\n          <tr>\n            <td class=\"row-lbl\"><ruby>機関<rt>きかん</rt></ruby></td>\n            <td>🏛 <ruby>家庭裁判所<rt>かていさいばんしょ</rt></ruby></td>\n            <td>🏢 <ruby>都道府県<rt>とどうふけん</rt></ruby>・指定都市<ruby>社会福祉協議会<rt>しゃかいふくしきょうぎかい</rt></ruby></td>\n          </tr>\n          <tr>\n            <td class=\"row-lbl\"><ruby>対象者<rt>たいしょうしゃ</rt></ruby></td>\n            <td>\n              <ruby>認知症高齢者<rt>にんちしょうこうれいしゃ</rt></ruby>・<ruby>知的障害者<rt>ちてきしょうがいしゃ</rt></ruby>・<ruby>精神障害者<rt>せいしんしょうがいしゃ</rt></ruby>など<br>\n              <span style=\"font-size:10px;color:#c1121f;\">後見：<ruby>判断能力<rt>はんだんのうりょく</rt></ruby>を欠く常時ある者</span><br>\n              <span style=\"font-size:10px;color:#e76f51;\">保佐：判断能力が著しく不十分な者</span><br>\n              <span style=\"font-size:10px;color:#457b9d;\">補助：判断能力が不十分な者</span>\n            </td>\n            <td>判断能力が<ruby>不十分<rt>ふじゅうぶん</rt></ruby>な者で、本事業の<strong><ruby>契約<rt>けいやく</rt></ruby>の内容について判断し得る能力を有している</strong>と認められる者<br>\n              <span style=\"font-size:10px;opacity:.7;\">Orang yang kemampuan keputusannya kurang namun masih dapat memahami isi kontrak</span>\n            </td>\n          </tr>\n          <tr>\n            <td class=\"row-lbl\"><ruby>手続<rt>てつづ</rt></ruby>き</td>\n            <td><ruby>家庭裁判所<rt>かていさいばんしょ</rt></ruby>に申立て<br>（本人・配偶者・4親等以内の親族・検察官・市町村長など）<br>\n              <span style=\"font-size:10px;color:#c1121f;\">※後見・保佐は本人同意不要、補助は必要</span></td>\n            <td><ruby>市町村社会福祉協議会<rt>しちょうそんしゃかいふくしきょうぎかい</rt></ruby>に<ruby>相談<rt>そうだん</rt></ruby>・<ruby>申込<rt>もうしこみ</rt></ruby><br>\n              ※本人と社会福祉協議会との<strong>契約</strong></td>\n          </tr>\n          <tr>\n            <td class=\"row-lbl\"><ruby>援助者<rt>えんじょしゃ</rt></ruby></td>\n            <td><ruby>後見人<rt>こうけんにん</rt></ruby>・<ruby>保佐人<rt>ほさにん</rt></ruby>・<ruby>補助人<rt>ほじょにん</rt></ruby>・<ruby>任意後見人<rt>にんいこうけんにん</rt></ruby></td>\n            <td><ruby>専門員<rt>せんもんいん</rt></ruby>・<ruby>生活支援員<rt>せいかつしえんいん</rt></ruby></td>\n          </tr>\n          <tr>\n            <td class=\"row-lbl\"><ruby>援助内容<rt>えんじょないよう</rt></ruby></td>\n            <td>\n              ●<ruby>財産管理<rt>ざいさんかんり</rt></ruby>（アパート家賃の管理、印鑑や通帳の管理、不動産の売却、遺産分割など）<br>\n              ●<ruby>身上監護<rt>しんじょうかんご</rt></ruby>（入院・施設の入退所の契約、介護サービスの契約・費用の支払い）\n            </td>\n            <td>\n              ●<ruby>日常的金銭管理<rt>にちじょうてききんせんかんり</rt></ruby>（公共料金・税金・医療費・福祉サービス利用料の支払い手続き）<br>\n              ●<ruby>書類等預かりサービス<rt>しょるいとうあずかりサービス</rt></ruby>（預貯金通帳50万円以内・銀行印の預かりなど）<br>\n              ●<ruby>福祉サービスの利用援助<rt>ふくしサービスのりようえんじょ</rt></ruby>\n            </td>\n          </tr>\n          <tr>\n            <td class=\"row-lbl\"><ruby>費用<rt>ひよう</rt></ruby></td>\n            <td>本人の財産から支弁<br><span style=\"font-size:10px;opacity:.7;\">Diambil dari aset pribadi</span></td>\n            <td><ruby>契約締結<rt>けいやくていけつ</rt></ruby>までは<ruby>公費<rt>こうひ</rt></ruby>負担、締結後は<ruby>利用者<rt>りようしゃ</rt></ruby>負担<br><span style=\"font-size:10px;opacity:.7;\">Sebelum kontrak = ditanggung publik; setelahnya = ditanggung pengguna</span></td>\n          </tr>\n        </tbody>\n      </table>\n      </div>\n\n      <div class=\"hl hl-orange\" style=\"margin-top:14px;\">\n        💡 <strong>ポイント ／ Poin Penting</strong><br>\n        <span style=\"font-size:12px;\">\n          ・<ruby>成年後見<rt>せいねんこうけん</rt></ruby>：<ruby>判断能力<rt>はんだんのうりょく</rt></ruby>が<ruby>低下<rt>ていか</rt></ruby>した<ruby>人<rt>ひと</rt></ruby>の<ruby>財産<rt>ざいさん</rt></ruby>・<ruby>身上<rt>みのうえ</rt></ruby>を<ruby>法的<rt>ほうてき</rt></ruby>に<ruby>守<rt>まも</rt></ruby>る → <ruby>家庭裁判所<rt>かていさいばんしょ</rt></ruby>が<ruby>関与<rt>かんよ</rt></ruby><br>\n          Perwalian dewasa: melindungi aset & fisik orang yang kemampuannya menurun → melibatkan pengadilan<br><br>\n          ・<ruby>日常生活自立支援<rt>にちじょうせいかつじりつしえん</rt></ruby>：<ruby>日常的<rt>にちじょうてき</rt></ruby>なお<ruby>金<rt>かね</rt></ruby>の<ruby>管理<rt>かんり</rt></ruby>や<ruby>福祉<rt>ふくし</rt></ruby>サービス<ruby>利用<rt>りよう</rt></ruby>の<ruby>支援<rt>しえん</rt></ruby> → <ruby>社会福祉協議会<rt>しゃかいふくしきょうぎかい</rt></ruby>が<ruby>担当<rt>たんとう</rt></ruby><br>\n          Layanan kemandirian: mendukung pengelolaan uang harian & layanan sosial → ditangani Dewan Kesejahteraan Sosial\n        </span>\n      </div>\n\n    </div></div>\n  </div>\n\n  <div style=\"text-align:center;margin-top:28px;font-size:11px;color:#2d6a4f;opacity:.65;\">\n    出典：厚生労働省・法務省資料（令和6年）<br>\n    Sumber: Kementerian Kesehatan & Kementerian Kehakiman Jepang\n  </div>\n</main>\n\n<script>\n  function toggle(id){\n    document.getElementById(id).classList.toggle('open');\n  }\n<\/script>\n</body>\n</html>\n","songen-4":"<!DOCTYPE html>\n<html lang=\"ja\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>第2節④ — 権利擁護（詳細）</title>\n<link href=\"https://fonts.googleapis.com/css2?family=Noto+Sans+JP:wght@300;400;500;700;900&family=Noto+Serif+JP:wght@400;700&display=swap\" rel=\"stylesheet\">\n<style>\n  :root {\n    --g1:#1b4332;--g2:#2d6a4f;--g3:#52b788;--gp:#d8f3dc;\n    --b1:#1d3557;--b2:#457b9d;--bp:#dce9f7;\n    --o1:#9e4a1e;--o2:#e76f51;--op:#fde4d8;\n    --y1:#7a5000;--y2:#f4a261;--yp:#fff3cd;\n    --p1:#3d2060;--p2:#6d597a;--pp:#ece5f5;\n    --t1:#0d4a44;--t2:#2a9d8f;--tp:#d5f5f2;\n    --r1:#7a0c13;--r2:#c1121f;--rp:#fce0e2;\n    --tx:#1b1b2f;\n  }\n  *{margin:0;padding:0;box-sizing:border-box;}\n  body{font-family:'Noto Sans JP',sans-serif;background:#eef4f0;color:var(--tx);min-height:100vh;}\n\n  header{background:linear-gradient(135deg,#7a3010 0%,#c1121f 55%,#e76f51 100%);\n    padding:34px 20px 26px;text-align:center;position:relative;overflow:hidden;}\n  header::before{content:'';position:absolute;top:-50px;right:-50px;\n    width:200px;height:200px;border-radius:50%;background:rgba(255,255,255,0.06);}\n  .hbadge{display:inline-block;background:rgba(255,255,255,0.15);border:1px solid rgba(255,255,255,0.3);\n    color:#fff;font-size:11px;letter-spacing:2px;padding:4px 14px;border-radius:20px;margin-bottom:10px;}\n  header h1{font-family:'Noto Serif JP',serif;color:#fff;\n    font-size:clamp(17px,5vw,29px);font-weight:700;line-height:1.45;margin-bottom:6px;}\n  header p{color:rgba(255,255,255,0.75);font-size:12px;}\n\n  main{max-width:820px;margin:0 auto;padding:26px 14px 60px;}\n  .intro-label{text-align:center;font-size:12px;color:#2d6a4f;margin-bottom:16px;letter-spacing:1px;font-weight:700;}\n\n  .section{margin-bottom:20px;animation:fadeUp .5s ease both;}\n  .section:nth-child(1){animation-delay:.05s}.section:nth-child(2){animation-delay:.10s}\n  .section:nth-child(3){animation-delay:.15s}.section:nth-child(4){animation-delay:.20s}\n  .section:nth-child(5){animation-delay:.25s}\n  @keyframes fadeUp{from{opacity:0;transform:translateY(16px)}to{opacity:1;transform:translateY(0)}}\n\n  .sec-head{display:flex;align-items:center;gap:12px;padding:13px 16px;\n    border-radius:13px 13px 0 0;cursor:pointer;user-select:none;transition:filter .2s;}\n  .sec-head:hover{filter:brightness(1.07)}\n  .sec-icon{width:36px;height:36px;border-radius:50%;background:rgba(255,255,255,0.2);\n    display:flex;align-items:center;justify-content:center;font-size:17px;flex-shrink:0;}\n  .sec-title .jp{font-size:16px;font-weight:700;color:#fff;display:block;}\n  .sec-title .id{font-size:11px;color:rgba(255,255,255,.73);display:block;margin-top:1px;}\n  .toggle-arr{color:rgba(255,255,255,.8);font-size:13px;margin-left:auto;transition:transform .3s;}\n  .section.open .toggle-arr{transform:rotate(180deg);}\n\n  .sec-body{background:#fff;border-radius:0 0 13px 13px;\n    border:1px solid #ddd;border-top:none;overflow:hidden;max-height:0;transition:max-height .45s ease;}\n  .section.open .sec-body{max-height:6000px;}\n  .sec-inner{padding:18px 16px 22px;}\n\n  .th-red   .sec-head{background:linear-gradient(90deg,#7a0c13,#c1121f);}\n  .th-orange.sec-head,.th-orange .sec-head{background:linear-gradient(90deg,#9e4a1e,#e76f51);}\n  .th-green .sec-head{background:linear-gradient(90deg,#1b4332,#2d6a4f);}\n  .th-blue  .sec-head{background:linear-gradient(90deg,#1d3557,#457b9d);}\n  .th-purple.sec-head,.th-purple .sec-head{background:linear-gradient(90deg,#3d2060,#6d597a);}\n  .th-teal  .sec-head{background:linear-gradient(90deg,#0d4a44,#2a9d8f);}\n\n  .node{border-radius:10px;padding:10px 13px;margin-bottom:8px;}\n  .node-lbl{font-size:10px;font-weight:700;letter-spacing:1px;opacity:.6;margin-bottom:4px;text-transform:uppercase;}\n  .node-main{font-size:14px;font-weight:700;line-height:1.45;}\n  .node-sub{font-size:11.5px;margin-top:4px;line-height:1.55;opacity:.82;}\n  .node-id{font-size:11px;margin-top:5px;padding-top:5px;border-top:1px dashed currentColor;opacity:.6;}\n\n  .n-green {background:#d8f3dc;color:#1b4332;}\n  .n-blue  {background:#dce9f7;color:#1d3557;}\n  .n-yellow{background:#fff3cd;color:#7a5000;}\n  .n-orange{background:#fde4d8;color:#7a2a10;}\n  .n-red   {background:#fce0e2;color:#7a0c13;}\n  .n-purple{background:#ece5f5;color:#3d2060;}\n  .n-teal  {background:#d5f5f2;color:#0d4a44;}\n  .n-gray  {background:#f3f4f6;color:#374151;}\n\n  .flow-conn{height:14px;display:flex;justify-content:flex-start;padding-left:24px;}\n  .flow-conn::before{content:'';width:2px;background:#b7d5c8;display:block;}\n\n  .hl{border-left:4px solid;padding:10px 13px;border-radius:0 10px 10px 0;\n    margin-top:10px;margin-bottom:10px;font-size:13px;line-height:1.6;}\n  .hl-green {border-color:#2d6a4f;background:#f0faf5;color:#1b4332;}\n  .hl-blue  {border-color:#457b9d;background:#eef5fc;color:#1d3557;}\n  .hl-orange{border-color:#e76f51;background:#fef5f2;color:#7a2a10;}\n  .hl-purple{border-color:#6d597a;background:#f5f0fb;color:#3d2060;}\n  .hl-teal  {border-color:#2a9d8f;background:#f0fbfa;color:#0d4a44;}\n  .hl-red   {border-color:#c1121f;background:#fef0f1;color:#7a0c13;}\n\n  .grid2{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:8px;}\n  .grid3{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-top:8px;}\n  @media(max-width:520px){.grid2,.grid3{grid-template-columns:1fr;}}\n\n  .tbl{width:100%;border-collapse:collapse;font-size:12px;margin-top:10px;}\n  .tbl th{padding:7px 9px;text-align:left;font-size:11px;font-weight:700;letter-spacing:.4px;border-bottom:2px solid #e0e0e0;}\n  .tbl td{padding:7px 9px;border-bottom:1px solid #f0f0f0;vertical-align:top;line-height:1.5;}\n  .tbl tr:last-child td{border-bottom:none;}\n\n  /* 3-level compare */\n  .cmp3{width:100%;border-collapse:collapse;font-size:12px;margin-top:10px;}\n  .cmp3 th{padding:7px 9px;font-size:11px;font-weight:700;border:1px solid #e0e0e0;text-align:center;}\n  .cmp3 td{padding:7px 9px;border:1px solid #efefef;vertical-align:top;line-height:1.5;font-size:12px;}\n  .cmp3 .row-lbl{background:#f5f5f5;font-weight:700;font-size:11px;text-align:center;color:#374151;}\n  .th-koken{background:#e8d5f5;color:#3d2060;}\n  .th-hosa {background:#fff3cd;color:#7a5000;}\n  .th-hojo {background:#d8f3dc;color:#1b4332;}\n\n  /* flow diagram */\n  .flow-diagram{background:#f8fcf9;border:1px solid #d4e8dc;border-radius:12px;padding:16px;margin-top:12px;}\n  .fd-row{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:8px;justify-content:center;}\n  .fd-box{border-radius:8px;padding:8px 12px;font-size:12px;font-weight:700;text-align:center;line-height:1.4;}\n  .fd-arrow{font-size:18px;color:#90c4a8;flex-shrink:0;}\n  .fd-label{font-size:10px;font-weight:700;color:#2d6a4f;text-align:center;margin-bottom:4px;}\n\n  /* stat badges */\n  .stat-row{display:flex;flex-wrap:wrap;gap:8px;margin-top:10px;}\n  .stat-b{border-radius:10px;padding:10px 12px;min-width:80px;text-align:center;}\n  .stat-b .sn{font-size:18px;font-weight:900;display:block;line-height:1.1;}\n  .stat-b .sl{font-size:10px;opacity:.7;display:block;margin-top:3px;}\n\n  .arrow-down{text-align:center;font-size:20px;color:#a0c4b0;margin:6px 0;}\n\n  ruby rt{font-size:9px;color:#2d6a4f;line-height:1;}\n\n  /* complaint flow */\n  .complaint-flow{display:flex;flex-direction:column;gap:6px;margin-top:10px;}\n  .cf-item{display:flex;align-items:stretch;gap:0;border-radius:10px;overflow:hidden;}\n  .cf-who{background:#2d6a4f;color:#fff;padding:8px 12px;font-size:12px;font-weight:700;\n    display:flex;align-items:center;min-width:110px;flex-shrink:0;}\n  .cf-what{padding:8px 12px;font-size:12px;line-height:1.5;flex:1;}\n</style>\n<style id=\"pk-fix\">\n.sec-body{max-height:none!important;overflow:visible!important;display:none;transition:none!important}\n.section.open .sec-body{display:block}\n.section{animation:none!important;opacity:1!important;transform:none!important}\n*{min-width:0}\nbody{overflow-x:hidden;-webkit-text-size-adjust:100%}\nmain{padding-left:10px!important;padding-right:10px!important}\np,div,span,td,th,li{overflow-wrap:anywhere;word-break:normal}\nimg,svg,video{max-width:100%;height:auto}\ntable{display:block;max-width:100%;overflow-x:auto;-webkit-overflow-scrolling:touch;border-collapse:collapse}\n@media (max-width:560px){\n [class*=\"grid\"],[class*=\"cols\"],[class*=\"compare\"],[class*=\"pair\"],[class*=\"two\"],[class*=\"stats\"]{grid-template-columns:1fr 1fr!important}\n [class*=\"grid3\"],[class*=\"grid-3\"],[class*=\"three\"]{grid-template-columns:1fr!important}\n [class*=\"row\"],[class*=\"flex\"],[class*=\"flow\"],[class*=\"chain\"]{flex-wrap:wrap!important}\n [class*=\"compare\"] > *,[class*=\"pair\"] > *{min-width:0}\n}\n</style>\n<script>\n(function(){\n function post(){try{parent.postMessage({pkH:Math.ceil(document.documentElement.scrollHeight)},'*');}catch(e){}}\n document.addEventListener('DOMContentLoaded',function(){\n  document.querySelectorAll('.section').forEach(function(s,i){ if(i===0) s.classList.add('open'); });\n  post();\n  if(window.ResizeObserver) new ResizeObserver(post).observe(document.body);\n  document.addEventListener('click',function(){setTimeout(post,30);setTimeout(post,400);});\n });\n window.addEventListener('load',post);\n})();\n<\/script></head>\n<body>\n\n<header>\n  <div class=\"hbadge\">第2節④ — まとめ（詳細）</div>\n  <h1><ruby>権利擁護<rt>けんりようご</rt></ruby>（<ruby>詳細<rt>しょうさい</rt></ruby>）<br>\n    <span style=\"font-size:.62em;font-weight:400;\">Perlindungan Hak — Detail Lengkap</span>\n  </h1>\n  <p>タップして各テーマを開く ／ Ketuk untuk membuka setiap topik</p>\n</header>\n\n<main>\n  <div class=\"intro-label\">▼ 順番に読もう ／ Baca Secara Berurutan ▼</div>\n\n  <!-- ===== SECTION 1: 成年後見制度（法定） ===== -->\n  <div class=\"section th-red open\" id=\"s1\">\n    <div class=\"sec-head\" onclick=\"toggle('s1')\">\n      <div class=\"sec-icon\">⚖️</div>\n      <div class=\"sec-title\">\n        <span class=\"jp\"><ruby>法定後見制度<rt>ほうていこうけんせいど</rt></ruby>：後見・保佐・補助</span>\n        <span class=\"id\">Perwalian Hukum: Kouken / Hosa / Hojo</span>\n      </div>\n      <span class=\"toggle-arr\">▼</span>\n    </div>\n    <div class=\"sec-body\"><div class=\"sec-inner\">\n\n      <div class=\"hl hl-red\">\n        📌 <strong><ruby>成年後見制度<rt>せいねんこうけんせいど</rt></ruby>とは ／ Tentang Sistem Perwalian Dewasa</strong><br>\n        <span style=\"font-size:12px;\"><ruby>精神上<rt>せいしんじょう</rt></ruby>の<ruby>障害<rt>しょうがい</rt></ruby>により<ruby>判断能力<rt>はんだんのうりょく</rt></ruby>が<ruby>不十分<rt>ふじゅうぶん</rt></ruby>なために<ruby>法律行為<rt>ほうりつこうい</rt></ruby>の<ruby>意思決定<rt>いしけってい</rt></ruby>が<ruby>困難<rt>こんなん</rt></ruby>な<ruby>人<rt>ひと</rt></ruby>を<ruby>後見人<rt>こうけんにん</rt></ruby>などが<ruby>保護<rt>ほご</rt></ruby>する<ruby>制度<rt>せいど</rt></ruby><br>\n        申立て先：<strong><ruby>家庭裁判所<rt>かていさいばんしょ</rt></ruby></strong>。家庭裁判所は<ruby>職権<rt>しょっけん</rt></ruby>で<ruby>法定後見人<rt>ほうていこうけんにん</rt></ruby>や<ruby>法定後見監督人<rt>ほうていこうけんかんとくにん</rt></ruby>を<ruby>選任<rt>せんにん</rt></ruby>する<br>\n        <span style=\"opacity:.7;\">Sistem perlindungan orang yang sulit mengambil keputusan hukum karena gangguan jiwa; ajukan ke Pengadilan Keluarga</span></span>\n      </div>\n\n      <!-- 3-way comparison -->\n      <div style=\"overflow-x:auto;\">\n      <table class=\"cmp3\">\n        <thead>\n          <tr>\n            <th style=\"background:#f5f5f5;width:90px;\"></th>\n            <th class=\"th-koken\">後見（<ruby>こうけん<rt></rt></ruby>）<br><span style=\"font-weight:400;font-size:10px;\">Perwalian Penuh</span></th>\n            <th class=\"th-hosa\">保佐（<ruby>ほさ<rt></rt></ruby>）<br><span style=\"font-weight:400;font-size:10px;\">Pendamping Hukum</span></th>\n            <th class=\"th-hojo\">補助（<ruby>ほじょ<rt></rt></ruby>）<br><span style=\"font-weight:400;font-size:10px;\">Asisten Hukum</span></th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td class=\"row-lbl\"><ruby>対象<rt>たいしょう</rt></ruby></td>\n            <td><ruby>判断能力<rt>はんだんのうりょく</rt></ruby>を<ruby>欠<rt>か</rt></ruby>く<ruby>常況<rt>じょうきょう</rt></ruby>にある者<br><span style=\"font-size:10px;opacity:.7;\">Selalu tidak mampu menentukan keputusan</span></td>\n            <td><ruby>判断能力<rt>はんだんのうりょく</rt></ruby>が<strong>著しく不十分</strong>な者<br><span style=\"font-size:10px;opacity:.7;\">Kemampuan keputusan sangat kurang</span></td>\n            <td><ruby>判断能力<rt>はんだんのうりょく</rt></ruby>が<strong>不十分</strong>な者<br><span style=\"font-size:10px;opacity:.7;\">Kemampuan keputusan kurang</span></td>\n          </tr>\n          <tr>\n            <td class=\"row-lbl\"><ruby>名称<rt>めいしょう</rt></ruby></td>\n            <td><ruby>成年後見人<rt>せいねんこうけんにん</rt></ruby></td>\n            <td><ruby>保佐人<rt>ほさにん</rt></ruby></td>\n            <td><ruby>補助人<rt>ほじょにん</rt></ruby></td>\n          </tr>\n          <tr>\n            <td class=\"row-lbl\"><ruby>代理権<rt>だいりけん</rt></ruby></td>\n            <td><ruby>財産<rt>ざいさん</rt></ruby>に<ruby>関<rt>かん</rt></ruby>する<ruby>すべての<rt></rt></ruby><ruby>法律行為<rt>ほうりつこうい</rt></ruby></td>\n            <td colspan=\"2\"><ruby>申立<rt>もうしたて</rt></ruby>ての<ruby>範囲内<rt>はんいない</rt></ruby>で<ruby>家庭裁判所<rt>かていさいばんしょ</rt></ruby>が<ruby>定<rt>さだ</rt></ruby>める「<strong><ruby>特定<rt>とくてい</rt></ruby>の<ruby>法律行為<rt>ほうりつこうい</rt></ruby></strong>」</td>\n          </tr>\n          <tr>\n            <td class=\"row-lbl\"><ruby>本人同意<rt>ほんにんどうい</rt></ruby></td>\n            <td style=\"text-align:center;font-size:13px;color:#c1121f;font-weight:700;\">不要</td>\n            <td style=\"text-align:center;font-size:13px;color:#c1121f;font-weight:700;\">不要</td>\n            <td style=\"text-align:center;font-size:13px;color:#2d6a4f;font-weight:700;\">必要</td>\n          </tr>\n        </tbody>\n      </table>\n      </div>\n\n      <!-- 申立てできる人 -->\n      <div class=\"hl hl-purple\" style=\"margin-top:12px;\">\n        <strong><ruby>申立<rt>もうしたて</rt></ruby>てができる<ruby>人<rt>ひと</rt></ruby> ／ Yang Bisa Mengajukan</strong><br>\n        <span style=\"font-size:12px;\"><ruby>本人<rt>ほんにん</rt></ruby>・<ruby>配偶者<rt>はいぐうしゃ</rt></ruby>・4<ruby>親等以内<rt>しんとういない</rt></ruby>の<ruby>親族<rt>しんぞく</rt></ruby>・<ruby>検察官<rt>けんさつかん</rt></ruby>・<strong><ruby>市町村長<rt>しちょうそんちょう</rt></ruby></strong>など<br>\n        Bisa diajukan oleh: diri sendiri, pasangan, kerabat s.d. tingkat ke-4, jaksa, kepala kota/desa</span>\n      </div>\n\n      <!-- 後見人の職務 -->\n      <div class=\"hl hl-blue\" style=\"margin-top:10px;\">\n        <strong><ruby>後見人<rt>こうけんにん</rt></ruby>の<ruby>職務<rt>しょくむ</rt></ruby> ／ Tugas Wali</strong>\n      </div>\n      <div class=\"grid2\" style=\"margin-top:8px;\">\n        <div class=\"node n-blue\">\n          <div class=\"node-lbl\"><ruby>財産管理<rt>ざいさんかんり</rt></ruby> ／ Manajemen Aset</div>\n          <div class=\"node-main\"><ruby>本人<rt>ほんにん</rt></ruby>のために<ruby>財産<rt>ざいさん</rt></ruby>を<ruby>管理<rt>かんり</rt></ruby>する</div>\n          <div class=\"node-sub\">Mengelola aset atas nama orang yang diwalikan</div>\n        </div>\n        <div class=\"node n-orange\">\n          <div class=\"node-lbl\"><ruby>身上監護<rt>しんじょうかんご</rt></ruby>（<ruby>身上保護<rt>しんじょうほご</rt></ruby>）</div>\n          <div class=\"node-main\"><ruby>介護契約<rt>かいごけいやく</rt></ruby>や<ruby>入院契約<rt>にゅういんけいやく</rt></ruby>の<ruby>代行<rt>だいこう</rt></ruby></div>\n          <div class=\"node-sub\" style=\"color:#c1121f;font-weight:700;\">⚠️ <ruby>介護行為<rt>かいごこうい</rt></ruby>は<ruby>含<rt>ふく</rt></ruby>まれない！<br>\n            <span style=\"font-weight:400;color:#7a2a10;font-size:11px;\">Tindakan perawatan langsung TIDAK termasuk</span></div>\n        </div>\n      </div>\n\n      <!-- 後見人になれる人 -->\n      <div class=\"hl hl-green\" style=\"margin-top:10px;\">\n        <strong><ruby>後見人<rt>こうけんにん</rt></ruby>になれる<ruby>人<rt>ひと</rt></ruby> ／ Yang Bisa Menjadi Wali</strong><br>\n        <span style=\"font-size:12px;\"><ruby>配偶者<rt>はいぐうしゃ</rt></ruby>や<ruby>親族<rt>しんぞく</rt></ruby>のほか、<strong>「<ruby>弁護士<rt>べんごし</rt></ruby>などの<ruby>専門職<rt>せんもんしょく</rt></ruby>」</strong>や<strong>「<ruby>社会福祉法人<rt>しゃかいふくしほうじん</rt></ruby>などの<ruby>法人<rt>ほうじん</rt></ruby>」</strong>も<ruby>選任<rt>せんにん</rt></ruby>できる<br>\n        Selain keluarga, pengacara, spesialis, dan lembaga hukum seperti yayasan sosial bisa menjadi wali</span>\n      </div>\n\n      <!-- 取消し -->\n      <div class=\"hl hl-red\" style=\"margin-top:10px;\">\n        🔁 <strong><ruby>取消<rt>とりけし</rt></ruby>し ／ Pembatalan Tindakan Hukum</strong><br>\n        <span style=\"font-size:12px;\"><ruby>成年被後見人<rt>せいねんひこうけんにん</rt></ruby>が<ruby>行<rt>おこな</rt></ruby>った<ruby>法律行為<rt>ほうりつこうい</rt></ruby>は、<strong><ruby>日用品<rt>にちようひん</rt></ruby>の<ruby>購入<rt>こうにゅう</rt></ruby>など<ruby>日常生活<rt>にちじょうせいかつ</rt></ruby>に<ruby>関<rt>かん</rt></ruby>する<ruby>行為以外<rt>こういいがい</rt></ruby>は<ruby>取消<rt>とりけ</rt></ruby>すことができる</strong><br>\n        Tindakan hukum yang dilakukan orang yang diwalikan DAPAT dibatalkan, kecuali pembelian kebutuhan sehari-hari</span>\n      </div>\n\n    </div></div>\n  </div>\n\n  <div class=\"arrow-down\">↓</div>\n\n  <!-- ===== SECTION 2: 任意後見制度 ===== -->\n  <div class=\"section th-orange\" id=\"s2\">\n    <div class=\"sec-head\" onclick=\"toggle('s2')\">\n      <div class=\"sec-icon\">📝</div>\n      <div class=\"sec-title\">\n        <span class=\"jp\"><ruby>任意後見制度<rt>にんいこうけんせいど</rt></ruby></span>\n        <span class=\"id\">Sistem Perwalian Sukarela (untuk masa depan)</span>\n      </div>\n      <span class=\"toggle-arr\">▼</span>\n    </div>\n    <div class=\"sec-body\"><div class=\"sec-inner\">\n\n      <div class=\"hl hl-orange\">\n        💡 <strong>ポイント ／ Poin Kunci</strong><br>\n        <span style=\"font-size:12px;\">本人が<ruby>判断能力<rt>はんだんのうりょく</rt></ruby>を有している<ruby>間<rt>あいだ</rt></ruby>に、<ruby>将来<rt>しょうらい</rt></ruby>のために<ruby>後見<rt>こうけん</rt></ruby>する<ruby>人<rt>ひと</rt></ruby>（任意後見人）と<ruby>後見事務<rt>こうけんじむ</rt></ruby>の<ruby>内容<rt>ないよう</rt></ruby>を<strong>あらかじめ<ruby>契約<rt>けいやく</rt></ruby>で<ruby>決<rt>き</rt></ruby>めておく</strong><ruby>制度<rt>せいど</rt></ruby><br>\n        Ketika masih mampu memutuskan, seseorang memilih sendiri siapa walinya & apa isinya untuk masa depan</span>\n      </div>\n\n      <!-- 3 steps -->\n      <div class=\"flow-diagram\">\n        <div class=\"fd-label\">プロセス ／ Alur</div>\n        <div class=\"fd-row\">\n          <div class=\"fd-box n-green\">①<ruby>任意後見契約<rt>にんいこうけんけいやく</rt></ruby><br><span style=\"font-size:10px;font-weight:400;\">公証役場で<strong>公正証書</strong>により締結<br>Di kantor notaris dengan Akta Notaris</span></div>\n          <div class=\"fd-arrow\">→</div>\n          <div class=\"fd-box n-blue\">②<ruby>登記<rt>とうき</rt></ruby><br><span style=\"font-size:10px;font-weight:400;\"><ruby>公証人<rt>こうしょうにん</rt></ruby>の<ruby>嘱託<rt>しょくたく</rt></ruby>により<br><ruby>法務局<rt>ほうむきょく</rt></ruby>に<ruby>登記<rt>とうき</rt></ruby><br>Didaftarkan ke Kantor Pertanahan</span></div>\n          <div class=\"fd-arrow\">→</div>\n          <div class=\"fd-box n-orange\">③<ruby>後見開始<rt>こうけんかいし</rt></ruby>の<ruby>審判<rt>しんぱん</rt></ruby><br><span style=\"font-size:10px;font-weight:400;\"><ruby>判断能力<rt>はんだんのうりょく</rt></ruby>が<ruby>不十分<rt>ふじゅうぶん</rt></ruby>になったとき<br>「<ruby>任意後見監督人<rt>にんいこうけんかんとくにん</rt></ruby><ruby>選任<rt>せんにん</rt></ruby>の申立て」<br>Saat kemampuan menurun, ajukan ke Pengadilan</span></div>\n        </div>\n      </div>\n\n      <div class=\"hl hl-blue\" style=\"margin-top:12px;\">\n        <strong><ruby>法定後見<rt>ほうていこうけん</rt></ruby> vs <ruby>任意後見<rt>にんいこうけん</rt></ruby> ／ Perbandingan Singkat</strong><br>\n        <span style=\"font-size:12px;\">\n          🔵 <ruby>法定後見<rt>ほうていこうけん</rt></ruby>：<ruby>すでに<rt></rt></ruby><ruby>判断能力<rt>はんだんのうりょく</rt></ruby>が<ruby>不十分<rt>ふじゅうぶん</rt></ruby>な<ruby>人<rt>ひと</rt></ruby>に<ruby>後見人<rt>こうけんにん</rt></ruby>を<ruby>選任<rt>せんにん</rt></ruby>する<ruby>制度<rt>せいど</rt></ruby><br>\n          🟠 <ruby>任意後見<rt>にんいこうけん</rt></ruby>：<ruby>今<rt>いま</rt></ruby>はしっかりしているが「<strong><ruby>将来<rt>しょうらい</rt></ruby></strong>」のために<ruby>後見人<rt>こうけんにん</rt></ruby>を<ruby>選<rt>えら</rt></ruby>んでおく<ruby>制度<rt>せいど</rt></ruby><br>\n          <span style=\"opacity:.7;\">Perwalian hukum: untuk yang sudah kurang kemampuannya | Perwalian sukarela: mempersiapkan wali untuk masa depan</span>\n        </span>\n      </div>\n\n    </div></div>\n  </div>\n\n  <div class=\"arrow-down\">↓</div>\n\n  <!-- ===== SECTION 3: 利用状況 ===== -->\n  <div class=\"section th-purple\" id=\"s3\">\n    <div class=\"sec-head\" onclick=\"toggle('s3')\">\n      <div class=\"sec-icon\">📊</div>\n      <div class=\"sec-title\">\n        <span class=\"jp\"><ruby>成年後見制度<rt>せいねんこうけんせいど</rt></ruby>の<ruby>利用状況<rt>りようじょうきょう</rt></ruby>（2024年）</span>\n        <span class=\"id\">Statistik Penggunaan Sistem Perwalian 2024</span>\n      </div>\n      <span class=\"toggle-arr\">▼</span>\n    </div>\n    <div class=\"sec-body\"><div class=\"sec-inner\">\n\n      <!-- 申立て件数 -->\n      <div class=\"hl hl-purple\"><strong><ruby>申立<rt>もうしたて</rt></ruby>て<ruby>件数<rt>けんすう</rt></ruby> ／ Jumlah Pengajuan</strong></div>\n      <div class=\"stat-row\" style=\"margin-top:8px;\">\n        <div class=\"stat-b n-red\" style=\"flex:1;\"><span class=\"sn\">28,785</span><span>後見<ruby>開始<rt>かいし</rt></ruby>（最多）</span><span class=\"sl\">Perwalian penuh (terbanyak)</span></div>\n        <div class=\"stat-b n-orange\" style=\"flex:1;\"><span class=\"sn\">9,156</span><span>保佐<ruby>開始<rt>かいし</rt></ruby></span><span class=\"sl\">Pendamping Hukum</span></div>\n        <div class=\"stat-b n-yellow\" style=\"flex:1;\"><span class=\"sn\">3,026</span><span>補助<ruby>開始<rt>かいし</rt></ruby></span><span class=\"sl\">Asisten Hukum</span></div>\n        <div class=\"stat-b n-green\" style=\"flex:1;\"><span class=\"sn\">874</span><span>任意<ruby>後見<rt>こうけん</rt></ruby></span><span class=\"sl\">Sukarela</span></div>\n      </div>\n\n      <!-- 申立人 -->\n      <div class=\"hl hl-purple\" style=\"margin-top:14px;\"><strong><ruby>申立人<rt>もうしたてにん</rt></ruby>と<ruby>本人<rt>ほんにん</rt></ruby>との<ruby>関係<rt>かんけい</rt></ruby> ／ Hubungan Pemohon dengan Terwali</strong></div>\n      <div class=\"stat-row\" style=\"margin-top:8px;\">\n        <div class=\"stat-b n-red\" style=\"flex:1;\"><span class=\"sn\">23.9%</span><span><ruby>市区町村長<rt>しくちょうそんちょう</rt></ruby></span><span class=\"sl\">Kepala Kota (terbanyak!)</span></div>\n        <div class=\"stat-b n-orange\" style=\"flex:1;\"><span class=\"sn\">23.5%</span><span><ruby>本人<rt>ほんにん</rt></ruby></span><span class=\"sl\">Diri Sendiri</span></div>\n        <div class=\"stat-b n-yellow\" style=\"flex:1;\"><span class=\"sn\">19%</span><span><ruby>子<rt>こ</rt></ruby></span><span class=\"sl\">Anak</span></div>\n        <div class=\"stat-b n-green\" style=\"flex:1;\"><span class=\"sn\">11%</span><span><ruby>兄弟姉妹<rt>きょうだいしまい</rt></ruby></span><span class=\"sl\">Saudara Kandung</span></div>\n      </div>\n\n      <!-- 後見人と本人との関係 -->\n      <div class=\"hl hl-purple\" style=\"margin-top:14px;\"><strong><ruby>後見人<rt>こうけんにん</rt></ruby>と<ruby>本人<rt>ほんにん</rt></ruby>との<ruby>関係<rt>かんけい</rt></ruby> ／ Hubungan Wali dengan Terwali</strong></div>\n      <div class=\"stat-row\" style=\"margin-top:8px;\">\n        <div class=\"stat-b n-red\" style=\"flex:1;\"><span class=\"sn\">83%</span><span><ruby>親族以外<rt>しんぞくいがい</rt></ruby></span><span class=\"sl\">Bukan Keluarga (~8割)</span></div>\n        <div class=\"stat-b n-orange\" style=\"flex:1;\"><span class=\"sn\">29%</span><span><ruby>司法書士<rt>しほうしょし</rt></ruby>（最多）</span><span class=\"sl\">Panitera Hukum</span></div>\n        <div class=\"stat-b n-yellow\" style=\"flex:1;\"><span class=\"sn\">21%</span><span><ruby>弁護士<rt>べんごし</rt></ruby></span><span class=\"sl\">Pengacara</span></div>\n        <div class=\"stat-b n-blue\" style=\"flex:1;\"><span class=\"sn\">17%</span><span><ruby>社会福祉士<rt>しゃかいふくしし</rt></ruby></span><span class=\"sl\">Pekerja Sosial</span></div>\n      </div>\n\n      <div class=\"hl hl-red\" style=\"margin-top:12px;\">\n        💡 <strong><ruby>親族以外<rt>しんぞくいがい</rt></ruby>が<ruby>約<rt>やく</rt></ruby>8<ruby>割<rt>わり</rt></ruby>！</strong><br>\n        <span style=\"font-size:12px;\">司法書士が最も多く、弁護士・社会福祉士・社会福祉協議会の順。<br>\n        <span style=\"opacity:.7;\">Sekitar 80% wali adalah non-keluarga — panitera hukum paling banyak, diikuti pengacara & pekerja sosial</span></span>\n      </div>\n\n    </div></div>\n  </div>\n\n  <div class=\"arrow-down\">↓</div>\n\n  <!-- ===== SECTION 4: 日常生活自立支援事業 ===== -->\n  <div class=\"section th-green\" id=\"s4\">\n    <div class=\"sec-head\" onclick=\"toggle('s4')\">\n      <div class=\"sec-icon\">🏢</div>\n      <div class=\"sec-title\">\n        <span class=\"jp\"><ruby>日常生活自立支援事業<rt>にちじょうせいかつじりつしえんじぎょう</rt></ruby></span>\n        <span class=\"id\">Layanan Kemandirian Hidup Sehari-hari</span>\n      </div>\n      <span class=\"toggle-arr\">▼</span>\n    </div>\n    <div class=\"sec-body\"><div class=\"sec-inner\">\n\n      <!-- 実施主体 -->\n      <div class=\"node n-green\">\n        <div class=\"node-lbl\"><ruby>実施主体<rt>じっしぬしたい</rt></ruby> ／ Pelaksana</div>\n        <div class=\"node-main\"><ruby>都道府県<rt>とどうふけん</rt></ruby>・<ruby>指定都市<rt>していとし</rt></ruby>の<ruby>社会福祉協議会<rt>しゃかいふくしきょうぎかい</rt></ruby></div>\n        <div class=\"node-sub\"><ruby>業務<rt>ぎょうむ</rt></ruby>の<ruby>一部<rt>いちぶ</rt></ruby>を<ruby>市町村社会福祉協議会<rt>しちょうそんしゃかいふくしきょうぎかい</rt></ruby>（<ruby>基幹的社協<rt>きかんてきしゃきょう</rt></ruby>）などに<ruby>委託<rt>いたく</rt></ruby>できる<br>\n          <span style=\"opacity:.7;\">Dapat mendelegasikan sebagian tugas ke Dewan Kesejahteraan tingkat kota</span></div>\n      </div>\n\n      <div class=\"flow-conn\"></div>\n\n      <!-- 利用対象者 -->\n      <div class=\"node n-yellow\">\n        <div class=\"node-lbl\"><ruby>利用対象者<rt>りようたいしょうしゃ</rt></ruby> ／ Target Pengguna</div>\n        <div class=\"node-main\"><ruby>認知症高齢者<rt>にんちしょうこうれいしゃ</rt></ruby>・<ruby>知的障害者<rt>ちてきしょうがいしゃ</rt></ruby>・<ruby>精神障害者<rt>せいしんしょうがいしゃ</rt></ruby>など<ruby>判断能力<rt>はんだんのうりょく</rt></ruby>が<ruby>不十分<rt>ふじゅうぶん</rt></ruby>な<ruby>人<rt>ひと</rt></ruby></div>\n        <div class=\"node-sub\">（本事業の<ruby>契約内容<rt>けいやくないよう</rt></ruby>について<ruby>判断<rt>はんだん</rt></ruby>できる<ruby>能力<rt>のうりょく</rt></ruby>が<ruby>必要<rt>ひつよう</rt></ruby>）<br>\n          <span style=\"opacity:.7;\">Orang dengan kemampuan keputusan kurang, namun masih bisa memahami isi kontrak layanan ini</span></div>\n      </div>\n\n      <!-- 実施体制 -->\n      <div class=\"hl hl-green\" style=\"margin-top:12px;\"><strong><ruby>実施体制<rt>じっしたいせい</rt></ruby> ／ Struktur Pelaksana</strong></div>\n      <div class=\"grid3\" style=\"margin-top:8px;\">\n        <div class=\"node n-blue\" style=\"margin-bottom:0;\">\n          <div class=\"node-lbl\"><ruby>専門員<rt>せんもんいん</rt></ruby></div>\n          <div class=\"node-main\"><ruby>支援計画<rt>しえんけいかく</rt></ruby>の<ruby>作成<rt>さくせい</rt></ruby>・<ruby>契約<rt>けいやく</rt></ruby>締結業務</div>\n          <div class=\"node-sub\"><ruby>社会福祉士<rt>しゃかいふくしし</rt></ruby>・<ruby>精神保健福祉士<rt>せいしんほけんふくしし</rt></ruby>などから<ruby>仕用<rt>やとよ</rt></ruby><br>\n            <span style=\"opacity:.7;\">Membuat rencana dukungan; direkrut dari pekerja sosial</span></div>\n        </div>\n        <div class=\"node n-green\" style=\"margin-bottom:0;\">\n          <div class=\"node-lbl\"><ruby>生活支援員<rt>せいかつしえんいん</rt></ruby></div>\n          <div class=\"node-main\"><ruby>支援計画<rt>しえんけいかく</rt></ruby>に<ruby>基<rt>もと</rt></ruby>づき<ruby>援助<rt>えんじょ</rt></ruby></div>\n          <div class=\"node-sub\"><ruby>専門員<rt>せんもんいん</rt></ruby>の<ruby>指示<rt>しじ</rt></ruby>を<ruby>受<rt>う</rt></ruby>けて<ruby>実際<rt>じっさい</rt></ruby>のサービスを<ruby>提供<rt>ていきょう</rt></ruby><br>\n            <span style=\"opacity:.7;\">Memberikan layanan nyata sesuai rencana</span></div>\n        </div>\n        <div class=\"node n-orange\" style=\"margin-bottom:0;\">\n          <div class=\"node-lbl\"><ruby>契約締結審査会<rt>けいやくていけつしんさかい</rt></ruby></div>\n          <div class=\"node-main\"><ruby>契約締結能力<rt>けいやくていけつのうりょく</rt></ruby>に<ruby>疑義<rt>ぎぎ</rt></ruby>がある<ruby>場合<rt>ばあい</rt></ruby>に<ruby>審査<rt>しんさ</rt></ruby></div>\n          <div class=\"node-sub\"><ruby>都道府県<rt>とどうふけん</rt></ruby>・<ruby>指定都市社会福祉協議会<rt>していとししゃかいふくしきょうぎかい</rt></ruby>に<ruby>設置<rt>せっち</rt></ruby><br>\n            <span style=\"opacity:.7;\">Dewan pemeriksa kemampuan kontrak</span></div>\n        </div>\n      </div>\n\n      <!-- 援助内容 -->\n      <div class=\"hl hl-teal\" style=\"margin-top:12px;\"><strong><ruby>援助内容<rt>えんじょないよう</rt></ruby> ／ Isi Bantuan</strong></div>\n      <div class=\"grid2\" style=\"margin-top:8px;\">\n        <div class=\"node n-teal\">\n          <div class=\"node-lbl\">① <ruby>福祉<rt>ふくし</rt></ruby>サービスの<ruby>利用援助<rt>りようえんじょ</rt></ruby></div>\n          <div class=\"node-main\"><ruby>情報提供<rt>じょうほうていきょう</rt></ruby>・<ruby>助言<rt>じょげん</rt></ruby>・<ruby>手続<rt>てつづ</rt></ruby>きの<ruby>援助<rt>えんじょ</rt></ruby></div>\n          <div class=\"node-sub\">\n            ・<ruby>苦情解決制度<rt>くじょうかいけつせいど</rt></ruby>の<ruby>利用援助<rt>りようえんじょ</rt></ruby><br>\n            ・<ruby>住宅改造<rt>じゅうたくかいぞう</rt></ruby>・<ruby>賃貸<rt>ちんたい</rt></ruby>・<ruby>消費契約<rt>しょうひけいやく</rt></ruby>・<ruby>行政手続<rt>ぎょうせいてつづ</rt></ruby>き（<ruby>住民票<rt>じゅうみんひょう</rt></ruby>など）に<ruby>関<rt>かん</rt></ruby>する<ruby>援助<rt>えんじょ</rt></ruby><br>\n            <span style=\"opacity:.7;\">Info layanan sosial, prosedur, keluhan, urusan administrasi</span>\n          </div>\n        </div>\n        <div class=\"node n-blue\">\n          <div class=\"node-lbl\">② <ruby>日常的金銭管理<rt>にちじょうてききんせんかんり</rt></ruby></div>\n          <div class=\"node-main\"><ruby>預金<rt>よきん</rt></ruby>の<ruby>払戻<rt>はらいもどし</rt></ruby>・<ruby>預入<rt>あずけいれ</rt></ruby>・<ruby>解約<rt>かいやく</rt></ruby>など</div>\n          <div class=\"node-sub\">\n            ・<ruby>福祉<rt>ふくし</rt></ruby>サービス<ruby>利用料<rt>りようりょう</rt></ruby>などの<ruby>支払<rt>しはらい</rt></ruby>い<br>\n            ・<ruby>定期的<rt>ていきてき</rt></ruby>な<ruby>訪問<rt>ほうもん</rt></ruby>による<ruby>生活変化<rt>せいかつへんか</rt></ruby>の<ruby>察知<rt>さっち</rt></ruby><br>\n            <span style=\"opacity:.7;\">Pengelolaan uang harian, pembayaran tagihan, pemantauan berkala</span>\n          </div>\n        </div>\n      </div>\n\n      <!-- 利用料 -->\n      <div class=\"hl hl-orange\" style=\"margin-top:10px;\">\n        💰 <strong><ruby>利用料<rt>りようりょう</rt></ruby> ／ Biaya Layanan</strong><br>\n        <span style=\"font-size:12px;\"><ruby>1回平均<rt>いっかいへいきん</rt></ruby> <strong>1,200円</strong>（<ruby>実施主体<rt>じっしぬしたい</rt></ruby>により<ruby>異<rt>こと</rt></ruby>なる）<br>\n        ※<ruby>契約締結前<rt>けいやくていけつまえ</rt></ruby>の<ruby>初期相談<rt>しょきそうだん</rt></ruby>・<ruby>生活保護世帯<rt>せいかつほごせたい</rt></ruby>の<ruby>利用<rt>りよう</rt></ruby>は<strong><ruby>無料<rt>むりょう</rt></ruby></strong><br>\n        <span style=\"opacity:.7;\">Rata-rata ¥1,200/kunjungan. Konsultasi awal & penerima bantuan sosial GRATIS</span></span>\n      </div>\n\n      <div class=\"hl hl-green\" style=\"margin-top:8px;\">\n        📋 <ruby>入院<rt>にゅういん</rt></ruby>・<ruby>入所<rt>にゅうしょ</rt></ruby>した<ruby>場合<rt>ばあい</rt></ruby>でも<ruby>利用<rt>りよう</rt></ruby>することができる<br>\n        <span style=\"font-size:11px;opacity:.7;\">Bisa digunakan bahkan saat dirawat di rumah sakit/fasilitas</span>\n      </div>\n\n    </div></div>\n  </div>\n\n  <div class=\"arrow-down\">↓</div>\n\n  <!-- ===== SECTION 5: 苦情解決のしくみ ===== -->\n  <div class=\"section th-blue\" id=\"s5\">\n    <div class=\"sec-head\" onclick=\"toggle('s5')\">\n      <div class=\"sec-icon\">📣</div>\n      <div class=\"sec-title\">\n        <span class=\"jp\"><ruby>苦情解決<rt>くじょうかいけつ</rt></ruby>のしくみ</span>\n        <span class=\"id\">Mekanisme Penyelesaian Keluhan</span>\n      </div>\n      <span class=\"toggle-arr\">▼</span>\n    </div>\n    <div class=\"sec-body\"><div class=\"sec-inner\">\n\n      <!-- 2 types -->\n      <div class=\"grid2\">\n        <div class=\"node n-red\">\n          <div class=\"node-lbl\"><ruby>審査請求<rt>しんさせいきゅう</rt></ruby> ／ Banding Administratif</div>\n          <div class=\"node-main\"><ruby>行政処分<rt>ぎょうせいしょぶん</rt></ruby>に<ruby>不服<rt>ふふく</rt></ruby>がある<ruby>場合<rt>ばあい</rt></ruby></div>\n          <div class=\"node-sub\"><ruby>処分<rt>しょぶん</rt></ruby>があったことを<ruby>知<rt>し</rt></ruby>った<ruby>日<rt>ひ</rt></ruby>の<ruby>翌日<rt>よくじつ</rt></ruby>から<strong>3か月以内</strong>に申立て<br>\n            <span style=\"opacity:.7;\">Diajukan dalam 3 bulan setelah mengetahui adanya tindakan administratif</span></div>\n        </div>\n        <div class=\"node n-orange\">\n          <div class=\"node-lbl\">サービスへの<ruby>苦情<rt>くじょう</rt></ruby> ／ Keluhan Layanan</div>\n          <div class=\"node-main\"><ruby>事業所<rt>じぎょうしょ</rt></ruby>の<ruby>サービス<rt></rt></ruby>に<ruby>不満<rt>ふまん</rt></ruby>がある<ruby>場合<rt>ばあい</rt></ruby></div>\n          <div class=\"node-sub\"><ruby>苦情解決責任者<rt>くじょうかいけつせきにんしゃ</rt></ruby>→<ruby>外部機関<rt>がいぶきかん</rt></ruby>へエスカレーション<br>\n            <span style=\"opacity:.7;\">Mulai dari staf penanganan keluhan di tempat, lalu ke lembaga eksternal</span></div>\n        </div>\n      </div>\n\n      <!-- 審査請求 先 -->\n      <div class=\"hl hl-red\" style=\"margin-top:12px;\"><strong>📋 <ruby>審査請求<rt>しんさせいきゅう</rt></ruby>の<ruby>申立先<rt>もうしたてさき</rt></ruby> ／ Tempat Mengajukan Banding</strong></div>\n      <div class=\"complaint-flow\" style=\"margin-top:8px;\">\n        <div class=\"cf-item\">\n          <div class=\"cf-who\" style=\"background:#c1121f;\"><ruby>国民健康保険審査会<rt>こくみんけんこうほけんしんさかい</rt></ruby></div>\n          <div class=\"cf-what\" style=\"background:#fef0f1;\"><ruby>国民健康保険<rt>こくみんけんこうほけん</rt></ruby>の<ruby>保険給付<rt>ほけんきゅうふ</rt></ruby>や<ruby>保険料<rt>ほけんりょう</rt></ruby>に<ruby>関<rt>かん</rt></ruby>する<ruby>処分<rt>しょぶん</rt></ruby>など<br><span style=\"font-size:10px;opacity:.7;\">Pemberian manfaat/iuran asuransi kesehatan nasional</span></div>\n        </div>\n        <div class=\"cf-item\">\n          <div class=\"cf-who\" style=\"background:#e76f51;\"><ruby>介護保険審査会<rt>かいごほけんしんさかい</rt></ruby></div>\n          <div class=\"cf-what\" style=\"background:#fef5f2;\"><ruby>介護保険<rt>かいごほけん</rt></ruby>の<ruby>要介護認定<rt>ようかいごにんてい</rt></ruby>・<ruby>保険給付<rt>ほけんきゅうふ</rt></ruby>・<ruby>保険料<rt>ほけんりょう</rt></ruby>に<ruby>関<rt>かん</rt></ruby>する<ruby>処分<rt>しょぶん</rt></ruby>など<br><span style=\"font-size:10px;opacity:.7;\">Penilaian kebutuhan perawatan, manfaat, iuran asuransi perawatan lansia</span></div>\n        </div>\n        <div class=\"cf-item\">\n          <div class=\"cf-who\" style=\"background:#7a5000;\"><ruby>都道府県知事<rt>とどうふけんちじ</rt></ruby></div>\n          <div class=\"cf-what\" style=\"background:#fff3cd;\"><ruby>市町村長<rt>しちょうそんちょう</rt></ruby>（<ruby>市町村<rt>しちょうそん</rt></ruby>の<ruby>執行機関<rt>しっこうきかん</rt></ruby>）が<ruby>行<rt>おこな</rt></ruby>った<ruby>処分<rt>しょぶん</rt></ruby>（<ruby>生活保護<rt>せいかつほご</rt></ruby>）など<br><span style=\"font-size:10px;opacity:.7;\">Tindakan dari kepala kota/desa termasuk bantuan kehidupan</span></div>\n        </div>\n        <div class=\"cf-item\">\n          <div class=\"cf-who\" style=\"background:#1d3557;\"><ruby>障害者介護給付費<rt>しょうがいしゃかいごきゅうふひ</rt></ruby>等不服審査会</div>\n          <div class=\"cf-what\" style=\"background:#eef5fc;\"><ruby>障害者総合支援法<rt>しょうがいしゃそうごうしえんほう</rt></ruby>の<ruby>障害支援区分<rt>しょうがいしえんくぶん</rt></ruby>・サービス<ruby>種類<rt>しゅるい</rt></ruby>・<ruby>支給決定<rt>しきゅうけってい</rt></ruby>・<ruby>利用者負担<rt>りようしゃふたん</rt></ruby>に<ruby>関<rt>かん</rt></ruby>する<ruby>処分<rt>しょぶん</rt></ruby>など<br><span style=\"font-size:10px;opacity:.7;\">Terkait klasifikasi, jenis layanan, keputusan pemberian dukungan disabilitas</span></div>\n        </div>\n      </div>\n\n      <!-- サービスへの苦情 -->\n      <div class=\"hl hl-orange\" style=\"margin-top:14px;\"><strong>📋 サービスへの<ruby>苦情<rt>くじょう</rt></ruby>の<ruby>窓口<rt>まどぐち</rt></ruby> ／ Saluran Keluhan Layanan</strong></div>\n      <div class=\"complaint-flow\" style=\"margin-top:8px;\">\n        <div class=\"cf-item\">\n          <div class=\"cf-who\" style=\"background:#2d6a4f;\"><ruby>市町村<rt>しちょうそん</rt></ruby></div>\n          <div class=\"cf-what\" style=\"background:#f0faf5;\"><ruby>保険者<rt>ほけんしゃ</rt></ruby>・<ruby>実施主体<rt>じっしぬしたい</rt></ruby>として<ruby>利用者<rt>りようしゃ</rt></ruby>からの<strong><ruby>第一次的<rt>だいいちじてき</rt></ruby>な<ruby>苦情<rt>くじょう</rt></ruby></strong>を<ruby>受<rt>う</rt></ruby>け<ruby>付<rt>つ</rt></ruby>ける<br><span style=\"font-size:10px;opacity:.7;\">Menerima keluhan lapis pertama dari pengguna</span></div>\n        </div>\n        <div class=\"cf-item\">\n          <div class=\"cf-who\" style=\"background:#457b9d;\"><ruby>介護<rt>かいご</rt></ruby>サービス<ruby>苦情処理委員会<rt>くじょうしょりいいんかい</rt></ruby></div>\n          <div class=\"cf-what\" style=\"background:#eef5fc;\"><strong><ruby>国民健康保険団体連合会<rt>こくみんけんこうほけんだんたいれんごうかい</rt></ruby></strong>に<ruby>設置<rt>せっち</rt></ruby>。<ruby>介護<rt>かいご</rt></ruby>サービス<ruby>事業者<rt>じぎょうしゃ</rt></ruby>に<ruby>対<rt>たい</rt></ruby>する<ruby>苦情<rt>くじょう</rt></ruby>を<ruby>受<rt>う</rt></ruby>け<ruby>付<rt>つ</rt></ruby>ける<br><span style=\"font-size:10px;opacity:.7;\">Ditempatkan di federasi asuransi kesehatan nasional</span></div>\n        </div>\n        <div class=\"cf-item\">\n          <div class=\"cf-who\" style=\"background:#6d597a;\"><ruby>運営適正化委員会<rt>うんえいてきせいかいいんかい</rt></ruby></div>\n          <div class=\"cf-what\" style=\"background:#f5f0fb;\"><strong><ruby>都道府県社会福祉協議会<rt>とどうふけんしゃかいふくしきょうぎかい</rt></ruby></strong>に<ruby>設置<rt>せっち</rt></ruby>。<ruby>福祉<rt>ふくし</rt></ruby>サービスに<ruby>関<rt>かん</rt></ruby>する<ruby>苦情<rt>くじょう</rt></ruby>を<ruby>受<rt>う</rt></ruby>け<ruby>付<rt>つ</rt></ruby>ける<br><span style=\"font-size:10px;opacity:.7;\">Ditempatkan di Dewan Kesejahteraan tingkat prefektur</span></div>\n        </div>\n        <div class=\"cf-item\">\n          <div class=\"cf-who\" style=\"background:#c1121f;\"><ruby>苦情解決責任者<rt>くじょうかいけつせきにんしゃ</rt></ruby><br>（<ruby>担当者<rt>たんとうしゃ</rt></ruby>）</div>\n          <div class=\"cf-what\" style=\"background:#fef0f1;\"><ruby>介護保険法<rt>かいごほけんほう</rt></ruby>や<ruby>障害者総合支援法<rt>しょうがいしゃそうごうしえんほう</rt></ruby>などに<ruby>基<rt>もと</rt></ruby>づいて<ruby>事業所<rt>じぎょうしょ</rt></ruby>に<ruby>配置<rt>はいち</rt></ruby>。<ruby>利用者<rt>りようしゃ</rt></ruby>からの<ruby>苦情<rt>くじょう</rt></ruby>に<ruby>対応<rt>たいおう</rt></ruby>する<br><span style=\"font-size:10px;opacity:.7;\">Petugas keluhan yang ditempatkan di setiap fasilitas layanan</span></div>\n        </div>\n      </div>\n\n    </div></div>\n  </div>\n\n  <div style=\"text-align:center;margin-top:28px;font-size:11px;color:#2d6a4f;opacity:.65;\">\n    出典：最高裁判所事務総局「成年後見関係事件の概況（令和6年1月〜12月）」<br>\n    Sumber: Mahkamah Agung Jepang & Kementerian Kesehatan\n  </div>\n</main>\n\n<script>\n  function toggle(id){document.getElementById(id).classList.toggle('open');}\n<\/script>\n</body>\n</html>\n","songen-5":"<!DOCTYPE html>\n<html lang=\"ja\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>虐待防止法フローチャート — Penganiayaan Lansia & Disabilitas</title>\n<link href=\"https://fonts.googleapis.com/css2?family=Noto+Sans+JP:wght@300;400;500;700;900&family=Noto+Serif+JP:wght@400;700;900&display=swap\" rel=\"stylesheet\">\n<style>\n:root{\n  --r1:#5c1010;--r2:#c1121f;--rp:#fce0e2;\n  --o1:#9e4a1e;--o2:#e76f51;--op:#fde4d8;\n  --b1:#1d3557;--b2:#457b9d;--bp:#dce9f7;\n  --p1:#3d2060;--p2:#6d597a;--pp:#ece5f5;\n  --t1:#0d4a44;--t2:#2a9d8f;--tp:#d5f5f2;\n  --g1:#1b4332;--g2:#2d6a4f;--gp:#d8f3dc;\n  --y1:#7a5000;--y2:#f4a261;--yp:#fff3cd;\n  --pk1:#880e4f;--pk2:#d6608a;--pkp:#fce4ec;\n  --tx:#1a1a2e;--txm:#374151;--txs:#6b7280;\n}\n*{margin:0;padding:0;box-sizing:border-box;}\nbody{font-family:'Noto Sans JP',sans-serif;background:#f3eef0;color:var(--tx);min-height:100vh;}\nheader{background:linear-gradient(135deg,#3d0a0a 0%,#5c1010 35%,#9e1515 70%,#c1121f 100%);padding:40px 20px 30px;text-align:center;position:relative;overflow:hidden;}\nheader::before{content:'';position:absolute;top:-80px;right:-80px;width:300px;height:300px;border-radius:50%;background:rgba(255,255,255,0.04);}\n.hbadge{display:inline-block;background:rgba(255,255,255,0.15);border:1px solid rgba(255,255,255,0.3);color:#fce0e2;font-size:11px;letter-spacing:3px;padding:5px 16px;border-radius:30px;margin-bottom:14px;font-weight:500;}\n.star-row{color:#f4d03f;font-size:18px;margin-bottom:12px;letter-spacing:3px;}\nheader h1{font-family:'Noto Serif JP',serif;color:#fff;font-size:clamp(20px,5.5vw,32px);font-weight:900;line-height:1.5;margin-bottom:8px;}\nheader p{color:rgba(255,255,255,0.65);font-size:12px;letter-spacing:1px;}\n.toc{max-width:860px;margin:18px auto 0;padding:0 14px;display:flex;flex-wrap:wrap;gap:8px;justify-content:center;}\n.toc-btn{background:rgba(255,255,255,0.12);border:1px solid rgba(255,255,255,0.25);color:#fff;font-size:11px;padding:6px 14px;border-radius:20px;cursor:pointer;text-decoration:none;transition:background .2s;white-space:nowrap;}\n.toc-btn:hover{background:rgba(255,255,255,0.25);}\nmain{max-width:860px;margin:0 auto;padding:24px 14px 70px;}\n\n.section{margin-bottom:18px;border-radius:16px;overflow:hidden;box-shadow:0 2px 14px rgba(0,0,0,0.08);animation:fadeUp .5s ease both;}\n@keyframes fadeUp{from{opacity:0;transform:translateY(18px)}to{opacity:1;transform:translateY(0)}}\n.sec-head{display:flex;align-items:center;gap:12px;padding:15px 18px;cursor:pointer;user-select:none;transition:filter .2s;}\n.sec-head:hover{filter:brightness(1.06);}\n.sec-icon{width:40px;height:40px;border-radius:50%;background:rgba(255,255,255,0.18);display:flex;align-items:center;justify-content:center;font-size:19px;flex-shrink:0;}\n.sec-title .jp{font-size:15px;font-weight:900;color:#fff;display:block;}\n.sec-title .id{font-size:11px;color:rgba(255,255,255,.7);display:block;margin-top:2px;}\n.toggle-arr{color:rgba(255,255,255,.8);font-size:13px;margin-left:auto;transition:transform .35s;flex-shrink:0;}\n.section.open .toggle-arr{transform:rotate(180deg);}\n.sec-body{background:#fdfdfb;overflow:hidden;max-height:0;transition:max-height .6s ease;}\n.section.open .sec-body{max-height:30000px;}\n.sec-inner{padding:22px 16px 28px;}\n.th-red    .sec-head{background:linear-gradient(90deg,#5c1010,#c1121f);}\n.th-orange .sec-head{background:linear-gradient(90deg,#9e4a1e,#e76f51);}\n.th-blue   .sec-head{background:linear-gradient(90deg,#1d3557,#457b9d);}\n.th-purple .sec-head{background:linear-gradient(90deg,#3d2060,#6d597a);}\n.th-teal   .sec-head{background:linear-gradient(90deg,#0d4a44,#2a9d8f);}\n\n.hl{border-left:5px solid;padding:12px 14px;border-radius:0 10px 10px 0;margin:10px 0;font-size:13px;line-height:1.75;}\n.hl-red   {border-color:#c1121f;background:#fef0f1;color:#7a0c13;}\n.hl-orange{border-color:#e76f51;background:#fef5f2;color:#7a2a10;}\n.hl-blue  {border-color:#457b9d;background:#eef5fc;color:#1d3557;}\n.hl-purple{border-color:#6d597a;background:#f5f0fb;color:#3d2060;}\n.hl-teal  {border-color:#2a9d8f;background:#f0fbfa;color:#0d4a44;}\n.hl-green {border-color:#2d6a4f;background:#f0faf5;color:#1b4332;}\n.hl b{font-weight:900;}\n.hl .id{display:block;color:var(--txs);font-size:11.5px;margin-top:4px;font-style:italic;font-weight:400;}\n\n/* ===== FLOWCHART CORE ===== */\n.flow{display:flex;flex-direction:column;align-items:center;margin:14px 0;}\n.fnode{border-radius:12px;padding:11px 16px;text-align:center;font-size:13px;font-weight:700;line-height:1.55;box-shadow:0 2px 6px rgba(0,0,0,.06);max-width:100%;}\n.fnode .id{display:block;font-size:11px;font-weight:400;color:var(--txm);margin-top:4px;}\n.fnode.start{background:linear-gradient(135deg,#5c1010,#e76f51);color:#fff;font-size:14px;font-weight:900;letter-spacing:.5px;}\n.fnode.start .id{color:#fde4d8;}\n.fnode.q{background:#fff3cd;color:#7a5000;border:2px dashed #f4a261;border-radius:50px;padding:11px 22px;}\n.fnode.q .id{color:#9c7a40;}\n.fnode.end{background:#5c1010;color:#fff;font-weight:900;}\n.fnode.end .id{color:#fce0e2;}\n.arrow-v{width:2px;height:18px;background:#e6b3b3;position:relative;}\n.arrow-v::after{content:'';position:absolute;bottom:-1px;left:50%;transform:translateX(-50%);border-left:5px solid transparent;border-right:5px solid transparent;border-top:7px solid #e6b3b3;}\n.fbranch{display:flex;width:100%;justify-content:center;gap:10px;margin-top:0;}\n.fbranch-col{display:flex;flex-direction:column;align-items:center;flex:1;min-width:0;}\n.fbranch-lbl{font-size:10px;font-weight:900;padding:2px 10px;border-radius:20px;margin-bottom:6px;white-space:nowrap;text-align:center;}\n.lbl-yes{background:#d8f3dc;color:#1b4332;}\n.lbl-no{background:#fce0e2;color:#7a0c13;}\n.lbl-a{background:#dce9f7;color:#1d3557;}\n.lbl-b{background:#fde4d8;color:#7a2a10;}\n.lbl-c{background:#ece5f5;color:#3d2060;}\n.connector-h{height:2px;background:#e6b3b3;width:100%;position:relative;margin-top:8px;}\n@media(max-width:520px){.fbranch{flex-direction:column;align-items:center;gap:6px;}.fbranch-col{width:100%;}}\n\n.fcard{border-radius:10px;padding:9px 12px;font-size:11.5px;line-height:1.65;width:100%;}\n.fcard b{font-size:12.5px;}\n.fcard .id{display:block;color:var(--txs);font-size:10.5px;margin-top:4px;font-style:italic;}\n.n-green {background:#d8f3dc;color:#1b4332;} .n-blue{background:#dce9f7;color:#1d3557;}\n.n-yellow{background:#fff3cd;color:#7a5000;} .n-orange{background:#fde4d8;color:#7a2a10;}\n.n-red{background:#fce0e2;color:#7a0c13;} .n-purple{background:#ece5f5;color:#3d2060;}\n.n-teal{background:#d5f5f2;color:#0d4a44;} .n-gray{background:#f3f4f6;color:#374151;}\n.n-pink{background:#fce4ec;color:#880e4f;}\n\n/* abuse cards */\n.abuse-card{border-radius:10px;padding:10px 12px;font-size:12.5px;line-height:1.6;}\n.abuse-card .ac-title{font-weight:900;font-size:13.5px;margin-bottom:5px;display:flex;align-items:center;gap:7px;}\n.ac-num{display:inline-flex;align-items:center;justify-content:center;width:23px;height:23px;border-radius:50%;color:#fff;font-size:11px;font-weight:900;flex-shrink:0;}\n.abuse-card .id{display:block;color:var(--txs);font-size:11px;margin-top:4px;font-style:italic;}\n\n/* mnemonic strip */\n.mnemo{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin:12px 0;}\n.mnemo div{background:#fff;border:1.5px solid #e3dada;border-radius:10px;padding:8px 6px;text-align:center;font-size:11px;font-weight:700;line-height:1.4;}\n.mnemo div span{display:block;font-size:18px;margin-bottom:2px;}\n@media(max-width:560px){.mnemo{grid-template-columns:repeat(2,1fr);}}\n\n/* stat bars */\n.bar-chart{margin:10px 0;}\n.bar-row{display:flex;align-items:center;gap:8px;margin:8px 0;}\n.bar-label{flex:0 0 100px;font-size:11.5px;text-align:right;line-height:1.3;}\n.bar-label i{font-size:10px;color:#888;display:block;font-weight:400;font-style:italic;}\n.bar-track{flex:1;background:#f1eaea;border-radius:8px;overflow:hidden;height:28px;}\n.bar-fill{height:100%;display:flex;align-items:center;padding-left:10px;color:#fff;font-size:11.5px;font-weight:900;white-space:nowrap;border-radius:8px;}\n\n/* stat badges */\n.stat-row{display:flex;flex-wrap:wrap;gap:8px;margin:10px 0;}\n.stat-b{border-radius:10px;padding:10px 11px;text-align:center;flex:1;min-width:90px;}\n.stat-b .sn{font-size:18px;font-weight:900;display:block;line-height:1.1;}\n.stat-b .sl{font-size:10.5px;display:block;margin-top:3px;line-height:1.3;}\n.stat-b .si{font-size:9.5px;opacity:.7;display:block;margin-top:1px;font-style:italic;}\n\n/* tables (reference) */\n.tbl{width:100%;border-collapse:collapse;font-size:11.5px;margin:8px 0;}\n.tbl th{padding:7px 8px;text-align:left;font-size:10.5px;font-weight:900;border-bottom:2px solid #e0e0e0;background:#f8f8f8;color:#374151;}\n.tbl td{padding:6px 8px;border-bottom:1px solid #f0f0f0;vertical-align:top;line-height:1.6;}\n.tbl tr:last-child td{border-bottom:none;}\n.table-wrap{overflow-x:auto;}\n.sec-sub{font-size:12px;font-weight:900;letter-spacing:1px;color:#fff;background:#9e4a1e;display:inline-block;padding:4px 12px;border-radius:20px;margin:16px 0 8px;}\n.sec-sub.red{background:#c1121f;} .sec-sub.blue{background:#457b9d;}\n.sec-sub.purple{background:#6d597a;} .sec-sub.teal{background:#2a9d8f;}\n.divider{border:none;border-top:1px dashed #e0c8c8;margin:16px 0;}\n.fn{font-size:10.5px;color:#6b7280;margin-top:8px;line-height:1.6;}\nruby rt{font-size:9px;color:#9e4a1e;line-height:1;}\n.th-red ruby rt, .section.th-red ruby rt{color:#c1121f;}\n\n/* comparison grid for 高齢者 vs 障害者 */\n.compare-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin:10px 0;}\n@media(max-width:480px){.compare-grid{grid-template-columns:1fr;}}\n.compare-card{border-radius:10px;padding:13px;}\n.compare-title{font-weight:900;font-size:13px;margin-bottom:8px;padding-bottom:6px;border-bottom:2px solid rgba(0,0,0,0.08);}\n</style>\n<style id=\"pk-fix\">\n.sec-body{max-height:none!important;overflow:visible!important;display:none;transition:none!important}\n.section.open .sec-body{display:block}\n.section{animation:none!important;opacity:1!important;transform:none!important}\n*{min-width:0}\nbody{overflow-x:hidden;-webkit-text-size-adjust:100%}\nmain{padding-left:10px!important;padding-right:10px!important}\np,div,span,td,th,li{overflow-wrap:anywhere;word-break:normal}\nimg,svg,video{max-width:100%;height:auto}\ntable{display:block;max-width:100%;overflow-x:auto;-webkit-overflow-scrolling:touch;border-collapse:collapse}\n@media (max-width:560px){\n [class*=\"grid\"],[class*=\"cols\"],[class*=\"compare\"],[class*=\"pair\"],[class*=\"two\"],[class*=\"stats\"]{grid-template-columns:1fr 1fr!important}\n [class*=\"grid3\"],[class*=\"grid-3\"],[class*=\"three\"]{grid-template-columns:1fr!important}\n [class*=\"row\"],[class*=\"flex\"],[class*=\"flow\"],[class*=\"chain\"]{flex-wrap:wrap!important}\n [class*=\"compare\"] > *,[class*=\"pair\"] > *{min-width:0}\n}\n</style>\n<script>\n(function(){\n function post(){try{parent.postMessage({pkH:Math.ceil(document.documentElement.scrollHeight)},'*');}catch(e){}}\n document.addEventListener('DOMContentLoaded',function(){\n  document.querySelectorAll('.section').forEach(function(s,i){ if(i===0) s.classList.add('open'); });\n  post();\n  if(window.ResizeObserver) new ResizeObserver(post).observe(document.body);\n  document.addEventListener('click',function(){setTimeout(post,30);setTimeout(post,400);});\n });\n window.addEventListener('load',post);\n})();\n<\/script></head>\n<body>\n<header>\n  <div class=\"hbadge\">第1章 第2節 ⑤ — フローチャート</div>\n  <div class=\"star-row\">★★☆</div>\n  <h1><ruby>虐待<rt>ぎゃくたい</rt></ruby>（<ruby>高齢者<rt>こうれいしゃ</rt></ruby>・<ruby>障害者<rt>しょうがいしゃ</rt></ruby>）<br>\n    <span style=\"font-size:.55em;font-weight:400;color:rgba(255,255,255,.7);\">Penganiayaan terhadap Lansia & Penyandang Disabilitas</span>\n  </h1>\n  <p>タップして各フローを開く ／ Ketuk untuk membuka tiap diagram alur</p>\n  <div class=\"toc\">\n    <a class=\"toc-btn\" href=\"#s1\">①高齢者虐待の定義</a>\n    <a class=\"toc-btn\" href=\"#s2\">②通報〜対応フロー</a>\n    <a class=\"toc-btn\" href=\"#s3\">③統計データ</a>\n    <a class=\"toc-btn\" href=\"#s4\">④障害者虐待の定義</a>\n    <a class=\"toc-btn\" href=\"#s5\">⑤障害者の対応・統計</a>\n  </div>\n</header>\n<main>\n\n<!-- ============ SECTION 1: 高齢者虐待 定義・5種類 ============ -->\n<section class=\"section open th-red\" id=\"s1\">\n  <div class=\"sec-head\" onclick=\"toggle('s1')\">\n    <div class=\"sec-icon\">👴</div>\n    <div class=\"sec-title\">\n      <span class=\"jp\">① <ruby>高齢者虐待防止法<rt>こうれいしゃぎゃくたいぼうしほう</rt></ruby> — <ruby>定義<rt>ていぎ</rt></ruby>と<ruby>5種類<rt>ごしゅるい</rt></ruby></span>\n      <span class=\"id\">UU Pencegahan Penganiayaan Lansia — Definisi & 5 Jenis Penganiayaan</span>\n    </div>\n    <span class=\"toggle-arr\">▾</span>\n  </div>\n  <div class=\"sec-body\">\n    <div class=\"sec-inner\">\n\n      <div class=\"hl hl-red\">\n        <b>正式名称</b>：<ruby>高齢者虐待<rt>こうれいしゃぎゃくたい</rt></ruby>の<ruby>防止<rt>ぼうし</rt></ruby>、<ruby>高齢者<rt>こうれいしゃ</rt></ruby>の<ruby>養護者<rt>ようごしゃ</rt></ruby>に<ruby>対<rt>たい</rt></ruby>する<ruby>支援等<rt>しえんとう</rt></ruby>に<ruby>関<rt>かん</rt></ruby>する<ruby>法律<rt>ほうりつ</rt></ruby>\n        <span class=\"id\">UU tentang Pencegahan Penganiayaan Lansia & Dukungan bagi Pengasuh Lansia</span>\n      </div>\n\n      <div class=\"flow\">\n        <div class=\"fnode start\">START — ある<ruby>人<rt>ひと</rt></ruby>を<ruby>虐待<rt>ぎゃくたい</rt></ruby>から<ruby>守<rt>まも</rt></ruby>りたい<span class=\"id\">Seseorang perlu dilindungi dari penganiayaan</span></div>\n        <div class=\"arrow-v\"></div>\n        <div class=\"fnode q\">その<ruby>人<rt>ひと</rt></ruby>は<ruby>65歳<rt>65さい</rt></ruby>以上ですか？<span class=\"id\">Apakah orang itu berusia 65 tahun ke atas?</span></div>\n        <div class=\"arrow-v\"></div>\n\n        <div class=\"fbranch\">\n          <div class=\"fbranch-col\">\n            <div class=\"fbranch-lbl lbl-yes\">はい（65歳以上）</div>\n            <div class=\"connector-h\" style=\"background:#d8f3dc;\"></div>\n            <div class=\"arrow-v\" style=\"background:#d8f3dc;\"></div>\n            <div class=\"fcard n-green\"><b><ruby>高齢者<rt>こうれいしゃ</rt></ruby>に<ruby>該当<rt>がいとう</rt></ruby></b><span class=\"id\">Termasuk \"lansia\" sesuai UU ini</span></div>\n          </div>\n          <div class=\"fbranch-col\">\n            <div class=\"fbranch-lbl lbl-no\">いいえ（65歳未満）</div>\n            <div class=\"connector-h\"></div>\n            <div class=\"arrow-v\"></div>\n            <div class=\"fnode q\" style=\"width:100%;\">でも、<ruby>養介護施設<rt>ようかいごしせつ</rt></ruby>に<ruby>入所<rt>にゅうしょ</rt></ruby>中、または<ruby>養介護事業<rt>ようかいごじぎょう</rt></ruby>の<ruby>サービス<rt>サービス</rt></ruby>を<ruby>受<rt>う</rt></ruby>けている<ruby>障害者<rt>しょうがいしゃ</rt></ruby>ですか？<span class=\"id\">Tapi apakah penyandang disabilitas pengguna fasilitas/layanan perawatan?</span></div>\n            <div class=\"arrow-v\"></div>\n            <div class=\"fbranch\">\n              <div class=\"fbranch-col\">\n                <div class=\"fbranch-lbl lbl-yes\">はい</div>\n                <div class=\"connector-h\" style=\"background:#d8f3dc;\"></div>\n                <div class=\"arrow-v\" style=\"background:#d8f3dc;\"></div>\n                <div class=\"fcard n-green\"><b>みなし<ruby>高齢者<rt>こうれいしゃ</rt></ruby></b>として<ruby>適用<rt>てきよう</rt></ruby><span class=\"id\">Tetap dianggap \"lansia\" — UU ini berlaku</span></div>\n              </div>\n              <div class=\"fbranch-col\">\n                <div class=\"fbranch-lbl lbl-no\">いいえ</div>\n                <div class=\"connector-h\"></div>\n                <div class=\"arrow-v\"></div>\n                <div class=\"fcard n-gray\"><b>この<ruby>法律<rt>ほうりつ</rt></ruby>の<ruby>対象外<rt>たいしょうがい</rt></ruby></b><span class=\"id\">Tidak termasuk dalam UU ini (cek UU penyandang disabilitas →④)</span></div>\n              </div>\n            </div>\n          </div>\n        </div>\n\n        <div class=\"arrow-v\" style=\"margin-top:14px;\"></div>\n        <div class=\"fnode q\">だれが<ruby>虐待<rt>ぎゃくたい</rt></ruby>しているか？<span class=\"id\">Siapa pelaku penganiayaan?</span></div>\n        <div class=\"arrow-v\"></div>\n        <div class=\"fbranch\">\n          <div class=\"fbranch-col\">\n            <div class=\"fbranch-lbl lbl-a\">① <ruby>養護者<rt>ようごしゃ</rt></ruby></div>\n            <div class=\"connector-h\" style=\"background:#fce0e2;\"></div>\n            <div class=\"arrow-v\" style=\"background:#fce0e2;\"></div>\n            <div class=\"fcard n-red\"><b><ruby>家族<rt>かぞく</rt></ruby>・<ruby>介護者<rt>かいごしゃ</rt></ruby>による<ruby>虐待<rt>ぎゃくたい</rt></ruby></b><span class=\"id\">Penganiayaan oleh pengasuh/anggota keluarga</span></div>\n          </div>\n          <div class=\"fbranch-col\">\n            <div class=\"fbranch-lbl lbl-b\">② <ruby>養介護施設従事者等<rt>ようかいごしせつじゅうじしゃとう</rt></ruby></div>\n            <div class=\"connector-h\" style=\"background:#fde4d8;\"></div>\n            <div class=\"arrow-v\" style=\"background:#fde4d8;\"></div>\n            <div class=\"fcard n-orange\"><b><ruby>施設<rt>しせつ</rt></ruby>・<ruby>事業所<rt>じぎょうしょ</rt></ruby>の<ruby>職員<rt>しょくいん</rt></ruby>による<ruby>虐待<rt>ぎゃくたい</rt></ruby></b><span class=\"id\">Penganiayaan oleh staf fasilitas/usaha perawatan</span></div>\n          </div>\n        </div>\n        <div class=\"hl hl-orange\" style=\"font-size:11.5px;margin-top:10px;width:100%;\">\n          <b><ruby>養介護施設<rt>ようかいごしせつ</rt></ruby>等</b>＝<ruby>老人福祉施設<rt>ろうじんふくししせつ</rt></ruby>・<ruby>有料老人ホーム<rt>ゆうりょうろうじんホーム</rt></ruby>・<ruby>介護保険施設<rt>かいごほけんしせつ</rt></ruby>・<ruby>地域包括支援センター<rt>ちいきほうかつしえんセンター</rt></ruby>等／<b><ruby>養介護事業<rt>ようかいごじぎょう</rt></ruby></b>＝<ruby>居宅生活支援事業<rt>きょたくせいかつしえんじぎょう</rt></ruby>・<ruby>居宅サービス事業<rt>きょたくサービスじぎょう</rt></ruby>等\n          <span class=\"id\">Fasilitas: panti lansia, panti berbayar, fasilitas asuransi perawatan, dll. Usaha: dukungan kehidupan & layanan di rumah</span>\n        </div>\n      </div>\n\n      <hr class=\"divider\">\n      <div class=\"sec-sub red\">⚠️ 虐待の5種類 ／ 5 Jenis Penganiayaan</div>\n      <div style=\"display:flex;flex-direction:column;gap:7px;margin-top:8px;\">\n        <div class=\"abuse-card n-red\">\n          <div class=\"ac-title\"><span class=\"ac-num\" style=\"background:#c1121f;\">1</span><ruby>身体的虐待<rt>しんたいてきぎゃくたい</rt></ruby> ／ Fisik</div>\n          <ruby>身体<rt>しんたい</rt></ruby>に<ruby>外傷<rt>がいしょう</rt></ruby>が<ruby>生<rt>しょう</rt></ruby>じ、または<ruby>生<rt>しょう</rt></ruby>じるおそれのある<b><ruby>暴行<rt>ぼうこう</rt></ruby></b>を<ruby>加<rt>くわ</rt></ruby>えること\n          <span class=\"id\">Tindakan kekerasan yang menyebabkan atau berpotensi menyebabkan cedera fisik</span>\n        </div>\n        <div class=\"abuse-card n-purple\">\n          <div class=\"ac-title\"><span class=\"ac-num\" style=\"background:#6d597a;\">2</span><ruby>心理的虐待<rt>しんりてきぎゃくたい</rt></ruby> ／ Psikologis</div>\n          <ruby>著<rt>いちじる</rt></ruby>しい<b><ruby>暴言<rt>ぼうげん</rt></ruby></b>、<ruby>拒絶的<rt>きょぜつてき</rt></ruby>な<ruby>対応<rt>たいおう</rt></ruby>など、<ruby>心理的外傷<rt>しんりてきがいしょう</rt></ruby>を<ruby>与<rt>あた</rt></ruby>える<ruby>言動<rt>げんどう</rt></ruby>\n          <span class=\"id\">Kata-kata kasar, penolakan, atau tindakan yang melukai psikologis</span>\n        </div>\n        <div class=\"abuse-card n-pink\">\n          <div class=\"ac-title\"><span class=\"ac-num\" style=\"background:#880e4f;\">3</span><ruby>性的虐待<rt>せいてきぎゃくたい</rt></ruby> ／ Seksual</div>\n          <ruby>高齢者<rt>こうれいしゃ</rt></ruby>に<b><ruby>わいせつな行為<rt>こうい</rt></ruby></b>をすること、またはさせること\n          <span class=\"id\">Melakukan atau memaksa tindakan asusila</span>\n        </div>\n        <div class=\"abuse-card n-yellow\">\n          <div class=\"ac-title\"><span class=\"ac-num\" style=\"background:#d9883e;\">4</span><ruby>介護等放棄<rt>かいごとうほうき</rt></ruby>（ネグレクト）／ Penelantaran</div>\n          <ruby>高齢者<rt>こうれいしゃ</rt></ruby>を<ruby>衰弱<rt>すいじゃく</rt></ruby>させるような<ruby>著<rt>いちじる</rt></ruby>しい<ruby>減食<rt>げんしょく</rt></ruby>、<ruby>長時間<rt>ちょうじかん</rt></ruby>の<ruby>放置<rt>ほうち</rt></ruby>など<b><ruby>養護<rt>ようご</rt></ruby>を<ruby>著<rt>いちじる</rt></ruby>しく<ruby>怠<rt>おこた</rt></ruby>る</b>こと\n          <span class=\"id\">Pembatasan makan ekstrem, penelantaran jangka panjang, pengabaian perawatan</span>\n        </div>\n        <div class=\"abuse-card n-orange\">\n          <div class=\"ac-title\"><span class=\"ac-num\" style=\"background:#9e4a1e;\">5</span><ruby>経済的虐待<rt>けいざいてきぎゃくたい</rt></ruby> ／ Ekonomi</div>\n          <ruby>高齢者<rt>こうれいしゃ</rt></ruby>の<ruby>財産<rt>ざいさん</rt></ruby>を<b><ruby>不当<rt>ふとう</rt></ruby>に<ruby>処分<rt>しょぶん</rt></ruby></b>すること、<ruby>高齢者<rt>こうれいしゃ</rt></ruby>から<ruby>不当<rt>ふとう</rt></ruby>に<ruby>財産上<rt>ざいさんじょう</rt></ruby>の<ruby>利益<rt>りえき</rt></ruby>を<ruby>得<rt>え</rt></ruby>ること\n          <span class=\"id\">Mengambil/mengelola aset lansia secara tidak sah untuk kepentingan sendiri</span>\n        </div>\n      </div>\n\n      <div class=\"mnemo\">\n        <div><span>👊</span>身体的＝外傷を生じる暴行</div>\n        <div><span>🗣️</span>心理的＝暴言・拒絶</div>\n        <div><span>🚫</span>性的＝わいせつ行為</div>\n        <div><span>🍽️</span>放棄＝減食・放置</div>\n      </div>\n      <div class=\"hl hl-red\" style=\"font-size:11.5px;\">\n        💡 <b>覚え方</b>：身体・心理・性的・放棄（ネグレクト）・経済 ＝ <b>「身・心・性・放・経」</b>の5つ。高齢者も障害者もこの5種類は<b>共通</b>。\n        <span class=\"id\">Trik hafalan: fisik・psikologis・seksual・penelantaran・ekonomi — 5 jenis ini SAMA untuk lansia maupun penyandang disabilitas.</span>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ============ SECTION 2: 通報義務・対応フロー ============ -->\n<section class=\"section th-orange\" id=\"s2\">\n  <div class=\"sec-head\" onclick=\"toggle('s2')\">\n    <div class=\"sec-icon\">📢</div>\n    <div class=\"sec-title\">\n      <span class=\"jp\">② <ruby>通報義務<rt>つうほうぎむ</rt></ruby>と<ruby>対応<rt>たいおう</rt></ruby>フロー（<ruby>高齢者<rt>こうれいしゃ</rt></ruby>）</span>\n      <span class=\"id\">Alur Kewajiban Lapor & Respons (Lansia)</span>\n    </div>\n    <span class=\"toggle-arr\">▾</span>\n  </div>\n  <div class=\"sec-body\">\n    <div class=\"sec-inner\">\n\n      <div class=\"flow\">\n        <div class=\"fnode start\"><ruby>高齢者虐待<rt>こうれいしゃぎゃくたい</rt></ruby>を<ruby>受<rt>う</rt></ruby>けたと<ruby>思<rt>おも</rt></ruby>われる<ruby>高齢者<rt>こうれいしゃ</rt></ruby>を<ruby>発見<rt>はっけん</rt></ruby>した<span class=\"id\">Menemukan lansia yang diduga mengalami penganiayaan</span></div>\n        <div class=\"arrow-v\"></div>\n        <div class=\"fnode q\">だれが<ruby>虐待<rt>ぎゃくたい</rt></ruby>していたか？<span class=\"id\">Siapa pelakunya?</span></div>\n        <div class=\"arrow-v\"></div>\n\n        <div class=\"fbranch\">\n          <div class=\"fbranch-col\">\n            <div class=\"fbranch-lbl lbl-a\">① <ruby>養護者<rt>ようごしゃ</rt></ruby>による<ruby>虐待<rt>ぎゃくたい</rt></ruby></div>\n            <div class=\"connector-h\" style=\"background:#fce0e2;\"></div>\n            <div class=\"arrow-v\" style=\"background:#fce0e2;\"></div>\n            <div class=\"fnode q\" style=\"width:100%;\"><ruby>生命<rt>せいめい</rt></ruby>または<ruby>身体<rt>しんたい</rt></ruby>に<b><ruby>重大<rt>じゅうだい</rt></ruby>な<ruby>危険<rt>きけん</rt></ruby></b>が<ruby>生<rt>しょう</rt></ruby>じている？<span class=\"id\">Ada bahaya nyata bagi jiwa/tubuh?</span></div>\n            <div class=\"arrow-v\"></div>\n            <div class=\"fcard n-red\"><b><ruby>速<rt>すみ</rt></ruby>やかに<ruby>市町村<rt>しちょうそん</rt></ruby>に<ruby>通報<rt>つうほう</rt></ruby>しなければならない（<ruby>義務<rt>ぎむ</rt></ruby>）</b><span class=\"id\">WAJIB segera lapor ke kota/desa</span></div>\n          </div>\n          <div class=\"fbranch-col\">\n            <div class=\"fbranch-lbl lbl-b\">② <ruby>養介護施設従事者等<rt>ようかいごしせつじゅうじしゃとう</rt></ruby>による<ruby>虐待<rt>ぎゃくたい</rt></ruby></div>\n            <div class=\"connector-h\" style=\"background:#fde4d8;\"></div>\n            <div class=\"arrow-v\" style=\"background:#fde4d8;\"></div>\n            <div class=\"fcard n-orange\" style=\"height:100%;display:flex;flex-direction:column;justify-content:center;\"><b><ruby>速<rt>すみ</rt></ruby>やかに<ruby>市町村<rt>しちょうそん</rt></ruby>に<ruby>通報<rt>つうほう</rt></ruby>（<ruby>危険<rt>きけん</rt></ruby>の<ruby>程度<rt>ていど</rt></ruby>に<ruby>関係<rt>かんけい</rt></ruby>なく<ruby>義務<rt>ぎむ</rt></ruby>）</b><span class=\"id\">WAJIB lapor ke kota/desa, tanpa syarat tingkat bahaya</span></div>\n          </div>\n        </div>\n      </div>\n\n      <div class=\"hl hl-green\" style=\"margin-top:14px;\">\n        🛡 <b><ruby>免責<rt>めんせき</rt></ruby></b>：<ruby>高齢者虐待<rt>こうれいしゃぎゃくたい</rt></ruby>の<ruby>通報<rt>つうほう</rt></ruby>をしても<b><ruby>守秘義務違反<rt>しゅひぎむいはん</rt></ruby>にならない</b>。<ruby>養介護施設従事者等<rt>ようかいごしせつじゅうじしゃとう</rt></ruby>は、<ruby>通報<rt>つうほう</rt></ruby>を<ruby>理由<rt>りゆう</rt></ruby>に<b><ruby>解雇<rt>かいこ</rt></ruby>その他<ruby>不利益<rt>ふりえき</rt></ruby>な<ruby>取扱<rt>とりあつかい</rt></ruby>いを<ruby>受<rt>う</rt></ruby>けない</b>。\n        <span class=\"id\">Pelapor tidak melanggar kerahasiaan; staf tidak boleh dipecat/dirugikan karena melapor</span>\n      </div>\n\n      <hr class=\"divider\">\n      <div class=\"sec-sub orange\">🔄 対応フロー（発見〜措置まで）／ Alur Penanganan Lengkap</div>\n      <div class=\"flow\">\n        <div class=\"fbranch\" style=\"gap:8px;\">\n          <div class=\"fbranch-col\">\n            <div class=\"fcard n-green\" style=\"text-align:center;\"><b><ruby>発見者<rt>はっけんしゃ</rt></ruby></b><br><ruby>通報<rt>つうほう</rt></ruby><span class=\"id\">Penemu → Lapor</span></div>\n          </div>\n          <div class=\"fbranch-col\">\n            <div class=\"fcard n-teal\" style=\"text-align:center;\"><b><ruby>本人<rt>ほんにん</rt></ruby></b><br><ruby>届出<rt>とどけで</rt></ruby><span class=\"id\">Korban sendiri → Memberi tahu</span></div>\n          </div>\n        </div>\n        <div class=\"arrow-v\"></div>\n        <div class=\"fnode\" style=\"background:#dce9f7;color:#1d3557;width:100%;\"><b><ruby>市町村<rt>しちょうそん</rt></ruby></b><br><span style=\"font-size:11px;font-weight:400;\"><ruby>相談<rt>そうだん</rt></ruby>・<ruby>指導<rt>しどう</rt></ruby>・<ruby>助言<rt>じょげん</rt></ruby> ／ <ruby>通報<rt>つうほう</rt></ruby>・<ruby>届出<rt>とどけで</rt></ruby>の<ruby>受理<rt>じゅり</rt></ruby></span><span class=\"id\">Kotamadya: konsultasi, bimbingan, saran, menerima laporan (boleh didelegasikan ke 地域包括支援センター)</span></div>\n        <div class=\"arrow-v\"></div>\n        <div class=\"fnode\" style=\"background:#fff3cd;color:#7a5000;width:100%;\"><b><ruby>安全確認<rt>あんぜんかくにん</rt></ruby>・<ruby>事実確認<rt>じじつかくにん</rt></ruby></b><span class=\"id\">Konfirmasi keselamatan & fakta</span></div>\n        <div class=\"arrow-v\"></div>\n        <div class=\"fnode\" style=\"background:#fde4d8;color:#7a2a10;width:100%;\"><b><ruby>立入調査<rt>たちいりちょうさ</rt></ruby>・<ruby>質問<rt>しつもん</rt></ruby></b><span class=\"id\">Investigasi masuk lokasi & wawancara</span></div>\n        <div class=\"arrow-v\"></div>\n        <div class=\"fnode end\" style=\"width:100%;\"><ruby>老人福祉法<rt>ろうじんふくしほう</rt></ruby>に<ruby>基<rt>もと</rt></ruby>づく<ruby>措置<rt>そち</rt></ruby> ／ <ruby>成年後見等開始<rt>せいねんこうけんとうかいし</rt></ruby>の<ruby>審判<rt>しんぱん</rt></ruby>の<ruby>請求<rt>せいきゅう</rt></ruby>など<span class=\"id\">Tindakan sesuai UU Kesejahteraan Lansia / pengajuan perwalian dewasa</span></div>\n      </div>\n\n      <div class=\"hl hl-red\" style=\"margin-top:10px;\">\n        ⚠️ <b><ruby>生命<rt>せいめい</rt></ruby>または<ruby>身体<rt>しんたい</rt></ruby>に<ruby>重大<rt>じゅうだい</rt></ruby>な<ruby>危険<rt>きけん</rt></ruby>のおそれ</b>がある場合 → <ruby>市町村<rt>しちょうそん</rt></ruby>は<b><ruby>警察署長<rt>けいさつしょちょう</rt></ruby>に<ruby>援助<rt>えんじょ</rt></ruby>を<ruby>要請<rt>ようせい</rt></ruby></b>できる。<br>\n        <ruby>市町村<rt>しちょうそん</rt></ruby>は<ruby>必要<rt>ひつよう</rt></ruby>に<ruby>応<rt>おう</rt></ruby>じ<b><ruby>特別養護老人ホーム<rt>とくべつようごろうじんホーム</rt></ruby>への<ruby>入所<rt>にゅうしょ</rt></ruby>など老人福祉法に基づく措置</b>（一時保護）を行う。<br>\n        <ruby>認知症高齢者<rt>にんちしょうこうれいしゃ</rt></ruby>などで<ruby>必要<rt>ひつよう</rt></ruby>があるときは<ruby>市町村長<rt>しちょうそんちょう</rt></ruby>が<b><ruby>成年後見等開始<rt>せいねんこうけんとうかいし</rt></ruby>の<ruby>審判<rt>しんぱん</rt></ruby>の<ruby>請求<rt>せいきゅう</rt></ruby></b>を行う。\n        <span class=\"id\">Jika ada bahaya nyata: minta bantuan polisi. Kota dapat menempatkan sementara (mis. ke panti khusus) & kepala kota dapat mengajukan perwalian bagi lansia demensia.</span>\n      </div>\n\n      <div class=\"mnemo\">\n        <div><span>①養護者</span>危険あり→通報義務</div>\n        <div><span>②施設職員</span>常に→通報義務</div>\n        <div><span>守秘義務</span>通報しても違反にならない</div>\n        <div><span>警察署長</span>援助要請の相手</div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ============ SECTION 3: 統計データ ============ -->\n<section class=\"section th-purple\" id=\"s3\">\n  <div class=\"sec-head\" onclick=\"toggle('s3')\">\n    <div class=\"sec-icon\">📊</div>\n    <div class=\"sec-title\">\n      <span class=\"jp\">③ <ruby>高齢者虐待<rt>こうれいしゃぎゃくたい</rt></ruby>の<ruby>統計<rt>とうけい</rt></ruby>（<ruby>令和<rt>れいわ</rt></ruby>5<ruby>年度<rt>ねんど</rt></ruby>）</span>\n      <span class=\"id\">Statistik Penganiayaan Lansia (Tahun Fiskal 2023)</span>\n    </div>\n    <span class=\"toggle-arr\">▾</span>\n  </div>\n  <div class=\"sec-body\">\n    <div class=\"sec-inner\">\n\n      <div class=\"hl hl-purple\"><b><ruby>相談<rt>そうだん</rt></ruby>・<ruby>通報件数<rt>つうほうけんすう</rt></ruby></b>と<b><ruby>虐待判断件数<rt>ぎゃくたいはんだんけんすう</rt></ruby></b>はどちらも<b>増加傾向</b>。<span class=\"id\">Jumlah konsultasi/laporan & jumlah kasus terkonfirmasi keduanya terus meningkat.</span></div>\n      <div class=\"stat-row\">\n        <div class=\"stat-b n-red\"><span class=\"sn\">40,386<small style=\"font-size:11px;\">件</small></span><span class=\"sl\"><ruby>養護者<rt>ようごしゃ</rt></ruby>による<br><ruby>相談<rt>そうだん</rt></ruby>・<ruby>通報<rt>つうほう</rt></ruby></span><span class=\"si\">Pengasuh: laporan</span></div>\n        <div class=\"stat-b n-red\"><span class=\"sn\">17,100<small style=\"font-size:11px;\">件</small></span><span class=\"sl\"><ruby>養護者<rt>ようごしゃ</rt></ruby>による<br><ruby>虐待判断<rt>ぎゃくたいはんだん</rt></ruby></span><span class=\"si\">Pengasuh: terkonfirmasi</span></div>\n        <div class=\"stat-b n-orange\"><span class=\"sn\">3,441<small style=\"font-size:11px;\">件</small></span><span class=\"sl\"><ruby>施設<rt>しせつ</rt></ruby>による<br><ruby>相談<rt>そうだん</rt></ruby>・<ruby>通報<rt>つうほう</rt></ruby></span><span class=\"si\">Fasilitas: laporan</span></div>\n        <div class=\"stat-b n-orange\"><span class=\"sn\">1,123<small style=\"font-size:11px;\">件</small></span><span class=\"sl\"><ruby>施設<rt>しせつ</rt></ruby>による<br><ruby>虐待判断<rt>ぎゃくたいはんだん</rt></ruby></span><span class=\"si\">Fasilitas: terkonfirmasi</span></div>\n      </div>\n      <div class=\"hl hl-purple\" style=\"font-size:11.5px;\">\n        💡 <b>覚え方</b>：「<ruby>養護者<rt>ようごしゃ</rt></ruby>」の<ruby>件数<rt>けんすう</rt></ruby>は<ruby>施設<rt>しせつ</rt></ruby>の<b>約10倍以上</b>多い（40,386件 vs 3,441件）。家庭内の虐待が圧倒的多数。\n        <span class=\"id\">Kasus oleh pengasuh keluarga >10x lebih banyak daripada oleh staf fasilitas — penganiayaan di rumah jauh lebih dominan.</span>\n      </div>\n\n      <hr class=\"divider\">\n      <div class=\"sec-sub red\">👨‍👩‍👧 養護者による高齢者虐待（詳細）／ Detail: Penganiayaan oleh Pengasuh</div>\n      <div class=\"bar-chart\">\n        <div class=\"bar-row\"><span class=\"bar-label\"><ruby>身体的<rt>しんたいてき</rt></ruby><i>Fisik</i></span><div class=\"bar-track\"><div class=\"bar-fill\" style=\"width:100%;background:#c1121f;\">11,362人 (65%) ← 最多</div></div></div>\n        <div class=\"bar-row\"><span class=\"bar-label\"><ruby>心理的<rt>しんりてき</rt></ruby><i>Psikologis</i></span><div class=\"bar-track\"><div class=\"bar-fill\" style=\"width:58%;background:#6d597a;\">6,680人 (38%)</div></div></div>\n        <div class=\"bar-row\"><span class=\"bar-label\"><ruby>介護等放棄<rt>かいごとうほうき</rt></ruby><i>Penelantaran</i></span><div class=\"bar-track\"><div class=\"bar-fill\" style=\"width:29%;background:#d9883e;\">3,393人 (19%)</div></div></div>\n        <div class=\"bar-row\"><span class=\"bar-label\"><ruby>経済的<rt>けいざいてき</rt></ruby><i>Ekonomi</i></span><div class=\"bar-track\"><div class=\"bar-fill\" style=\"width:25%;background:#9e4a1e;\">2,773人 (16%)</div></div></div>\n      </div>\n\n      <div class=\"table-wrap\">\n      <table class=\"tbl\">\n        <tr style=\"background:#fef0f1;\"><th colspan=\"2\"><ruby>被虐待者<rt>ひぎゃくたいしゃ</rt></ruby>（<ruby>被害者<rt>ひがいしゃ</rt></ruby>）の<ruby>特徴<rt>とくちょう</rt></ruby> ／ Karakteristik korban</th></tr>\n        <tr><td><ruby>性別<rt>せいべつ</rt></ruby> <i style=\"color:#888;\">Gender</i></td><td><b style=\"color:#880e4f;\"><ruby>女性<rt>じょせい</rt></ruby> 76%</b>　<ruby>男性<rt>だんせい</rt></ruby> 24%</td></tr>\n        <tr><td><ruby>年齢<rt>ねんれい</rt></ruby> <i style=\"color:#888;\">Usia</i></td><td>80〜84<ruby>歳<rt>さい</rt></ruby>が<b>最多（26%）</b>、85〜89歳22%、75〜79歳19%</td></tr>\n        <tr><td><ruby>要介護認定<rt>ようかいごにんてい</rt></ruby> <i style=\"color:#888;\">Status pengakuan butuh perawatan</i></td><td><b><ruby>認定済<rt>にんていず</rt></ruby>み 72%</b>（<ruby>未申請<rt>みしんせい</rt></ruby>・<ruby>申請中<rt>しんせいちゅう</rt></ruby>等28%）</td></tr>\n        <tr><td><ruby>認知症日常生活自立度<rt>にんちしょうにちじょうせいかつじりつど</rt></ruby> <i style=\"color:#888;\">Tingkat kemandirian demensia</i></td><td><b>Ⅱ以上 74%</b>（重い認知症が多い）</td></tr>\n      </table>\n      <table class=\"tbl\">\n        <tr style=\"background:#fef0f1;\"><th colspan=\"2\"><ruby>虐待者<rt>ぎゃくたいしゃ</rt></ruby>（<ruby>加害者<rt>かがいしゃ</rt></ruby>）の<ruby>特徴<rt>とくちょう</rt></ruby> ／ Karakteristik pelaku</th></tr>\n        <tr><td><ruby>続柄<rt>つづきがら</rt></ruby> <i style=\"color:#888;\">Hubungan keluarga</i></td><td><b style=\"color:#c1121f;\"><ruby>息子<rt>むすこ</rt></ruby> 39%（<ruby>最多<rt>さいた</rt></ruby>）</b>　<ruby>夫<rt>おっと</rt></ruby> 23%　<ruby>娘<rt>むすめ</rt></ruby> 19%　<ruby>妻<rt>つま</rt></ruby> 8%</td></tr>\n        <tr><td><ruby>同居<rt>どうきょ</rt></ruby>・<ruby>別居<rt>べっきょ</rt></ruby> <i style=\"color:#888;\">Tinggal bersama/tidak</i></td><td><b><ruby>虐待者<rt>ぎゃくたいしゃ</rt></ruby>のみと<ruby>同居<rt>どうきょ</rt></ruby> 53%</b>、虐待者及び他家族と同居33%、別居等14%</td></tr>\n      </table>\n      <table class=\"tbl\">\n        <tr style=\"background:#fef0f1;\"><th colspan=\"2\"><ruby>対応状況<rt>たいおうじょうきょう</rt></ruby> ／ Status penanganan</th></tr>\n        <tr><td><ruby>相談<rt>そうだん</rt></ruby>・<ruby>通報者<rt>つうほうしゃ</rt></ruby> <i style=\"color:#888;\">Pelapor</i></td><td><b><ruby>警察<rt>けいさつ</rt></ruby> 34%</b>（<ruby>最多<rt>さいた</rt></ruby>）、<ruby>介護支援専門員<rt>かいごしえんせんもんいん</rt></ruby>25%、<ruby>家族<rt>かぞく</rt></ruby>・<ruby>親族<rt>しんぞく</rt></ruby>8%</td></tr>\n        <tr><td><ruby>分離<rt>ぶんり</rt></ruby>の<ruby>有無<rt>うむ</rt></ruby> <i style=\"color:#888;\">Apakah dipisahkan</i></td><td><ruby>虐待者<rt>ぎゃくたいしゃ</rt></ruby>と<ruby>分離<rt>ぶんり</rt></ruby> 34%、<b><ruby>分離<rt>ぶんり</rt></ruby>していない 52%</b>（<ruby>最多<rt>さいた</rt></ruby>）</td></tr>\n        <tr><td><ruby>分離<rt>ぶんり</rt></ruby>の<ruby>方法<rt>ほうほう</rt></ruby> <i style=\"color:#888;\">Cara pemisahan</i></td><td><b><ruby>介護保険サービス利用<rt>かいごほけんサービスりよう</rt></ruby> 34%</b>（<ruby>最多<rt>さいた</rt></ruby>）、<ruby>医療機関<rt>いりょうきかん</rt></ruby>への<ruby>一時入院<rt>いちじにゅういん</rt></ruby>17%</td></tr>\n      </table>\n      </div>\n\n      <hr class=\"divider\">\n      <div class=\"sec-sub orange\">🏢 養介護施設従事者等による高齢者虐待 ／ Oleh Staf Fasilitas</div>\n      <div class=\"bar-chart\">\n        <div class=\"bar-row\"><span class=\"bar-label\"><ruby>身体的<rt>しんたいてき</rt></ruby><i>Fisik</i></span><div class=\"bar-track\"><div class=\"bar-fill\" style=\"width:100%;background:#c1121f;\">1,198人 (51%) ← 最多</div></div></div>\n        <div class=\"bar-row\"><span class=\"bar-label\"><ruby>心理的<rt>しんりてき</rt></ruby><i>Psikologis</i></span><div class=\"bar-track\"><div class=\"bar-fill\" style=\"width:47%;background:#6d597a;\">568人 (24%)</div></div></div>\n        <div class=\"bar-row\"><span class=\"bar-label\"><ruby>介護等放棄<rt>かいごとうほうき</rt></ruby><i>Penelantaran</i></span><div class=\"bar-track\"><div class=\"bar-fill\" style=\"width:43%;background:#d9883e;\">521人 (22%)</div></div></div>\n      </div>\n      <div class=\"table-wrap\">\n      <table class=\"tbl\">\n        <tr><td><ruby>性別<rt>せいべつ</rt></ruby> <i style=\"color:#888;\">Gender korban</i></td><td><b style=\"color:#880e4f;\"><ruby>女性<rt>じょせい</rt></ruby> 72%</b>　<ruby>男性<rt>だんせい</rt></ruby> 28%</td></tr>\n        <tr><td><ruby>施設<rt>しせつ</rt></ruby>の<ruby>種別<rt>しゅべつ</rt></ruby> <i style=\"color:#888;\">Jenis fasilitas</i></td><td><b><ruby>特別養護老人ホーム<rt>とくべつようごろうじんホーム</rt></ruby> 31%</b>（最多）、<ruby>有料老人ホーム<rt>ゆうりょうろうじんホーム</rt></ruby>28%</td></tr>\n      </table>\n      </div>\n      <div class=\"fn\">出典：厚生労働省「高齢者虐待の防止、高齢者の養護者に対する支援等に関する法律」に基づく対応状況等に関する調査結果（令和5年度）</div>\n\n      <div class=\"mnemo\">\n        <div><span>65%</span>養護者による虐待で最多＝身体的</div>\n        <div><span>息子39%</span>虐待者の続柄で最多</div>\n        <div><span>80-84歳</span>被虐待者の年齢で最多</div>\n        <div><span>52%</span>分離していないケースが最多</div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ============ SECTION 4: 障害者虐待防止法 ============ -->\n<section class=\"section th-blue\" id=\"s4\">\n  <div class=\"sec-head\" onclick=\"toggle('s4')\">\n    <div class=\"sec-icon\">♿</div>\n    <div class=\"sec-title\">\n      <span class=\"jp\">④ <ruby>障害者虐待防止法<rt>しょうがいしゃぎゃくたいぼうしほう</rt></ruby> — <ruby>定義<rt>ていぎ</rt></ruby>と<ruby>3種類<rt>さんしゅるい</rt></ruby></span>\n      <span class=\"id\">UU Pencegahan Penganiayaan Penyandang Disabilitas</span>\n    </div>\n    <span class=\"toggle-arr\">▾</span>\n  </div>\n  <div class=\"sec-body\">\n    <div class=\"sec-inner\">\n\n      <div class=\"hl hl-blue\">\n        <b>正式名称</b>：<ruby>障害者虐待<rt>しょうがいしゃぎゃくたい</rt></ruby>の<ruby>防止<rt>ぼうし</rt></ruby>、<ruby>障害者<rt>しょうがいしゃ</rt></ruby>の<ruby>養護者<rt>ようごしゃ</rt></ruby>に<ruby>対<rt>たい</rt></ruby>する<ruby>支援等<rt>しえんとう</rt></ruby>に<ruby>関<rt>かん</rt></ruby>する<ruby>法律<rt>ほうりつ</rt></ruby>\n        <span class=\"id\">UU tentang Pencegahan Penganiayaan Penyandang Disabilitas & Dukungan bagi Pengasuh</span>\n      </div>\n\n      <div class=\"flow\">\n        <div class=\"fnode start\">START — <ruby>障害者<rt>しょうがいしゃ</rt></ruby>とは？<span class=\"id\">Siapa yang disebut \"penyandang disabilitas\"?</span></div>\n        <div class=\"arrow-v\"></div>\n        <div class=\"fnode q\"><ruby>身体障害<rt>しんたいしょうがい</rt></ruby>・<ruby>知的障害<rt>ちてきしょうがい</rt></ruby>・<ruby>精神障害<rt>せいしんしょうがい</rt></ruby>（<ruby>発達障害<rt>はったつしょうがい</rt></ruby>を<ruby>含<rt>ふく</rt></ruby>む）その他の心身の<ruby>機能<rt>きのう</rt></ruby>の<ruby>障害<rt>しょうがい</rt></ruby>がある？<span class=\"id\">Ada gangguan fisik, intelektual, mental (termasuk perkembangan), atau fungsi tubuh lainnya?</span></div>\n        <div class=\"arrow-v\"></div>\n        <div class=\"fnode q\">かつ、<ruby>障害<rt>しょうがい</rt></ruby>と<ruby>社会的障壁<rt>しゃかいてきしょうへき</rt></ruby>により<ruby>継続的<rt>けいぞくてき</rt></ruby>に<ruby>日常生活<rt>にちじょうせいかつ</rt></ruby>・<ruby>社会生活<rt>しゃかいせいかつ</rt></ruby>に<b><ruby>相当<rt>そうとう</rt></ruby>な<ruby>制限<rt>せいげん</rt></ruby></b>を受けている？<span class=\"id\">Dan secara berkelanjutan mengalami batasan signifikan dalam hidup sehari-hari/sosial akibat hambatan & disabilitas?</span></div>\n        <div class=\"arrow-v\"></div>\n        <div class=\"fnode end\" style=\"background:#1d3557;\">はい → <ruby>障害者<rt>しょうがいしゃ</rt></ruby>に<ruby>該当<rt>がいとう</rt></ruby><span class=\"id\" style=\"color:#dce9f7;\">Termasuk \"penyandang disabilitas\" menurut UU ini</span></div>\n      </div>\n\n      <hr class=\"divider\">\n      <div class=\"sec-sub blue\">👤 だれが虐待するか？／ Pelaku ada 3 jenis (≠ lansia yang 2 jenis!)</div>\n      <div class=\"flow\" style=\"gap:0;\">\n        <div class=\"fbranch\" style=\"gap:8px;\">\n          <div class=\"fbranch-col\">\n            <div class=\"fbranch-lbl lbl-a\">① <ruby>養護者<rt>ようごしゃ</rt></ruby></div>\n            <div class=\"connector-h\" style=\"background:#fce0e2;\"></div>\n            <div class=\"arrow-v\" style=\"background:#fce0e2;\"></div>\n            <div class=\"fcard n-red\" style=\"text-align:center;\"><ruby>家族<rt>かぞく</rt></ruby>・<ruby>介護者<rt>かいごしゃ</rt></ruby><span class=\"id\">Pengasuh/keluarga</span></div>\n          </div>\n          <div class=\"fbranch-col\">\n            <div class=\"fbranch-lbl lbl-b\">② <ruby>障害者福祉施設従事者等<rt>しょうがいしゃふくしじゅうじしゃとう</rt></ruby></div>\n            <div class=\"connector-h\" style=\"background:#fde4d8;\"></div>\n            <div class=\"arrow-v\" style=\"background:#fde4d8;\"></div>\n            <div class=\"fcard n-orange\" style=\"text-align:center;\"><ruby>福祉施設<rt>ふくししせつ</rt></ruby>の<ruby>職員<rt>しょくいん</rt></ruby><span class=\"id\">Staf fasilitas kesejahteraan</span></div>\n          </div>\n          <div class=\"fbranch-col\">\n            <div class=\"fbranch-lbl lbl-c\">③ <ruby>使用者<rt>しようしゃ</rt></ruby></div>\n            <div class=\"connector-h\" style=\"background:#dce9f7;\"></div>\n            <div class=\"arrow-v\" style=\"background:#dce9f7;\"></div>\n            <div class=\"fcard n-blue\" style=\"text-align:center;\"><ruby>勤務先<rt>きんむさき</rt></ruby>の<ruby>雇用主<rt>こようぬし</rt></ruby><span class=\"id\">Pemberi kerja / atasan tempat bekerja</span></div>\n          </div>\n        </div>\n      </div>\n      <div class=\"hl hl-purple\" style=\"font-size:11.5px;margin-top:10px;\">\n        💡 <b>覚え方</b>：<ruby>高齢者<rt>こうれいしゃ</rt></ruby>＝<b>2種類</b>（養護者／施設従事者）に対し、<ruby>障害者<rt>しょうがいしゃ</rt></ruby>＝<b>3種類</b>（＋使用者＝職場での虐待が追加）。これは<b>職場で働く障害者がいる</b>ためのケア。\n        <span class=\"id\">Lansia: 2 jenis pelaku. Disabilitas: 3 jenis (ditambah \"pemberi kerja\", karena penyandang disabilitas bisa bekerja).</span>\n      </div>\n\n      <div class=\"hl hl-red\" style=\"margin-top:10px;\">\n        🚫 <b><ruby>何人<rt>なんぴと</rt></ruby>も、<ruby>障害者<rt>しょうがいしゃ</rt></ruby>に<ruby>対<rt>たい</rt></ruby>し、<ruby>虐待<rt>ぎゃくたい</rt></ruby>をしてはならない</b>（<ruby>虐待<rt>ぎゃくたい</rt></ruby>の<ruby>禁止<rt>きんし</rt></ruby>）\n        <span class=\"id\">Siapapun dilarang melakukan penganiayaan terhadap penyandang disabilitas — larangan tegas dalam UU.</span>\n      </div>\n\n      <hr class=\"divider\">\n      <div class=\"sec-sub blue\">🏛️ 関係機関 ／ Lembaga Terkait</div>\n      <div class=\"compare-grid\">\n        <div class=\"compare-card n-green\">\n          <div class=\"compare-title\"><ruby>市町村<rt>しちょうそん</rt></ruby>レベル</div>\n          <b><ruby>市町村障害者虐待防止センター<rt>しちょうそんしょうがいしゃぎゃくたいぼうしセンター</rt></ruby></b><br>\n          <span style=\"font-size:11.5px;\"><ruby>市町村<rt>しちょうそん</rt></ruby>が<ruby>障害者福祉<rt>しょうがいしゃふくし</rt></ruby>の<ruby>事務<rt>じむ</rt></ruby>を<ruby>所掌<rt>しょしょう</rt></ruby>する<ruby>部局<rt>ぶきょく</rt></ruby>または<ruby>設置施設<rt>せっちしせつ</rt></ruby>に<ruby>機能<rt>きのう</rt></ruby>を<ruby>持<rt>も</rt></ruby>たせる</span>\n          <span class=\"id\">Fungsi dilekatkan pada unit/fasilitas yang ditetapkan kotamadya</span>\n        </div>\n        <div class=\"compare-card n-blue\">\n          <div class=\"compare-title\"><ruby>都道府県<rt>とどうふけん</rt></ruby>レベル</div>\n          <b><ruby>都道府県障害者権利擁護センター<rt>とどうふけんしょうがいしゃけんりようごセンター</rt></ruby></b><br>\n          <span style=\"font-size:11.5px;\"><ruby>都道府県<rt>とどうふけん</rt></ruby>が<ruby>障害者福祉<rt>しょうがいしゃふくし</rt></ruby>の<ruby>事務<rt>じむ</rt></ruby>を<ruby>所掌<rt>しょしょう</rt></ruby>する<ruby>部局<rt>ぶきょく</rt></ruby>または<ruby>設置施設<rt>せっちしせつ</rt></ruby>に<ruby>機能<rt>きのう</rt></ruby>を<ruby>持<rt>も</rt></ruby>たせる</span>\n          <span class=\"id\">Fungsi dilekatkan pada unit/fasilitas yang ditetapkan prefektur</span>\n        </div>\n      </div>\n\n      <div class=\"mnemo\">\n        <div><span>3種類</span>養護者・施設職員・使用者</div>\n        <div><span>＋使用者</span>障害者だけにある区分</div>\n        <div><span>市町村</span>虐待防止センター設置</div>\n        <div><span>都道府県</span>権利擁護センター設置</div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ============ SECTION 5: 障害者虐待 対応フロー＆統計 ============ -->\n<section class=\"section th-teal\" id=\"s5\">\n  <div class=\"sec-head\" onclick=\"toggle('s5')\">\n    <div class=\"sec-icon\">📋</div>\n    <div class=\"sec-title\">\n      <span class=\"jp\">⑤ <ruby>障害者<rt>しょうがいしゃ</rt></ruby>虐待の<ruby>対応<rt>たいおう</rt></ruby>フローと<ruby>統計<rt>とうけい</rt></ruby></span>\n      <span class=\"id\">Alur Penanganan & Statistik Penganiayaan Disabilitas</span>\n    </div>\n    <span class=\"toggle-arr\">▾</span>\n  </div>\n  <div class=\"sec-body\">\n    <div class=\"sec-inner\">\n\n      <div class=\"sec-sub teal\">📢 通報義務 ／ Kewajiban Lapor</div>\n      <div class=\"flow\">\n        <div class=\"fnode q\">だれによる<ruby>虐待<rt>ぎゃくたい</rt></ruby>を<ruby>発見<rt>はっけん</rt></ruby>したか？<span class=\"id\">Pelaku penganiayaan yang ditemukan siapa?</span></div>\n        <div class=\"arrow-v\"></div>\n        <div class=\"fbranch\">\n          <div class=\"fbranch-col\">\n            <div class=\"fbranch-lbl lbl-a\">①② <ruby>養護者<rt>ようごしゃ</rt></ruby> ／ <ruby>福祉施設従事者<rt>ふくししせつじゅうじしゃ</rt></ruby></div>\n            <div class=\"connector-h\"></div>\n            <div class=\"arrow-v\"></div>\n            <div class=\"fcard n-blue\"><b><ruby>速<rt>すみ</rt></ruby>やかに<ruby>市町村<rt>しちょうそん</rt></ruby>に<ruby>通報<rt>つうほう</rt></ruby></b><span class=\"id\">WAJIB segera lapor ke kotamadya</span></div>\n          </div>\n          <div class=\"fbranch-col\">\n            <div class=\"fbranch-lbl lbl-c\">③ <ruby>使用者<rt>しようしゃ</rt></ruby></div>\n            <div class=\"connector-h\"></div>\n            <div class=\"arrow-v\"></div>\n            <div class=\"fcard n-teal\"><b><ruby>速<rt>すみ</rt></ruby>やかに<ruby>市町村<rt>しちょうそん</rt></ruby><u>または</u><ruby>都道府県<rt>とどうふけん</rt></ruby>に<ruby>通報<rt>つうほう</rt></ruby></b><span class=\"id\">WAJIB lapor ke kotamadya ATAU prefektur</span></div>\n          </div>\n        </div>\n      </div>\n\n      <div class=\"hl hl-blue\" style=\"font-size:12px;\">\n        🔁 <b>報告の連鎖（使用者による虐待の場合）</b>：<ruby>福祉施設従事者<rt>ふくししせつじゅうじしゃ</rt></ruby>の<ruby>通報<rt>つうほう</rt></ruby>を<ruby>受<rt>う</rt></ruby>けた<ruby>市町村<rt>しちょうそん</rt></ruby>は<b><ruby>都道府県<rt>とどうふけん</rt></ruby>へ<ruby>報告<rt>ほうこく</rt></ruby></b>。<br>\n        <ruby>使用者<rt>しようしゃ</rt></ruby>による<ruby>虐待<rt>ぎゃくたい</rt></ruby>の<ruby>通報<rt>つうほう</rt></ruby>を<ruby>受<rt>う</rt></ruby>けた<ruby>市町村<rt>しちょうそん</rt></ruby>は<b><ruby>都道府県<rt>とどうふけん</rt></ruby>へ<ruby>通知<rt>つうち</rt></ruby></b>し、<ruby>都道府県知事<rt>とどうふけんちじ</rt></ruby>は<b><ruby>都道府県労働局<rt>とどうふけんろうどうきょく</rt></ruby>へ<ruby>報告<rt>ほうこく</rt></ruby></b>しなければならない。\n        <span class=\"id\">Rantai pelaporan: kotamadya → prefektur → (untuk kasus pemberi kerja) → kantor tenaga kerja prefektur.</span>\n      </div>\n\n      <div class=\"hl hl-green\">\n        🛡 <b><ruby>免責<rt>めんせき</rt></ruby></b>：<ruby>障害者虐待<rt>しょうがいしゃぎゃくたい</rt></ruby>の<ruby>通報<rt>つうほう</rt></ruby>をしても<b><ruby>守秘義務違反<rt>しゅひぎむいはん</rt></ruby>にならない</b>。<ruby>障害者福祉施設従事者等<rt>しょうがいしゃふくししせつじゅうじしゃとう</rt></ruby>または<ruby>労働者<rt>ろうどうしゃ</rt></ruby>は、<ruby>通報<rt>つうほう</rt></ruby>を<ruby>理由<rt>りゆう</rt></ruby>に<b><ruby>解雇<rt>かいこ</rt></ruby>その他<ruby>不利益<rt>ふりえき</rt></ruby>な<ruby>取扱<rt>とりあつかい</rt></ruby>いを<ruby>受<rt>う</rt></ruby>けない</b>。\n        <span class=\"id\">Melapor tidak melanggar kerahasiaan; pelapor tidak boleh dipecat/dirugikan karena melapor.</span>\n      </div>\n\n      <hr class=\"divider\">\n      <div class=\"sec-sub teal\">🔄 対応フロー ／ Alur Penanganan</div>\n      <div class=\"flow\">\n        <div class=\"fbranch\" style=\"gap:8px;\">\n          <div class=\"fbranch-col\"><div class=\"fcard n-green\" style=\"text-align:center;\"><b><ruby>発見者<rt>はっけんしゃ</rt></ruby></b><br><ruby>通報<rt>つうほう</rt></ruby></div></div>\n          <div class=\"fbranch-col\"><div class=\"fcard n-teal\" style=\"text-align:center;\"><b><ruby>本人<rt>ほんにん</rt></ruby></b><br><ruby>届出<rt>とどけで</rt></ruby></div></div>\n        </div>\n        <div class=\"arrow-v\"></div>\n        <div class=\"fnode\" style=\"background:#dce9f7;color:#1d3557;width:100%;\"><b><ruby>市町村<rt>しちょうそん</rt></ruby></b><br><span style=\"font-size:11px;font-weight:400;\"><ruby>相談<rt>そうだん</rt></ruby>・<ruby>指導<rt>しどう</rt></ruby>・<ruby>助言<rt>じょげん</rt></ruby> ／ <ruby>通報<rt>つうほう</rt></ruby>・<ruby>届出<rt>とどけで</rt></ruby>の<ruby>受理<rt>じゅり</rt></ruby></span><span class=\"id\">委託可：障害者虐待防止センターへ委託できる</span></div>\n        <div class=\"arrow-v\"></div>\n        <div class=\"fnode\" style=\"background:#fff3cd;color:#7a5000;width:100%;\"><b><ruby>安全確認<rt>あんぜんかくにん</rt></ruby>・<ruby>事実確認<rt>じじつかくにん</rt></ruby></b></div>\n        <div class=\"arrow-v\"></div>\n        <div class=\"fnode\" style=\"background:#fde4d8;color:#7a2a10;width:100%;\"><b><ruby>立入調査<rt>たちいりちょうさ</rt></ruby>・<ruby>質問<rt>しつもん</rt></ruby></b><span class=\"id\">援助要請 → 警察署長</span></div>\n        <div class=\"arrow-v\"></div>\n        <div class=\"fnode end\" style=\"width:100%;background:#0d4a44;\"><ruby>障害者支援施設<rt>しょうがいしゃしえんしせつ</rt></ruby>等への<ruby>一時保護<rt>いちじほご</rt></ruby> ／ <ruby>成年後見開始<rt>せいねんこうけんかいし</rt></ruby>の<ruby>審判<rt>しんぱん</rt></ruby>の<ruby>請求<rt>せいきゅう</rt></ruby>など<span class=\"id\" style=\"color:#d5f5f2;\">Perlindungan sementara di fasilitas dukungan disabilitas / pengajuan perwalian dewasa</span></div>\n      </div>\n      <div class=\"hl hl-teal\" style=\"font-size:11.5px;\">\n        💡 <b>覚え方</b>：高齢者の対応フローと<b>ほぼ同じ構造</b>（発見→市町村→確認→調査→措置）。違いは最後の<b>措置の根拠法</b>（高齢者＝老人福祉法／障害者＝障害者支援施設への一時保護）。\n        <span class=\"id\">Strukturnya hampir identik dengan alur lansia; perbedaannya pada dasar hukum tindakan akhir.</span>\n      </div>\n\n      <hr class=\"divider\">\n      <div class=\"sec-sub teal\">📊 統計データ（令和5年度）／ Statistik</div>\n      <div class=\"stat-row\">\n        <div class=\"stat-b n-red\"><span class=\"sn\">9,972<small style=\"font-size:11px;\">件</small></span><span class=\"sl\"><ruby>養護者<rt>ようごしゃ</rt></ruby>による<br><ruby>相談<rt>そうだん</rt></ruby>・<ruby>通報<rt>つうほう</rt></ruby></span></div>\n        <div class=\"stat-b n-red\"><span class=\"sn\">2,283<small style=\"font-size:11px;\">件</small></span><span class=\"sl\"><ruby>養護者<rt>ようごしゃ</rt></ruby>による<br><ruby>虐待判断<rt>ぎゃくたいはんだん</rt></ruby></span></div>\n        <div class=\"stat-b n-orange\"><span class=\"sn\">5,618<small style=\"font-size:11px;\">件</small></span><span class=\"sl\"><ruby>施設職員<rt>しせつしょくいん</rt></ruby>による<br><ruby>相談<rt>そうだん</rt></ruby>・<ruby>通報<rt>つうほう</rt></ruby></span></div>\n        <div class=\"stat-b n-orange\"><span class=\"sn\">1,194<small style=\"font-size:11px;\">件</small></span><span class=\"sl\"><ruby>施設職員<rt>しせつしょくいん</rt></ruby>による<br><ruby>虐待判断<rt>ぎゃくたいはんだん</rt></ruby></span></div>\n        <div class=\"stat-b n-blue\"><span class=\"sn\">675<small style=\"font-size:11px;\">件</small></span><span class=\"sl\"><ruby>使用者<rt>しようしゃ</rt></ruby>による<br><ruby>相談<rt>そうだん</rt></ruby>・<ruby>通報<rt>つうほう</rt></ruby></span></div>\n      </div>\n\n      <div class=\"sec-sub red\" style=\"margin-top:14px;\">👨‍👩‍👧 養護者による障害者虐待（9,972件）</div>\n      <div class=\"bar-chart\">\n        <div class=\"bar-row\"><span class=\"bar-label\"><ruby>身体的<rt>しんたいてき</rt></ruby><i>Fisik</i></span><div class=\"bar-track\"><div class=\"bar-fill\" style=\"width:100%;background:#c1121f;\">1,542件 (68%) ← 最多</div></div></div>\n        <div class=\"bar-row\"><span class=\"bar-label\"><ruby>心理的<rt>しんりてき</rt></ruby><i>Psikologis</i></span><div class=\"bar-track\"><div class=\"bar-fill\" style=\"width:47%;background:#6d597a;\">730件 (32%)</div></div></div>\n      </div>\n      <div class=\"table-wrap\">\n      <table class=\"tbl\">\n        <tr><td><ruby>性別<rt>せいべつ</rt></ruby>（<ruby>被害者<rt>ひがいしゃ</rt></ruby>）</td><td><b style=\"color:#880e4f;\"><ruby>女性<rt>じょせい</rt></ruby> 64%</b>　<ruby>男性<rt>だんせい</rt></ruby> 36%</td></tr>\n        <tr><td><ruby>障害種別<rt>しょうがいしゅべつ</rt></ruby></td><td><b><ruby>知的障害<rt>ちてきしょうがい</rt></ruby> 1,044人</b>（<ruby>最多<rt>さいた</rt></ruby>）、<ruby>精神障害<rt>せいしんしょうがい</rt></ruby>1,015人、<ruby>身体障害<rt>しんたいしょうがい</rt></ruby>384人</td></tr>\n        <tr><td><ruby>同居<rt>どうきょ</rt></ruby>・<ruby>別居<rt>べっきょ</rt></ruby></td><td><b><ruby>虐待者<rt>ぎゃくたいしゃ</rt></ruby>と<ruby>同居<rt>どうきょ</rt></ruby> 85%</b>（高齢者の53%より高い）</td></tr>\n        <tr><td><ruby>続柄<rt>つづきがら</rt></ruby></td><td><b><ruby>母<rt>はは</rt></ruby> 25%</b>（最多、高齢者は「息子」が最多で対照的）、<ruby>父<rt>ちち</rt></ruby>24%、<ruby>夫<rt>おっと</rt></ruby>16%</td></tr>\n        <tr><td><ruby>相談<rt>そうだん</rt></ruby>・<ruby>通報者<rt>つうほうしゃ</rt></ruby></td><td><b><ruby>警察<rt>けいさつ</rt></ruby> 53%</b>（最多）</td></tr>\n        <tr><td><ruby>分離<rt>ぶんり</rt></ruby>の<ruby>有無<rt>うむ</rt></ruby></td><td><b><ruby>分離<rt>ぶんり</rt></ruby>していない 47%</b>（最多）、分離34%</td></tr>\n      </table>\n      </div>\n\n      <div class=\"sec-sub orange\" style=\"margin-top:14px;\">🏢 障害者福祉施設従事者等による障害者虐待（5,618件）</div>\n      <div class=\"bar-chart\">\n        <div class=\"bar-row\"><span class=\"bar-label\"><ruby>身体的<rt>しんたいてき</rt></ruby><i>Fisik</i></span><div class=\"bar-track\"><div class=\"bar-fill\" style=\"width:100%;background:#c1121f;\">620件 (52%) ← 最多</div></div></div>\n        <div class=\"bar-row\"><span class=\"bar-label\"><ruby>心理的<rt>しんりてき</rt></ruby><i>Psikologis</i></span><div class=\"bar-track\"><div class=\"bar-fill\" style=\"width:92%;background:#6d597a;\">573件 (48%)</div></div></div>\n      </div>\n      <div class=\"table-wrap\">\n      <table class=\"tbl\">\n        <tr><td><ruby>性別<rt>せいべつ</rt></ruby>（<ruby>被害者<rt>ひがいしゃ</rt></ruby>）</td><td><b style=\"color:#1d3557;\"><ruby>男性<rt>だんせい</rt></ruby> 67%</b>（高齢者・養護者ケースと違い男性が多い）　<ruby>女性<rt>じょせい</rt></ruby> 33%</td></tr>\n        <tr><td><ruby>障害種別<rt>しょうがいしゅべつ</rt></ruby></td><td><b><ruby>知的障害<rt>ちてきしょうがい</rt></ruby> 1,751人</b>（最多）、<ruby>精神障害<rt>せいしんしょうがい</rt></ruby>446人、<ruby>身体障害<rt>しんたいしょうがい</rt></ruby>444人</td></tr>\n        <tr><td><ruby>施設<rt>しせつ</rt></ruby>の<ruby>種別<rt>しゅべつ</rt></ruby></td><td><b><ruby>共同生活援助<rt>きょうどうせいかつえんじょ</rt></ruby> 28%</b>（最多）、<ruby>障害者支援施設<rt>しょうがいしゃしえんしせつ</rt></ruby>20%</td></tr>\n      </table>\n      </div>\n\n      <div class=\"sec-sub blue\" style=\"margin-top:14px;\">💼 使用者による障害者虐待（675件）</div>\n      <div class=\"hl hl-blue\" style=\"font-size:12px;\">\n        <ruby>対応状況<rt>たいおうじょうきょう</rt></ruby>の<ruby>相談<rt>そうだん</rt></ruby>・<ruby>通報者<rt>つうほうしゃ</rt></ruby>：<b><ruby>本人<rt>ほんにん</rt></ruby>による<ruby>届出<rt>とどけで</rt></ruby> 41%</b>（最多）、<ruby>障害者福祉施設従事者等<rt>しょうがいしゃふくししせつじゅうじしゃとう</rt></ruby>12%、<ruby>家族<rt>かぞく</rt></ruby>・<ruby>親族<rt>しんぞく</rt></ruby>12%\n        <span class=\"id\">Pelapor terbanyak adalah korban sendiri (41%) — berbeda dari kasus lain yang biasanya polisi/keluarga.</span>\n      </div>\n      <div class=\"fn\">出典：厚生労働省「障害者虐待の防止、障害者の養護者に対する支援等に関する法律」に基づく対応状況等に関する調査結果（令和5年度）</div>\n\n      <hr class=\"divider\">\n      <div class=\"sec-sub purple\">⚖️ 高齢者 vs 障害者 — 比較まとめ ／ Perbandingan</div>\n      <div class=\"compare-grid\">\n        <div class=\"compare-card n-red\">\n          <div class=\"compare-title\">👴 高齢者虐待</div>\n          <span style=\"font-size:12px;line-height:1.8;\">\n          対象：<b>65歳以上</b><br>\n          虐待者：<b>2種類</b>（養護者／施設従事者）<br>\n          最多虐待種類：<b>身体的（65%）</b><br>\n          虐待者の続柄：<b>息子（39%）</b>が最多<br>\n          機関：地域包括支援センター（委託可）\n          </span>\n        </div>\n        <div class=\"compare-card n-blue\">\n          <div class=\"compare-title\">♿ 障害者虐待</div>\n          <span style=\"font-size:12px;line-height:1.8;\">\n          対象：<b>障害の定義</b>を満たす人（年齢無関係）<br>\n          虐待者：<b>3種類</b>（養護者／施設従事者／使用者）<br>\n          最多虐待種類（養護者）：<b>身体的（68%）</b><br>\n          虐待者の続柄：<b>母（25%）</b>が最多<br>\n          機関：市町村虐待防止センター／都道府県権利擁護センター\n          </span>\n        </div>\n      </div>\n\n      <div class=\"mnemo\">\n        <div><span>知的障害</span>養護者・施設職員ケースどちらも最多の障害種別</div>\n        <div><span>母25%</span>養護者(障害者)の続柄で最多</div>\n        <div><span>本人41%</span>使用者ケースの通報者で最多</div>\n        <div><span>同居85%</span>障害者は同居率が高齢者より高い</div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<div style=\"text-align:center;margin-top:24px;font-size:11px;color:#9ca3af;\">\n  📚 第1章 第2節 ⑤ 虐待（高齢者・障害者）／ Versi Flowchart Furigana untuk Hafalan\n</div>\n\n</main>\n<script>\nfunction toggle(id){\n  document.getElementById(id).classList.toggle('open');\n}\ndocument.querySelectorAll('.toc-btn').forEach(btn=>{\n  btn.addEventListener('click', function(e){\n    e.preventDefault();\n    const id = this.getAttribute('href').substring(1);\n    const sec = document.getElementById(id);\n    if(!sec.classList.contains('open')) sec.classList.add('open');\n    setTimeout(()=>{ sec.scrollIntoView({behavior:'smooth', block:'start'}); }, 50);\n  });\n});\n<\/script>\n</body>\n</html>\n","songen-6":"<!DOCTYPE html>\n<html lang=\"ja\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>児童虐待・DVフローチャート — Penganiayaan Anak & KDRT</title>\n<link href=\"https://fonts.googleapis.com/css2?family=Noto+Sans+JP:wght@300;400;500;700;900&family=Noto+Serif+JP:wght@400;700;900&display=swap\" rel=\"stylesheet\">\n<style>\n:root{\n  --r1:#5c1010;--r2:#c1121f;--rp:#fce0e2;\n  --o1:#9e4a1e;--o2:#e76f51;--op:#fde4d8;\n  --b1:#1d3557;--b2:#457b9d;--bp:#dce9f7;\n  --p1:#3d2060;--p2:#6d597a;--pp:#ece5f5;\n  --t1:#0d4a44;--t2:#2a9d8f;--tp:#d5f5f2;\n  --g1:#1b4332;--g2:#2d6a4f;--gp:#d8f3dc;\n  --y1:#7a5000;--y2:#f4a261;--yp:#fff3cd;\n  --pk1:#880e4f;--pk2:#d6608a;--pkp:#fce4ec;\n  --tx:#1a1a2e;--txm:#374151;--txs:#6b7280;\n}\n*{margin:0;padding:0;box-sizing:border-box;}\nbody{font-family:'Noto Sans JP',sans-serif;background:#f0eef3;color:var(--tx);min-height:100vh;}\nheader{background:linear-gradient(135deg,#2a1845 0%,#3d2060 35%,#6d597a 70%,#9c7a8e 100%);padding:40px 20px 30px;text-align:center;position:relative;overflow:hidden;}\nheader::before{content:'';position:absolute;top:-80px;right:-80px;width:300px;height:300px;border-radius:50%;background:rgba(255,255,255,0.04);}\n.hbadge{display:inline-block;background:rgba(255,255,255,0.15);border:1px solid rgba(255,255,255,0.3);color:#ece5f5;font-size:11px;letter-spacing:3px;padding:5px 16px;border-radius:30px;margin-bottom:14px;font-weight:500;}\n.star-row{color:#f4d03f;font-size:18px;margin-bottom:12px;letter-spacing:3px;}\nheader h1{font-family:'Noto Serif JP',serif;color:#fff;font-size:clamp(19px,5.2vw,30px);font-weight:900;line-height:1.5;margin-bottom:8px;}\nheader p{color:rgba(255,255,255,0.65);font-size:12px;letter-spacing:1px;}\n.toc{max-width:860px;margin:18px auto 0;padding:0 14px;display:flex;flex-wrap:wrap;gap:8px;justify-content:center;}\n.toc-btn{background:rgba(255,255,255,0.12);border:1px solid rgba(255,255,255,0.25);color:#fff;font-size:11px;padding:6px 14px;border-radius:20px;cursor:pointer;text-decoration:none;transition:background .2s;white-space:nowrap;}\n.toc-btn:hover{background:rgba(255,255,255,0.25);}\nmain{max-width:860px;margin:0 auto;padding:24px 14px 70px;}\n\n.section{margin-bottom:18px;border-radius:16px;overflow:hidden;box-shadow:0 2px 14px rgba(0,0,0,0.08);animation:fadeUp .5s ease both;}\n@keyframes fadeUp{from{opacity:0;transform:translateY(18px)}to{opacity:1;transform:translateY(0)}}\n.sec-head{display:flex;align-items:center;gap:12px;padding:15px 18px;cursor:pointer;user-select:none;transition:filter .2s;}\n.sec-head:hover{filter:brightness(1.06);}\n.sec-icon{width:40px;height:40px;border-radius:50%;background:rgba(255,255,255,0.18);display:flex;align-items:center;justify-content:center;font-size:19px;flex-shrink:0;}\n.sec-title .jp{font-size:15px;font-weight:900;color:#fff;display:block;}\n.sec-title .id{font-size:11px;color:rgba(255,255,255,.7);display:block;margin-top:2px;}\n.toggle-arr{color:rgba(255,255,255,.8);font-size:13px;margin-left:auto;transition:transform .35s;flex-shrink:0;}\n.section.open .toggle-arr{transform:rotate(180deg);}\n.sec-body{background:#fdfdfb;overflow:hidden;max-height:0;transition:max-height .6s ease;}\n.section.open .sec-body{max-height:30000px;}\n.sec-inner{padding:22px 16px 28px;}\n.th-green  .sec-head{background:linear-gradient(90deg,#1b4332,#2d6a4f);}\n.th-pink   .sec-head{background:linear-gradient(90deg,#880e4f,#d6608a);}\n.th-purple .sec-head{background:linear-gradient(90deg,#3d2060,#6d597a);}\n\n.hl{border-left:5px solid;padding:12px 14px;border-radius:0 10px 10px 0;margin:10px 0;font-size:13px;line-height:1.75;}\n.hl-green {border-color:#2d6a4f;background:#f0faf5;color:#1b4332;}\n.hl-pink  {border-color:#d6608a;background:#fef0f5;color:#880e4f;}\n.hl-purple{border-color:#6d597a;background:#f5f0fb;color:#3d2060;}\n.hl-orange{border-color:#e76f51;background:#fef5f2;color:#7a2a10;}\n.hl-blue  {border-color:#457b9d;background:#eef5fc;color:#1d3557;}\n.hl-red   {border-color:#c1121f;background:#fef0f1;color:#7a0c13;}\n.hl b{font-weight:900;}\n.hl .id{display:block;color:var(--txs);font-size:11.5px;margin-top:4px;font-style:italic;font-weight:400;}\n\n/* ===== FLOWCHART CORE ===== */\n.flow{display:flex;flex-direction:column;align-items:center;margin:14px 0;}\n.fnode{border-radius:12px;padding:11px 16px;text-align:center;font-size:13px;font-weight:700;line-height:1.55;box-shadow:0 2px 6px rgba(0,0,0,.06);max-width:100%;}\n.fnode .id{display:block;font-size:11px;font-weight:400;color:var(--txm);margin-top:4px;}\n.fnode.start{background:linear-gradient(135deg,#1b4332,#52b788);color:#fff;font-size:14px;font-weight:900;letter-spacing:.5px;}\n.fnode.start.pink{background:linear-gradient(135deg,#880e4f,#d6608a);}\n.fnode.start .id{color:#d8f3dc;}\n.fnode.start.pink .id{color:#fce4ec;}\n.fnode.q{background:#fff3cd;color:#7a5000;border:2px dashed #f4a261;border-radius:50px;padding:11px 22px;}\n.fnode.q .id{color:#9c7a40;}\n.fnode.end{background:#1b4332;color:#fff;font-weight:900;}\n.fnode.end.pink{background:#880e4f;}\n.fnode.end .id{color:#d8f3dc;}\n.fnode.end.pink .id{color:#fce4ec;}\n.arrow-v{width:2px;height:18px;background:#a8d5ba;position:relative;}\n.arrow-v::after{content:'';position:absolute;bottom:-1px;left:50%;transform:translateX(-50%);border-left:5px solid transparent;border-right:5px solid transparent;border-top:7px solid #a8d5ba;}\n.arrow-v.pink{background:#eab3c9;}\n.arrow-v.pink::after{border-top-color:#eab3c9;}\n.fbranch{display:flex;width:100%;justify-content:center;gap:10px;margin-top:0;}\n.fbranch-col{display:flex;flex-direction:column;align-items:center;flex:1;min-width:0;}\n.fbranch-lbl{font-size:10px;font-weight:900;padding:2px 10px;border-radius:20px;margin-bottom:6px;white-space:nowrap;text-align:center;}\n.lbl-yes{background:#d8f3dc;color:#1b4332;}\n.lbl-no{background:#fce0e2;color:#7a0c13;}\n.lbl-a{background:#dce9f7;color:#1d3557;}\n.lbl-b{background:#fde4d8;color:#7a2a10;}\n.lbl-c{background:#ece5f5;color:#3d2060;}\n.connector-h{height:2px;background:#a8d5ba;width:100%;position:relative;margin-top:8px;}\n.connector-h.pink{background:#eab3c9;}\n@media(max-width:520px){.fbranch{flex-direction:column;align-items:center;gap:6px;}.fbranch-col{width:100%;}}\n\n.fcard{border-radius:10px;padding:9px 12px;font-size:11.5px;line-height:1.65;width:100%;}\n.fcard b{font-size:12.5px;}\n.fcard .id{display:block;color:var(--txs);font-size:10.5px;margin-top:4px;font-style:italic;}\n.n-green {background:#d8f3dc;color:#1b4332;} .n-blue{background:#dce9f7;color:#1d3557;}\n.n-yellow{background:#fff3cd;color:#7a5000;} .n-orange{background:#fde4d8;color:#7a2a10;}\n.n-red{background:#fce0e2;color:#7a0c13;} .n-purple{background:#ece5f5;color:#3d2060;}\n.n-teal{background:#d5f5f2;color:#0d4a44;} .n-gray{background:#f3f4f6;color:#374151;}\n.n-pink{background:#fce4ec;color:#880e4f;}\n\n/* mnemonic strip */\n.mnemo{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin:12px 0;}\n.mnemo div{background:#fff;border:1.5px solid #e3dada;border-radius:10px;padding:8px 6px;text-align:center;font-size:11px;font-weight:700;line-height:1.4;}\n.mnemo div span{display:block;font-size:18px;margin-bottom:2px;}\n@media(max-width:560px){.mnemo{grid-template-columns:repeat(2,1fr);}}\n\n/* bar charts */\n.bar-chart{margin:10px 0;}\n.bar-row{display:flex;align-items:center;gap:8px;margin:8px 0;}\n.bar-label{flex:0 0 100px;font-size:11.5px;text-align:right;line-height:1.3;}\n.bar-label i{font-size:10px;color:#888;display:block;font-weight:400;font-style:italic;}\n.bar-track{flex:1;background:#f1eef3;border-radius:8px;overflow:hidden;height:28px;}\n.bar-fill{height:100%;display:flex;align-items:center;padding-left:10px;color:#fff;font-size:11.5px;font-weight:900;white-space:nowrap;border-radius:8px;}\n\n/* trend mini chart */\n.trend-box{background:#f7f5fa;border-radius:12px;padding:14px;margin:12px 0;text-align:center;}\n.trend-num{font-size:26px;font-weight:900;color:#3d2060;}\n.trend-sub{font-size:11px;color:#6b7280;margin-top:2px;}\n.trend-arrow{font-size:22px;color:#2a9d8f;margin:0 8px;}\n\n/* tables */\n.tbl{width:100%;border-collapse:collapse;font-size:11.5px;margin:8px 0;}\n.tbl th{padding:7px 8px;text-align:left;font-size:10.5px;font-weight:900;border-bottom:2px solid #e0e0e0;background:#f8f8f8;color:#374151;}\n.tbl td{padding:6px 8px;border-bottom:1px solid #f0f0f0;vertical-align:top;line-height:1.6;}\n.tbl tr:last-child td{border-bottom:none;}\n.table-wrap{overflow-x:auto;}\n.sec-sub{font-size:12px;font-weight:900;letter-spacing:1px;color:#fff;background:#2d6a4f;display:inline-block;padding:4px 12px;border-radius:20px;margin:16px 0 8px;}\n.sec-sub.pink{background:#d6608a;} .sec-sub.purple{background:#6d597a;}\n.sec-sub.orange{background:#e76f51;} .sec-sub.blue{background:#457b9d;}\n.divider{border:none;border-top:1px dashed #d9cfe0;margin:16px 0;}\n.fn{font-size:10.5px;color:#6b7280;margin-top:8px;line-height:1.6;}\nruby rt{font-size:9px;color:#2d6a4f;line-height:1;}\n.th-pink ruby rt{color:#d6608a;}\n.th-purple ruby rt{color:#6d597a;}\n\n/* big comparison table - 4 laws */\n.law-table{width:100%;border-collapse:collapse;font-size:10.8px;margin:10px 0;}\n.law-table th{padding:7px 6px;text-align:center;font-weight:900;border:1px solid #e3dada;line-height:1.4;}\n.law-table td{padding:6px 6px;border:1px solid #ececec;vertical-align:top;line-height:1.55;text-align:center;}\n.law-table td.row-head{text-align:left;background:#faf8fb;font-weight:700;font-size:10.5px;}\n.law-table .lt-elder{background:#fef0f1;} .law-table .lt-elder-h{background:#c1121f;color:#fff;}\n.law-table .lt-disab{background:#eef5fc;} .law-table .lt-disab-h{background:#457b9d;color:#fff;}\n.law-table .lt-child{background:#f0faf5;} .law-table .lt-child-h{background:#2d6a4f;color:#fff;}\n.law-table .lt-dv{background:#fef0f5;} .law-table .lt-dv-h{background:#d6608a;color:#fff;}\n.law-table .yes-mark{color:#2d6a4f;font-weight:900;font-size:13px;}\n.law-table .partial-mark{color:#9c7a40;font-weight:900;font-size:11px;}\n.table-scroll{overflow-x:auto;-webkit-overflow-scrolling:touch;}\n.table-scroll .law-table{min-width:680px;}\n.scroll-hint{font-size:10px;color:#9ca3af;text-align:center;margin-bottom:4px;}\n\n.compare-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin:10px 0;}\n@media(max-width:480px){.compare-grid{grid-template-columns:1fr;}}\n.compare-card{border-radius:10px;padding:13px;}\n.compare-title{font-weight:900;font-size:13px;margin-bottom:8px;padding-bottom:6px;border-bottom:2px solid rgba(0,0,0,0.08);}\n</style>\n<style id=\"pk-fix\">\n.sec-body{max-height:none!important;overflow:visible!important;display:none;transition:none!important}\n.section.open .sec-body{display:block}\n.section{animation:none!important;opacity:1!important;transform:none!important}\n*{min-width:0}\nbody{overflow-x:hidden;-webkit-text-size-adjust:100%}\nmain{padding-left:10px!important;padding-right:10px!important}\np,div,span,td,th,li{overflow-wrap:anywhere;word-break:normal}\nimg,svg,video{max-width:100%;height:auto}\ntable{display:block;max-width:100%;overflow-x:auto;-webkit-overflow-scrolling:touch;border-collapse:collapse}\n@media (max-width:560px){\n [class*=\"grid\"],[class*=\"cols\"],[class*=\"compare\"],[class*=\"pair\"],[class*=\"two\"],[class*=\"stats\"]{grid-template-columns:1fr 1fr!important}\n [class*=\"grid3\"],[class*=\"grid-3\"],[class*=\"three\"]{grid-template-columns:1fr!important}\n [class*=\"row\"],[class*=\"flex\"],[class*=\"flow\"],[class*=\"chain\"]{flex-wrap:wrap!important}\n [class*=\"compare\"] > *,[class*=\"pair\"] > *{min-width:0}\n}\n</style>\n<script>\n(function(){\n function post(){try{parent.postMessage({pkH:Math.ceil(document.documentElement.scrollHeight)},'*');}catch(e){}}\n document.addEventListener('DOMContentLoaded',function(){\n  document.querySelectorAll('.section').forEach(function(s,i){ if(i===0) s.classList.add('open'); });\n  post();\n  if(window.ResizeObserver) new ResizeObserver(post).observe(document.body);\n  document.addEventListener('click',function(){setTimeout(post,30);setTimeout(post,400);});\n });\n window.addEventListener('load',post);\n})();\n<\/script></head>\n<body>\n<header>\n  <div class=\"hbadge\">第1章 第2節 ⑤ — フローチャート 続編</div>\n  <div class=\"star-row\">★★☆</div>\n  <h1><ruby>児童虐待<rt>じどうぎゃくたい</rt></ruby>・<ruby>DV<rt>ディーブイ</rt></ruby>・<ruby>4法<rt>よんほう</rt></ruby>比較<br>\n    <span style=\"font-size:.55em;font-weight:400;color:rgba(255,255,255,.7);\">Penganiayaan Anak, KDRT, & Perbandingan 4 UU</span>\n  </h1>\n  <p>タップして各フローを開く ／ Ketuk untuk membuka tiap diagram alur</p>\n  <div class=\"toc\">\n    <a class=\"toc-btn\" href=\"#s1\">①児童虐待の定義</a>\n    <a class=\"toc-btn\" href=\"#s2\">②児童相談所の対応</a>\n    <a class=\"toc-btn\" href=\"#s3\">③DVの定義と統計</a>\n    <a class=\"toc-btn\" href=\"#s4\">④4法まるごと比較</a>\n  </div>\n</header>\n<main>\n\n<!-- ============ SECTION 1: 児童虐待の定義・統計 ============ -->\n<section class=\"section open th-green\" id=\"s1\">\n  <div class=\"sec-head\" onclick=\"toggle('s1')\">\n    <div class=\"sec-icon\">🧒</div>\n    <div class=\"sec-title\">\n      <span class=\"jp\">① <ruby>児童虐待<rt>じどうぎゃくたい</rt></ruby>の<ruby>定義<rt>ていぎ</rt></ruby>と<ruby>統計<rt>とうけい</rt></ruby></span>\n      <span class=\"id\">Definisi & Statistik Penganiayaan Anak</span>\n    </div>\n    <span class=\"toggle-arr\">▾</span>\n  </div>\n  <div class=\"sec-body\">\n    <div class=\"sec-inner\">\n\n      <div class=\"hl hl-green\">\n        <b>関連法</b>：<ruby>児童虐待<rt>じどうぎゃくたい</rt></ruby>の<ruby>防止<rt>ぼうし</rt></ruby>等に<ruby>関<rt>かん</rt></ruby>する<ruby>法律<rt>ほうりつ</rt></ruby>（<ruby>児童虐待防止法<rt>じどうぎゃくたいぼうしほう</rt></ruby>）— <ruby>平成<rt>へいせい</rt></ruby>12<ruby>年<rt>ねん</rt></ruby>施行<span class=\"id\">UU Pencegahan Penganiayaan Anak — berlaku sejak 2000</span>\n      </div>\n\n      <div class=\"trend-box\">\n        <span class=\"trend-num\">225,509<small style=\"font-size:14px;\">件</small></span>\n        <div class=\"trend-sub\"><ruby>令和<rt>れいわ</rt></ruby>5<ruby>年度<rt>ねんど</rt></ruby>の<ruby>児童相談所<rt>じどうそうだんしょ</rt></ruby>における<ruby>児童虐待相談<rt>じどうぎゃくたいそうだん</rt></ruby>の<ruby>対応件数<rt>たいおうけんすう</rt></ruby></div>\n        <div class=\"trend-sub\" style=\"font-style:italic;\">Jumlah kasus konsultasi penganiayaan anak di Pusat Konsultasi Anak (TA2023)</div>\n      </div>\n      <div class=\"hl hl-green\" style=\"font-size:11.5px;\">\n        📈 <ruby>平成<rt>へいせい</rt></ruby>2<ruby>年<rt>ねん</rt></ruby>（1990<ruby>年<rt>ねん</rt></ruby>）からほぼ<b>右肩上がりで急増</b>、特に平成20年以降の増加が著しい。<span class=\"id\">Meningkat tajam sejak 1990, lonjakan paling besar setelah 2008.</span>\n      </div>\n\n      <hr class=\"divider\">\n      <div class=\"sec-sub\">📊 相談別対応件数 ／ Berdasarkan Jenis Penganiayaan</div>\n      <div class=\"bar-chart\">\n        <div class=\"bar-row\"><span class=\"bar-label\"><ruby>心理的虐待<rt>しんりてきぎゃくたい</rt></ruby><i>Psikologis</i></span><div class=\"bar-track\"><div class=\"bar-fill\" style=\"width:100%;background:#52b788;\">60% ← 最多</div></div></div>\n        <div class=\"bar-row\"><span class=\"bar-label\"><ruby>身体的虐待<rt>しんたいてきぎゃくたい</rt></ruby><i>Fisik</i></span><div class=\"bar-track\"><div class=\"bar-fill\" style=\"width:38%;background:#e76f51;\">23%</div></div></div>\n        <div class=\"bar-row\"><span class=\"bar-label\"><ruby>ネグレクト<rt></rt></ruby><i>Penelantaran</i></span><div class=\"bar-track\"><div class=\"bar-fill\" style=\"width:27%;background:#f4a261;\">16%</div></div></div>\n        <div class=\"bar-row\"><span class=\"bar-label\"><ruby>性的虐待<rt>せいてきぎゃくたい</rt></ruby><i>Seksual</i></span><div class=\"bar-track\"><div class=\"bar-fill\" style=\"width:3%;background:#880e4f;\">約1%</div></div></div>\n      </div>\n      <div class=\"hl hl-orange\" style=\"font-size:11.5px;\">\n        💡 <b>注意</b>：<ruby>高齢者<rt>こうれいしゃ</rt></ruby>・<ruby>障害者<rt>しょうがいしゃ</rt></ruby>は<b>身体的虐待</b>が最多だったが、<ruby>児童<rt>じどう</rt></ruby>は<b>心理的虐待（60%）</b>が最多 — ここが試験で狙われやすい対比点。\n        <span class=\"id\">PENTING: Pada lansia/disabilitas, fisik adalah yang terbanyak. Pada anak, justru PSIKOLOGIS (60%) yang terbanyak — kontras ini sering jadi soal ujian.</span>\n      </div>\n\n      <hr class=\"divider\">\n      <div class=\"sec-sub\">📞 相談経路 ／ Jalur Pelaporan</div>\n      <div class=\"bar-chart\">\n        <div class=\"bar-row\"><span class=\"bar-label\"><ruby>警察等<rt>けいさつとう</rt></ruby><i>Polisi dll</i></span><div class=\"bar-track\"><div class=\"bar-fill\" style=\"width:100%;background:#6d597a;\">52% ← 最多</div></div></div>\n        <div class=\"bar-row\"><span class=\"bar-label\"><ruby>近隣知人<rt>きんりんちじん</rt></ruby><i>Tetangga/kenalan</i></span><div class=\"bar-track\"><div class=\"bar-fill\" style=\"width:19%;background:#457b9d;\">10%</div></div></div>\n        <div class=\"bar-row\"><span class=\"bar-label\"><ruby>家族<rt>かぞく</rt></ruby>・<ruby>親戚<rt>しんせき</rt></ruby><i>Keluarga</i></span><div class=\"bar-track\"><div class=\"bar-fill\" style=\"width:17%;background:#2a9d8f;\">9%</div></div></div>\n        <div class=\"bar-row\"><span class=\"bar-label\"><ruby>学校<rt>がっこう</rt></ruby><i>Sekolah</i></span><div class=\"bar-track\"><div class=\"bar-fill\" style=\"width:13%;background:#f4a261;\">7%</div></div></div>\n      </div>\n\n      <hr class=\"divider\">\n      <div class=\"sec-sub\">⚖️ 基本ルール ／ Aturan Dasar</div>\n      <div class=\"flow\">\n        <div class=\"fcard n-red\" style=\"text-align:center;\"><b>🚫 <ruby>何人<rt>なんぴと</rt></ruby>も、<ruby>児童<rt>じどう</rt></ruby>に<ruby>対<rt>たい</rt></ruby>し、<ruby>虐待<rt>ぎゃくたい</rt></ruby>をしてはならない</b><span class=\"id\">Siapapun dilarang menganiaya anak</span></div>\n        <div class=\"arrow-v\"></div>\n        <div class=\"fcard n-green\" style=\"text-align:center;\"><b>早期発見の努力義務</b>：<ruby>児童福祉<rt>じどうふくし</rt></ruby>に<ruby>業務<rt>ぎょうむ</rt></ruby>（<ruby>職務<rt>しょくむ</rt></ruby>）上<ruby>関係<rt>かんけい</rt></ruby>のある<b><ruby>団体<rt>だんたい</rt></ruby>（<ruby>人<rt>ひと</rt></ruby>）</b>は、<ruby>児童虐待<rt>じどうぎゃくたい</rt></ruby>を<ruby>発見<rt>はっけん</rt></ruby>しやすい<ruby>立場<rt>たちば</rt></ruby>にあることを<ruby>自覚<rt>じかく</rt></ruby>し、<ruby>早期発見<rt>そうきはっけん</rt></ruby>に<ruby>努<rt>つと</rt></ruby>めなければならない<span class=\"id\">Pihak terkait kesejahteraan anak wajib berupaya menemukan kasus sejak dini</span></div>\n        <div class=\"arrow-v\"></div>\n        <div class=\"fcard n-blue\" style=\"text-align:center;\"><b><ruby>児童<rt>じどう</rt></ruby>の<ruby>人格<rt>じんかく</rt></ruby>の<ruby>尊重<rt>そんちょう</rt></ruby></b>：<ruby>親権<rt>しんけん</rt></ruby>を<ruby>行<rt>おこな</rt></ruby>う<ruby>者<rt>もの</rt></ruby>は、しつけに<ruby>際<rt>さい</rt></ruby>して<ruby>児童<rt>じどう</rt></ruby>の<ruby>人格<rt>じんかく</rt></ruby>を<ruby>尊重<rt>そんちょう</rt></ruby>し、<ruby>年齢<rt>ねんれい</rt></ruby>・<ruby>発達<rt>はったつ</rt></ruby>の<ruby>程度<rt>ていど</rt></ruby>に<ruby>配慮<rt>はいりょ</rt></ruby>しなければならず、<b><ruby>体罰<rt>たいばつ</rt></ruby>その他<ruby>心身<rt>しんしん</rt></ruby>の<ruby>健全<rt>けんぜん</rt></ruby>な<ruby>発達<rt>はったつ</rt></ruby>に<ruby>有害<rt>ゆうがい</rt></ruby>な<ruby>言動<rt>げんどう</rt></ruby>をしてはならない</b><span class=\"id\">PENTING: Pemegang hak asuh wajib hormati kepribadian anak; DILARANG menggunakan hukuman fisik dalam mendidik</span></div>\n      </div>\n\n      <div class=\"mnemo\">\n        <div><span>60%</span>心理的虐待が最多（児童の特徴）</div>\n        <div><span>52%</span>相談経路は警察等が最多</div>\n        <div><span>体罰禁止</span>しつけでも体罰は不可</div>\n        <div><span>225,509件</span>令和5年度の対応件数</div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ============ SECTION 2: 児童相談所の対応フロー ============ -->\n<section class=\"section th-green\" id=\"s2\">\n  <div class=\"sec-head\" onclick=\"toggle('s2')\">\n    <div class=\"sec-icon\">🏢</div>\n    <div class=\"sec-title\">\n      <span class=\"jp\">② <ruby>通報<rt>つうほう</rt></ruby>から<ruby>措置<rt>そち</rt></ruby>までの<ruby>対応<rt>たいおう</rt></ruby>フロー</span>\n      <span class=\"id\">Alur Penanganan: dari Lapor sampai Tindakan</span>\n    </div>\n    <span class=\"toggle-arr\">▾</span>\n  </div>\n  <div class=\"sec-body\">\n    <div class=\"sec-inner\">\n\n      <div class=\"flow\">\n        <div class=\"fnode start\"><ruby>児童虐待<rt>じどうぎゃくたい</rt></ruby>を<ruby>受<rt>う</rt></ruby>けたと<ruby>思<rt>おも</rt></ruby>われる<ruby>児童<rt>じどう</rt></ruby>を<ruby>発見<rt>はっけん</rt></ruby>した<span class=\"id\">Menemukan anak yang diduga mengalami penganiayaan</span></div>\n        <div class=\"arrow-v\"></div>\n        <div class=\"fnode end\" style=\"background:#5c1010;\">⚖️ <b><ruby>通告義務<rt>つうこくぎむ</rt></ruby></b>（<ruby>通報<rt>つうほう</rt></ruby>ではなく「<ruby>通告<rt>つうこく</rt></ruby>」と<ruby>呼<rt>よ</rt></ruby>ぶ点に<ruby>注意<rt>ちゅうい</rt></ruby>）<span class=\"id\" style=\"color:#fce0e2;\">PERHATIAN: untuk anak, istilahnya \"tsuukoku\" (pemberitahuan wajib), bukan \"tsuuhou\"</span></div>\n        <div class=\"arrow-v\"></div>\n        <div class=\"fcard n-green\" style=\"text-align:center;\"><b><ruby>速<rt>すみ</rt></ruby>やかに<ruby>市町村<rt>しちょうそん</rt></ruby>、<ruby>都道府県<rt>とどうふけん</rt></ruby>の<ruby>設置<rt>せっち</rt></ruby>する<ruby>福祉事務所<rt>ふくしじむしょ</rt></ruby>、<ruby>児童相談所<rt>じどうそうだんしょ</rt></ruby>に<ruby>通告<rt>つうこく</rt></ruby>しなければならない</b><span class=\"id\">WAJIB lapor segera ke kotamadya, kantor kesejahteraan prefektur, atau pusat konsultasi anak</span></div>\n      </div>\n\n      <hr class=\"divider\">\n      <div class=\"sec-sub\">🔍 都道府県知事による調査の3段階 ／ 3 Tahap Investigasi oleh Gubernur</div>\n      <div class=\"flow\">\n        <div class=\"fnode q\"><ruby>児童虐待<rt>じどうぎゃくたい</rt></ruby>が<ruby>行<rt>おこな</rt></ruby>われているおそれがあると<ruby>認<rt>みと</rt></ruby>めた</div>\n        <div class=\"arrow-v\"></div>\n        <div class=\"fcard n-yellow\" style=\"text-align:center;width:100%;\">\n          <b>STEP 1：<ruby>出頭要求等<rt>しゅっとうようきゅうとう</rt></ruby></b><br>\n          <ruby>都道府県知事<rt>とどうふけんちじ</rt></ruby>は<ruby>児童<rt>じどう</rt></ruby>の<ruby>保護者<rt>ほごしゃ</rt></ruby>に<ruby>対<rt>たい</rt></ruby>し、<ruby>児童<rt>じどう</rt></ruby>を<ruby>同伴<rt>どうはん</rt></ruby>して<b><ruby>出頭<rt>しゅっとう</rt></ruby></b>することを<ruby>求<rt>もと</rt></ruby>め、<ruby>児童委員<rt>じどういいん</rt></ruby>又は<ruby>職員<rt>しょくいん</rt></ruby>に<ruby>調査<rt>ちょうさ</rt></ruby>・<ruby>質問<rt>しつもん</rt></ruby>させることができる\n          <span class=\"id\">Meminta orang tua membawa anak untuk datang & diperiksa petugas</span>\n        </div>\n        <div class=\"arrow-v\"></div>\n        <div class=\"fcard n-orange\" style=\"text-align:center;width:100%;\">\n          <b>STEP 2：<ruby>立入調査等<rt>たちいりちょうさとう</rt></ruby></b><br>\n          <ruby>児童委員<rt>じどういいん</rt></ruby>又は<ruby>職員<rt>しょくいん</rt></ruby>に、<ruby>児童<rt>じどう</rt></ruby>の<ruby>住所<rt>じゅうしょ</rt></ruby>又は<ruby>居所<rt>いどころ</rt></ruby>に<b><ruby>立<rt>た</rt></ruby>ち<ruby>入<rt>い</rt></ruby>り</b>、<ruby>調査<rt>ちょうさ</rt></ruby>・<ruby>質問<rt>しつもん</rt></ruby>させることができる\n          <span class=\"id\">Petugas dapat masuk langsung ke kediaman anak untuk memeriksa</span>\n        </div>\n        <div class=\"arrow-v\"></div>\n        <div class=\"fnode q\">STEP1の<ruby>出頭要求<rt>しゅっとうようきゅう</rt></ruby>等に<ruby>保護者<rt>ほごしゃ</rt></ruby>が<ruby>正当<rt>せいとう</rt></ruby>な<ruby>理由<rt>りゆう</rt></ruby>なく<ruby>応<rt>おう</rt></ruby>じない？<span class=\"id\">Orang tua menolak tanpa alasan sah?</span></div>\n        <div class=\"arrow-v\"></div>\n        <div class=\"fcard n-red\" style=\"text-align:center;width:100%;\">\n          <b>STEP 3：<ruby>臨検<rt>りんけん</rt></ruby>・<ruby>捜索<rt>そうさく</rt></ruby>等</b><br>\n          <ruby>安全<rt>あんぜん</rt></ruby>を<ruby>確保<rt>かくほ</rt></ruby>するため、<b><ruby>裁判所<rt>さいばんしょ</rt></ruby>の<ruby>裁判官<rt>さいばんかん</rt></ruby>があらかじめ<ruby>発<rt>はっ</rt></ruby>する<ruby>許可状<rt>きょかじょう</rt></ruby></b>により、<ruby>臨検<rt>りんけん</rt></ruby>させ、又は<ruby>当該児童<rt>とうがいじどう</rt></ruby>を<ruby>捜索<rt>そうさく</rt></ruby>させることができる\n          <span class=\"id\">Dengan surat izin hakim, dapat melakukan pemeriksaan paksa & mencari anak tersebut</span>\n        </div>\n      </div>\n      <div class=\"hl hl-green\" style=\"font-size:11.5px;\">\n        💡 <b>覚え方</b>：「<ruby>出頭<rt>しゅっとう</rt></ruby>→<ruby>立入<rt>たちいり</rt></ruby>→<ruby>臨検<rt>りんけん</rt></ruby>」の<b>3段階で強制力が増す</b>。最後の臨検・捜索だけ<b>裁判官の許可状が必要</b>（高齢者・障害者の対応フローにはこの3段階の細分化はない、児童虐待特有のしくみ）。\n        <span class=\"id\">3 tahap dengan kekuatan paksaan meningkat. Hanya tahap terakhir butuh surat izin hakim — mekanisme khusus untuk anak, tidak ada di lansia/disabilitas.</span>\n      </div>\n\n      <hr class=\"divider\">\n      <div class=\"sec-sub\">🚓 その他の対応 ／ Tindakan Lainnya</div>\n      <div class=\"flow\">\n        <div class=\"fcard n-blue\" style=\"text-align:center;\"><b><ruby>警察署長<rt>けいさつしょちょう</rt></ruby>に<ruby>対<rt>たい</rt></ruby>する<ruby>援助要請等<rt>えんじょようせいとう</rt></ruby></b>：<ruby>児童相談所長<rt>じどうそうだんしょちょう</rt></ruby>は、<ruby>必要<rt>ひつよう</rt></ruby>があると<ruby>認<rt>みと</rt></ruby>めるときは、<ruby>警察署長<rt>けいさつしょちょう</rt></ruby>に<ruby>援助<rt>えんじょ</rt></ruby>を<ruby>求<rt>もと</rt></ruby>めることができる<span class=\"id\">Kepala pusat konsultasi anak dapat meminta bantuan kepala polisi</span></div>\n        <div class=\"arrow-v\"></div>\n        <div class=\"fnode end\" style=\"width:100%;\">⛔ <b><ruby>面会等<rt>めんかいとう</rt></ruby>の<ruby>制限<rt>せいげん</rt></ruby></b><span class=\"id\" style=\"color:#d8f3dc;\">Pembatasan kontak dengan korban</span></div>\n      </div>\n      <div class=\"hl hl-blue\" style=\"font-size:12px;\">\n        <ruby>施設入所等<rt>しせつにゅうしょとう</rt></ruby>の<ruby>措置<rt>そち</rt></ruby>や<ruby>一時保護<rt>いちじほご</rt></ruby>が<ruby>行<rt>おこな</rt></ruby>われた<ruby>場合<rt>ばあい</rt></ruby>、<ruby>虐待<rt>ぎゃくたい</rt></ruby>を<ruby>行<rt>おこな</rt></ruby>った<ruby>保護者<rt>ほごしゃ</rt></ruby>について、<b>「<ruby>児童<rt>じどう</rt></ruby>との<ruby>面会<rt>めんかい</rt></ruby>」「<ruby>児童<rt>じどう</rt></ruby>との<ruby>通信<rt>つうしん</rt></ruby>」を<ruby>制限<rt>せいげん</rt></ruby></b>することができる。\n        <span class=\"id\">Setelah anak dilindungi sementara/dititipkan ke fasilitas, kontak (tatap muka maupun komunikasi) dengan orang tua pelaku dapat dibatasi.</span>\n      </div>\n\n      <div class=\"mnemo\">\n        <div><span>通告</span>児童は「通告」（他は「通報」）</div>\n        <div><span>3段階</span>出頭→立入→臨検捜索</div>\n        <div><span>許可状</span>臨検・捜索のみ裁判官の許可が必要</div>\n        <div><span>面会制限</span>保護者の面会・通信を制限可</div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ============ SECTION 3: DV ============ -->\n<section class=\"section th-pink\" id=\"s3\">\n  <div class=\"sec-head\" onclick=\"toggle('s3')\">\n    <div class=\"sec-icon\">💔</div>\n    <div class=\"sec-title\">\n      <span class=\"jp\">③ <ruby>DV<rt>ディーブイ</rt></ruby>（<ruby>配偶者暴力<rt>はいぐうしゃぼうりょく</rt></ruby>）の<ruby>定義<rt>ていぎ</rt></ruby>と<ruby>統計<rt>とうけい</rt></ruby></span>\n      <span class=\"id\">Definisi & Statistik Domestic Violence (Kekerasan Pasangan)</span>\n    </div>\n    <span class=\"toggle-arr\">▾</span>\n  </div>\n  <div class=\"sec-body\">\n    <div class=\"sec-inner\">\n\n      <div class=\"hl hl-pink\">\n        <b>正式名称</b>：<ruby>配偶者<rt>はいぐうしゃ</rt></ruby>からの<ruby>暴力<rt>ぼうりょく</rt></ruby>の<ruby>防止<rt>ぼうし</rt></ruby>及び<ruby>被害者<rt>ひがいしゃ</rt></ruby>の<ruby>保護等<rt>ほごとう</rt></ruby>に<ruby>関<rt>かん</rt></ruby>する<ruby>法律<rt>ほうりつ</rt></ruby>（<ruby>DV防止法<rt>ディーブイぼうしほう</rt></ruby>）— <ruby>平成<rt>へいせい</rt></ruby>13<ruby>年<rt>ねん</rt></ruby>施行\n        <span class=\"id\">UU Pencegahan Kekerasan Pasangan & Perlindungan Korban — berlaku sejak 2001</span>\n      </div>\n\n      <div class=\"trend-box\">\n        <span class=\"trend-num\">約127<small style=\"font-size:14px;\">千件</small></span>\n        <div class=\"trend-sub\"><ruby>配偶者暴力相談支援センター<rt>はいぐうしゃぼうりょくそうだんしえんセンター</rt></ruby>における<ruby>相談件数<rt>そうだんけんすう</rt></ruby>（2023<ruby>年度<rt>ねんど</rt></ruby>）</div>\n        <div class=\"trend-sub\" style=\"font-style:italic;\">Jumlah konsultasi di Pusat Dukungan Konsultasi Kekerasan Pasangan (TA2023)</div>\n      </div>\n      <div class=\"hl hl-pink\" style=\"font-size:11.5px;\">\n        📈 2002<ruby>年<rt>ねん</rt></ruby>（約35千件）から<b>2023年まで一貫して増加</b>、特に2010年代後半から急増。内訳は<b><ruby>電話<rt>でんわ</rt></ruby>「約66%」</b>が<ruby>来所<rt>らいしょ</rt></ruby>（約30%）より多い。\n        <span class=\"id\">Konsisten meningkat dari 2002 hingga 2023. Konsultasi via telepon (66%) jauh lebih banyak dari datang langsung (30%).</span>\n      </div>\n\n      <hr class=\"divider\">\n      <div class=\"sec-sub pink\">🏠 相談した施設の種類 ／ Jenis Fasilitas Tempat Konsultasi</div>\n      <div class=\"bar-chart\">\n        <div class=\"bar-row\"><span class=\"bar-label\"><ruby>男女共同参画<rt>だんじょきょうどうさんかく</rt></ruby>センター等<i>Pusat Kesetaraan Gender</i></span><div class=\"bar-track\"><div class=\"bar-fill\" style=\"width:100%;background:#d6608a;\">27% ← 最多</div></div></div>\n        <div class=\"bar-row\"><span class=\"bar-label\"><ruby>婦人相談所<rt>ふじんそうだんしょ</rt></ruby><i>Pusat Konsultasi Wanita</i></span><div class=\"bar-track\"><div class=\"bar-fill\" style=\"width:93%;background:#880e4f;\">25%</div></div></div>\n        <div class=\"bar-row\"><span class=\"bar-label\"><ruby>福祉事務所<rt>ふくしじむしょ</rt></ruby>・<ruby>保健所<rt>ほけんじょ</rt></ruby><i>Kantor kesejahteraan</i></span><div class=\"bar-track\"><div class=\"bar-fill\" style=\"width:74%;background:#9c5478;\">20%</div></div></div>\n      </div>\n\n      <div class=\"sec-sub pink\">👤 相談者の性別 ／ Gender Pelapor</div>\n      <div class=\"bar-chart\">\n        <div class=\"bar-row\"><span class=\"bar-label\"><ruby>女性<rt>じょせい</rt></ruby><i>Wanita</i></span><div class=\"bar-track\"><div class=\"bar-fill\" style=\"width:100%;background:#880e4f;\">97%</div></div></div>\n      </div>\n\n      <div class=\"sec-sub pink\">💑 加害者との関係 ／ Hubungan dengan Pelaku</div>\n      <div class=\"bar-chart\">\n        <div class=\"bar-row\"><span class=\"bar-label\"><ruby>配偶者<rt>はいぐうしゃ</rt></ruby>（<ruby>届出<rt>とどけで</rt></ruby>あり）<i>Pasangan resmi</i></span><div class=\"bar-track\"><div class=\"bar-fill\" style=\"width:100%;background:#6d597a;\">79%</div></div></div>\n        <div class=\"bar-row\"><span class=\"bar-label\"><ruby>離婚済<rt>りこんず</rt></ruby>み<i>Sudah bercerai</i></span><div class=\"bar-track\"><div class=\"bar-fill\" style=\"width:18%;background:#9c7a8e;\">14%</div></div></div>\n      </div>\n\n      <hr class=\"divider\">\n      <div class=\"sec-sub purple\">📖 重要な定義 ／ Definisi Penting</div>\n      <div class=\"flow\">\n        <div class=\"fcard n-purple\" style=\"text-align:center;\"><b><ruby>配偶者<rt>はいぐうしゃ</rt></ruby>からの<ruby>暴力<rt>ぼうりょく</rt></ruby></b>＝<ruby>配偶者<rt>はいぐうしゃ</rt></ruby>からの<ruby>身体<rt>しんたい</rt></ruby>に<ruby>対<rt>たい</rt></ruby>する<ruby>暴力<rt>ぼうりょく</rt></ruby>又はこれに<ruby>準<rt>じゅん</rt></ruby>ずる<ruby>心身<rt>しんしん</rt></ruby>に<ruby>有害<rt>ゆうがい</rt></ruby>な<ruby>影響<rt>えいきょう</rt></ruby>を<ruby>及<rt>およ</rt></ruby>ぼす<b><ruby>言動<rt>げんどう</rt></ruby></b>をいう<span class=\"id\">Kekerasan fisik dari pasangan, atau tindakan/ucapan yang memberi dampak buruk setara pada fisik & mental</span></div>\n        <div class=\"arrow-v pink\"></div>\n        <div class=\"fcard n-pink\" style=\"text-align:center;\"><b><ruby>配偶者<rt>はいぐうしゃ</rt></ruby></b>には、<ruby>婚姻<rt>こんいん</rt></ruby>の<ruby>届出<rt>とどけで</rt></ruby>をしていないが<b><ruby>事実上婚姻関係<rt>じじつじょうこんいんかんけい</rt></ruby>と<ruby>同様<rt>どうよう</rt></ruby>の<ruby>事情<rt>じじょう</rt></ruby>にある<ruby>者<rt>もの</rt></ruby></b>を<ruby>含<rt>ふく</rt></ruby>む<span class=\"id\">\"Pasangan\" termasuk yang belum mendaftarkan nikah tapi hubungannya setara perkawinan (nikah siri)</span></div>\n        <div class=\"arrow-v pink\"></div>\n        <div class=\"fcard n-pink\" style=\"text-align:center;\"><b><ruby>離婚<rt>りこん</rt></ruby></b>には、<ruby>婚姻<rt>こんいん</rt></ruby>の<ruby>届出<rt>とどけで</rt></ruby>をしていないが事実上婚姻関係と同様の事情にあった者が、<b>事実上離婚したと同様の事情</b>に入ることを含む<span class=\"id\">\"Bercerai\" termasuk pasangan nikah siri yang berakhir secara faktual</span></div>\n        <div class=\"arrow-v pink\"></div>\n        <div class=\"fcard n-orange\" style=\"text-align:center;\"><b><ruby>準用<rt>じゅんよう</rt></ruby></b>：<ruby>生活<rt>せいかつ</rt></ruby>の<ruby>本拠<rt>ほんきょ</rt></ruby>を<ruby>共<rt>とも</rt></ruby>にする<ruby>交際<rt>こうさい</rt></ruby>をする<ruby>関係<rt>かんけい</rt></ruby>にある<ruby>相手<rt>あいて</rt></ruby>からの<ruby>暴力<rt>ぼうりょく</rt></ruby>及びその<ruby>被害者<rt>ひがいしゃ</rt></ruby>についても、<b>この法律を準用する</b><span class=\"id\">Pasangan yang tinggal bersama (kumpul kebo) tanpa status nikah pun dilindungi UU ini secara analogis</span></div>\n      </div>\n      <div class=\"hl hl-purple\" style=\"font-size:11.5px;\">\n        💡 <b>覚え方</b>：法律婚→ <ruby>事実婚<rt>じじつこん</rt></ruby>（内縁）→ <b>生活の本拠を共にする交際相手（準用）</b>と、<ruby>適用範囲<rt>てきようはんい</rt></ruby>が<ruby>段階的<rt>だんかいてき</rt></ruby>に<ruby>広<rt>ひろ</rt></ruby>がっている。\n        <span class=\"id\">Jangkauan UU melebar bertahap: nikah resmi → nikah siri → pasangan kumpul kebo (via \"準用\").</span>\n      </div>\n\n      <hr class=\"divider\">\n      <div class=\"sec-sub blue\">🏛️ 支援機関と通報 ／ Lembaga Dukungan & Pelaporan</div>\n      <div class=\"flow\">\n        <div class=\"fbranch\">\n          <div class=\"fbranch-col\">\n            <div class=\"fbranch-lbl lbl-a\"><ruby>都道府県<rt>とどうふけん</rt></ruby></div>\n            <div class=\"connector-h\"></div>\n            <div class=\"arrow-v\"></div>\n            <div class=\"fcard n-blue\"><b><ruby>配偶者暴力相談支援センター<rt>はいぐうしゃぼうりょくそうだんしえんセンター</rt></ruby></b>として<ruby>機能<rt>きのう</rt></ruby>を<ruby>果<rt>はた</rt></ruby>たすようにする（<b><ruby>義務的<rt>ぎむてき</rt></ruby></b>）<span class=\"id\">Prefektur WAJIB menjadikan fasilitas (mis. 女性相談支援センター) sebagai pusat ini</span></div>\n          </div>\n          <div class=\"fbranch-col\">\n            <div class=\"fbranch-lbl lbl-b\"><ruby>市町村<rt>しちょうそん</rt></ruby></div>\n            <div class=\"connector-h\"></div>\n            <div class=\"arrow-v\"></div>\n            <div class=\"fcard n-teal\"><b><ruby>当該施設<rt>とうがいしせつ</rt></ruby>が<ruby>機能<rt>きのう</rt></ruby>を<ruby>果<rt>はた</rt></ruby>たすよう<ruby>努<rt>つと</rt></ruby>める</b>（<b><ruby>努力義務<rt>どりょくぎむ</rt></ruby></b>）<span class=\"id\">Kotamadya HANYA wajib upaya (boleh menyediakan fasilitas serupa)</span></div>\n          </div>\n        </div>\n        <div class=\"arrow-v\"></div>\n        <div class=\"fcard n-purple\" style=\"text-align:center;width:100%;\"><b><ruby>女性自立支援施設<rt>じょせいじりつしえんしせつ</rt></ruby></b>：<ruby>都道府県<rt>とどうふけん</rt></ruby>は、ここで<ruby>被害者<rt>ひがいしゃ</rt></ruby>の<ruby>保護<rt>ほご</rt></ruby>を<ruby>行<rt>おこな</rt></ruby>うことができる<span class=\"id\">Prefektur dapat memberi perlindungan korban di Fasilitas Dukungan Kemandirian Wanita</span></div>\n        <div class=\"arrow-v\"></div>\n        <div class=\"fnode end\" style=\"background:#880e4f;width:100%;\">⚠️ <ruby>配偶者<rt>はいぐうしゃ</rt></ruby>からの<ruby>身体<rt>しんたい</rt></ruby>に<ruby>対<rt>たい</rt></ruby>する<ruby>暴力<rt>ぼうりょく</rt></ruby>を<ruby>受<rt>う</rt></ruby>けている<ruby>者<rt>もの</rt></ruby>を<ruby>発見<rt>はっけん</rt></ruby>した<ruby>者<rt>もの</rt></ruby>は、<b><ruby>配偶者暴力相談支援センター<rt>はいぐうしゃぼうりょくそうだんしえんセンター</rt></ruby>もしくは<ruby>警察官<rt>けいさつかん</rt></ruby>に<ruby>通報<rt>つうほう</rt></ruby>するよう<ruby>努<rt>つと</rt></ruby>めなければならない</b>（努力義務）<span class=\"id\" style=\"color:#fce4ec;\">Penemu HANYA berkewajiban upaya melapor (bukan wajib mutlak) ke pusat dukungan/polisi — dan terbatas hanya untuk kekerasan FISIK</span></div>\n      </div>\n      <div class=\"hl hl-pink\" style=\"font-size:11.5px;\">\n        💡 <b>覚え方</b>：DVの<ruby>通報<rt>つうほう</rt></ruby>は<b>「努力義務」</b>かつ<b>「身体的暴力のみ」</b>が対象 — 児童虐待・障害者虐待・養護者による高齢者虐待（危険あり）の「通報義務」より<ruby>緩<rt>ゆる</rt></ruby>い。\n        <span class=\"id\">Kewajiban lapor DV hanya bersifat upaya & terbatas kekerasan fisik saja — lebih ringan dibanding kewajiban lapor anak/disabilitas.</span>\n      </div>\n\n      <div class=\"mnemo\">\n        <div><span>97%</span>相談者は女性が大多数</div>\n        <div><span>事実婚も対象</span>配偶者の定義に内縁含む</div>\n        <div><span>努力義務</span>通報は義務でなく努力義務</div>\n        <div><span>身体的暴力のみ</span>定義上の暴力は身体的が中心</div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ============ SECTION 4: 4法 まるごと比較 ============ -->\n<section class=\"section th-purple\" id=\"s4\">\n  <div class=\"sec-head\" onclick=\"toggle('s4')\">\n    <div class=\"sec-icon\">⚖️</div>\n    <div class=\"sec-title\">\n      <span class=\"jp\">④ <ruby>4法<rt>よんほう</rt></ruby>まるごと<ruby>比較<rt>ひかく</rt></ruby>表</span>\n      <span class=\"id\">Tabel Perbandingan Lengkap 4 UU Anti-Penganiayaan</span>\n    </div>\n    <span class=\"toggle-arr\">▾</span>\n  </div>\n  <div class=\"sec-body\">\n    <div class=\"sec-inner\">\n\n      <div class=\"hl hl-purple\">\n        <ruby>虐待<rt>ぎゃくたい</rt></ruby>などを<ruby>受<rt>う</rt></ruby>けている<ruby>方<rt>かた</rt></ruby>を<ruby>守<rt>まも</rt></ruby>る<ruby>法律<rt>ほうりつ</rt></ruby>は<b>4つ</b>。<ruby>対象<rt>たいしょう</rt></ruby>者と<ruby>施行年<rt>しこうねん</rt></ruby>から<ruby>整理<rt>せいり</rt></ruby>しよう。\n        <span class=\"id\">4 UU yang melindungi korban penganiayaan — mari rangkum berdasarkan sasaran & tahun berlaku.</span>\n      </div>\n\n      <div class=\"flow\">\n        <div class=\"fbranch\" style=\"gap:6px;\">\n          <div class=\"fbranch-col\">\n            <div class=\"fcard n-red\" style=\"text-align:center;\"><b><ruby>高齢者虐待防止法<rt>こうれいしゃぎゃくたいぼうしほう</rt></ruby></b><br><span style=\"font-size:10px;\">平成18年施行</span></div>\n          </div>\n          <div class=\"fbranch-col\">\n            <div class=\"fcard n-blue\" style=\"text-align:center;\"><b><ruby>障害者虐待防止法<rt>しょうがいしゃぎゃくたいぼうしほう</rt></ruby></b><br><span style=\"font-size:10px;\">平成24年施行</span></div>\n          </div>\n        </div>\n        <div class=\"fbranch\" style=\"gap:6px;margin-top:6px;\">\n          <div class=\"fbranch-col\">\n            <div class=\"fcard n-green\" style=\"text-align:center;\"><b><ruby>児童虐待防止法<rt>じどうぎゃくたいぼうしほう</rt></ruby></b><br><span style=\"font-size:10px;\">平成12年施行</span></div>\n          </div>\n          <div class=\"fbranch-col\">\n            <div class=\"fcard n-pink\" style=\"text-align:center;\"><b><ruby>配偶者暴力防止法<rt>はいぐうしゃぼうりょくぼうしほう</rt></ruby>（DV法）</b><br><span style=\"font-size:10px;\">平成13年施行</span></div>\n          </div>\n        </div>\n      </div>\n      <div class=\"hl hl-purple\" style=\"font-size:11.5px;\">\n        💡 <b>施行年の覚え方</b>：<ruby>児童<rt>じどう</rt></ruby>(12)→<ruby>DV<rt>ディーブイ</rt></ruby>(13)→<ruby>高齢者<rt>こうれいしゃ</rt></ruby>(18)→<ruby>障害者<rt>しょうがいしゃ</rt></ruby>(24)の<b>順番</b>。「<ruby>児童<rt>じどう</rt></ruby>とDVが先、その後高齢者、最後に障害者」と覚える。\n        <span class=\"id\">Urutan berlaku: Anak(2000) → DV(2001) → Lansia(2006) → Disabilitas(2012). Anak & DV duluan, baru lansia, terakhir disabilitas.</span>\n      </div>\n\n      <hr class=\"divider\">\n      <div class=\"sec-sub purple\">📋 対象者の比較 ／ Perbandingan Sasaran</div>\n      <div class=\"scroll-hint\">← スワイプで全体を見る ／ Geser untuk lihat semua →</div>\n      <div class=\"table-scroll\">\n      <table class=\"law-table\">\n        <tr>\n          <td class=\"row-head\"></td>\n          <th class=\"lt-elder-h\"><ruby>高齢者虐待<br>防止法<rt>こうれいしゃぎゃくたいぼうしほう</rt></ruby><br><span style=\"font-size:9px;font-weight:400;\">(平18施行)</span></th>\n          <th class=\"lt-disab-h\"><ruby>障害者虐待<br>防止法<rt>しょうがいしゃぎゃくたいぼうしほう</rt></ruby><br><span style=\"font-size:9px;font-weight:400;\">(平24施行)</span></th>\n          <th class=\"lt-child-h\"><ruby>児童虐待<br>防止法<rt>じどうぎゃくたいぼうしほう</rt></ruby><br><span style=\"font-size:9px;font-weight:400;\">(平12施行)</span></th>\n          <th class=\"lt-dv-h\"><ruby>配偶者暴力<br>防止法<rt>はいぐうしゃぼうりょくぼうしほう</rt></ruby><br><span style=\"font-size:9px;font-weight:400;\">(平13施行)</span></th>\n        </tr>\n        <tr>\n          <td class=\"row-head\"><ruby>対象<rt>たいしょう</rt></ruby><br><i style=\"font-size:9px;color:#888;\">Sasaran</i></td>\n          <td class=\"lt-elder\"><b>65歳以上</b>の者<br><span style=\"font-size:9px;color:#888;\">(※養介護施設利用の障害者も含む)</span></td>\n          <td class=\"lt-disab\"><b>身体・知的・精神障害</b>（発達障害含む）</td>\n          <td class=\"lt-child\"><b>保護者が監護する児童</b>（18歳未満）</td>\n          <td class=\"lt-dv\"><b>配偶者</b>（内縁・同棲含む）からの暴力を受けた者</td>\n        </tr>\n        <tr style=\"background:#faf8fb;\"><td class=\"row-head\" colspan=\"5\" style=\"text-align:left;font-weight:900;\">虐待の定義（5種類があるか）</td></tr>\n        <tr>\n          <td class=\"row-head\"><ruby>身体的虐待<rt>しんたいてきぎゃくたい</rt></ruby></td>\n          <td class=\"lt-elder\"><span class=\"yes-mark\">○</span></td><td class=\"lt-disab\"><span class=\"yes-mark\">○</span></td><td class=\"lt-child\"><span class=\"yes-mark\">○</span></td>\n          <td class=\"lt-dv\" rowspan=\"5\" style=\"vertical-align:middle;font-size:10px;\">配偶者からの<b>身体に対する暴力</b>又はこれに準ずる<b>心身に有害な影響を及ぼす言動</b></td>\n        </tr>\n        <tr><td class=\"row-head\"><ruby>心理的虐待<rt>しんりてきぎゃくたい</rt></ruby></td><td class=\"lt-elder\"><span class=\"yes-mark\">○</span></td><td class=\"lt-disab\"><span class=\"yes-mark\">○</span></td><td class=\"lt-child\"><span class=\"yes-mark\">○</span></td></tr>\n        <tr><td class=\"row-head\"><ruby>性的虐待<rt>せいてきぎゃくたい</rt></ruby></td><td class=\"lt-elder\"><span class=\"yes-mark\">○</span></td><td class=\"lt-disab\"><span class=\"yes-mark\">○</span></td><td class=\"lt-child\"><span class=\"yes-mark\">○</span></td></tr>\n        <tr><td class=\"row-head\"><ruby>ネグレクト<rt></rt></ruby></td><td class=\"lt-elder\"><span class=\"yes-mark\">○</span></td><td class=\"lt-disab\"><span class=\"yes-mark\">○</span></td><td class=\"lt-child\"><span class=\"yes-mark\">○</span></td></tr>\n        <tr><td class=\"row-head\"><ruby>経済的虐待<rt>けいざいてきぎゃくたい</rt></ruby></td><td class=\"lt-elder\"><span class=\"yes-mark\">○</span></td><td class=\"lt-disab\"><span class=\"yes-mark\">○</span></td><td class=\"lt-child\" style=\"color:#c1121f;font-weight:900;\">✕ <span style=\"font-size:9px;\">(規定なし)</span></td></tr>\n      </table>\n      </div>\n      <div class=\"hl hl-purple\" style=\"font-size:11.5px;\">\n        💡 <b>最大の落とし穴</b>：<ruby>児童虐待防止法<rt>じどうぎゃくたいぼうしほう</rt></ruby>には<b>経済的虐待の規定がない</b>（高齢者・障害者にはある）。<ruby>DV防止法<rt>ディーブイぼうしほう</rt></ruby>はそもそも5分類ではなく<b>「身体的暴力」中心の独自定義</b>。\n        <span class=\"id\">JEBAKAN UTAMA: UU Anak TIDAK punya kategori \"penganiayaan ekonomi\" (beda dari lansia & disabilitas). UU DV pakai definisi sendiri yang berfokus pada kekerasan fisik, bukan 5 kategori.</span>\n      </div>\n\n      <hr class=\"divider\">\n      <div class=\"sec-sub purple\">📢 通報・通告のルール比較 ／ Perbandingan Aturan Lapor</div>\n      <div class=\"table-scroll\">\n      <table class=\"law-table\">\n        <tr>\n          <td class=\"row-head\"></td>\n          <th class=\"lt-elder-h\">高齢者</th><th class=\"lt-disab-h\">障害者</th><th class=\"lt-child-h\">児童</th><th class=\"lt-dv-h\">配偶者暴力</th>\n        </tr>\n        <tr>\n          <td class=\"row-head\"><ruby>発見した人<rt>はっけんしたひと</rt></ruby><br><i style=\"font-size:9px;color:#888;\">Penemu umum</i></td>\n          <td class=\"lt-elder\">生命・身体に<b>重大な危険</b>あり→<b>通報義務</b>／それ以外は<b>通報努力義務</b></td>\n          <td class=\"lt-disab\">（養護者による）<b>通報義務</b></td>\n          <td class=\"lt-child\"><b><ruby>通告<rt>つうこく</rt></ruby>義務</b></td>\n          <td class=\"lt-dv\">身体的暴力のみ／<b>通報努力義務</b></td>\n        </tr>\n        <tr>\n          <td class=\"row-head\"><ruby>専門職など<rt>せんもんしょくなど</rt></ruby><br><i style=\"font-size:9px;color:#888;\">Profesional/staf</i></td>\n          <td class=\"lt-elder\">関係団体・専門職：<b>早期発見努力義務</b>／施設従事者等：<b>通報義務</b></td>\n          <td class=\"lt-disab\">関係団体・専門職：<b>早期発見努力義務</b>／施設従事者等・<b>使用者</b>：<b>通報義務</b></td>\n          <td class=\"lt-child\">関係団体・専門職：<b>早期発見努力義務</b></td>\n          <td class=\"lt-dv\">医療関係者：<b>通報できる</b>（本人の意思を尊重する努力義務）</td>\n        </tr>\n        <tr>\n          <td class=\"row-head\"><ruby>通報先<rt>つうほうさき</rt></ruby><br><i style=\"font-size:9px;color:#888;\">Tujuan lapor</i></td>\n          <td class=\"lt-elder\"><b>市町村</b>（地域包括支援センター等へ委託可）</td>\n          <td class=\"lt-disab\"><b>市町村、都道府県</b></td>\n          <td class=\"lt-child\"><b>児童相談所、市町村</b>など（直接または児童委員を介して）</td>\n          <td class=\"lt-dv\"><b>配偶者暴力相談支援センター、警察官</b></td>\n        </tr>\n      </table>\n      </div>\n\n      <hr class=\"divider\">\n      <div class=\"sec-sub purple\">🛡️ 対応・措置の比較 ／ Perbandingan Tindakan</div>\n      <div class=\"table-scroll\">\n      <table class=\"law-table\">\n        <tr>\n          <td class=\"row-head\"></td>\n          <th class=\"lt-elder-h\">高齢者</th><th class=\"lt-disab-h\">障害者</th><th class=\"lt-child-h\">児童</th><th class=\"lt-dv-h\">配偶者暴力</th>\n        </tr>\n        <tr>\n          <td class=\"row-head\"><ruby>一時保護<rt>いちじほご</rt></ruby></td>\n          <td class=\"lt-elder\"><b>市町村</b>による老人短期入所施設等への措置</td>\n          <td class=\"lt-disab\"><b>市町村</b>による障害者福祉施設への一時保護</td>\n          <td class=\"lt-child\"><b>児童相談所</b>による一時保護</td>\n          <td class=\"lt-dv\"><b>女性相談支援センター</b>等による一時保護</td>\n        </tr>\n        <tr>\n          <td class=\"row-head\"><ruby>警察署長等<rt>けいさつしょちょうとう</rt></ruby></td>\n          <td class=\"lt-elder\">立入調査等に協力</td><td class=\"lt-disab\">立入調査等に協力</td><td class=\"lt-child\">立入調査等に協力</td>\n          <td class=\"lt-dv\">被害の発生を<b>防止</b>するための必要な援助</td>\n        </tr>\n        <tr>\n          <td class=\"row-head\"><ruby>措置など<rt>そちなど</rt></ruby></td>\n          <td class=\"lt-elder\">面会の制限／<b>市町村長</b>による成年後見開始の審判など</td>\n          <td class=\"lt-disab\">面会の制限／<b>市町村長</b>による成年後見開始の審判など</td>\n          <td class=\"lt-child\">施設入所等の措置／面接・通信の制限／<b>接近禁止</b>／<b>親権の喪失</b>の審判など</td>\n          <td class=\"lt-dv\"><b>地方裁判所</b>の<b>保護命令</b>／<b>接近禁止命令</b>／<b>退去等命令</b>など</td>\n        </tr>\n      </table>\n      </div>\n      <div class=\"hl hl-purple\" style=\"font-size:11.5px;\">\n        💡 <b>覚え方</b>：「<ruby>措置<rt>そち</rt></ruby>」の<ruby>主体<rt>しゅたい</rt></ruby>に注目 — 高齢者・障害者は<b>市町村長</b>が成年後見を請求。児童は<b>親権喪失</b>という独自の措置がある。DVだけ<b>裁判所の保護命令</b>という司法手続きが入る点が特殊。\n        <span class=\"id\">Fokus pada siapa yang bertindak: Lansia/Disabilitas → kepala kotamadya ajukan perwalian. Anak → ada \"pencabutan hak asuh\" yang unik. DV → satu-satunya yang melibatkan perintah pengadilan (lebih bersifat yudisial).</span>\n      </div>\n\n      <div class=\"hl hl-orange\">\n        <b>(※5)</b> 65<ruby>歳<rt>さい</rt></ruby>未満で、<ruby>養介護施設入所者<rt>ようかいごしせつにゅうしょしゃ</rt></ruby>や<ruby>養介護事業<rt>ようかいごじぎょう</rt></ruby>のサービスを受ける<ruby>障害者<rt>しょうがいしゃ</rt></ruby>は、<ruby>高齢者<rt>こうれいしゃ</rt></ruby>とみなして、<ruby>養介護施設従事者等<rt>ようかいごしせつじゅうじしゃとう</rt></ruby>による<ruby>高齢者虐待<rt>こうれいしゃぎゃくたい</rt></ruby>に<ruby>関<rt>かん</rt></ruby>する<ruby>規定<rt>きてい</rt></ruby>を<ruby>適用<rt>てきよう</rt></ruby>。\n        <span class=\"id\">Catatan: penyandang disabilitas di bawah 65 tahun yang menggunakan fasilitas/layanan perawatan tetap dianggap \"lansia\" untuk pasal penganiayaan oleh staf fasilitas.</span>\n      </div>\n\n      <div class=\"mnemo\">\n        <div><span>4法</span>高齢者・障害者・児童・配偶者暴力</div>\n        <div><span>経済的✕</span>児童だけ経済的虐待の規定なし</div>\n        <div><span>通告</span>児童だけ「通告」、他は「通報」</div>\n        <div><span>裁判所</span>DVだけ司法（保護命令）が登場</div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<div style=\"text-align:center;margin-top:24px;font-size:11px;color:#9ca3af;\">\n  📚 第1章 第2節 ⑤ 虐待（児童・DV・4法比較）／ Versi Flowchart Furigana untuk Hafalan\n</div>\n\n</main>\n<script>\nfunction toggle(id){\n  document.getElementById(id).classList.toggle('open');\n}\ndocument.querySelectorAll('.toc-btn').forEach(btn=>{\n  btn.addEventListener('click', function(e){\n    e.preventDefault();\n    const id = this.getAttribute('href').substring(1);\n    const sec = document.getElementById(id);\n    if(!sec.classList.contains('open')) sec.classList.add('open');\n    setTimeout(()=>{ sec.scrollIntoView({behavior:'smooth', block:'start'}); }, 50);\n  });\n});\n<\/script>\n</body>\n</html>\n","shakai-7":"<!DOCTYPE html>\n<html lang=\"ja\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>第3節⑥ — 社会保障制度の概要（完全版）</title>\n<link href=\"https://fonts.googleapis.com/css2?family=Noto+Sans+JP:wght@300;400;500;700;900&family=Noto+Serif+JP:wght@400;700&display=swap\" rel=\"stylesheet\">\n<style>\n:root{\n  --g1:#1b4332;--g2:#2d6a4f;--g3:#52b788;--gp:#d8f3dc;\n  --b1:#1d3557;--b2:#457b9d;--bp:#dce9f7;\n  --o1:#7d3112;--o2:#e76f51;--op:#fde4d8;\n  --y1:#7a5000;--y2:#f4a261;--yp:#fff3cd;\n  --p1:#3d2060;--p2:#6d597a;--pp:#ece5f5;\n  --t1:#0d4a44;--t2:#2a9d8f;--tp:#d5f5f2;\n  --r1:#7a0c13;--r2:#c1121f;--rp:#fce0e2;\n  --tx:#1a1a2e;--txm:#374151;--txs:#6b7280;\n}\n*{margin:0;padding:0;box-sizing:border-box;}\nbody{font-family:'Noto Sans JP',sans-serif;background:#eef4f0;color:var(--tx);min-height:100vh;}\nheader{background:linear-gradient(135deg,#0a2e1a 0%,#1b4332 40%,#2d6a4f 75%,#52b788 100%);padding:40px 20px 30px;text-align:center;position:relative;overflow:hidden;}\nheader::before{content:'';position:absolute;top:-80px;right:-80px;width:300px;height:300px;border-radius:50%;background:rgba(255,255,255,0.04);}\n.hbadge{display:inline-block;background:rgba(255,255,255,0.15);border:1px solid rgba(255,255,255,0.3);color:#d8f3dc;font-size:11px;letter-spacing:3px;padding:5px 16px;border-radius:30px;margin-bottom:14px;font-weight:500;}\n.star-row{color:#f4d03f;font-size:18px;margin-bottom:12px;letter-spacing:3px;}\nheader h1{font-family:'Noto Serif JP',serif;color:#fff;font-size:clamp(19px,5.5vw,32px);font-weight:700;line-height:1.4;margin-bottom:8px;}\nheader p{color:rgba(255,255,255,0.65);font-size:12px;letter-spacing:1px;}\n.toc{max-width:820px;margin:18px auto 0;padding:0 14px;display:flex;flex-wrap:wrap;gap:8px;justify-content:center;}\n.toc-btn{background:rgba(255,255,255,0.12);border:1px solid rgba(255,255,255,0.25);color:#fff;font-size:11px;padding:5px 12px;border-radius:20px;cursor:pointer;text-decoration:none;transition:background .2s;white-space:nowrap;}\n.toc-btn:hover{background:rgba(255,255,255,0.25);}\nmain{max-width:820px;margin:0 auto;padding:24px 14px 70px;}\n.section{margin-bottom:18px;border-radius:14px;overflow:hidden;box-shadow:0 2px 12px rgba(0,0,0,0.07);animation:fadeUp .5s ease both;}\n@keyframes fadeUp{from{opacity:0;transform:translateY(18px)}to{opacity:1;transform:translateY(0)}}\n.sec-head{display:flex;align-items:center;gap:12px;padding:14px 18px;cursor:pointer;user-select:none;transition:filter .2s;}\n.sec-head:hover{filter:brightness(1.06);}\n.sec-icon{width:38px;height:38px;border-radius:50%;background:rgba(255,255,255,0.18);display:flex;align-items:center;justify-content:center;font-size:18px;flex-shrink:0;}\n.sec-title .jp{font-size:15.5px;font-weight:700;color:#fff;display:block;}\n.sec-title .id{font-size:11px;color:rgba(255,255,255,.68);display:block;margin-top:2px;}\n.badge-num{background:rgba(255,255,255,0.2);color:#fff;font-size:10px;font-weight:700;padding:2px 8px;border-radius:20px;margin-left:6px;vertical-align:middle;}\n.toggle-arr{color:rgba(255,255,255,.75);font-size:13px;margin-left:auto;transition:transform .35s;flex-shrink:0;}\n.section.open .toggle-arr{transform:rotate(180deg);}\n.sec-body{background:#fff;overflow:hidden;max-height:0;transition:max-height .55s ease;}\n.section.open .sec-body{max-height:15000px;}\n.sec-inner{padding:20px 18px 26px;}\n.th-green  .sec-head{background:linear-gradient(90deg,#1b4332,#2d6a4f);}\n.th-blue   .sec-head{background:linear-gradient(90deg,#1d3557,#3a7dbf);}\n.th-orange .sec-head{background:linear-gradient(90deg,#7d3112,#e07b58);}\n.th-purple .sec-head{background:linear-gradient(90deg,#3d2060,#6d597a);}\n.th-teal   .sec-head{background:linear-gradient(90deg,#0d4a44,#2a9d8f);}\n.th-red    .sec-head{background:linear-gradient(90deg,#7a0c13,#c1121f);}\n.th-yellow .sec-head{background:linear-gradient(90deg,#7a5000,#d9883e);}\n.hl{border-left:4px solid;padding:11px 14px;border-radius:0 10px 10px 0;margin:10px 0;font-size:13px;line-height:1.65;}\n.hl-green {border-color:#2d6a4f;background:#f0faf5;color:#1b4332;}\n.hl-blue  {border-color:#457b9d;background:#eef5fc;color:#1d3557;}\n.hl-orange{border-color:#e76f51;background:#fef5f2;color:#7a2a10;}\n.hl-purple{border-color:#6d597a;background:#f5f0fb;color:#3d2060;}\n.hl-teal  {border-color:#2a9d8f;background:#f0fbfa;color:#0d4a44;}\n.hl-red   {border-color:#c1121f;background:#fef0f1;color:#7a0c13;}\n.hl-yellow{border-color:#d9883e;background:#fffbf0;color:#7a5000;}\n.hl-gray  {border-color:#9ca3af;background:#f9fafb;color:#374151;}\n.node{border-radius:10px;padding:12px 14px;margin-bottom:8px;}\n.node-lbl{font-size:10px;font-weight:700;letter-spacing:1px;opacity:.6;margin-bottom:5px;text-transform:uppercase;}\n.node-main{font-size:14px;font-weight:700;line-height:1.4;}\n.node-sub{font-size:11.5px;margin-top:5px;line-height:1.6;color:var(--txm);}\n.n-green {background:#d8f3dc;color:#1b4332;} .n-blue{background:#dce9f7;color:#1d3557;}\n.n-yellow{background:#fff3cd;color:#7a5000;} .n-orange{background:#fde4d8;color:#7a2a10;}\n.n-red{background:#fce0e2;color:#7a0c13;} .n-purple{background:#ece5f5;color:#3d2060;}\n.n-teal{background:#d5f5f2;color:#0d4a44;} .n-gray{background:#f3f4f6;color:#374151;}\n.grid2{display:grid;grid-template-columns:1fr 1fr;gap:9px;margin:10px 0;}\n.grid3{display:grid;grid-template-columns:repeat(3,1fr);gap:9px;margin:10px 0;}\n.grid4{display:grid;grid-template-columns:repeat(4,1fr);gap:9px;margin:10px 0;}\n@media(max-width:560px){.grid3,.grid4{grid-template-columns:1fr 1fr;}}\n@media(max-width:380px){.grid2,.grid3,.grid4{grid-template-columns:1fr;}}\n.sec-sub{font-size:12px;font-weight:700;letter-spacing:1px;color:#fff;background:#2d6a4f;display:inline-block;padding:4px 12px;border-radius:20px;margin:14px 0 8px;}\n.sec-sub.blue{background:#457b9d;} .sec-sub.orange{background:#e07b58;}\n.sec-sub.purple{background:#6d597a;} .sec-sub.teal{background:#2a9d8f;}\n.sec-sub.red{background:#c1121f;} .sec-sub.yellow{background:#d9883e;}\n.tbl{width:100%;border-collapse:collapse;font-size:12px;margin:8px 0;}\n.tbl th{padding:7px 9px;text-align:left;font-size:11px;font-weight:700;border-bottom:2px solid #e0e0e0;background:#f8f8f8;color:#374151;}\n.tbl td{padding:7px 9px;border-bottom:1px solid #f0f0f0;vertical-align:top;line-height:1.55;}\n.tbl tr:last-child td{border-bottom:none;}\n.ins-tbl{width:100%;border-collapse:collapse;font-size:12px;margin:8px 0;}\n.ins-tbl th{padding:8px 9px;font-size:11px;font-weight:700;border:1px solid #ddd;text-align:center;background:#e8f5e9;color:#1b4332;}\n.ins-tbl td{padding:7px 9px;border:1px solid #eee;vertical-align:top;line-height:1.55;}\n.ins-tbl .cat-cell{background:#c8e6c9;font-weight:700;font-size:11.5px;text-align:center;color:#1b4332;}\n.ins-tbl .sub-cat{background:#f1f8f2;font-weight:700;color:#2d6a4f;font-size:11px;}\n.ins-tbl .row-alt{background:#fafff8;}\n.tl{position:relative;padding-left:24px;margin-top:12px;}\n.tl::before{content:'';position:absolute;left:8px;top:4px;bottom:4px;width:2px;background:linear-gradient(180deg,#b7d5c8,#a8d5ba);}\n.tl-item{position:relative;margin-bottom:14px;}\n.tl-item::before{content:'';position:absolute;left:-19px;top:5px;width:12px;height:12px;border-radius:50%;border:2.5px solid #2d6a4f;background:#fff;box-shadow:0 0 0 3px rgba(45,106,79,0.12);}\n.tl-year{font-weight:900;font-size:11px;color:#2d6a4f;display:inline-block;background:#d8f3dc;padding:2px 9px;border-radius:20px;margin-bottom:3px;}\n.tl-law{font-weight:700;color:#1b4332;font-size:13px;margin-bottom:2px;}\n.tl-desc{color:#374151;font-size:12px;line-height:1.6;}\n.tl-desc .id{color:#6b7280;font-size:11px;display:block;margin-top:2px;font-style:italic;}\n.tl-key{display:inline-block;background:#d8f3dc;color:#1b4332;font-size:11px;font-weight:700;padding:1px 8px;border-radius:10px;margin:2px 2px 0;}\n.tl-key.red{background:#fce0e2;color:#7a0c13;} .tl-key.blue{background:#dce9f7;color:#1d3557;}\n.tl-key.yellow{background:#fff3cd;color:#7a5000;} .tl-key.purple{background:#ece5f5;color:#3d2060;}\n.era-bar{background:linear-gradient(90deg,#2d6a4f,#52b788);color:#fff;font-size:11px;font-weight:700;padding:5px 14px;border-radius:8px;margin:14px 0 4px;letter-spacing:1px;display:inline-block;}\n.era-bar.blue{background:linear-gradient(90deg,#1d3557,#457b9d);}\n.era-bar.purple{background:linear-gradient(90deg,#3d2060,#6d597a);}\n.era-bar.teal{background:linear-gradient(90deg,#0d4a44,#2a9d8f);}\n.era-bar.orange{background:linear-gradient(90deg,#7d3112,#e07b58);}\n.pillar{border-radius:12px;padding:14px 15px;font-size:12.5px;line-height:1.6;height:100%;}\n.p-title{font-weight:900;font-size:14.5px;margin-bottom:6px;display:flex;align-items:center;gap:6px;}\n.p-en{font-size:10px;opacity:.65;font-weight:400;}\n.bar-wrap{margin:6px 0;}\n.bar-label{font-size:12px;font-weight:500;margin-bottom:3px;display:flex;justify-content:space-between;}\n.bar-track{background:#e5e7eb;border-radius:20px;height:22px;overflow:hidden;}\n.bar-fill{height:100%;border-radius:20px;display:flex;align-items:center;padding-left:10px;font-size:11px;font-weight:700;color:#fff;}\n.compare-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin:10px 0;}\n@media(max-width:400px){.compare-grid{grid-template-columns:1fr;}}\n.compare-card{border-radius:10px;padding:14px;}\n.compare-title{font-weight:900;font-size:13px;margin-bottom:8px;padding-bottom:6px;border-bottom:2px solid rgba(0,0,0,0.08);}\n.intl-bar{margin:5px 0;display:flex;align-items:center;gap:8px;}\n.intl-label{font-size:11px;font-weight:500;min-width:72px;text-align:right;line-height:1.3;}\n.intl-track{flex:1;background:#e5e7eb;border-radius:20px;height:22px;overflow:hidden;}\n.intl-fill{height:100%;border-radius:20px;display:flex;align-items:center;justify-content:flex-end;padding-right:8px;font-size:11px;font-weight:700;color:#fff;}\n.intl-val{font-size:12px;font-weight:700;min-width:40px;}\n.tl.blue::before{background:linear-gradient(180deg,#b7c8d5,#a8c0d8);}\n.tl.blue .tl-item::before{border-color:#457b9d;box-shadow:0 0 0 3px rgba(69,123,157,0.12);}\n.tl.purple::before{background:linear-gradient(180deg,#c0b0d5,#b0a0c8);}\n.tl.purple .tl-item::before{border-color:#6d597a;box-shadow:0 0 0 3px rgba(109,89,122,0.12);}\n.fn{font-size:10.5px;color:#6b7280;margin-top:8px;line-height:1.6;border-top:1px solid #f0f0f0;padding-top:8px;}\n.fn-mark{color:#2d6a4f;font-weight:700;}\nruby rt{font-size:9px;color:#2d6a4f;line-height:1;}\n.tag{display:inline-block;padding:1px 7px;border-radius:20px;font-size:10px;font-weight:700;margin:0 2px;}\n.tag-red{background:#fce0e2;color:#7a0c13;} .tag-green{background:#d8f3dc;color:#1b4332;}\n.tag-blue{background:#dce9f7;color:#1d3557;} .tag-yellow{background:#fff3cd;color:#7a5000;}\n.tag-purple{background:#ece5f5;color:#3d2060;}\n.arrow-down{text-align:center;font-size:22px;color:#a0c4b0;margin:4px 0;}\n.divider{border:none;border-top:1px dashed #c8e6c9;margin:14px 0;}\n.table-wrap{overflow-x:auto;}\n.bar-chart{margin:10px 0;}\n.bar-row{display:flex;align-items:center;gap:8px;margin:8px 0;}\n.bar-label{flex:0 0 90px;font-size:12px;text-align:right;}\n.bar-label i{font-size:10px;color:#888;display:block;}\n.bar-track{flex:1;background:#eef2f0;border-radius:6px;overflow:hidden;height:26px;}\n.bar-fill{height:100%;display:flex;align-items:center;padding-left:8px;color:#fff;font-size:11px;font-weight:700;white-space:nowrap;border-radius:6px;}\n.timeline{position:relative;border-left:3px solid #95d5b2;margin-left:8px;padding-left:18px;}\n.tl-item{margin-bottom:14px;position:relative;}\n.tl-item::before{content:'';position:absolute;left:-25px;top:4px;width:11px;height:11px;border-radius:50%;background:#52b788;border:2px solid #fff;}\n.tl-year{font-weight:700;color:#1b4332;font-size:13px;}\n.tl-title{font-weight:700;}\n.tl-desc{font-size:13px;color:#444;}\n.tl-desc i{color:#888;}\n</style>\n<style id=\"pk-fix\">\n.sec-body{max-height:none!important;overflow:visible!important;display:none;transition:none!important}\n.section.open .sec-body{display:block}\n.section{animation:none!important;opacity:1!important;transform:none!important}\n*{min-width:0}\nbody{overflow-x:hidden;-webkit-text-size-adjust:100%}\nmain{padding-left:10px!important;padding-right:10px!important}\np,div,span,td,th,li{overflow-wrap:anywhere;word-break:normal}\nimg,svg,video{max-width:100%;height:auto}\ntable{display:block;max-width:100%;overflow-x:auto;-webkit-overflow-scrolling:touch;border-collapse:collapse}\n@media (max-width:560px){\n [class*=\"grid\"],[class*=\"cols\"],[class*=\"compare\"],[class*=\"pair\"],[class*=\"two\"],[class*=\"stats\"]{grid-template-columns:1fr 1fr!important}\n [class*=\"grid3\"],[class*=\"grid-3\"],[class*=\"three\"]{grid-template-columns:1fr!important}\n [class*=\"row\"],[class*=\"flex\"],[class*=\"flow\"],[class*=\"chain\"]{flex-wrap:wrap!important}\n [class*=\"compare\"] > *,[class*=\"pair\"] > *{min-width:0}\n}\n</style>\n<script>\n(function(){\n function post(){try{parent.postMessage({pkH:Math.ceil(document.documentElement.scrollHeight)},'*');}catch(e){}}\n document.addEventListener('DOMContentLoaded',function(){\n  document.querySelectorAll('.section').forEach(function(s,i){ if(i===0) s.classList.add('open'); });\n  post();\n  if(window.ResizeObserver) new ResizeObserver(post).observe(document.body);\n  document.addEventListener('click',function(){setTimeout(post,30);setTimeout(post,400);});\n });\n window.addEventListener('load',post);\n})();\n<\/script></head>\n<body>\n<header>\n  <div class=\"hbadge\">第1章 第3節 ⑥ — 完全版まとめ</div>\n  <div class=\"star-row\">★★☆</div>\n  <h1><ruby>社会保障制度<rt>しゃかいほしょうせいど</rt></ruby>の<ruby>概要<rt>がいよう</rt></ruby><br>\n    <span style=\"font-size:.55em;font-weight:400;color:rgba(255,255,255,.7);\">Ikhtisar Sistem Jaminan Sosial Jepang — Lengkap</span>\n  </h1>\n  <p>タップして各テーマを開く ／ Ketuk untuk membuka setiap topik</p>\n  <div class=\"toc\">\n    <a class=\"toc-btn\" href=\"#s1\">①自助〜公助</a>\n    <a class=\"toc-btn\" href=\"#s2\">②社会保険5種</a>\n    <a class=\"toc-btn\" href=\"#s3\">③法体系</a>\n    <a class=\"toc-btn\" href=\"#s4\">④利用方式</a>\n    <a class=\"toc-btn\" href=\"#s5\">⑤給付費</a>\n    <a class=\"toc-btn\" href=\"#s6\">⑥高齢者歴史</a>\n    <a class=\"toc-btn\" href=\"#s7\">⑦障害者歴史</a>\n    <a class=\"toc-btn\" href=\"#s8\">⑧社会保険歴史</a>\n  </div>\n</header>\n<main>\n<section class=\"section open\" id=\"s1\">\n  <div class=\"sec-head th-green\" onclick=\"toggle('s1')\">\n    <span>① <ruby>自助<rt>じじょ</rt></ruby>・<ruby>互助<rt>ごじょ</rt></ruby>・<ruby>共助<rt>きょうじょ</rt></ruby>・<ruby>公助<rt>こうじょ</rt></ruby></span>\n    <span class=\"toggle-arr\">▾</span>\n  </div>\n  <div class=\"sec-body\">\n    <div class=\"sec-inner\">\n      <p><b>社会保障</b>とは、国民の生活を支えるしくみで、4つの段階に分けられる。<br>\n      <i>Jaminan sosial dibagi menjadi 4 tingkatan dukungan:</i></p>\n      <div class=\"grid2\">\n        <div class=\"node n-green\">\n          <div class=\"node-main\">自助 (Jiji)</div><div class=\"node-sub\">自分自身や家族の努力によって生活上の課題を解決すること。<br>\n          <i>Usaha sendiri/keluarga untuk mengatasi masalah hidup.</i></div>\n        </div>\n        <div class=\"node n-blue\">\n          <div class=\"node-main\">互助 (Gojo)</div><div class=\"node-sub\">近隣住民やボランティアなど、地域の人々が互いに支え合うこと（制度化されていない）。<br>\n          <i>Saling membantu antarwarga/relawan, bersifat informal.</i></div>\n        </div>\n        <div class=\"node n-orange\">\n          <div class=\"node-main\">共助 (Kyojo)</div><div class=\"node-sub\">社会保険のように、リスクを共有する仲間同士で支え合う制度化されたしくみ。<br>\n          <i>Sistem terstruktur (asuransi sosial) berbagi risiko antaranggota.</i></div>\n        </div>\n        <div class=\"node n-purple\">\n          <div class=\"node-main\">公助 (Kojo)</div><div class=\"node-sub\">生活保護など、税を財源として公的機関が行う支援。<br>\n          <i>Bantuan dari negara berbasis pajak (misal: bantuan kesejahteraan).</i></div>\n        </div>\n      </div>\n\n      <hr class=\"divider\">\n      <div class=\"sec-sub\">📊 <ruby>社会保障<rt>しゃかいほしょう</rt></ruby>の<ruby>2つ<rt>ふたつ</rt></ruby>のしくみ</div>\n      <table class=\"tbl\">\n        <tr><th>しくみ</th><th>説明 (Penjelasan)</th><th>例</th></tr>\n        <tr><td class=\"fn-mark\">社会保険</td><td>保険料を払い、リスクが発生した時に給付を受ける（共助に近い）<br><i>Membayar premi, menerima tunjangan saat terjadi risiko</i></td><td>医療保険・年金保険など</td></tr>\n        <tr><td class=\"fn-mark\">社会扶助</td><td>税を財源として、必要な人に給付する（公助に近い）<br><i>Dibiayai pajak, diberikan kepada yang membutuhkan</i></td><td>生活保護・児童手当など</td></tr>\n      </table>\n\n      <hr class=\"divider\">\n      <div class=\"sec-sub\">📋 <ruby>社会保障制度<rt>しゃかいほしょうせいど</rt></ruby>の<ruby>保障内容<rt>ほしょうないよう</rt></ruby>マトリックス</div>\n      <div class=\"table-wrap\">\n      <table class=\"tbl small\">\n        <tr><th>制度</th><th>所得保障<br><i>Jaminan Pendapatan</i></th><th>医療保障<br><i>Jaminan Medis</i></th><th>福祉サービス<br><i>Layanan Sosial</i></th></tr>\n        <tr><td class=\"fn-mark\">医療保険</td><td>○（傷病手当金等）</td><td>◎</td><td>－</td></tr>\n        <tr><td class=\"fn-mark\">年金保険</td><td>◎</td><td>－</td><td>－</td></tr>\n        <tr><td class=\"fn-mark\">介護保険</td><td>－</td><td>○</td><td>◎</td></tr>\n        <tr><td class=\"fn-mark\">雇用保険</td><td>◎（失業給付等）</td><td>－</td><td>○（職業訓練等）</td></tr>\n        <tr><td class=\"fn-mark\">労災保険</td><td>◎（補償給付）</td><td>◎</td><td>○</td></tr>\n      </table>\n      </div>\n      <p style=\"font-size:12px;color:#666;\">◎=主要な機能 ／ ○=一部対応 ／ －=対象外</p>\n    </div>\n  </div>\n</section>\n\n<section class=\"section\" id=\"s2\">\n  <div class=\"sec-head th-blue\" onclick=\"toggle('s2')\">\n    <span>② <ruby>社会保険<rt>しゃかいほけん</rt></ruby>制度（5種類）</span>\n    <span class=\"toggle-arr\">▾</span>\n  </div>\n  <div class=\"sec-body\">\n    <div class=\"sec-inner\">\n      <p>社会保険には<b>医療・年金・介護・雇用・労災</b>の5種類があり、それぞれ「保険者」「被保険者」「保険事故」「保険給付」が定められている。<br>\n      <i>5 jenis asuransi sosial: medis, pensiun, perawatan lansia, ketenagakerjaan, dan kecelakaan kerja.</i></p>\n\n      <div class=\"table-wrap\">\n      <table class=\"tbl small\">\n        <tr><th>種類</th><th>保険者<br><i>Penyelenggara</i></th><th>被保険者<br><i>Tertanggung</i></th><th>保険事故<br><i>Risiko</i></th><th>保険給付<br><i>Tunjangan</i></th></tr>\n        <tr>\n          <td class=\"fn-mark\">医療保険<br><span style=\"font-size:11px;color:#888;\">いりょうほけん</span></td>\n          <td>国・健康保険組合・市町村など</td>\n          <td>被用者・自営業者・後期高齢者等</td>\n          <td>病気・けが・出産・死亡</td>\n          <td>療養の給付・出産費・葬祭費等</td>\n        </tr>\n        <tr>\n          <td class=\"fn-mark\">年金保険<br><span style=\"font-size:11px;color:#888;\">ねんきんほけん</span></td>\n          <td>国（日本年金機構）</td>\n          <td>20歳以上の全国民・被用者等</td>\n          <td>老齢・障害・死亡</td>\n          <td>老齢年金・障害年金・遺族年金</td>\n        </tr>\n        <tr>\n          <td class=\"fn-mark\">介護保険<br><span style=\"font-size:11px;color:#888;\">かいごほけん</span></td>\n          <td>市町村・特別区</td>\n          <td>40歳以上の住民</td>\n          <td>要介護・要支援状態</td>\n          <td>介護サービス・予防サービス</td>\n        </tr>\n        <tr>\n          <td class=\"fn-mark\">雇用保険<br><span style=\"font-size:11px;color:#888;\">こようほけん</span></td>\n          <td>国（政府）</td>\n          <td>被用者（労働者）</td>\n          <td>失業・教育訓練・育児休業等</td>\n          <td>失業給付・育児休業給付等</td>\n        </tr>\n        <tr>\n          <td class=\"fn-mark\">労災保険<br><span style=\"font-size:11px;color:#888;\">ろうさいほけん</span></td>\n          <td>国（政府）</td>\n          <td>労働者（事業主が加入）</td>\n          <td>業務上の病気・けが・死亡</td>\n          <td>療養補償・休業補償・遺族補償</td>\n        </tr>\n      </table>\n      </div>\n\n      <hr class=\"divider\">\n      <div class=\"sec-sub\">🏢 <ruby>民間保険<rt>みんかんほけん</rt></ruby>（3分野）</div>\n      <p>社会保険を補完するものとして、民間の保険会社が提供する保険もある。<br>\n      <i>Asuransi swasta sebagai pelengkap asuransi sosial, terbagi 3 bidang:</i></p>\n      <div class=\"grid3\">\n        <div class=\"node n-yellow\"><div class=\"node-main\">第一分野</div><div class=\"node-sub\">生命保険<br><i>Asuransi jiwa</i></div></div>\n        <div class=\"node n-yellow\"><div class=\"node-main\">第二分野</div><div class=\"node-sub\">損害保険<br><i>Asuransi kerugian (kebakaran, kendaraan, dll)</i></div></div>\n        <div class=\"node n-yellow\"><div class=\"node-main\">第三分野</div><div class=\"node-sub\">医療保険・がん保険・介護保険等<br><i>Asuransi medis, kanker, perawatan lansia, dll (swasta)</i></div></div>\n      </div>\n    </div>\n  </div>\n</section>\n<section class=\"section\" id=\"s3\">\n  <div class=\"sec-head th-orange\" onclick=\"toggle('s3')\">\n    <span>③ <ruby>社会福祉<rt>しゃかいふくし</rt></ruby>の<ruby>法体系<rt>ほうたいけい</rt></ruby></span>\n    <span class=\"toggle-arr\">▾</span>\n  </div>\n  <div class=\"sec-body\">\n    <div class=\"sec-inner\">\n      <p>戦後、まず<b>福祉三法</b>（生活保護法・児童福祉法・身体障害者福祉法）が整備され、その後<b>福祉六法</b>体制となった。<br>\n      <i>Pasca perang, pertama dibentuk \"3 UU Kesejahteraan\", kemudian berkembang menjadi \"6 UU Kesejahteraan\".</i></p>\n\n      <div class=\"grid2\">\n        <div class=\"node n-green\">\n          <div class=\"node-main\">福祉三法（1950年代）</div><div class=\"node-sub\">① 生活保護法<br>② 児童福祉法<br>③ 身体障害者福祉法</div>\n        </div>\n        <div class=\"node n-blue\">\n          <div class=\"node-main\">福祉六法（1960年代〜）</div><div class=\"node-sub\">上記3法 ＋<br>④ 精神薄弱者福祉法（現：知的障害者福祉法）<br>⑤ 老人福祉法<br>⑥ 母子福祉法（現：母子及び父子並びに寡婦福祉法）</div>\n        </div>\n      </div>\n\n      <hr class=\"divider\">\n      <div class=\"sec-sub\">📜 <ruby>主要<rt>しゅよう</rt></ruby>な<ruby>社会福祉関連法<rt>しゃかいふくしかんれんほう</rt></ruby></div>\n      <div class=\"table-wrap\">\n      <table class=\"tbl small\">\n        <tr><th>法律名</th><th>概要・改正経緯<br><i>Ringkasan/Riwayat Revisi</i></th></tr>\n        <tr><td class=\"fn-mark\">社会福祉法</td><td>社会福祉事業の共通基盤を定める。旧「社会福祉事業法」（1951年）が2000年に改正・改称<span class=\"fn-mark\">※1</span></td></tr>\n        <tr><td class=\"fn-mark\">生活保護法</td><td>最低限度の生活を保障し、自立を助長する</td></tr>\n        <tr><td class=\"fn-mark\">児童福祉法</td><td>児童の福祉を保障するための原理・原則を規定<span class=\"fn-mark\">※2</span></td></tr>\n        <tr><td class=\"fn-mark\">身体障害者福祉法</td><td>身体障害者の自立と社会経済活動への参加を促進</td></tr>\n        <tr><td class=\"fn-mark\">知的障害者福祉法</td><td>旧「精神薄弱者福祉法」（1960年）が1998年に改称<span class=\"fn-mark\">※3</span></td></tr>\n        <tr><td class=\"fn-mark\">老人福祉法</td><td>老人の福祉に関する原理を明らかにし、必要な措置を規定</td></tr>\n        <tr><td class=\"fn-mark\">母子及び父子並びに寡婦福祉法</td><td>旧「母子福祉法」（1964年）が改称<span class=\"fn-mark\">※4</span></td></tr>\n        <tr><td class=\"fn-mark\">障害者基本法</td><td>旧「心身障害者対策基本法」（1970年）が1993年に改称<span class=\"fn-mark\">※5</span></td></tr>\n        <tr><td class=\"fn-mark\">障害者総合支援法</td><td>正式名称：障害者の日常生活及び社会生活を総合的に支援するための法律。旧「障害者自立支援法」が2012年に改称<span class=\"fn-mark\">※6</span></td></tr>\n        <tr><td class=\"fn-mark\">介護保険法</td><td>1997年制定・2000年施行。介護を社会保険方式で支える</td></tr>\n      </table>\n      </div>\n      <div class=\"node n-yellow\" style=\"font-size:13px;margin-top:10px;\">\n        <p>\n        <span class=\"fn-mark\">※1</span> 社会福祉事業法(1951)→社会福祉法(2000)<br>\n        <span class=\"fn-mark\">※2</span> 児童福祉法は2016年・2022年等に複数回改正<br>\n        <span class=\"fn-mark\">※3</span> 精神薄弱者福祉法(1960)→知的障害者福祉法(1998)<br>\n        <span class=\"fn-mark\">※4</span> 母子福祉法(1964)→母子及び父子並びに寡婦福祉法<br>\n        <span class=\"fn-mark\">※5</span> 心身障害者対策基本法(1970)→障害者基本法(1993)<br>\n        <span class=\"fn-mark\">※6</span> 障害者自立支援法(2005)→障害者総合支援法(2012)\n        </p>\n      </div>\n    </div>\n  </div>\n</section>\n\n<section class=\"section\" id=\"s4\">\n  <div class=\"sec-head th-purple\" onclick=\"toggle('s4')\">\n    <span>④ <ruby>サービス利用方式<rt>りようほうしき</rt></ruby></span>\n    <span class=\"toggle-arr\">▾</span>\n  </div>\n  <div class=\"sec-body\">\n    <div class=\"sec-inner\">\n      <p>福祉サービスの利用方法は、かつての「<b>措置制度</b>」から、現在は主に「<b>利用契約制度</b>」へと移行した（2000年社会福祉基礎構造改革）。<br>\n      <i>Sistem layanan kesejahteraan beralih dari \"sistem penetapan (措置)\" ke \"sistem kontrak penggunaan (利用契約)\".</i></p>\n\n      <div class=\"grid2\">\n        <div class=\"node n-red\">\n          <div class=\"node-main\">措置制度<br><span style=\"font-size:11px;\">そちせいど</span></div><div class=\"node-sub\"><b>行政（措置権者）</b>がサービスの種類・提供者を決定する。<br>\n          利用者に選択権はない。<br>\n          <i>Pemerintah menentukan jenis & penyedia layanan; pengguna tidak memilih.</i></div>\n        </div>\n        <div class=\"node n-green\">\n          <div class=\"node-main\">利用契約制度<br><span style=\"font-size:11px;\">りようけいやくせいど</span></div><div class=\"node-sub\"><b>利用者自身</b>が事業者を選び、対等な関係で契約を結ぶ。<br>\n          行政は財政支援等を行う。<br>\n          <i>Pengguna sendiri memilih penyedia & membuat kontrak setara; pemerintah memberi dukungan finansial.</i></div>\n        </div>\n      </div>\n\n      <hr class=\"divider\">\n      <div class=\"sec-sub\">💰 <ruby>費用負担<rt>ひようふたん</rt></ruby>の<ruby>考え方<rt>かんがえかた</rt></ruby></div>\n      <div class=\"grid2\">\n        <div class=\"node n-blue\">\n          <div class=\"node-main\">応益負担<br><span style=\"font-size:11px;\">おうえきふたん</span></div><div class=\"node-sub\">受けたサービスの量に応じて費用を負担する。<br>\n          <i>Biaya sesuai jumlah/banyaknya layanan yang diterima.</i></div>\n        </div>\n        <div class=\"node n-orange\">\n          <div class=\"node-main\">応能負担<br><span style=\"font-size:11px;\">おうのうふたん</span></div><div class=\"node-sub\">本人の所得など、負担能力に応じて費用を負担する。<br>\n          <i>Biaya sesuai kemampuan ekonomi/pendapatan pengguna.</i></div>\n        </div>\n      </div>\n      <p style=\"font-size:13px;color:#555;\">現在は多くの福祉サービスで応能負担が基本とされている（介護保険の利用者負担は原則1割など応益負担的要素も併存）。<br>\n      <i>Saat ini sebagian besar layanan menggunakan prinsip 応能負担, meski beberapa (mis. asuransi perawatan lansia) tetap memiliki elemen 応益負担.</i></p>\n    </div>\n  </div>\n</section>\n<section class=\"section\" id=\"s5\">\n  <div class=\"sec-head th-teal\" onclick=\"toggle('s5')\">\n    <span>⑤ <ruby>社会保障給付費<rt>しゃかいほしょうきゅうふひ</rt></ruby></span>\n    <span class=\"toggle-arr\">▾</span>\n  </div>\n  <div class=\"sec-body\">\n    <div class=\"sec-inner\">\n      <p>社会保障給付費は<b>約134兆円</b>規模（2021年度）で、年々増加傾向にある。<br>\n      <i>Total belanja jaminan sosial Jepang sekitar 134 triliun yen (TA 2021), terus meningkat setiap tahun.</i></p>\n\n      <div class=\"sec-sub\">📊 <ruby>部門別<rt>ぶもんべつ</rt></ruby>の<ruby>構成<rt>こうせい</rt></ruby></div>\n      <div class=\"bar-chart\">\n        <div class=\"bar-row\"><span class=\"bar-label\">年金<br><i>Pensiun</i></span><div class=\"bar-track\"><div class=\"bar-fill\" style=\"width:90%;background:#52b788;\">約40.2%</div></div></div>\n        <div class=\"bar-row\"><span class=\"bar-label\">医療<br><i>Medis</i></span><div class=\"bar-track\"><div class=\"bar-fill\" style=\"width:70%;background:#4895ef;\">約32.4%</div></div></div>\n        <div class=\"bar-row\"><span class=\"bar-label\">福祉その他<br><i>Lainnya</i></span><div class=\"bar-track\"><div class=\"bar-fill\" style=\"width:60%;background:#f3a261;\">約27.4%</div></div></div>\n      </div>\n\n      <div class=\"sec-sub\">📊 <ruby>機能別<rt>きのうべつ</rt></ruby>の<ruby>構成<rt>こうせい</rt></ruby></div>\n      <p style=\"font-size:13px;\">高齢、遺族、障害、保健医療、家族、失業、住宅、生活保護その他の8分野に分類される。最大は「高齢」分野。<br>\n      <i>Diklasifikasikan dalam 8 bidang fungsi: lansia, ahli waris, disabilitas, kesehatan, keluarga, pengangguran, perumahan, bantuan hidup lainnya. Terbesar: bidang \"lansia\".</i></p>\n      <div class=\"bar-chart\">\n        <div class=\"bar-row\"><span class=\"bar-label\">高齢<br><i>Lansia</i></span><div class=\"bar-track\"><div class=\"bar-fill\" style=\"width:85%;background:#52b788;\">最大</div></div></div>\n        <div class=\"bar-row\"><span class=\"bar-label\">保健医療<br><i>Kesehatan</i></span><div class=\"bar-track\"><div class=\"bar-fill\" style=\"width:65%;background:#4895ef;\">大</div></div></div>\n        <div class=\"bar-row\"><span class=\"bar-label\">家族・遺族・他<br><i>Keluarga/Lainnya</i></span><div class=\"bar-track\"><div class=\"bar-fill\" style=\"width:35%;background:#f3a261;\">中〜小</div></div></div>\n      </div>\n\n      <hr class=\"divider\">\n      <div class=\"sec-sub\">💴 <ruby>財源<rt>ざいげん</rt></ruby>の<ruby>内訳<rt>うちわけ</rt></ruby></div>\n      <p>社会保障の財源は、主に<b>社会保険料</b>と<b>公費（税金）</b>から成る。<br>\n      <i>Sumber dana jaminan sosial utamanya berasal dari premi asuransi sosial dan dana publik (pajak).</i></p>\n      <div class=\"grid2\">\n        <div class=\"node n-green\"><div class=\"node-main\">社会保険料</div><div class=\"node-sub\">被保険者・事業主が負担<br><i>Premi dari tertanggung & pemberi kerja — porsi terbesar</i></div></div>\n        <div class=\"node n-blue\"><div class=\"node-main\">公費（国・地方）</div><div class=\"node-sub\">税金を財源とする負担<br><i>Dana dari pajak (pusat & daerah)</i></div></div>\n      </div>\n\n      <hr class=\"divider\">\n      <div class=\"sec-sub\">🏛️ <ruby>一般会計<rt>いっぱんかいけい</rt></ruby>における<ruby>社会保障関係費<rt>しゃかいほしょうかんけいひ</rt></ruby></div>\n      <p>国の一般会計予算の中で、社会保障関係費は最大の割合を占める歳出項目である。<br>\n      <i>Dalam anggaran umum nasional, belanja terkait jaminan sosial adalah pos pengeluaran terbesar.</i></p>\n      <div class=\"bar-chart\">\n        <div class=\"bar-row\"><span class=\"bar-label\">社会保障<br><i>Jaminan Sosial</i></span><div class=\"bar-track\"><div class=\"bar-fill\" style=\"width:95%;background:#e76f51;\">最大の割合(約3割超)</div></div></div>\n        <div class=\"bar-row\"><span class=\"bar-label\">国債費<br><i>Bunga Utang</i></span><div class=\"bar-track\"><div class=\"bar-fill\" style=\"width:55%;background:#4895ef;\">大</div></div></div>\n        <div class=\"bar-row\"><span class=\"bar-label\">地方交付税等<br><i>Hibah Daerah</i></span><div class=\"bar-track\"><div class=\"bar-fill\" style=\"width:40%;background:#f3a261;\">中</div></div></div>\n      </div>\n\n      <hr class=\"divider\">\n      <div class=\"sec-sub\">🌍 <ruby>国際比較<rt>こくさいひかく</rt></ruby>（<ruby>国民負担率<rt>こくみんふたんりつ</rt></ruby>等）</div>\n      <p>日本の国民負担率（税＋社会保険料の対国民所得比）は、欧米諸国と比べると中程度に位置する。<br>\n      <i>Rasio beban nasional Jepang (pajak + premi sosial terhadap pendapatan nasional) berada di tingkat menengah dibanding negara Barat.</i></p>\n      <div class=\"bar-chart\">\n        <div class=\"bar-row\"><span class=\"bar-label\">フランス<br><i>Prancis</i></span><div class=\"bar-track\"><div class=\"bar-fill\" style=\"width:95%;background:#9d4edd;\">高い</div></div></div>\n        <div class=\"bar-row\"><span class=\"bar-label\">ドイツ<br><i>Jerman</i></span><div class=\"bar-track\"><div class=\"bar-fill\" style=\"width:80%;background:#4895ef;\">高め</div></div></div>\n        <div class=\"bar-row\"><span class=\"bar-label\">日本<br><i>Jepang</i></span><div class=\"bar-track\"><div class=\"bar-fill\" style=\"width:60%;background:#52b788;\">中程度</div></div></div>\n        <div class=\"bar-row\"><span class=\"bar-label\">アメリカ<br><i>Amerika</i></span><div class=\"bar-track\"><div class=\"bar-fill\" style=\"width:40%;background:#f3a261;\">低め</div></div></div>\n      </div>\n      <p style=\"font-size:12px;color:#666;\">※グラフはおおよその傾向を示すイメージ図です。<br><i>*Grafik bersifat ilustratif tren umum.</i></p>\n    </div>\n  </div>\n</section>\n<section class=\"section\" id=\"s6\">\n  <div class=\"sec-head th-red\" onclick=\"toggle('s6')\">\n    <span>⑥ <ruby>高齢者福祉<rt>こうれいしゃふくし</rt></ruby>の<ruby>歴史<rt>れきし</rt></ruby></span>\n    <span class=\"toggle-arr\">▾</span>\n  </div>\n  <div class=\"sec-body\">\n    <div class=\"sec-inner\">\n      <p>1950年代以降、高齢化の進行とともに高齢者福祉制度は段階的に整備されてきた。<br>\n      <i>Sejak 1950-an, sistem kesejahteraan lansia dikembangkan secara bertahap seiring penuaan populasi.</i></p>\n      <div class=\"tl\">\n        <div class=\"tl-item\"><span class=\"tl-year\">1950年（昭和25）</span><div class=\"tl-law\">生活保護法（改正）</div><div class=\"tl-desc\">養老施設を規定<span class=\"id\">Mengatur fasilitas perawatan lansia dalam UU Bantuan Hidup</span></div></div>\n        <div class=\"tl-item\"><span class=\"tl-year\">1963年（昭和38）</span><div class=\"tl-law\">老人福祉法</div><div class=\"tl-desc\">老人福祉に関する原理を明示。特別養護老人ホーム創設<span class=\"id\">UU Kesejahteraan Lansia; pendirian panti rawat lansia khusus</span></div></div>\n        <div class=\"tl-item\"><span class=\"tl-year\">1973年（昭和48）</span><div class=\"tl-law\">老人医療費支給制度</div><div class=\"tl-desc\">70歳以上の医療費無料化（老人福祉法改正）<span class=\"id\">Biaya medis gratis untuk lansia 70+ tahun</span></div></div>\n        <div class=\"tl-item\"><span class=\"tl-year\">1982年（昭和57）</span><div class=\"tl-law\">老人保健法</div><div class=\"tl-desc\">老人医療費無料化を見直し、一部負担を導入<span class=\"id\">Meninjau ulang biaya medis gratis, memperkenalkan iuran sebagian</span></div></div>\n        <div class=\"tl-item\"><span class=\"tl-year\">1989年（平成元）</span><div class=\"tl-law\">高齢者保健福祉推進十か年戦略（ゴールドプラン）</div><div class=\"tl-desc\">在宅福祉・施設福祉の整備目標を設定<span class=\"id\">Strategi 10 tahun pengembangan layanan kesehatan & kesejahteraan lansia</span></div></div>\n        <div class=\"tl-item\"><span class=\"tl-year\">1990年（平成2）</span><div class=\"tl-law\">福祉関係八法改正</div><div class=\"tl-desc\">在宅福祉サービスの法定化、権限の市町村への一元化<span class=\"id\">8 UU kesejahteraan direvisi; layanan berbasis rumah dilegalkan, kewenangan dialihkan ke pemerintah kota</span></div></div>\n        <div class=\"tl-item\"><span class=\"tl-year\">1994年（平成6）</span><div class=\"tl-law\">新ゴールドプラン</div><div class=\"tl-desc\">ゴールドプランの目標を上方修正<span class=\"id\">Revisi target Gold Plan ke arah lebih tinggi</span></div></div>\n        <div class=\"tl-item\"><span class=\"tl-year\">1997年（平成9）</span><div class=\"tl-law\">介護保険法</div><div class=\"tl-desc\">2000年施行。介護を社会保険方式で支える制度創設<span class=\"id\">UU Asuransi Perawatan Lansia (berlaku 2000); sistem berbasis asuransi sosial</span></div></div>\n        <div class=\"tl-item\"><span class=\"tl-year\">1999年（平成11）</span><div class=\"tl-law\">ゴールドプラン21</div><div class=\"tl-desc\">介護保険制度を支える基盤整備計画<span class=\"id\">Gold Plan 21 — rencana infrastruktur pendukung asuransi perawatan</span></div></div>\n        <div class=\"tl-item\"><span class=\"tl-year\">2005年（平成17）</span><div class=\"tl-law\">介護保険法改正</div><div class=\"tl-desc\">予防重視型システムへの転換、地域支援事業・地域包括支援センター創設<span class=\"id\">Reformasi ke sistem berorientasi pencegahan; pendirian pusat dukungan komunitas terpadu</span></div></div>\n        <div class=\"tl-item\"><span class=\"tl-year\">2011年（平成23）</span><div class=\"tl-law\">介護保険法改正</div><div class=\"tl-desc\">地域包括ケアシステムの推進、定期巡回・随時対応サービス創設<span class=\"id\">Mendorong sistem perawatan komunitas terintegrasi</span></div></div>\n        <div class=\"tl-item\"><span class=\"tl-year\">2014年（平成26）</span><div class=\"tl-law\">医療介護総合確保推進法</div><div class=\"tl-desc\">地域医療構想、地域包括ケアシステムの構築を推進<span class=\"id\">UU promosi integrasi medis & perawatan; mendorong sistem perawatan komunitas</span></div></div>\n        <div class=\"tl-item\"><span class=\"tl-year\">2017年（平成29）</span><div class=\"tl-law\">介護保険法改正</div><div class=\"tl-desc\">介護医療院の創設、共生型サービスの位置づけ<span class=\"id\">Pendirian fasilitas perawatan medis; layanan berbasis koeksistensi (kyosei)</span></div></div>\n        <div class=\"tl-item\"><span class=\"tl-year\">2020年（令和2）</span><div class=\"tl-law\">地域共生社会の実現のための社会福祉法等改正</div><div class=\"tl-desc\">重層的支援体制整備事業の創設<span class=\"id\">Revisi UU untuk merealisasikan masyarakat koeksistensi komunitas</span></div></div>\n        <div class=\"tl-item\"><span class=\"tl-year\">2021年（令和3）</span><div class=\"tl-law\">介護保険法改正</div><div class=\"tl-desc\">高齢者の地域における社会参加の推進、認知症対策の推進<span class=\"id\">Mendorong partisipasi sosial lansia & penanganan demensia</span></div></div>\n      </div>\n    </div>\n  </div>\n</section>\n<section class=\"section\" id=\"s7\">\n  <div class=\"sec-head th-purple\" onclick=\"toggle('s7')\">\n    <span>⑦ <ruby>障害者福祉<rt>しょうがいしゃふくし</rt></ruby>の<ruby>歴史<rt>れきし</rt></ruby></span>\n    <span class=\"toggle-arr\">▾</span>\n  </div>\n  <div class=\"sec-body\">\n    <div class=\"sec-inner\">\n      <p>障害者福祉は「保護」から「ノーマライゼーション」「共生社会」へと理念が変化してきた。<br>\n      <i>Filosofi kesejahteraan disabilitas berevolusi dari \"perlindungan\" → \"normalisasi\" → \"masyarakat inklusif\".</i></p>\n\n      <div class=\"grid3\">\n        <div class=\"node n-green\"><div class=\"node-main\">①長期計画</div><div class=\"node-sub\">1983〜1992年<br>障害者対策に関する長期計画<span class=\"id\">Rencana jangka panjang kebijakan disabilitas</span></div></div>\n        <div class=\"node n-blue\"><div class=\"node-main\">②新長期計画</div><div class=\"node-sub\">1993〜2002年<br>ノーマライゼーション<span class=\"id\">Normalisasi</span></div></div>\n        <div class=\"node n-purple\"><div class=\"node-main\">③障害者基本計画</div><div class=\"node-sub\">2003〜2027年<br>共生社会<span class=\"id\">Masyarakat inklusif (kyosei shakai)</span></div></div>\n      </div>\n\n      <div class=\"tl purple\">\n        <div class=\"tl-item\"><span class=\"tl-year\">1949年（昭和24）</span><div class=\"tl-law\">身体障害者福祉法</div><div class=\"tl-desc\">身体障害者の定義、更生援護、事業及び施設等を規定<span class=\"id\">UU Kesejahteraan Penyandang Disabilitas Fisik</span></div></div>\n        <div class=\"tl-item\"><span class=\"tl-year\">1950年（昭和25）</span><div class=\"tl-law\">精神衛生法</div><div class=\"tl-desc\">1987年→精神保健法、1995年→精神保健及び精神障害者福祉に関する法律へ改正<span class=\"id\">Direvisi menjadi UU Kesehatan Jiwa & Kesejahteraan Penyandang Disabilitas Mental</span></div></div>\n        <div class=\"tl-item\"><span class=\"tl-year\">1960年（昭和35）</span><div class=\"tl-law\">精神薄弱者福祉法／身体障害者雇用促進法</div><div class=\"tl-desc\">1998年→知的障害者福祉法、1987年→障害者雇用促進法へ改正<span class=\"id\">Direvisi menjadi UU Kesejahteraan Disabilitas Intelektual & UU Promosi Ketenagakerjaan Disabilitas</span></div></div>\n        <div class=\"tl-item\"><span class=\"tl-year\">1964年（昭和39）</span><div class=\"tl-law\">特別児童扶養手当等の支給に関する法律</div><div class=\"tl-desc\">特別児童扶養手当・障害児福祉手当・特別障害者手当<span class=\"id\">UU tunjangan anak/anak disabilitas khusus</span></div></div>\n        <div class=\"tl-item\"><span class=\"tl-year\">1970年（昭和45）</span><div class=\"tl-law\">心身障害者対策基本法</div><div class=\"tl-desc\">1993年→障害者基本法へ改正<span class=\"id\">Direvisi menjadi UU Dasar Disabilitas (1993)</span></div></div>\n        <div class=\"tl-item\"><span class=\"tl-year\">1981年（昭和56）</span><div class=\"tl-law\">国際障害者年</div><div class=\"tl-desc\">テーマ：完全参加と平等<span class=\"id\">Tahun Internasional Penyandang Disabilitas — \"Partisipasi Penuh dan Kesetaraan\"</span></div></div>\n        <div class=\"tl-item\"><span class=\"tl-year\">1985年（昭和60）</span><div class=\"tl-law\">年金制度改正</div><div class=\"tl-desc\">障害基礎年金制度を導入<span class=\"id\">Memperkenalkan tunjangan pensiun dasar disabilitas</span></div></div>\n        <div class=\"tl-item\"><span class=\"tl-year\">1990年（平成2）</span><div class=\"tl-law\">福祉関係八法改正</div><div class=\"tl-desc\">在宅福祉サービスの推進、市町村への一元化<span class=\"id\">Mendorong layanan berbasis rumah; kewenangan ke pemerintah kota</span></div></div>\n        <div class=\"tl-item\"><span class=\"tl-year\">1993年（平成5）</span><div class=\"tl-law\">障害者基本法</div><div class=\"tl-desc\">障害者の福祉に関する基本的施策等を規定<span class=\"id\">UU Dasar Disabilitas — kebijakan dasar kesejahteraan disabilitas</span></div></div>\n        <div class=\"tl-item\"><span class=\"tl-year\">1995年（平成7）</span><div class=\"tl-law\">障害者プラン</div><div class=\"tl-desc\">ノーマライゼーション7か年計画<span class=\"id\">Rencana 7 tahun normalisasi</span></div></div>\n        <div class=\"tl-item\"><span class=\"tl-year\">2002年（平成14）</span><div class=\"tl-law\">身体障害者補助犬法</div><div class=\"tl-desc\">補助犬を使う身体障害者の自立と社会参加の促進<span class=\"id\">UU anjing pendamping disabilitas fisik</span></div></div>\n        <div class=\"tl-item\"><span class=\"tl-year\">2003年（平成15）</span><div class=\"tl-law\">支援費制度</div><div class=\"tl-desc\">身体障害者・知的障害者・障害児が市町村から支援費の支給を受け、事業者と契約<span class=\"id\">Sistem tunjangan dukungan — kontrak langsung dengan penyedia</span></div></div>\n        <div class=\"tl-item\"><span class=\"tl-year\">2004年（平成16）</span><div class=\"tl-law\">発達障害者支援法</div><div class=\"tl-desc\">発達障害の早期発見・支援、発達障害者支援センターの指定<span class=\"id\">UU dukungan disabilitas perkembangan; deteksi & dukungan dini</span></div></div>\n        <div class=\"tl-item\"><span class=\"tl-year\">2005年（平成17）</span><div class=\"tl-law\">障害者自立支援法</div><div class=\"tl-desc\">2006年施行。障害種別に関わりなく一元的な共通サービスを提供<span class=\"id\">UU dukungan kemandirian disabilitas (berlaku 2006); layanan terpadu lintas jenis disabilitas</span></div></div>\n        <div class=\"tl-item\"><span class=\"tl-year\">2011年（平成23）</span><div class=\"tl-law\">障害者虐待防止法<span class=\"tl-key purple\">※1</span></div><div class=\"tl-desc\">2012年10月施行<span class=\"id\">UU pencegahan kekerasan terhadap penyandang disabilitas (berlaku Okt 2012)</span></div></div>\n        <div class=\"tl-item\"><span class=\"tl-year\">2012年（平成24）</span><div class=\"tl-law\">児童福祉法改正／障害者総合支援法<span class=\"tl-key purple\">※2</span></div><div class=\"tl-desc\">2013年施行。障害者の定義に難病等の患者を追加<span class=\"id\">UU dukungan komprehensif disabilitas (berlaku 2013); definisi disabilitas diperluas mencakup penyakit langka</span></div></div>\n        <div class=\"tl-item\"><span class=\"tl-year\">2013年（平成25）</span><div class=\"tl-law\">障害者差別解消法<span class=\"tl-key purple\">※3</span></div><div class=\"tl-desc\">2016年4月施行<span class=\"id\">UU penghapusan diskriminasi disabilitas (berlaku Apr 2016)</span></div></div>\n        <div class=\"tl-item\"><span class=\"tl-year\">2016年（平成28）</span><div class=\"tl-law\">障害者総合支援法改正</div><div class=\"tl-desc\">就労定着支援・自立生活援助の創設<span class=\"id\">Pendirian dukungan keberlanjutan kerja & dukungan hidup mandiri</span></div></div>\n        <div class=\"tl-item\"><span class=\"tl-year\">2022年（令和4）</span><div class=\"tl-law\">障害者総合支援法改正</div><div class=\"tl-desc\">就労選択支援の創設（2025年10月施行予定）<span class=\"id\">Pendirian dukungan pemilihan kerja (berlaku rencana Okt 2025)</span></div></div>\n      </div>\n\n      <div class=\"hl hl-purple\" style=\"font-size:12px;\">\n        <span class=\"tl-key purple\">※1</span> 障害者虐待の防止、障害者の養護者に対する支援等に関する法律<br>\n        <span class=\"tl-key purple\">※2</span> 障害者の日常生活及び社会生活を総合的に支援するための法律<br>\n        <span class=\"tl-key purple\">※3</span> 障害を理由とする差別の解消の推進に関する法律\n      </div>\n    </div>\n  </div>\n</section>\n<section class=\"section\" id=\"s8\">\n  <div class=\"sec-head th-blue\" onclick=\"toggle('s8')\">\n    <span>⑧ <ruby>社会保険<rt>しゃかいほけん</rt></ruby>・その<ruby>他<rt>た</rt></ruby>の<ruby>福祉関連法<rt>ふくしかんれんほう</rt></ruby>の<ruby>歴史<rt>れきし</rt></ruby></span>\n    <span class=\"toggle-arr\">▾</span>\n  </div>\n  <div class=\"sec-body\">\n    <div class=\"sec-inner\">\n      <p>社会保険制度は1920年代の健康保険法から始まり、1961年の「<b>国民皆保険・皆年金</b>」体制を経て、現在まで拡充され続けている。<br>\n      <i>Sistem asuransi sosial dimulai dari UU Asuransi Kesehatan (1922), mencapai \"asuransi & pensiun nasional universal\" pada 1961, dan terus berkembang.</i></p>\n\n      <div class=\"tl blue\">\n        <div class=\"tl-item\"><span class=\"tl-year\">1922年（大正11）</span><div class=\"tl-law\">健康保険法</div><div class=\"tl-desc\">ブルーカラーの労働者を対象<span class=\"id\">UU Asuransi Kesehatan — untuk pekerja buruh (blue-collar)</span></div></div>\n        <div class=\"tl-item\"><span class=\"tl-year\">1938年（昭和13）</span><div class=\"tl-law\">国民健康保険法</div><div class=\"tl-desc\">任意設立・任意加入、保険者は国民健康保険組合<span class=\"id\">UU Asuransi Kesehatan Nasional — pendirian & kepesertaan sukarela</span></div></div>\n        <div class=\"tl-item\"><span class=\"tl-year\">1947年（昭和22）</span><div class=\"tl-law\">失業保険法／労災保険法</div><div class=\"tl-desc\">失業保険金支給／労働基準法による災害補償責任を保険で担保<span class=\"id\">UU Asuransi Pengangguran & UU Asuransi Kecelakaan Kerja</span></div></div>\n        <div class=\"tl-item\"><span class=\"tl-year\">1950年（昭和25）</span><div class=\"tl-law\">社会保障制度審議会勧告</div><div class=\"tl-desc\">社会保険・国家扶助・公衆衛生及び医療・社会福祉の4部門で構成<span class=\"id\">Rekomendasi struktur jaminan sosial 4 pilar</span></div></div>\n        <div class=\"tl-item\"><span class=\"tl-year\">1951年（昭和26）</span><div class=\"tl-law\">社会福祉事業法</div><div class=\"tl-desc\">2000年「社会福祉法」へ改正<span class=\"id\">Direvisi menjadi UU Kesejahteraan Sosial (2000)</span></div></div>\n        <div class=\"tl-item\"><span class=\"tl-year\">1954年（昭和29）</span><div class=\"tl-law\">厚生年金保険法</div><div class=\"tl-desc\">昭和16年の法律を全部改正して制定<span class=\"id\">UU Asuransi Pensiun Karyawan — revisi total UU 1941</span></div></div>\n        <div class=\"tl-item\"><span class=\"tl-year\">1958年（昭和33）</span><div class=\"tl-law\">国民健康保険法改正</div><div class=\"tl-desc\">1961年から<b>国民皆保険体制</b>を実現<span class=\"id\">Merealisasikan asuransi kesehatan nasional universal sejak 1961</span></div></div>\n        <div class=\"tl-item\"><span class=\"tl-year\">1959年（昭和34）</span><div class=\"tl-law\">国民年金法</div><div class=\"tl-desc\">1961年から<b>国民皆年金制度</b>を実現<span class=\"id\">Merealisasikan pensiun nasional universal sejak 1961</span></div></div>\n        <div class=\"tl-item\"><span class=\"tl-year\">1974年（昭和49）</span><div class=\"tl-law\">雇用保険法</div><div class=\"tl-desc\">失業保険法が廃止され、代わって雇用保険法を公布<span class=\"id\">UU Asuransi Ketenagakerjaan menggantikan UU Asuransi Pengangguran</span></div></div>\n        <div class=\"tl-item\"><span class=\"tl-year\">1985年（昭和60）</span><div class=\"tl-law\">年金制度改正</div><div class=\"tl-desc\"><b>基礎年金制度</b>導入<span class=\"id\">Memperkenalkan sistem pensiun dasar</span></div></div>\n        <div class=\"tl-item\"><span class=\"tl-year\">1987年（昭和62）</span><div class=\"tl-law\">社会福祉士及び介護福祉士法</div><div class=\"tl-desc\">国家資格「社会福祉士」「介護福祉士」が誕生<span class=\"id\">UU yang melahirkan kualifikasi nasional Pekerja Sosial & Care Worker</span></div></div>\n        <div class=\"tl-item\"><span class=\"tl-year\">1994年（平成6）</span><div class=\"tl-law\">地域保健法</div><div class=\"tl-desc\">保健所法から題名改正、保健所の機能を評価・強化<span class=\"id\">UU Kesehatan Komunitas — revisi dari UU Pusat Kesehatan Masyarakat</span></div></div>\n        <div class=\"tl-item\"><span class=\"tl-year\">2000年（平成12）</span><div class=\"tl-law\">社会福祉基礎構造改革</div><div class=\"tl-desc\">措置制度→契約制度へ転換、地域福祉権利擁護事業・苦情解決制度を創設<span class=\"id\">Reformasi struktur dasar kesejahteraan sosial — dari sistem penetapan ke sistem kontrak</span></div></div>\n        <div class=\"tl-item\"><span class=\"tl-year\">2001年（平成13）</span><div class=\"tl-law\">DV防止法</div><div class=\"tl-desc\">配偶者からの暴力の防止及び被害者の保護等に関する法律の略称<span class=\"id\">UU Pencegahan Kekerasan dalam Rumah Tangga (DV)</span></div></div>\n        <div class=\"tl-item\"><span class=\"tl-year\">2002年（平成14）</span><div class=\"tl-law\">健康増進法</div><div class=\"tl-desc\">国民の健康維持と生活習慣病の予防を目的<span class=\"id\">UU Peningkatan Kesehatan — pencegahan penyakit gaya hidup</span></div></div>\n        <div class=\"tl-item\"><span class=\"tl-year\">2006年（平成18）</span><div class=\"tl-law\">バリアフリー法／自殺対策基本法／がん対策基本法</div><div class=\"tl-desc\">ハートビル法と交通バリアフリー法を統合<span class=\"id\">UU Akses Bebas Hambatan (gabungan UU bangunan & transportasi), UU Dasar Pencegahan Bunuh Diri, UU Dasar Penanggulangan Kanker</span></div></div>\n        <div class=\"tl-item\"><span class=\"tl-year\">2006年（平成18）</span><div class=\"tl-law\">健康保険法等改正</div><div class=\"tl-desc\"><b>後期高齢者医療制度</b>の創設<span class=\"id\">Pendirian Sistem Perawatan Medis Lansia Usia Lanjut (75+)</span></div></div>\n        <div class=\"tl-item\"><span class=\"tl-year\">2007年（平成19）</span><div class=\"tl-law\">社会福祉士及び介護福祉士法改正</div><div class=\"tl-desc\">定義規定・義務規定・資格取得方法の見直し<span class=\"id\">Revisi definisi, kewajiban, dan metode perolehan kualifikasi</span></div></div>\n        <div class=\"tl-item\"><span class=\"tl-year\">2012年（平成24）</span><div class=\"tl-law\">社会保障・税一体改革大綱</div><div class=\"tl-desc\">2012年2月閣議決定。社会保障と税の一体改革に関する関連8法案が成立<span class=\"id\">Garis besar reformasi terpadu jaminan sosial & pajak — 8 RUU terkait disahkan</span></div></div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<div style=\"text-align:center;margin-top:24px;font-size:11px;color:#9ca3af;\">\n  📚 第1章 第3節 ⑥ 社会保障制度の概要（完全版） ／ Materi Jaminan Sosial Jepang — Versi Lengkap\n</div>\n\n</main>\n<script>\nfunction toggle(id){\n  document.getElementById(id).classList.toggle('open');\n}\ndocument.querySelectorAll('.toc-btn').forEach(btn=>{\n  btn.addEventListener('click', function(e){\n    e.preventDefault();\n    const id = this.getAttribute('href').substring(1);\n    const sec = document.getElementById(id);\n    if(!sec.classList.contains('open')) sec.classList.add('open');\n    setTimeout(()=>{ sec.scrollIntoView({behavior:'smooth', block:'start'}); }, 50);\n  });\n});\n<\/script>\n</body>\n</html>\n"};
